SUPPORTED_Z_MODELS = ("IDEAL", "FIXED_Z")


def _normalize_z_model(value: Any) -> str:
    z_model = str(value or "IDEAL").strip().upper() or "IDEAL"
    return z_model if z_model in SUPPORTED_Z_MODELS else "IDEAL"

