def _mole_env_mode(session: Optional[Dict[str, Any]] = None) -> str:
    """Return runtime environment mode.

    TRAINING is a sandboxed simulation environment intended for technician training.
    PRODUCTION is the default.
    """
    # explicit session hint wins (when provided)
    try:
        if isinstance(session, dict):
            sv = str(session.get("environment") or session.get("env") or "").strip().upper()
            if sv in ("TRAINING", "SIM_TRAINING"):
                return "TRAINING"
    except Exception:
        pass
    try:
        v = os.getenv("MOLE_ENV", "") or ""
        v = str(v).strip().upper()
    except Exception:
        v = ""
    if v in ("TRAINING", "SIM_TRAINING", "SIMTRAINING", "TRAIN"):
        return "TRAINING"
    return "PRODUCTION"


def _pkg_root_dir() -> Path:
    """Return runtime package root directory (contains mole_assets + mole_das_data)."""
    try:
        return _app_base_dir().parent
    except Exception:
        return Path(__file__).resolve().parent.parent


def _training_data_root() -> Path:
    return _pkg_root_dir() / "mole_das_data" / "training"


def _is_frozen() -> bool:
    """Return True when running as a frozen/packaged executable (e.g., PyInstaller)."""
    return bool(getattr(sys, "frozen", False))


def _app_base_dir() -> Path:
    """Base directory for bundled resources (works in dev + frozen builds)."""
    try:
        if _is_frozen() and hasattr(sys, "_MEIPASS"):
            return Path(getattr(sys, "_MEIPASS")).resolve()
    except Exception:
        pass
    return Path(__file__).resolve().parent


def _resource_path(*parts: str) -> Path:
    """Resolve a resource path relative to the application base directory."""
    return _app_base_dir().joinpath(*parts)


def _entrypoint_for_subprocess() -> list[str]:
    """Command prefix for relaunching this program in a new process."""
    # In frozen mode, sys.executable is the packaged EXE. In dev mode, sys.executable + script path.
    try:
        if _is_frozen():
            return [sys.executable]
    except Exception:
        pass
    return [sys.executable, str(Path(__file__).resolve())]

