def _intake_check_complete(sess: Dict[str, Any]) -> Tuple[bool, List[str]]:
    """Return (ok, missing_item_ids) for session['project']['intake'].

    Policy: If an item is required, it must be either:
      - provided == True
      - OR not_available == True AND reason is non-empty
    Additionally, regulatory_purpose.category must be STATE/FEDERAL/OTHER (and if OTHER, other_reason is required).
    """
    proj = sess.get("project") or {}
    intake = proj.get("intake") or {}
    items = intake.get("items") or {}
    rp = intake.get("regulatory_purpose") or {}

    required = [
        "FUEL_GAS_ANALYSIS",
        "PERMIT_LIMITS",
        "TMI",
        "SITE_CONTACT",
        "REGION",
        "AGENCY_ID",
        "COORDINATES",
        "ELEVATION",
        "REG_PURPOSE",
    ]

    missing: List[str] = []
    for iid in required:
        d = items.get(iid) or {}
        provided = bool(d.get("provided", False))
        na = bool(d.get("not_available", False))
        reason = str(d.get("reason") or "").strip()
        if provided:
            continue
        if na and reason:
            continue
        missing.append(iid)

    cat = str(rp.get("category") or "").strip().upper()
    other_reason = str(rp.get("other_reason") or "").strip()
    if cat not in ("STATE", "FEDERAL", "OTHER"):
        if "REG_PURPOSE" not in missing:
            missing.append("REG_PURPOSE")
    elif cat == "OTHER" and not other_reason:
        if "REG_PURPOSE" not in missing:
            missing.append("REG_PURPOSE")

    return (len(missing) == 0, missing)

def _now_iso() -> str:
    return now_iso()

def _iso_now() -> str:
    return now_iso()

def now_iso() -> str:
    try:
        return datetime.now().astimezone().isoformat(timespec="seconds")
    except Exception:
        return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def _coerce_int(value: Any, default: Optional[int] = None) -> Optional[int]:
    try:
        return int(value)
    except Exception:
        return default


def ensure_session_schema(session: Dict[str, Any], *, actor: str = "runner", tool_version: str = VERSION) -> Dict[str, Any]:
    if not isinstance(session, dict):
        session = {}

    meta = session.get("meta")
    if not isinstance(meta, dict):
        meta = {}
        session["meta"] = meta

    migrations = meta.get("schema_migrations")
    if not isinstance(migrations, list):
        migrations = []
        meta["schema_migrations"] = migrations

    prev_schema = str(session.get("schema_version") or meta.get("session_schema_version") or "").strip()
    prev_rev = _coerce_int(meta.get("session_schema_revision"))
    migrated = (prev_schema != SESSION_SCHEMA_VERSION) or (prev_rev != SESSION_SCHEMA_REVISION)
    notes: List[str] = []
    if not prev_schema:
        notes.append("Session schema version was unset.")
    elif prev_schema != SESSION_SCHEMA_VERSION:
        notes.append(f"Session schema updated from {prev_schema}.")
    if prev_rev != SESSION_SCHEMA_REVISION:
        notes.append(f"Session schema revision normalized to {SESSION_SCHEMA_REVISION}.")

    sm = session.get("session_mode")
    if not isinstance(sm, dict):
        sm = {}
        session["session_mode"] = sm
    diag_only = bool(sm.get("diagnostic_only"))
    may_support = bool(sm.get("may_support_compliance"))
    if diag_only and may_support:
        sm["may_support_compliance"] = False
        migrated = True
        notes.append("Diagnostic-only session was carrying may_support_compliance=true; compliance support was cleared.")

    daq = session.get("daq_runner")
    if not isinstance(daq, dict):
        daq = {}
        session["daq_runner"] = daq
    ui_mode = str(daq.get("ui_mode") or "").strip().upper()
    if (not diag_only) and ui_mode == "DIAGNOSTICS":
        daq.pop("ui_mode", None)
        migrated = True
        notes.append("Stale diagnostics UI mode was cleared from a non-diagnostic session.")

    sc = session.get("site_conditions")
    if not isinstance(sc, dict):
        sc = {}
        session["site_conditions"] = sc
    legacy_z_model = sc.get("z_model", sc.get("compressibility_model", sc.get("z_basis", "IDEAL")))
    normalized_z_model = str(legacy_z_model or "IDEAL").strip().upper() or "IDEAL"
    if normalized_z_model not in SUPPORTED_Z_MODELS:
        normalized_z_model = "IDEAL"
    if str(sc.get("z_model") or "").strip().upper() != normalized_z_model:
        sc["z_model"] = normalized_z_model
        migrated = True
        if str(legacy_z_model or "").strip():
            notes.append(f"Unsupported compressibility mode '{legacy_z_model}' was normalized to {normalized_z_model}.")
    if "compressibility_model" in sc:
        sc.pop("compressibility_model", None)
        migrated = True
        notes.append("Legacy site_conditions.compressibility_model key was retired.")
    if "z_basis" in sc:
        sc.pop("z_basis", None)
        migrated = True
        notes.append("Legacy site_conditions.z_basis key was retired.")

    fuel = session.get("fuel")
    if not isinstance(fuel, dict):
        fuel = {}
        session["fuel"] = fuel
    dg = fuel.get("dg")
    if not isinstance(dg, dict):
        dg = {}
        fuel["dg"] = dg
    if ("liquid_fraction_volpct" in dg) and (str(dg.get("share_basis") or "").strip().upper() != "SELECTED_HEAT_INPUT_PCT"):
        dg["share_basis"] = "SELECTED_HEAT_INPUT_PCT"
        migrated = True
        notes.append("Dual-fuel liquid share semantics were normalized to selected-basis heat-input share.")

    reg = session.get("regulatory")
    if not isinstance(reg, dict):
        reg = {}
        session["regulatory"] = reg
    selected_rule_ids = reg.get("selected_rule_ids")
    if not isinstance(selected_rule_ids, list):
        selected_rule_ids = []
        reg["selected_rule_ids"] = selected_rule_ids
    stale_placeholder = "STATE_PERMIT_GENERAL"
    if stale_placeholder in [str(x) for x in selected_rule_ids]:
        reg["selected_rule_ids"] = [str(x) for x in selected_rule_ids if str(x) != stale_placeholder]
        sel_meta = reg.get("selected_rule_meta")
        if isinstance(sel_meta, dict):
            sel_meta.pop(stale_placeholder, None)
        migrated = True
        notes.append("Removed stale placeholder regulatory rule id STATE_PERMIT_GENERAL.")

    session["schema_version"] = SESSION_SCHEMA_VERSION
    meta["session_schema_version"] = SESSION_SCHEMA_VERSION
    meta["session_schema_revision"] = SESSION_SCHEMA_REVISION
    meta["session_schema_last_actor"] = str(actor or "").strip() or "runner"
    meta["session_schema_last_tool_version"] = str(tool_version or "").strip() or VERSION
    meta["session_schema_last_checked_iso"] = now_iso()
    meta["session_schema_status"] = "MIGRATED" if migrated else "CURRENT"
    meta["session_schema_last_notes"] = list(notes) if notes else ["No schema changes were required."]
    if migrated:
        meta["session_schema_summary"] = f"Session schema normalized to {SESSION_SCHEMA_VERSION} rev {SESSION_SCHEMA_REVISION}."
        meta["session_schema_notice"] = " | ".join(notes) if notes else "Session schema metadata normalized."
    else:
        meta["session_schema_summary"] = f"Session schema current: {SESSION_SCHEMA_VERSION} rev {SESSION_SCHEMA_REVISION}."
        meta["session_schema_notice"] = "No schema changes were required."

    if migrated:
        entry = {
            "ts_iso": now_iso(),
            "actor": meta["session_schema_last_actor"],
            "tool_version": meta["session_schema_last_tool_version"],
            "from_schema_version": prev_schema or "(unset)",
            "from_schema_revision": prev_rev,
            "to_schema_version": SESSION_SCHEMA_VERSION,
            "to_schema_revision": SESSION_SCHEMA_REVISION,
            "notes": notes or ["Session schema metadata normalized."],
        }
        if not migrations or migrations[-1] != entry:
            migrations.append(entry)
        meta["session_schema_migrated_iso"] = entry["ts_iso"]
        meta["session_schema_migrated_from_version"] = entry["from_schema_version"]
        meta["session_schema_migrated_from_revision"] = entry["from_schema_revision"]

    return session

DISPLAY_DECIMALS = 2
POLLUTANT_MEASUREMENT_DECIMALS = 4
SUPPORT_GAS_MEASUREMENT_DECIMALS = 2
SUPPORT_GAS_CODES = {"O2", "CO2"}

def _fmt_sig_digits(value: Any, sig: int, fallback: str = "(n/a)", zero_decimals: Optional[int] = None) -> str:
    try:
        if value is None:
            return fallback
        v = float(value)
        if math.isnan(v) or math.isinf(v):
            return fallback
        sig2 = max(1, int(sig))
        if abs(v) < 1e-300:
            dec = max(0, int(zero_decimals if zero_decimals is not None else sig2))
            return f"{0:,.{dec}f}" if dec > 0 else "0"
        magnitude = math.floor(math.log10(abs(v)))
        decimals = max(0, sig2 - magnitude - 1)
        rounded = round(v, decimals)
        if abs(rounded) < (0.5 * (10 ** (-decimals))):
            rounded = 0.0
        text = f"{rounded:,.{decimals}f}" if decimals > 0 else f"{rounded:,.0f}"
        if text.startswith("-0"):
            return f"{0:,.{decimals}f}" if decimals > 0 else "0"
        return text
    except Exception:
        return fallback

def _fmt_display_num(
    value: Any,
    decimals: int = DISPLAY_DECIMALS,
    fallback: str = "(n/a)",
    *,
    sig: Optional[int] = None,
) -> str:
    # Backward-compatible alias for older trim/print callers that still pass sig=.
    if sig is not None:
        try:
            decimals = int(sig)
        except Exception:
            pass
    return _fmt_sig_digits(value, max(1, int(decimals)), fallback=fallback, zero_decimals=max(0, int(decimals)))

def _pollutant_measurement_decimals(code: Any = None) -> int:
    try:
        norm = str(code or "").strip().upper()
        if norm in SUPPORT_GAS_CODES:
            return SUPPORT_GAS_MEASUREMENT_DECIMALS
    except Exception:
        pass
    return POLLUTANT_MEASUREMENT_DECIMALS

def _fmt_pollutant_measurement(value: Any, fallback: str = "(n/a)", code: Any = None) -> str:
    sig = _pollutant_measurement_decimals(code)
    return _fmt_sig_digits(value, sig, fallback=fallback, zero_decimals=sig)

def _fmt_num(value: Any, decimals: int = 3, fallback: str = "(n/a)") -> str:
    return _fmt_display_num(value, DISPLAY_DECIMALS, fallback)

def _fmt_num_g(value: Any, sig: int = 6, fallback: str = "(n/a)") -> str:
    return _fmt_display_num(value, DISPLAY_DECIMALS, fallback)

def _fmt_minutes_m(value: Any, fallback: str = "(n/a)") -> str:
    try:
        minutes = float(value)
        if math.isnan(minutes) or math.isinf(minutes):
            return fallback
        if abs(minutes - round(minutes)) < 1e-9:
            return f"{int(round(minutes))} min"
        return f"{minutes:,.1f} min"
    except Exception:
        return fallback

@dataclass
class ExecStep:
    step_id: str
    test_id: str
    name: str
    required: bool
    min_points: int = 0
    points: int = 0
    capture_fields: Dict[str, Any] = field(default_factory=dict)
    status: str = "PENDING"  # PENDING|IN_PROGRESS|DONE|SKIPPED|WAIVED|FAILED_NEEDS_FIXUP
    data: Dict[str, Any] = field(default_factory=dict)
    waive_reason: Optional[str] = None

@dataclass
class ExecPlan:
    steps: List[ExecStep]

def _qaqc_required_by_policy(session: Dict[str, Any]) -> bool:
    sm = session.get("session_mode", {})
    return bool(sm.get("record_data")) and bool(sm.get("tokenize")) and (not bool(sm.get("diagnostic_only")))

def _diagnostics_ui_active(session: Optional[Dict[str, Any]]) -> bool:
    try:
        if not isinstance(session, dict):
            return False
        daq = session.get("daq_runner") or {}
        if isinstance(daq, dict):
            ui_mode = str(daq.get("ui_mode") or "").strip().upper()
            if ui_mode == "DIAGNOSTICS":
                return True
        return False
    except Exception:
        return False

def _effective_exhaust_flow_method(session: Optional[Dict[str, Any]], method: Any) -> str:
    method_u = str(method or "").strip().upper()
    if _diagnostics_ui_active(session) and method_u == "STACK_MEASURED":
        return "STOICH_FUEL"
    return method_u

def _diag_optin(session: Dict[str, Any]) -> bool:
    sm = session.get("session_mode", {})
    # TRAINING is sandboxed: never persist into master DB (functional separation)
    if _mole_env_mode(session) == "TRAINING":
        return
    qa = session.get("qa_qc") or {}
    return bool(sm.get("record_data")) and bool(sm.get("tokenize")) and bool(sm.get("diagnostic_only")) and bool(qa.get("diag_optin_cal_lin"))


def _qaqc_is_complete(session: Dict[str, Any]) -> bool:
    """True if all required QA/QC tests are performed or waived.

    Uses test_matrix.tests and mirrors the 'diag opt-in' de-requirement for CAL/LIN.
    """
    tm = session.get("test_matrix")
    if not tm:
        return True

    tests = tm.get("tests", [])
    # If policy indicates QA/QC required but matrix is empty, treat as incomplete
    if (tm.get("required") or _qaqc_required_by_policy(session)) and not tests:
        return False

    diag_optin = _diag_optin(session)

    for t in tests:
        tid = (t.get("id") or "").strip()
        required = bool(t.get("required"))
        if diag_optin and tid in ("CAL", "LIN"):
            required = False
        if not required:
            continue
        if bool(t.get("performed")) or bool(t.get("waived")):
            continue
        return False

    return True

def _ensure_test_execution_block(session: Dict[str, Any], cfg_path: Path) -> None:
    if "test_execution" not in session or not isinstance(session["test_execution"], dict):
        session["test_execution"] = {
            "status": "IN_PROGRESS",
            "started_iso": now_iso(),
            "active_step_id": None,
            "step_index": 0,
            "steps": [],
            "audit_trail": [{"ts": now_iso(), "event": "START", "config": str(cfg_path)}],
        }

def _persist_session(session: Dict[str, Any], cfg_path: Path) -> None:
    cfg_path.write_text(json.dumps(ensure_session_schema(session, actor="runner_persist"), indent=2), encoding="utf-8")

def build_exec_plan(session: Dict[str, Any]) -> ExecPlan:
    tm = session.get("test_matrix")
    if not tm:
        return ExecPlan(steps=[])

    tests = tm.get("tests", [])
    steps: List[ExecStep] = []
    for t in tests:
        tid = (t.get("id") or "").strip()
        if not tid:
            continue
        name = t.get("name") or tid
        required = bool(t.get("required"))
        min_points = int(t.get("min_points") or 0)
        points = int(t.get("points") or 0)
        capture_fields = dict(t.get("capture_fields") or {})

        if _diag_optin(session) and tid in ("CAL", "LIN"):
            required = False

        steps.append(
            ExecStep(
                step_id=tid,
                test_id=tid,
                name=name,
                required=required,
                min_points=min_points,
                points=max(points, min_points),
                capture_fields=capture_fields,
            )
        )
    return ExecPlan(steps=steps)

def _prompt_yes_no(msg: str, default: bool = False) -> bool:
    suffix = " [Y/n]: " if default else " [y/N]: "
    while True:
        s = input(msg + suffix).strip().lower()
        if not s:
            return default
        if s in ("y", "yes"):
            return True
        if s in ("n", "no"):
            return False

def _prompt_text(label: str, default: Optional[str] = None) -> str:
    if default is not None and default != "":
        s = input(f"{label} [{default}]: ").strip()
        return s if s else str(default)
    return input(f"{label}: ").strip()

def _prompt_float(label: str, default: Optional[float] = None) -> Optional[float]:
    while True:
        d = str(default) if default is not None else ""
        s = _prompt_text(label, d if d else None)
        if not s:
            return None
        try:
            return float(s)
        except ValueError:
            print("  Invalid number. Try again.")

def _validate_step(step: ExecStep, data: Dict[str, Any]) -> Tuple[bool, str]:
    if step.required:
        if step.test_id == "CYLINDER_META":
            if not (data.get("low_cylinder_id") and data.get("high_cylinder_id")):
                return False, "Cylinder metadata requires low_cylinder_id and high_cylinder_id."
        if step.test_id == "CAL":
            if not (data.get("low_cylinder_id") and data.get("high_cylinder_id")):
                return False, "Calibration requires low/high cylinder IDs."
            if data.get("low_concentration") is None or data.get("high_concentration") is None:
                return False, "Calibration requires low/high concentrations."
        if step.test_id == "LIN":
            pts = int(data.get("points_expected") or step.points or 0)
            if pts < int(step.min_points or 0):
                return False, f"Linearity points_expected {pts} below minimum {step.min_points}."
    return True, ""

def _prompt_step(step: ExecStep) -> Dict[str, Any]:
    data = dict(step.capture_fields or {})
    data["timestamp_iso"] = now_iso()

    print("")
    print(f"--- STEP: {step.test_id} — {step.name} ---")
    print(f"Required: {step.required} | Points: {step.points} (min {step.min_points})")

    if not step.required:
        if _prompt_yes_no("Waive this step?", default=False):
            reason = _prompt_text("Waive reason (required)", None).strip()
            if not reason:
                reason = "Operator waived (no reason provided)"
            data["_waived"] = True
            data["_waive_reason"] = reason
            return data
        if _prompt_yes_no("Skip this step (no results captured)?", default=False):
            data["_skipped"] = True
            data["_skip_reason"] = _prompt_text("Skip reason", "Operator skipped")
            return data

    if step.test_id == "CYLINDER_META":
        data["instrument_id"] = _prompt_text("Instrument ID", data.get("instrument_id") or "")
        data["standard_units"] = _prompt_text("Standard units (ppm, %, etc.)", data.get("standard_units") or "")
        data["low_cylinder_id"] = _prompt_text("Low cylinder ID", data.get("low_cylinder_id") or "")
        data["low_expiration"] = _prompt_text("Low cylinder expiration (YYYY-MM-DD)", data.get("low_expiration") or "")
        data["low_concentration"] = _prompt_float("Low concentration", data.get("low_concentration"))
        data["high_cylinder_id"] = _prompt_text("High cylinder ID", data.get("high_cylinder_id") or "")
        data["high_expiration"] = _prompt_text("High cylinder expiration (YYYY-MM-DD)", data.get("high_expiration") or "")
        data["high_concentration"] = _prompt_float("High concentration", data.get("high_concentration"))
        data["notes"] = _prompt_text("Notes", data.get("notes") or "")

    elif step.test_id == "CAL":
        data["instrument_id"] = _prompt_text("Instrument ID", data.get("instrument_id") or "")
        data["standard_units"] = _prompt_text("Standard units (ppm, %, etc.)", data.get("standard_units") or "")
        data["low_cylinder_id"] = _prompt_text("Low cylinder ID", data.get("low_cylinder_id") or "")
        data["low_expiration"] = _prompt_text("Low cylinder expiration (YYYY-MM-DD)", data.get("low_expiration") or "")
        data["low_concentration"] = _prompt_float("Low concentration", data.get("low_concentration"))
        data["high_cylinder_id"] = _prompt_text("High cylinder ID", data.get("high_cylinder_id") or "")
        data["high_expiration"] = _prompt_text("High cylinder expiration (YYYY-MM-DD)", data.get("high_expiration") or "")
        data["high_concentration"] = _prompt_float("High concentration", data.get("high_concentration"))
        data["points_expected"] = int(_prompt_text("Calibration points expected", str(data.get("points_expected") or step.points or 2)))
        data["points_table"] = _prompt_text("Paste/enter points table (optional)", data.get("points_table") or "")
        data["pass"] = _prompt_yes_no("Calibration passed?", default=True)
        data["notes"] = _prompt_text("Notes", data.get("notes") or "")

    elif step.test_id == "LIN":
        data["instrument_id"] = _prompt_text("Instrument ID", data.get("instrument_id") or "")
        data["standard_units"] = _prompt_text("Standard units (ppm, %, etc.)", data.get("standard_units") or "")
        data["points_expected"] = int(_prompt_text("Linearity points expected", str(data.get("points_expected") or step.points or 2)))
        data["points_table"] = _prompt_text("Paste/enter points table (optional)", data.get("points_table") or "")
        data["acceptance_criteria"] = _prompt_text("Acceptance criteria (optional)", data.get("acceptance_criteria") or "")
        data["pass"] = _prompt_yes_no("Linearity passed?", default=True)
        data["notes"] = _prompt_text("Notes", data.get("notes") or "")

    else:
        data["instrument_id"] = _prompt_text("Instrument ID (optional)", data.get("instrument_id") or "")
        data["result"] = _prompt_text("Result (free text)", data.get("result") or "")
        data["notes"] = _prompt_text("Notes", data.get("notes") or "")

    return data

def _commit_step(session: Dict[str, Any], step: ExecStep, data: Dict[str, Any]) -> None:
    te = session["test_execution"]
    entry = {
        "step_id": step.step_id,
        "test_id": step.test_id,
        "name": step.name,
        "required": step.required,
        "min_points": step.min_points,
        "points": step.points,
        "status": step.status,
        "started_iso": step.data.get("started_iso"),
        "completed_iso": now_iso(),
        "data": data,
        "waive_reason": step.waive_reason,
    }
    te["steps"].append(entry)
    te["audit_trail"].append({"ts": now_iso(), "event": "STEP_COMMIT", "step_id": step.step_id, "status": step.status})

