# -----------------------------------------------------------------------------
# Countdown helpers (shared across timer splashes)
# -----------------------------------------------------------------------------

def _remaining_s(end_epoch: float) -> int:
    """Return remaining seconds (>=0) to an epoch deadline.

    Uses ceil() so all countdown displays stay visually aligned (no early -1).
    """
    try:
        import math
        now = time.time()
        return max(0, int(math.ceil(float(end_epoch) - float(now))))
    except Exception:
        try:
            return max(0, int(float(end_epoch) - time.time()))
        except Exception:
            return 0


def _next_tick_ms() -> int:
    """Schedule the next UI tick on the next wall-clock second boundary.

    This keeps multiple countdowns (panel + splash) in sync and reduces drift.
    """
    try:
        import math
        now = time.time()
        nxt = math.floor(now) + 1.0
        ms = int((nxt - now) * 1000.0)
        # clamp to a sane range
        if ms < 50:
            ms = 50
        elif ms > 1000:
            ms = 1000
        return ms
    except Exception:
        return 250

