@dataclass
class SiteConditionsActive:
    mode: str
    T_amb_F: float
    P_bar_psia: float
    RH_frac: float
    z: float
    source: str
    timestamp_iso: str


def _float(v: Any, default: float) -> float:
    try:
        if v is None:
            return float(default)
        return float(v)
    except Exception:
        return float(default)


def _site_std_defaults(session: Dict[str, Any]) -> Dict[str, float]:
    std = (session.get("site_conditions", {}) or {}).get("standard_conditions", {}) or {}
    return {
        "T_std_F": _float(std.get("T_std_F"), 60.0),
        "P_std_psia": _float(std.get("P_std_psia"), 14.696),
    }




def prompt_site_conditions_manual(session: Dict[str, Any]) -> SiteConditionsActive:
    """Return manual site conditions from session.site_conditions.manual_entry (non-interactive).

    The Wizard is responsible for collecting manual entry. The runner uses it deterministically.
    """
    sc = session.get("site_conditions") or {}
    me = sc.get("manual_entry") or {}
    if not isinstance(me, dict):
        me = {}

    T = me.get("T_amb_F")
    P = me.get("P_bar_psia")
    RH = me.get("RH_frac")
    z = me.get("z")

    if T is None or P is None:
        raise ConfigError("Manual site conditions selected but manual_entry is incomplete (need T_amb_F and P_bar_psia).")

    try:
        T_f = float(T)
    except Exception:
        raise ConfigError("Manual site conditions: T_amb_F must be numeric.")
    try:
        P_f = float(P)
    except Exception:
        raise ConfigError("Manual site conditions: P_bar_psia must be numeric.")

    try:
        RH_f = float(RH) if RH is not None else 0.0
    except Exception:
        RH_f = 0.0

    if z is None:
        z_f = _compute_z(session, T_f, P_f)
    else:
        try:
            z_f = float(z)
        except Exception:
            z_f = _compute_z(session, T_f, P_f)

    ts = me.get("timestamp_iso") or _now_iso()
    return SiteConditionsActive(
        mode="MANUAL",
        T_amb_F=float(T_f),
        P_bar_psia=float(P_f),
        RH_frac=float(RH_f),
        z=float(z_f),
        source="MANUAL_ENTRY",
        timestamp_iso=str(ts),
    )

# -------------------- NOAA/NWS Weather Fetch + Backfill --------------------

def _http_get_json(url: str, timeout_s: int = 12) -> Dict[str, Any]:
    headers = {
        "User-Agent": "MOLE-DAQ-RUNNER/5.7 (NOAA/NWS API)",
        "Accept": "application/geo+json, application/json;q=0.9,*/*;q=0.8",
    }
    req = urllib.request.Request(url, headers=headers)
    with urllib.request.urlopen(req, timeout=timeout_s) as resp:
        raw = resp.read().decode("utf-8", errors="replace")
    return json.loads(raw)


def _noaa_resolve_station_id(lat: float, lon: float) -> str:
    pts = _http_get_json(f"https://api.weather.gov/points/{lat:.6f},{lon:.6f}")
    stations_url = (pts.get("properties") or {}).get("observationStations")
    if not stations_url:
        raise RuntimeError("NOAA points response missing observationStations URL.")
    st = _http_get_json(stations_url)
    feats = st.get("features") or []
    if not feats:
        raise RuntimeError("NOAA station list is empty for the provided coordinates.")
    props0 = feats[0].get("properties") or {}
    sid = props0.get("stationIdentifier")
    if not sid:
        fid = feats[0].get("id") or ""
        sid = fid.split("/")[-1] if fid else ""
    if not sid:
        raise RuntimeError("Unable to resolve NOAA station identifier.")
    return sid


def _c_to_f(c: float) -> float:
    return (c * 9.0 / 5.0) + 32.0


def _pa_to_psia(pa: float) -> float:
    return pa / 6894.757293168


def _parse_iso(ts: str) -> datetime:
    # NWS often uses Z; datetime.fromisoformat expects +00:00
    ts = ts.strip()
    if ts.endswith("Z"):
        ts = ts[:-1] + "+00:00"
    return datetime.fromisoformat(ts)

def _parse_float(val, default=None):
    """Parse float from numeric/string inputs, allowing comma grouping.
    Returns default on failure."""
    try:
        if val is None:
            return default
        if isinstance(val, (int, float)):
            f = float(val)
            # NaN check
            if f != f:
                return default
            return f
        s = str(val).strip()
        if not s:
            return default
        sl = s.lower()
        if sl in ("n/a", "na", "none", "null", "nan"):
            return default
        s = s.replace(",", "")
        try:
            f = float(s)
        except Exception:
            import re as _re
            m = _re.search(r"[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?", s)
            if not m:
                return default
            f = float(m.group(0))
        if f != f:
            return default
        return f
    except Exception:
        return default




def _units_is_dry(units: str) -> bool:
    """Return True if the unit string implies a dry-basis measurement.

    Heuristics:
      - contains 'dry'
      - contains 'vd'/'dv' (ppmvd, ppbvd, etc.)
      - contains 'dscf' or 'dscm' (dry standard volume)
    """
    try:
        u = str(units or "").strip().lower()
        if not u:
            return False
        u2 = u.replace(" ", "")
        if "dry" in u2:
            return True
        # ppmvd / ppbvd / ppmdv style
        if "vd" in u2 or "dv" in u2:
            return True
        if "dscf" in u2 or "dscm" in u2:
            return True
        return False
    except Exception:
        return False


def _units_is_concentration(units: str) -> bool:
    """Return True if the unit string implies a concentration measurement.

    We use this to gate O2 correction. Do *not* O2-correct mass-rate / heat-rate / work-rate
    units like lb/MMBtu or g/bhp-hr.

    Allowed (examples): ppm, ppmvd, ppb, %, mg/m3
    Rejected (examples): lb/hr, lb/MMBtu, g/bhp-hr, scfh
    """
    try:
        u = str(units or "").strip().lower()
        if not u:
            return False
        u2 = u.replace(" ", "")

        # Common non-concentration unit families
        for bad in (
            "lb", "mmbtu", "bhp", "hp", "g/hp", "g/bhp", "lbhr", "lb/hr",
            "scfh", "scfm", "scfd", "acfm", "dscf", "dscm",
        ):
            if bad in u2:
                return False

        if "ppm" in u2 or "ppb" in u2:
            return True
        if "%" in u2 or "pct" in u2:
            return True
        if "mg/m3" in u2 or "mgm3" in u2 or "ug/m3" in u2 or "µg/m3" in u2:
            return True

        return False
    except Exception:
        return False


def _units_key(units: str) -> str:
    """Normalize a unit string for best-effort comparisons."""
    u = str(units or "").strip().lower()
    u = u.replace(" ", "")
    # Drop common basis markers
    for tok in ("(dry)", "(wet)", "dry", "wet", "vd", "dv"):
        u = u.replace(tok, "")
    u = u.replace("_", "")
    return u


def _units_compatible(units_obs: str, units_lim: str) -> bool:
    """Best-effort units compatibility check.

    We only use this for %limit display. Be permissive for common emissions units
    (ppm vs ppmvd, etc.), but avoid nonsense comparisons.
    """
    u1 = _units_key(units_obs)
    u2 = _units_key(units_lim)
    if not u1 or not u2:
        return False
    if u1 == u2:
        return True

    # ppm family
    if ("ppm" in u1) and ("ppm" in u2):
        return True
    # ppb family
    if ("ppb" in u1) and ("ppb" in u2):
        return True
    # percent family
    if ((u1.endswith("%") or "pct" in u1 or "percent" in u1) and (u2.endswith("%") or "pct" in u2 or "percent" in u2)):
        return True
    # lb/hr family
    if (("lb/hr" in u1 or "lbhr" in u1) and ("lb/hr" in u2 or "lbhr" in u2)):
        return True
    # g/bhp-hr family
    if (("g/bhp" in u1 or "gbhp" in u1) and ("g/bhp" in u2 or "gbhp" in u2)):
        return True

    return False


def _limit_o2_ref_pct(limit: Dict[str, Any]) -> Optional[float]:
    """Extract O2 reference percent from a limit record (if present)."""
    try:
        if not isinstance(limit, dict):
            return None
        for k in ("o2_ref_pct", "o2_ref", "o2"):
            v = _parse_float(limit.get(k))
            if v is not None:
                return float(v)
    except Exception:
        return None
    return None

def _hours_between_iso(ts0: str, ts1: str) -> Optional[float]:
    """Return (ts1 - ts0) in hours, or None if missing/unparseable."""
    if not ts0 or not ts1:
        return None
    try:
        dt0 = _parse_iso(str(ts0))
        dt1 = _parse_iso(str(ts1))
        delta_s = (dt1 - dt0).total_seconds()
        if delta_s <= 0:
            return None
        return float(delta_s) / 3600.0
    except Exception:
        return None


def _qaqc_health_from_ratio(ratio: Optional[float], hard_fail: bool = False) -> str:
    """PASS/WARN/FAIL from a dimensionless combined drift ratio."""
    if hard_fail:
        return "FAIL"
    if ratio is None:
        return "WARN"
    try:
        r = float(ratio)
    except Exception:
        return "WARN"
    if r <= 1.0:
        return "PASS"
    if r <= 1.5:
        return "WARN"
    return "FAIL"


def _qaqc_combined_ratio(
    drift_abs: Optional[float],
    drift_recovery_pct: Optional[float],
    tol_abs: Optional[float],
    tol_pct: Optional[float],
) -> Optional[float]:
    """RSS-combine normalized zero+span drift into a single ratio."""
    try:
        da = float(drift_abs) if drift_abs is not None else None
    except Exception:
        da = None
    try:
        dp = float(drift_recovery_pct) if drift_recovery_pct is not None else None
    except Exception:
        dp = None
    try:
        ta = float(tol_abs) if tol_abs is not None else None
    except Exception:
        ta = None
    try:
        tp = float(tol_pct) if tol_pct is not None else None
    except Exception:
        tp = None

    if (da is None and dp is None):
        return None
    nz = 0.0
    ns = 0.0
    if da is not None and ta and ta > 0:
        nz = abs(da) / ta
    if dp is not None and tp and tp > 0:
        ns = abs(dp) / tp
    # if tolerance missing, treat as unknown
    if (da is not None and (not ta or ta <= 0)) or (dp is not None and (not tp or tp <= 0)):
        return None
    return float((nz * nz + ns * ns) ** 0.5)


def _masterdb_dyn_open(db_path: str) -> Optional[Any]:
    """Best-effort open of MoleMasterDB (dynamic import)."""
    try:
        base = _app_base_dir()
        repo_py = base / "mole_master_db_repo_v1.py"
        if not repo_py.exists():
            return None
        spec = importlib.util.spec_from_file_location("mole_master_db_repo_v1", str(repo_py))
        if spec is None or spec.loader is None:
            return None
        mod = importlib.util.module_from_spec(spec)
        import sys
        sys.modules[spec.name] = mod
        spec.loader.exec_module(mod)  # type: ignore

        schema_path = base / "mole_db_schema_v1.sql"
        schema_sql = ""
        try:
            if schema_path.exists():
                schema_sql = schema_path.read_text(encoding="utf-8")
        except Exception:
            schema_sql = ""

        db = mod.MoleMasterDB(mod.MoleDBConfig(db_path=Path(db_path)))
        # Ensure schema v2 (idempotent IF NOT EXISTS)
        if schema_sql:
            try:
                mod.ensure_schema(db.con, schema_sql, target_version=2)
            except Exception:
                pass
        return db
    except Exception:
        return None


def _persist_qaqc_trending_events(session: Dict[str, Any], run_no: int, prun: Dict[str, Any]) -> None:
    """Persist PRE/POST cal events to master DB for trending (best-effort)."""
    if _diagnostics_ui_active(session):
        return
    qa = session.get("qa_qc") or {}
    if not bool(qa.get("persist_cal_to_master_db", False)):
        return
    if prun.get("_persisted_master_db"):
        return

    db_path = ((session.get("paths") or {}).get("db_path") or "").strip()
    if not db_path:
        return

    db = _masterdb_dyn_open(db_path)
    if db is None:
        return

    try:
        proj = session.get("project") or {}
        src = session.get("source") or {}
        det = session.get("source_details") or {}
        site_id = str(proj.get("job_id") or "")
        location_id = str(proj.get("asset_unit_id") or "")
        source_category = str(src.get("source_category") or det.get("source_category") or "")

        manufacturer = str(det.get("manufacturer") or src.get("manufacturer") or "")
        model_number = str(det.get("model_number") or src.get("model_number") or "")
        serial_number = str(det.get("serial_number") or src.get("serial_number") or "")
        asset_tag = str(det.get("asset_tag") or src.get("asset_tag") or "")
        manufacture_date = str(det.get("manufacture_date") or src.get("manufacture_date") or "")
        install_date = str(det.get("install_date") or src.get("install_date") or "")

        # Prefer explicit session binding when provided (v10.0.9)
        instance_id = None
        try:
            raw_iid = det.get("instance_id") if isinstance(det, dict) else None
            if raw_iid in (None, "", 0) and isinstance(src, dict):
                raw_iid = src.get("instance_id")
            if raw_iid not in (None, "", 0):
                try:
                    instance_id = int(raw_iid)
                except Exception:
                    instance_id = None
        except Exception:
            instance_id = None

        # Resolve/ensure instance_id if we have minimally identifying fields
        if instance_id is None:
            try:
                if site_id and location_id and source_category and (manufacturer or model_number or serial_number):
                    up = db.upsert_instance(
                        site_id=site_id,
                        location_id=location_id,
                        source_category=source_category or "Other",
                        manufacturer=manufacturer,
                        model_number=model_number,
                        serial_number=serial_number,
                        asset_tag=asset_tag,
                        manufacture_date=manufacture_date,
                        install_date=install_date,
                    ) or {}
                    instance_id = up.get("instance_id") or up.get("instance_id".upper())
                    try:
                        instance_id = int(instance_id) if instance_id is not None else None
                    except Exception:
                        instance_id = None
            except Exception:
                instance_id = None

        run_id = session.get("run_id")

        # Payloads exist under prun["zero"]/["span"] and ["postcal"]["zero"/"span"]
        pre_zero = (prun.get("zero") or {})
        pre_span = (prun.get("span") or {})
        post = (prun.get("postcal") or {})
        post_zero = (post.get("zero") or {})
        post_span = (post.get("span") or {})

        health_by = prun.get("health_by_channel") or {}
        comb_by = prun.get("combined_drift_ratio") or {}

        for pollutant in sorted(set(list(pre_zero.keys()) + list(pre_span.keys()) + list(post_zero.keys()) + list(post_span.keys()))):
            # PRE ZERO
            z = pre_zero.get(pollutant) or {}
            if z.get("ts_iso"):
                db.insert_qaqc_cal_event({
                    "event_iso": z.get("ts_iso"),
                    "phase": "PRE",
                    "pollutant": pollutant,
                    "event_type": "ZERO",
                    "meas": z.get("meas"),
                    "target": z.get("target"),
                    "pass": z.get("pass"),
                    "tol_abs": z.get("tol_abs"),
                    "run_id": run_id,
                    "run_no": run_no,
                    "site_id": site_id,
                    "location_id": location_id,
                    "source_category": source_category,
                    "manufacturer": manufacturer,
                    "model_number": model_number,
                    "serial_number": serial_number,
                    "instance_id": instance_id,
                })

            # PRE SPAN
            s = pre_span.get(pollutant) or {}
            if s.get("ts_iso"):
                db.insert_qaqc_cal_event({
                    "event_iso": s.get("ts_iso"),
                    "phase": "PRE",
                    "pollutant": pollutant,
                    "event_type": "SPAN",
                    "meas": s.get("meas"),
                    "target": s.get("target"),
                    "recovery_pct": s.get("recovery_pct"),
                    "pass": s.get("pass"),
                    "tol_pct": s.get("tol_pct"),
                    "run_id": run_id,
                    "run_no": run_no,
                    "site_id": site_id,
                    "location_id": location_id,
                    "source_category": source_category,
                    "manufacturer": manufacturer,
                    "model_number": model_number,
                    "serial_number": serial_number,
                    "instance_id": instance_id,
                })

            # POST ZERO (includes drift info)
            pz = post_zero.get(pollutant) or {}
            if pz.get("ts_iso"):
                db.insert_qaqc_cal_event({
                    "event_iso": pz.get("ts_iso"),
                    "phase": "POST",
                    "pollutant": pollutant,
                    "event_type": "ZERO",
                    "meas": pz.get("meas"),
                    "target": pz.get("target"),
                    "pass": pz.get("pass"),
                    "tol_abs": pz.get("tol_abs"),
                    "drift_abs": pz.get("drift_abs"),
                    "drift_rate_abs_per_hr": pz.get("drift_rate_abs_per_hr"),
                    "combined_drift_ratio": comb_by.get(pollutant),
                    "health": health_by.get(pollutant),
                    "run_id": run_id,
                    "run_no": run_no,
                    "site_id": site_id,
                    "location_id": location_id,
                    "source_category": source_category,
                    "manufacturer": manufacturer,
                    "model_number": model_number,
                    "serial_number": serial_number,
                    "instance_id": instance_id,
                })

            # POST SPAN
            ps = post_span.get(pollutant) or {}
            if ps.get("ts_iso"):
                db.insert_qaqc_cal_event({
                    "event_iso": ps.get("ts_iso"),
                    "phase": "POST",
                    "pollutant": pollutant,
                    "event_type": "SPAN",
                    "meas": ps.get("meas"),
                    "target": ps.get("target"),
                    "recovery_pct": ps.get("recovery_pct"),
                    "pass": ps.get("pass"),
                    "tol_pct": ps.get("tol_pct"),
                    "drift_recovery_pct": ps.get("drift_recovery_pct"),
                    "drift_rate_recovery_pct_per_hr": ps.get("drift_rate_recovery_pct_per_hr"),
                    "combined_drift_ratio": comb_by.get(pollutant),
                    "health": health_by.get(pollutant),
                    "run_id": run_id,
                    "run_no": run_no,
                    "site_id": site_id,
                    "location_id": location_id,
                    "source_category": source_category,
                    "manufacturer": manufacturer,
                    "model_number": model_number,
                    "serial_number": serial_number,
                    "instance_id": instance_id,
                })
    except Exception:
        # best-effort only
        pass
    finally:
        try:
            db.close()
        except Exception:
            pass

    prun["_persisted_master_db"] = True



def _noaa_latest_observation(station_id: str) -> Dict[str, Any]:
    obs = _http_get_json(f"https://api.weather.gov/stations/{station_id}/observations/latest")
    props = obs.get("properties") or {}

    def _val(node: Any) -> Optional[float]:
        return node.get("value") if isinstance(node, dict) else None

    temp_c = _val(props.get("temperature"))
    rh_pct = _val(props.get("relativeHumidity"))
    p_pa = _val(props.get("barometricPressure"))
    if p_pa is None:
        p_pa = _val(props.get("seaLevelPressure"))
    if p_pa is None:
        p_pa = _val(props.get("altimeter"))

    if temp_c is None or p_pa is None or rh_pct is None:
        raise RuntimeError("NOAA observation missing temperature/pressure/RH fields.")

    ts = props.get("timestamp") or _now_iso()
    return {
        "station_id": station_id,
        "timestamp_iso": str(ts),
        "T_amb_F": round(_c_to_f(float(temp_c)), 3),
        "P_bar_psia": round(_pa_to_psia(float(p_pa)), 6),
        "RH_frac": round(float(rh_pct) / 100.0, 6),
    }


def _noaa_observations_range(station_id: str, start_iso: str, end_iso: str) -> List[Dict[str, Any]]:
    # Query observations in a time range for backfill.
    # NOTE: API may paginate; for typical short ranges (hours) this is usually sufficient.
    url = f"https://api.weather.gov/stations/{station_id}/observations?start={start_iso}&end={end_iso}"
    j = _http_get_json(url)
    feats = j.get("features") or []
    out: List[Dict[str, Any]] = []
    for f in feats:
        props = (f.get("properties") or {})
        ts = props.get("timestamp")
        if not ts:
            continue

        def _val(node: Any) -> Optional[float]:
            return node.get("value") if isinstance(node, dict) else None

        temp_c = _val(props.get("temperature"))
        rh_pct = _val(props.get("relativeHumidity"))
        p_pa = _val(props.get("barometricPressure"))
        if p_pa is None:
            p_pa = _val(props.get("seaLevelPressure"))
        if p_pa is None:
            p_pa = _val(props.get("altimeter"))
        if temp_c is None or rh_pct is None or p_pa is None:
            continue
        out.append(
            {
                "timestamp_iso": str(ts),
                "T_amb_F": round(_c_to_f(float(temp_c)), 3),
                "P_bar_psia": round(_pa_to_psia(float(p_pa)), 6),
                "RH_frac": round(float(rh_pct) / 100.0, 6),
            }
        )
    return out


def _compute_z(session: Dict[str, Any], T_amb_F: float, P_bar_psia: float) -> float:
    sc = session.get("site_conditions") or {}
    z_model = _normalize_z_model(sc.get("z_model"))
    if isinstance(sc, dict):
        sc["z_model"] = z_model
    if z_model == "FIXED_Z":
        try:
            return float(sc.get("fixed_z") or 1.0)
        except Exception:
            return 1.0
    # This runtime supports only IDEAL and FIXED_Z.
    return 1.0


def fetch_site_conditions_stub(session: Dict[str, Any]) -> Tuple[bool, Optional[SiteConditionsActive], str]:
    """
    Fetch live site conditions from NOAA/NWS station observations.

    Returns:
        ok: bool
        active: SiteConditionsActive | None
        err: str

    Notes:
    - Uses session.site_conditions.location.lat/lon to resolve a station (unless station_id is provided).
    - Caches station_id into session.site_conditions.weather_compile.station_id when resolved.
    """
    sc = session.get("site_conditions") or {}
    wc = sc.get("weather_compile") or {}
    station_id = wc.get("station_id")
    loc = sc.get("location") or {}
    lat = loc.get("lat")
    lon = loc.get("lon")

    try:
        if not station_id:
            if lat is None or lon is None:
                return False, None, "Missing site_conditions.location lat/lon and no station_id provided."
            station_id = _noaa_resolve_station_id(float(lat), float(lon))
            if not isinstance(wc, dict):
                wc = {}
                sc["weather_compile"] = wc
            wc["station_id"] = station_id
            session["site_conditions"] = sc

        wx = _noaa_latest_observation(str(station_id))
        z = _compute_z(session, wx["T_amb_F"], wx["P_bar_psia"])
        active = SiteConditionsActive(
            mode="AUTO_WEATHER",
            T_amb_F=wx["T_amb_F"],
            P_bar_psia=wx["P_bar_psia"],
            RH_frac=wx["RH_frac"],
            z=z,
            source=f"NOAA:{station_id}",
            timestamp_iso=wx["timestamp_iso"],
        )
        return True, active, ""
    except Exception as e:
        return False, None, str(e)

class WeatherCompiler:
    """
    Writes a deterministic weather stream for compliance records.

    - When enabled, logs weather observations to weather.jsonl at a fixed interval.
    - If a fetch fails, records the requested timestamp to weather_pending.json.
    - When connectivity returns, backfills missing intervals using station observation history.
    """

    def __init__(
        self,
        *,
        enabled: bool,
        interval_s: float,
        weather_path: Path,
        pending_path: Path,
        session: Dict[str, Any],
    ) -> None:
        self.enabled = bool(enabled)
        self.interval_s = float(interval_s)
        self.weather_path = weather_path
        self.pending_path = pending_path
        self.session = session

        self._last_attempt_monotonic: float = 0.0
        self._pending: List[str] = self._load_pending()

        # Ensure files exist
        self.weather_path.parent.mkdir(parents=True, exist_ok=True)
        if not self.weather_path.exists():
            self.weather_path.write_text("", encoding="utf-8")

    def _load_pending(self) -> List[str]:
        try:
            if self.pending_path.exists():
                data = json.loads(self.pending_path.read_text(encoding="utf-8"))
                if isinstance(data, list):
                    return [str(x) for x in data]
        except Exception:
            pass
        return []

    def _save_pending(self) -> None:
        try:
            self.pending_path.write_text(json.dumps(self._pending, indent=2), encoding="utf-8")
        except Exception:
            # do not fail the run for pending serialization
            pass

    def _append_jsonl(self, rec: Dict[str, Any]) -> None:
        with open(self.weather_path, "a", encoding="utf-8") as f:
            f.write(json.dumps(rec, ensure_ascii=False) + "\n")

    def record_site(self, site: SiteConditionsActive, *, kind: str = "LIVE", requested_ts_iso: Optional[str] = None, note: Optional[str] = None) -> None:
        rec = {
            "kind": kind,
            "requested_ts_iso": requested_ts_iso,
            "obs_ts_iso": site.timestamp_iso,
            "source": site.source,
            "T_amb_F": site.T_amb_F,
            "P_bar_psia": site.P_bar_psia,
            "RH_frac": site.RH_frac,
            "z": site.z,
            "note": note,
        }
        self._append_jsonl(rec)

    def record_failure(self, requested_ts_iso: str, err: str) -> None:
        rec = {"kind": "FAIL", "requested_ts_iso": requested_ts_iso, "err": err}
        self._append_jsonl(rec)
        self._pending.append(str(requested_ts_iso))
        # de-dup (preserve order)
        seen = set()
        self._pending = [x for x in self._pending if (x not in seen and not seen.add(x))]
        self._save_pending()

    def _station_id(self) -> Optional[str]:
        sc = self.session.get("site_conditions") or {}
        wc = sc.get("weather_compile") or {}
        sid = wc.get("station_id")
        return str(sid) if sid else None

    def maybe_poll(self) -> None:
        if not self.enabled:
            return

        now_m = time.monotonic()
        if (now_m - self._last_attempt_monotonic) < self.interval_s:
            return
        self._last_attempt_monotonic = now_m

        req_ts = _now_iso()
        ok, site, err = fetch_site_conditions_stub(self.session)
        if ok:
            self.record_site(site, kind="LIVE", requested_ts_iso=req_ts)
            self.try_backfill()
        else:
            self.record_failure(req_ts, err or "NOAA fetch failed")

    def try_backfill(self) -> None:
        if not self.enabled:
            return
        if not self._pending:
            return

        sid = self._station_id()
        if not sid:
            return

        # Build a reasonable query window around pending timestamps
        try:
            dts = [_parse_iso(ts) for ts in self._pending]
        except Exception:
            return

        start_dt = min(dts) - timedelta(minutes=30)
        end_dt = max(dts) + timedelta(minutes=30)
        start_iso = start_dt.isoformat()
        end_iso = end_dt.isoformat()

        try:
            obs = _noaa_observations_range(sid, start_iso, end_iso)
            if not obs:
                return
        except Exception:
            return

        # Parse observations into (dt, rec)
        obs_dt: List[Tuple[datetime, Dict[str, Any]]] = []
        for r in obs:
            try:
                obs_dt.append((_parse_iso(r["timestamp_iso"]), r))
            except Exception:
                continue
        if not obs_dt:
            return

        # For each pending timestamp, find nearest observation within 30 minutes
        new_pending: List[str] = []
        for req_ts in list(self._pending):
            try:
                req_dt = _parse_iso(req_ts)
            except Exception:
                new_pending.append(req_ts)
                continue

            best = None
            best_delta = None
            for odt, r in obs_dt:
                delta = abs((odt - req_dt).total_seconds())
                if best is None or (best_delta is not None and delta < best_delta):
                    best = (odt, r)
                    best_delta = delta
            if best is None or best_delta is None or best_delta > (2 * 60 * 60):
                new_pending.append(req_ts)
                continue

            odt, r = best
            # Synthesize a SiteConditionsActive for logging
            site = SiteConditionsActive(
                mode="AUTO_WEATHER",
                source=f"NOAA:{sid}",
                timestamp_iso=r["timestamp_iso"],
                T_amb_F=r["T_amb_F"],
                P_bar_psia=r["P_bar_psia"],
                RH_frac=r["RH_frac"],
                z=_compute_z(self.session, r["T_amb_F"], r["P_bar_psia"]),
            )
            self.record_site(site, kind="BACKFILL", requested_ts_iso=req_ts, note="Recovered via history endpoint")

        self._pending = new_pending
        self._save_pending()


