class IAcqDriver(Protocol):
    """Acquisition driver contract.

    The DAQ Runner must be instrument-agnostic. Drivers return a flat frame dict
    with at least:
      - ts_iso: ISO timestamp string
      - comm_ok: bool (best-effort)
    and any number of channel keys (pollutants, temps, pressures, etc).
    """

    name: str

    def connect(self) -> None: ...
    def close(self) -> None: ...
    def read_all(self) -> Dict[str, Any]: ...


def _driver_spec_from_session(session: Dict[str, Any]) -> Any:
    # Accept either a string or a dict
    if isinstance(session.get("daq_driver"), (str, dict)):
        return session.get("daq_driver")
    daq = session.get("daq") or {}
    if isinstance(daq, dict) and isinstance(daq.get("driver"), (str, dict)):
        return daq.get("driver")
    return None


def _driver_type_from_spec(spec: Any, default_type: str) -> str:
    if isinstance(spec, str) and spec.strip():
        return spec.strip().upper()
    if isinstance(spec, dict):
        for k in ("type", "name", "driver", "id"):
            v = spec.get(k)
            if isinstance(v, str) and v.strip():
                return v.strip().upper()
    return default_type


def _resolve_driver_path(py_path: str) -> Path:
    p = Path(py_path)
    if p.is_absolute():
        return p
    # Prefer app base dir (works in frozen + dev)
    base = _app_base_dir()
    cand = (base / p).resolve()
    if cand.exists():
        return cand
    # Next try: relative to this file
    try:
        here = Path(__file__).resolve().parent
        cand2 = (here / p).resolve()
        if cand2.exists():
            return cand2
    except Exception:
        pass
    return p.resolve()


def _load_driver_from_py(py_path: str, factory_name: str, session: Dict[str, Any]) -> Optional[IAcqDriver]:
    """Optional plugin loader.

    spec example in session JSON:
      "daq_driver": {"type":"PY", "py_path":"drivers/mole_modbus_driver.py", "factory":"create_driver"}

    Factory must return an object matching IAcqDriver.
    """
    try:
        p = _resolve_driver_path(py_path)
        if not p.exists():
            return None
        mod_name = f"mole_driver_{p.stem}"
        spec = importlib.util.spec_from_file_location(mod_name, str(p))
        if spec is None or spec.loader is None:
            return None
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)  # type: ignore[attr-defined]
        fn = getattr(mod, factory_name, None)
        if not callable(fn):
            return None
        drv = fn(session)
        return drv  # type: ignore[return-value]
    except Exception:
        return None


class UIDummyDriver:
    """UI-friendly dummy driver that emits stable values per selected pollutant."""

    name = "UI_DUMMY"

    def __init__(self, poll_codes: Sequence[str], pres: Dict[str, Dict[str, Any]]):
        self._t0 = time.time()
        self._poll_codes = list(poll_codes)
        self._pres = pres or {}

    def connect(self) -> None:
        return

    def close(self) -> None:
        return

    def read_all(self) -> Dict[str, Any]:
        t = time.time() - self._t0
        out: Dict[str, Any] = {"ts_iso": _now_iso(), "comm_ok": True}
        for i, code in enumerate(self._poll_codes):
            p = self._pres.get(code) or {}
            vmax = p.get("expected_max")
            try:
                vmax_f = float(vmax) if vmax not in (None, "", 0) else 100.0
            except Exception:
                vmax_f = 100.0
            base = 0.30 + 0.25 * math.sin(0.23 * t + (i * 0.7))
            jitter = random.uniform(-0.015, 0.015)
            val = max(0.0, (base + jitter) * vmax_f)
            out[code] = round(val, 3)

        # Convenience channels
        if "O2" not in out:
            out["O2"] = round(6.0 + 1.25 * math.sin(0.11 * t), 3)
        if "CO2" not in out:
            out["CO2"] = round(8.5 + 0.75 * math.sin(0.09 * t + 1.0), 3)

        return out



def build_driver(
    session: Dict[str, Any],
    *,
    ui: bool = False,
    poll_codes: Optional[Sequence[str]] = None,
    prescriptions: Optional[Dict[str, Dict[str, Any]]] = None,
) -> IAcqDriver:
    """Factory for acquisition drivers.

    Defaults:
      - UI mode: UI_DUMMY
      - headless mode: DUMMY

    Supports plugin drivers via:
      daq_driver: {"type":"PY", "py_path":"...", "factory":"create_driver"}

    Training mode:
      - FORCE simulation-only driver (SIM_TRAINING)
      - BLOCK plugin / hardware drivers (functional separation from production test system)
    """
    default_type = "UI_DUMMY" if ui else "DUMMY"
    spec = _driver_spec_from_session(session)
    dtype = _driver_type_from_spec(spec, default_type)

    env = _mole_env_mode(session)

    # Enforce sandboxed training environment (simulation-only)
    if env == "TRAINING":
        dtype = "SIM_TRAINING"

    # Plugin driver (disabled in training)
    if env != "TRAINING" and dtype in ("PY", "PLUGIN", "CUSTOM") and isinstance(spec, dict):
        py_path = str(spec.get("py_path") or spec.get("path") or "")
        factory_name = str(spec.get("factory") or "create_driver")
        if py_path.strip():
            drv = _load_driver_from_py(py_path, factory_name, session)
            if drv is not None:
                return drv

    # Built-in mapped Modbus driver: uses pollutant comm settings + active hardware profile.
    if env != "TRAINING" and mole_modbus_acq_driver is not None:
        try:
            allow_mapped = spec is None or dtype in (
                "",
                "AUTO",
                "UI_DUMMY",
                "DUMMY_UI",
                "UI",
                "DUMMY",
                "MODBUS_MAPPED",
                "MOLE_MAPPED_COMM",
                "COMM",
            )
            if allow_mapped:
                drv = mole_modbus_acq_driver.maybe_build_mapped_comm_driver(
                    session,
                    poll_codes=poll_codes,
                    prescriptions=prescriptions,
                )
                if drv is not None:
                    return drv
        except Exception:
            pass

    # Built-in drivers

    # Built-in SIM_TRAINING (interactive, workstep-driven)
    if dtype in ("SIM_TRAINING", "TRAINING_SIM", "TRAINING"):
        sim = {}
        if isinstance(spec, dict):
            sim = spec.get("sim") or spec
        else:
            sim = (session.get("daq") or {}).get("sim") or {}

        seed = sim.get("seed", 1337)
        dt_s = sim.get("dt_s", 1.0)
        base_ts_iso = sim.get("base_ts_iso", "2020-01-01T00:00:00Z")
        faults = sim.get("faults") or {}

        poll = (session.get("pollutants") or {})
        codes = list(poll_codes or []) or list(poll.get("selected") or [])
        pres = prescriptions or (poll.get("prescriptions") or {})

        scenario = build_sim_training_scenario(session, codes=codes, prescriptions=pres)
        drv = SimTrainingDriver(codes, pres, scenario=scenario, seed=seed, dt_s=dt_s, base_ts_iso=base_ts_iso, faults=faults)
        try:
            if _diagnostics_ui_active(session):
                drv.prime_mode("SAMPLE")
        except Exception:
            pass
        return drv

    # Built-in SIM (deterministic)
    if dtype in ("SIM", "SIMULATOR"):
        sim = {}
        if isinstance(spec, dict):
            sim = spec.get("sim") or spec
        else:
            sim = (session.get("daq") or {}).get("sim") or {}

        seed = sim.get("seed", 1337)
        dt_s = sim.get("dt_s", 1.0)
        base_ts_iso = sim.get("base_ts_iso", "2020-01-01T00:00:00Z")
        faults = sim.get("faults") or {}
        profile = str(sim.get("profile") or sim.get("sim_profile") or "ENGINE_TRANSIENT").strip().upper()
        profile_params = sim.get("profile_params") or sim.get("params") or {}

        poll = (session.get("pollutants") or {})
        codes = list(poll_codes or []) or list(poll.get("selected") or [])
        pres = prescriptions or (poll.get("prescriptions") or {})
        return SimDriver(codes, pres, seed=seed, dt_s=dt_s, base_ts_iso=base_ts_iso, profile=profile, profile_params=profile_params, faults=faults)

    if dtype in ("UI_DUMMY", "DUMMY_UI", "UI"):
        return UIDummyDriver(poll_codes or [], prescriptions or {})  # type: ignore[return-value]

    # Fallback
    return DummyDriver()  # type: ignore[return-value]


# -------------------------
# SIM Driver (deterministic)
# -------------------------
import math
import random
import hashlib

def _seed_to_int(seed: object) -> int:
    """Stable mapping for int/str/None -> int seed."""
    if seed is None:
        return 1337
    if isinstance(seed, int):
        return int(seed)
    s = str(seed).encode("utf-8", errors="ignore")
    h = hashlib.sha256(s).digest()
    return int.from_bytes(h[:8], "big", signed=False)

def _parse_iso_z(s: str) -> datetime:
    """Parse ISO string; accept trailing 'Z'. Always returns tz-aware UTC."""
    from datetime import timezone
    ss = (s or "").strip()
    if not ss:
        return datetime(2020, 1, 1, tzinfo=timezone.utc)
    if ss.endswith("Z"):
        ss = ss[:-1] + "+00:00"
    try:
        dt = datetime.fromisoformat(ss)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except Exception:
        return datetime(2020, 1, 1, tzinfo=timezone.utc)

class SimDriver:
    """Deterministic simulator driver for end-to-end testing, demos, and regression runs.

    Profiles (select via sim.profile or --sim-profile):
      - ENGINE_TRANSIENT: fast load steps + transient spikes (good for engines/CI control demos)
      - BOILER_STEADY: slow ramps + tight noise (good for boilers/heaters)
      - FLARE_SPIKY: low baseline + intermittent spikes (good for flare instability)
      - CAL_CYCLE: structured zero/span plateaus bracketing a short transient test window
    Fault injection (optional):
      - dropout_every: every Nth sample returns comm_ok=False and omits channels
      - stuck_after: after N samples, freezes channel values
      - drift_per_k: additive drift per sample (engineering units)
    """

    name = "SIM"

    def __init__(
        self,
        poll_codes: Sequence[str],
        prescriptions: Dict[str, Dict[str, Any]],
        *,
        seed: object = 1337,
        dt_s: float = 1.0,
        base_ts_iso: str = "2020-01-01T00:00:00Z",
        profile: str = "ENGINE_TRANSIENT",
        profile_params: Optional[Dict[str, Any]] = None,
        faults: Optional[Dict[str, Any]] = None,
    ) -> None:
        self._poll_codes = [str(x).strip().upper() for x in (poll_codes or []) if str(x).strip()]
        self._pres = prescriptions or {}
        self._seed = _seed_to_int(seed)
        self._rng = random.Random(self._seed)
        self._n = 0
        self._dt = float(dt_s or 1.0)
        self._t0 = _parse_iso_z(base_ts_iso)
        self._faults = faults or {}

        self._profile = str(profile or "ENGINE_TRANSIENT").strip().upper()
        self._pp = profile_params or {}

        # phases for any "fallback" channels
        self._phase = {c: self._rng.uniform(0.0, 6.283185307) for c in self._poll_codes}

        # Fault toggles
        self._dropout_every = int(self._faults.get("dropout_every", 0) or 0)
        self._stuck_after = int(self._faults.get("stuck_after", -1) or -1)
        self._drift_per_k = float(self._faults.get("drift_per_k", 0.0) or 0.0)
        self._stuck_values: Dict[str, float] = {}

        # Load state (shared across channels for realistic correlations)
        _il = self._pp.get("initial_load", None)
        try:
            _il_f = float(_il) if _il is not None else None
        except Exception:
            _il_f = None
        self._load = float(_il_f) if _il_f is not None else float(self._rng.uniform(0.25, 0.65))
        self._target = self._load
        self._next_step_t = 0.0

        # flare spike scheduler
        self._flare_in_spike = False
        self._flare_spike_end_t = 0.0
        self._flare_next_spike_t = self._rng.uniform(6.0, 18.0)

        # Ensure first step happens quickly
        self._schedule_next_target(t=0.0)

    def connect(self) -> None:
        return

    def close(self) -> None:
        return

    def _ts_iso(self) -> str:
        from datetime import timezone
        dt = self._t0 + timedelta(seconds=self._n * self._dt)
        dt = dt.astimezone(timezone.utc)
        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

    @staticmethod
    def _clamp(x: float, lo: float, hi: float) -> float:
        return lo if x < lo else (hi if x > hi else x)

    def _schedule_next_target(self, t: float) -> None:
        """Deterministically schedule the next load target based on profile."""
        p = self._profile

        if p == "BOILER_STEADY":
            dur = self._rng.uniform(18.0, 60.0)
            self._target = self._rng.uniform(0.45, 0.95)
            self._next_step_t = t + dur
            return

        if p == "FLARE_SPIKY":
            # baseline only; spikes handled separately
            self._target = self._rng.uniform(0.02, 0.08)
            self._next_step_t = t + self._rng.uniform(10.0, 30.0)
            return

        if p == "CAL_CYCLE":
            # CAL_CYCLE defines phase behavior by time; target used for embedded transient window
            self._target = self._rng.uniform(0.35, 0.85)
            self._next_step_t = t + self._rng.uniform(4.0, 12.0)
            return

        # default: ENGINE_TRANSIENT
        dur = self._rng.uniform(4.0, 14.0)
        # occasional big swings
        if self._rng.random() < 0.18:
            self._target = self._rng.choice([self._rng.uniform(0.15, 0.30), self._rng.uniform(0.80, 1.00)])
        else:
            self._target = self._rng.uniform(0.20, 0.98)
        self._next_step_t = t + dur

    def _update_load(self, t: float) -> tuple[float, str]:
        """Return (load, phase_label)."""
        p = self._profile

        if p == "CAL_CYCLE":
            # 0-25s: ZERO; 25-50s: SPAN; 50-110s: TEST; 110-135s: POST_ZERO; 135-160s: POST_SPAN
            if t < 25.0:
                return 0.0, "CAL_ZERO_PRE"
            if t < 50.0:
                return 1.0, "CAL_SPAN_PRE"
            if t < 110.0:
                # embedded transient test window
                if t >= self._next_step_t:
                    self._schedule_next_target(t)
                tau = self._pp.get("tau_s", None)
                try:
                    tau = float(tau) if tau is not None else float(3.0)
                except Exception:
                    tau = float(3.0)
                alpha = self._dt / max(1e-6, tau)
                self._load += (self._target - self._load) * self._clamp(alpha, 0.0, 1.0)
                return self._clamp(self._load, 0.0, 1.0), "TEST"
            if t < 135.0:
                return 0.0, "CAL_ZERO_POST"
            if t < 160.0:
                return 1.0, "CAL_SPAN_POST"
            # after cycle, settle into a steady mid-load
            return 0.55, "POST"

        if p == "FLARE_SPIKY":
            baseline = self._clamp(self._target, 0.0, 0.15)

            # schedule spikes deterministically
            if self._flare_in_spike and t >= self._flare_spike_end_t:
                self._flare_in_spike = False
                self._flare_next_spike_t = t + self._rng.uniform(8.0, 22.0)

            if (not self._flare_in_spike) and t >= self._flare_next_spike_t:
                self._flare_in_spike = True
                spike_dur = self._rng.uniform(1.0, 4.0)
                self._flare_spike_end_t = t + spike_dur

            if t >= self._next_step_t:
                self._schedule_next_target(t)

            if self._flare_in_spike:
                spike = self._rng.uniform(0.55, 0.95)
                return spike, "SPIKE"
            return baseline, "BASE"

        if p == "BOILER_STEADY":
            if t >= self._next_step_t:
                self._schedule_next_target(t)
            tau = self._pp.get("tau_s", None)
            try:
                tau = float(tau) if tau is not None else float(18.0)
            except Exception:
                tau = float(18.0)
            alpha = self._dt / max(1e-6, tau)
            self._load += (self._target - self._load) * self._clamp(alpha, 0.0, 1.0)
            return self._clamp(self._load, 0.0, 1.0), "STEADY"

        # ENGINE_TRANSIENT
        if t >= self._next_step_t:
            self._schedule_next_target(t)
        tau = self._pp.get("tau_s", None)
        try:
            tau = float(tau) if tau is not None else float(2.2)
        except Exception:
            tau = float(2.2)
        alpha = self._dt / max(1e-6, tau)
        self._load += (self._target - self._load) * self._clamp(alpha, 0.0, 1.0)
        return self._clamp(self._load, 0.0, 1.0), "TRANSIENT"

    def _expected_max(self, code: str, default: float) -> float:
        p = self._pres.get(code) or {}
        vmax = p.get("expected_max", None)
        try:
            vmax_f = float(vmax) if vmax not in (None, "", 0) else float(default)
        except Exception:
            vmax_f = float(default)
        return max(1e-9, vmax_f)

    def _maybe_transient_spike(self, prob: float, mag: float) -> float:
        # deterministic spikes to mimic combustion hiccups / sampling disturbances
        if self._rng.random() < prob:
            return self._rng.uniform(0.0, mag)
        return 0.0

    def read_all(self) -> Dict[str, Any]:
        self._n += 1

        # Dropout fault: comm false; no channel data
        if self._dropout_every > 0 and (self._n % self._dropout_every == 0):
            return {
                "ts_iso": self._ts_iso(),
                "comm_ok": False,
                "diag_fault": "DROPOUT",
                "diag_n": self._n,
                "diag_profile": self._profile,
            }

        t = self._n * self._dt
        out: Dict[str, Any] = {"ts_iso": self._ts_iso(), "comm_ok": True, "diag_n": self._n, "diag_profile": self._profile}

        # stuck
        stuck_mode = (self._stuck_after >= 0 and self._n >= self._stuck_after)

        load, phase = self._update_load(t)
        out["diag_load"] = round(float(load), 4)
        out["diag_phase"] = phase

        # Core correlated signals
        base_noise = self._rng.uniform(-0.02, 0.02)

        # percent-like
        o2_pct = self._clamp(10.5 - 8.2 * load + 0.25 * base_noise, 0.0, 21.0)
        co2_pct = self._clamp(7.0 + 7.5 * load + 0.30 * base_noise, 0.0, 20.0)

        # ppm-like
        nox_ppm = self._clamp(60.0 + 1800.0 * (load ** 1.55) + self._maybe_transient_spike(0.05, 250.0), 0.0, 5000.0)
        ch4_ppm = self._clamp(40.0 + 650.0 * (1.0 - load) + self._maybe_transient_spike(0.08, 600.0), 0.0, 15000.0)
        voc_ppm = self._clamp(15.0 + 520.0 * (1.0 - load) + self._maybe_transient_spike(0.06, 400.0), 0.0, 15000.0)

        # CAL phases: override to look like zero/span plateaus
        if phase.startswith("CAL_"):
            if "ZERO" in phase:
                o2_pct, co2_pct, nox_ppm, ch4_ppm, voc_ppm = 0.05, 0.05, 1.0, 1.0, 1.0
            if "SPAN" in phase:
                o2_pct, co2_pct = 0.8, 0.8
                nox_ppm, ch4_ppm, voc_ppm = 0.8, 0.8, 0.8

        canon: Dict[str, float] = {"O2": o2_pct, "CO2": co2_pct, "NOX": nox_ppm, "CH4": ch4_ppm, "VOC": voc_ppm}
        canon["NO"] = 0.86 * canon["NOX"]
        canon["NO2"] = 0.14 * canon["NOX"]

        for i, code in enumerate(self._poll_codes):
            uc = code.upper()

            key = None
            if uc in ("O2", "OXYGEN", "O2%"):
                key = "O2"
            elif uc in ("CO2", "CARBON_DIOXIDE", "CO2%"):
                key = "CO2"
            elif uc in ("NOX", "NOX_PPM", "NOXPPM", "NO_X"):
                key = "NOX"
            elif uc in ("NO", "NITRIC_OXIDE"):
                key = "NO"
            elif uc in ("NO2", "NITROGEN_DIOXIDE"):
                key = "NO2"
            elif uc in ("CH4", "METHANE", "METHANE_DRY"):
                key = "CH4"
            elif uc in ("VOC", "VOCS", "VOC_PPM"):
                key = "VOC"

            if key is not None:
                val = float(canon[key])

                if phase.startswith("CAL_") and "SPAN" in phase and val <= 1.0:
                    vmax = self._expected_max(uc, 100.0)
                    val = 0.80 * vmax

                vmax = self._expected_max(uc, 21.0 if key in ("O2", "CO2") else 5000.0)
                if key in ("O2", "CO2") and vmax <= 40.0:
                    val = self._clamp(val, 0.0, vmax)
                else:
                    if vmax < 500.0 and val > vmax:
                        val = vmax * (0.92 + 0.06 * self._rng.random())
                    if val < 0:
                        val = 0.0

                if self._drift_per_k:
                    val = val + (self._n * self._drift_per_k)

                if stuck_mode:
                    if uc not in self._stuck_values:
                        self._stuck_values[uc] = float(val)
                    val = self._stuck_values[uc]

                out[uc] = round(float(val), 3)
                continue

            # Fallback channel behavior: sine wave scaled to expected_max
            p = self._pres.get(uc) or {}
            vmax = p.get("expected_max", None)
            try:
                vmax_f = float(vmax) if vmax not in (None, "", 0) else 100.0
            except Exception:
                vmax_f = 100.0

            base = 0.25 + 0.20 * math.sin(0.23 * t + self._phase.get(uc, 0.0) + (i * 0.7))
            noise = self._rng.uniform(-0.020, 0.020)
            val = max(0.0, (base + noise) * vmax_f)

            if self._drift_per_k:
                val = val + (self._n * self._drift_per_k)

            if stuck_mode:
                if uc not in self._stuck_values:
                    self._stuck_values[uc] = float(val)
                val = self._stuck_values[uc]

            out[uc] = round(float(val), 3)

        # Always include O2/CO2 in the output frame for correction/normalization
        # even when they are not explicitly selected as pollutant codes.
        try:
            if "O2" not in out:
                out["O2"] = round(float(o2_pct), 3)
            if "CO2" not in out:
                out["CO2"] = round(float(co2_pct), 3)
        except Exception:
            pass

        if stuck_mode:
            out["diag_fault"] = "STUCK"

        return out



def build_sim_training_scenario(
    session: Dict[str, Any],
    *,
    codes: Sequence[str],
    prescriptions: Dict[str, Dict[str, Any]],
) -> Dict[str, Any]:
    """Build a scenario dict for SIM_TRAINING.

    Design goals (training realism):
      - Follow operator-selected pollutants + worksteps from the *session config*.
      - Populate ZERO/MID/SPAN targets from QA/QC workstep targets (or analyte suggestions).
      - Populate SAMPLE targets from empirical emissions ranges (when available), so the
        live frame "looks like a real test" during the TEST RUN step.
      - Deterministic per-session: repeated UI refreshes / driver rebuilds do not change
        the scenario unless the session config changes.
    """

    if mole_spec_engine is not None:
        try:
            scenario = mole_spec_engine.build_training_scenario(
                session,
                codes=codes,
                prescriptions=prescriptions,
                package_root=_pkg_root_dir(),
            )
            if isinstance(scenario, dict) and isinstance(scenario.get("targets"), dict):
                return scenario
        except Exception:
            pass

    # stdlib only (keep SIM driver light / portable)
    import hashlib
    import json
    import math

    def _sf(x: Any) -> Optional[float]:
        """Parse a float from x, tolerating common unit suffixes (e.g., '20.9%', '500 ppm')."""
        try:
            if x is None:
                return None
            if isinstance(x, (int, float)):
                return float(x)
            s = str(x).strip()
            if not s:
                return None
            s = s.replace(',', '')
            import re as _re
            m = _re.search(r'[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?', s)
            if not m:
                return None
            return float(m.group(0))
        except Exception:
            return None

    # Stable per-session seed (do NOT use random module state here)
    job_id = str(
        (session.get("project") or {}).get("job_id")
        or (session.get("project_session") or {}).get("job_id")
        or session.get("job_id")
        or "session"
    ).strip()

    def _stable_u01(tag: str) -> float:
        h = hashlib.sha256((job_id + "|" + tag).encode("utf-8")).hexdigest()[:16]
        # 16 hex chars => 64 bits
        u = int(h, 16) / float(0xFFFFFFFFFFFFFFFF)
        if u < 0.0:
            return 0.0
        if u > 1.0:
            return 1.0
        return float(u)

    def _triangular(u: float, a: float, c: float, b: float) -> float:
        # Quantile of a triangular distribution (a <= c <= b)
        if b <= a:
            return a
        if c < a:
            c = a
        if c > b:
            c = b
        u = 0.0 if u < 0.0 else (1.0 if u > 1.0 else u)
        fc = (c - a) / (b - a) if (b - a) > 0 else 0.5
        if u < fc:
            return a + math.sqrt(u * (b - a) * (c - a))
        return b - math.sqrt((1.0 - u) * (b - a) * (b - c))

    # Empirical ranges (cached on the function object)
    def _ranges_db() -> Dict[str, Any]:
        cache = getattr(build_sim_training_scenario, "_ranges_cache", None)
        if isinstance(cache, dict):
            return cache
        db: Dict[str, Any] = {}
        try:
            p = _pkg_root_dir() / "mole_das_data" / "configs" / "sim_emissions_ranges.json"
            if p.exists():
                db = json.loads(p.read_text(encoding="utf-8"))
        except Exception:
            db = {}
        if not isinstance(db, dict):
            db = {}
        setattr(build_sim_training_scenario, "_ranges_cache", db)
        return db

    ranges = (_ranges_db().get("pollutants") or {}) if isinstance(_ranges_db(), dict) else {}

    # --- Determine the active pollutant set ---
    poll = session.get("pollutants") or {}
    resolved_by = (((poll.get("resolved") or {}).get("resolved_by_analyte") or {}) if isinstance(poll, dict) else {})
    selected = poll.get("selected") or []
    if not isinstance(selected, list):
        selected = []

    poll_codes = [str(c or "").strip().upper() for c in selected if str(c or "").strip()]
    poll_codes = [c for c in poll_codes if c]

    # Always provide O2/CO2 channels for correction/normalization UX
    for extra in ("O2", "CO2"):
        if extra not in poll_codes:
            poll_codes.append(extra)
    # --- Workstep QA/QC targets (authoritative for training) ---
    ws = ((session.get("daq_runner") or {}).get("worksteps") or {})
    ws_q = (ws.get("qaqc") or {})

    # Normalize QA/QC dict keys to uppercase so targets can be looked up case-insensitively
    # (e.g., 'o2' vs 'O2').
    def _upper_qblk(d: Any) -> Dict[str, Any]:
        out: Dict[str, Any] = {}
        if isinstance(d, dict):
            for k, v in d.items():
                kk = str(k or "").strip().upper()
                if kk:
                    out[kk] = v
        return out

    q_zero = _upper_qblk(ws_q.get("zero") or {})
    q_mid = _upper_qblk(ws_q.get("mid") or {})
    q_span = _upper_qblk(ws_q.get("span") or {})

    # --- AMBIENT / base conditions ---
    targets_ambient: Dict[str, float] = {}
    for code in poll_codes:
        targets_ambient[code] = 0.0
    # Ambient air defaults (good for UI + correction sanity)
    targets_ambient["O2"] = 20.9
    targets_ambient["CO2"] = 0.04

    # --- ZERO / MID / SPAN targets ---
    targets_zero: Dict[str, float] = {}
    targets_mid: Dict[str, float] = {}
    targets_span: Dict[str, float] = {}
    for code in poll_codes:
        zt = _sf((q_zero.get(code) or {}).get("target"))
        mt = _sf((q_mid.get(code) or {}).get("target"))
        st = _sf((q_span.get(code) or {}).get("target"))

        # Authoritative project inputs come from the wizard session.
        p = prescriptions.get(code) or {}
        rr = resolved_by.get(code) or {}
        if st is None:
            st = _sf(p.get("span_target"))
        if mt is None:
            mt = _sf(p.get("mid_target"))

        # ZERO default: this architecture uses 100% N2 zero gas for every channel.
        zt = 0.0

        # MID default
        if mt is None and st is not None:
            mid_frac = _sf((rr.get("mid_fraction") if isinstance(rr, dict) else None))
            if mid_frac is None or not (0.0 < float(mid_frac) < 1.0):
                mid_frac = 0.50
            mt = st * float(mid_frac)

        targets_zero[code] = float(zt or 0.0)
        targets_mid[code] = float(mt) if mt is not None else float(zt or 0.0)
        targets_span[code] = float(st) if st is not None else float(mt or zt or 0.0)
    # HOUSEKEEPING (SIM realism):
    #   - ZERO gas in this architecture is 100% N2, so all channels target zero unless the session
    #     explicitly says otherwise.
    #   - SPAN gas targets come from the wizard/session inputs; do not synthesize generic spans.
    #   - If the operator provided explicit QA/QC targets (or prescription targets), we do NOT override them.

    def _has_explicit_target(qblk: Dict[str, Any], code: str) -> bool:
        try:
            row = qblk.get(code)
            if isinstance(row, dict):
                return _sf(row.get("target")) is not None
            # allow shorthand numeric targets
            return _sf(row) is not None
        except Exception:
            return False

    for code in ("O2", "CO2"):
        try:
            p = prescriptions.get(code) or {}
            z_exp = _has_explicit_target(q_zero, code) or (_sf(p.get("zero_target")) is not None)
            m_exp = _has_explicit_target(q_mid, code)
            s_exp = _has_explicit_target(q_span, code) or (_sf(p.get("span_target")) is not None)

            if code == "O2":
                # IMPORTANT:
                # Field practice varies.
                # - Many O2 analyzers are zeroed on N2 (0% O2) and spanned on a certified O2 mix.
                # - Some programs use "zero air" (synthetic/ambient ~20.9%) for non-O2 analytes.
                # Policy here: if the operator did NOT provide explicit O2 targets, default O2 to
                # N2-balance (0%) for ZERO/MID/SPAN so O2 visibly responds to gas steps.
                # If you want ambient O2, set an explicit target (e.g., 20.9) in the Wizard/Worksteps.
                if not z_exp:
                    targets_zero[code] = 0.0
                if not m_exp:
                    targets_mid[code] = 0.0
                if not s_exp:
                    targets_span[code] = 0.0
            else:
                # CO2: zero air + cal gases are typically scrubbed / N2-balance => ~0 unless targeted
                if not z_exp:
                    targets_zero[code] = 0.0
                if not m_exp:
                    targets_mid[code] = 0.0
                if not s_exp:
                    targets_span[code] = 0.0
        except Exception:
            pass

    # --- SAMPLE (test-run) targets: empirical ranges when possible ---
    targets_sample: Dict[str, float] = dict(targets_span)

    for code in poll_codes:
        # O2/CO2 sample targets should look like stack gas, not ambient
        if code in ("O2", "CO2"):
            r = ranges.get(code) if isinstance(ranges, dict) else None
            if isinstance(r, dict):
                lo = _sf(r.get("p25") or r.get("p10") or r.get("p05"))
                md = _sf(r.get("p50") or r.get("median"))
                hi = _sf(r.get("p75") or r.get("p90") or r.get("p95"))
                if lo is not None and md is not None and hi is not None:
                    u = _stable_u01(f"{code}:sample")
                    targets_sample[code] = float(_triangular(u, float(lo), float(md), float(hi)))
                    continue
            # fallback
            targets_sample[code] = 8.4 if code == "O2" else 7.7
            continue

        r = ranges.get(code) if isinstance(ranges, dict) else None
        st = float(targets_span.get(code, 0.0) or 0.0)

        sample_val: Optional[float] = None
        if isinstance(r, dict):
            lo = _sf(r.get("p25") or r.get("p10") or r.get("p05"))
            md = _sf(r.get("p50") or r.get("median"))
            hi = _sf(r.get("p75") or r.get("p90") or r.get("p95"))
            if lo is not None and md is not None and hi is not None:
                u = _stable_u01(f"{code}:sample")
                sample_val = float(_triangular(u, float(lo), float(md), float(hi)))

        if sample_val is None:
            sample_val = st * 0.60 if st > 0.0 else 0.0

        # Keep sample below span target (training realism)
        if st > 0.0 and sample_val > 0.85 * st:
            sample_val = 0.85 * st

        if sample_val < 0.0:
            sample_val = 0.0

        targets_sample[code] = float(sample_val)

    # --- POST-CAL (bias check): introduce small deterministic drift ---
    post_zero: Dict[str, float] = dict(targets_zero)
    post_span: Dict[str, float] = dict(targets_span)

    postcal = (ws.get("postcal") or {})
    try:
        run_no = int(postcal.get("run_no") or 0)
    except Exception:
        run_no = 0

    # Unit-aware post-cal drift simulation (bias checks) so POST modes affect O2 too.
    # (Zero drift is absolute; span drift is ±1% of span.)
    poll_units: Dict[str, str] = {}
    try:
        if isinstance(prescriptions, dict):
            for _code, _row in prescriptions.items():
                code_u = str(_code or "").strip().upper()
                row_d = _row if isinstance(_row, dict) else {}
                raw_u = str(
                    row_d.get("units")
                    or row_d.get("expected_units")
                    or row_d.get("unit")
                    or ""
                ).strip().lower()
                if (not raw_u) and code_u in ("O2", "CO2", "H2O", "RH"):
                    raw_u = "%"
                if code_u:
                    poll_units[code_u] = raw_u
    except Exception:
        poll_units = {}

    for code in poll_codes:
        st = float(targets_span.get(code, 0.0) or 0.0)
        zt = float(targets_zero.get(code, 0.0) or 0.0)
        u = str(poll_units.get(code, "ppm") or "ppm").lower().strip()
        is_pct_units = bool(("%" in u) or ("pct" in u) or ("percent" in u))

        # Drift model:
        #   - ppm/ppb channels: absolute zero drift + % span drift
        #   - pct channels (O2/CO2): modest absolute zero drift + % span drift
        if is_pct_units:
            if code == "O2":
                drift_abs = max(0.20, 0.01 * st)   # percent O2
            else:
                drift_abs = max(0.02, 0.05 * st)   # percent CO2 (or other pct channels)
        else:
            drift_abs = max(0.5, 0.001 * st)

        # Post-zero drift (absolute)
        u0 = (_stable_u01(f"{code}:run{run_no}:zero_drift") - 0.5) * 2.0
        post_zero_val = zt + (u0 * drift_abs)

        # Post-span drift (percentage of span)
        u1 = (_stable_u01(f"{code}:run{run_no}:span_drift") - 0.5) * 2.0
        post_span_val = st * (1.0 + (u1 * 0.01))

        # Clamp to plausible ranges
        if code == "O2":
            post_zero_val = max(0.0, min(21.0, post_zero_val))
            post_span_val = max(0.0, min(21.0, post_span_val))
        elif code == "CO2":
            post_zero_val = max(0.0, min(25.0, post_zero_val))
            post_span_val = max(0.0, min(25.0, post_span_val))
        else:
            post_zero_val = max(0.0, post_zero_val)
            post_span_val = max(0.0, post_span_val)

        post_zero[code] = post_zero_val
        post_span[code] = post_span_val
    scenario = {
        "name": "sim_training",
        "targets": {
            "AMBIENT": targets_ambient,
            "ZERO": targets_zero,
            "MID": targets_mid,
            "SPAN": targets_span,
            "SAMPLE": targets_sample,
            "POST_ZERO": post_zero,
            "POST_SPAN": post_span,
        },
        "tau_s": 4.0,
        "noise": 0.02,
    }
    return scenario
class SimTrainingDriver:
    """Interactive simulator driver designed for technician training.

    Key design goals:
      - Follows selected pollutants (session.pollutants.selected) and QA/QC workstep targets
      - Supports workstep-driven gas mode transitions (ZERO/MID/SPAN/SAMPLE/AMBIENT)
      - Sandbox separation: no hardware IO; deterministic timestamps

    The DAQ runner UI will toggle phases via Worksteps buttons in TRAINING mode.
    """

    name = "SIM_TRAINING"

    def __init__(
        self,
        poll_codes: Sequence[str],
        prescriptions: Dict[str, Dict[str, Any]],
        *,
        scenario: Optional[Dict[str, Any]] = None,
        seed: object = 1337,
        dt_s: float = 1.0,
        base_ts_iso: str = "2020-01-01T00:00:00Z",
        faults: Optional[Dict[str, Any]] = None,
    ) -> None:
        self._codes = [str(c).strip().upper() for c in (poll_codes or []) if str(c).strip()]
        self._pres = prescriptions or {}
        self._scenario = scenario or {"targets": {}}
        self._seed = _seed_to_int(seed)
        self._rng = random.Random(self._seed)
        self._dt = float(dt_s or 1.0)
        self._t0 = _parse_iso_z(base_ts_iso)
        self._n = 0
        self._connected = False
        self._faults = faults or {}
        self._mode = "AMBIENT"

        # internal state (first-order lag)
        self._state: Dict[str, float] = {}

        # Initialize state to ambient
        try:
            amb = (self._scenario.get("targets") or {}).get("AMBIENT") or {}
            for k, v in amb.items():
                try:
                    self._state[str(k)] = float(v)
                except Exception:
                    continue
        except Exception:
            pass

    def connect(self) -> None:
        self._connected = True

    def close(self) -> None:
        self._connected = False

    def update_scenario(self, scenario: Dict[str, Any]) -> None:
        if isinstance(scenario, dict):
            self._scenario = scenario

    def set_manifold_mode(self, mode: str) -> None:
        m = str(mode or "").strip().upper()
        if not m:
            return
        # Allow scenario-defined modes (e.g., POST_ZERO / POST_SPAN). If the mode is unknown,
        # read_all() will safely fall back to AMBIENT targets.
        self._mode = m

    def prime_mode(self, mode: str) -> None:
        self.set_manifold_mode(mode)
        try:
            tgt = ((self._scenario.get("targets") or {}).get(self._mode) or {})
        except Exception:
            tgt = {}
        if not isinstance(tgt, dict):
            return
        for k, v in tgt.items():
            try:
                self._state[str(k).strip().upper()] = float(v)
            except Exception:
                continue

    def get_manifold_mode(self) -> str:
        return str(self._mode)

    def _ts_iso(self) -> str:
        # Deterministic timestamp progression
        try:
            from datetime import timedelta
            dt = self._t0 + timedelta(seconds=self._n * self._dt)
            s = dt.isoformat()
            return s.replace("+00:00", "Z")
        except Exception:
            return _now_iso()

    def read_all(self) -> Dict[str, Any]:
        # Fault: dropout_every
        try:
            de = self._faults.get("dropout_every")
            if de and isinstance(de, int) and de > 0 and (self._n % de == 0) and self._n != 0:
                self._n += 1
                return {"ts_iso": self._ts_iso(), "comm_ok": False, "diag_n": self._n, "diag_profile": self.name}
        except Exception:
            pass

        # Resolve target vector for current mode
        tgt = {}
        try:
            tgt = ((self._scenario.get("targets") or {}).get(self._mode) or {})
        except Exception:
            tgt = {}

        tau_s = 4.0
        noise_frac = 0.004
        try:
            tau_s = float(self._scenario.get("tau_s") or tau_s)
        except Exception:
            pass
        try:
            noise_frac = float(self._scenario.get("noise_frac") or noise_frac)
        except Exception:
            pass
        tau_s = max(0.25, float(tau_s))
        noise_frac = max(0.0, float(noise_frac))

        # Exponential smoothing coefficient
        try:
            alpha = 1.0 - math.exp(-self._dt / tau_s)
        except Exception:
            alpha = 0.25

        out: Dict[str, Any] = {
            "ts_iso": self._ts_iso(),
            "comm_ok": True,
            "diag_n": self._n,
            "diag_profile": self.name,
            "sim_env": "TRAINING",
            "sim_mode": self._mode,
        }

        # Ensure we emit at least the scenario codes
        keys = list((self._scenario.get("codes") or []) if isinstance(self._scenario, dict) else [])
        if not keys:
            keys = sorted(set(self._codes + ["O2", "CO2"]))

        for k in keys:
            try:
                kk = str(k).strip().upper()
                if not kk:
                    continue
                cur = float(self._state.get(kk, 0.0))
                target = float(tgt.get(kk, 0.0))
                # Noise scaled to magnitude (avoid 0*noise)
                mag = max(abs(target), 1.0)
                noise = self._rng.uniform(-1.0, 1.0) * noise_frac * mag
                nxt = cur + alpha * (target - cur) + noise
                # Clamp negatives for concentration channels (except O2/CO2 which are still >=0)
                if nxt < 0.0:
                    nxt = 0.0
                self._state[kk] = float(nxt)
                out[kk] = round(float(nxt), 4)
            except Exception:
                continue

        self._n += 1
        return out

class DummyDriver:
    name = "DUMMY"

    def __init__(self) -> None:
        self._t0 = time.time()

    def connect(self) -> None:
        return

    def close(self) -> None:
        return

    def read_all(self) -> Dict[str, Any]:
        # Replace with real analyzer reads (O2, CO2, NOx, VOC, etc.)
        t = time.time() - self._t0
        return {
            "ts_iso": now_iso(),
            "dummy_signal": round(10.0 + 2.0 * (t % 10) / 10.0, 3),
            "comm_ok": True,
        }


