def apply_channel_offsets(frame: Dict[str, Any], sess: Dict[str, Any]) -> Dict[str, Any]:
    """Apply per-channel linear corrections (scale + offset) for drift compensation.

    Policy:
      corrected = raw * scale + offset

    - Only channels listed in sess['daq_runner']['channel_offsets']['channels'] are modified.
    - Originals are preserved in frame['_raw_channels'] for audit/replay.
    """
    try:
        blk = (sess.get('daq_runner') or {}) if isinstance(sess, dict) else {}
        co = blk.get('channel_offsets') or {}
        if (not isinstance(co, dict)) or (not bool(co.get('enabled'))):
            return frame
        ch = co.get('channels') or {}
        if not isinstance(ch, dict) or not ch:
            return frame

        raw_map = {}
        applied = {}
        for k, spec in ch.items():
            if k not in frame:
                continue
            v = frame.get(k)
            try:
                if v is None or v == '':
                    continue
                fv = float(v)
            except Exception:
                continue

            off = 0.0
            scl = 1.0
            try:
                spec = spec or {}
                if isinstance(spec, dict):
                    off = float(spec.get('offset') or 0.0)
                    scl = float(spec.get('scale') or 1.0)
            except Exception:
                off, scl = 0.0, 1.0

            raw_map[str(k)] = fv
            frame[k] = fv * scl + off
            applied[str(k)] = {'offset': off, 'scale': scl}

        if raw_map:
            # Internal keys (hidden from the main raw channel table; still present in JSON view + logs).
            try:
                frame.setdefault('_raw_channels', {})
                if isinstance(frame.get('_raw_channels'), dict):
                    frame['_raw_channels'].update(raw_map)
            except Exception:
                frame['_raw_channels'] = dict(raw_map)

            try:
                frame.setdefault('_channel_corrections', {})
                if isinstance(frame.get('_channel_corrections'), dict):
                    frame['_channel_corrections'].update(applied)
            except Exception:
                frame['_channel_corrections'] = dict(applied)

            frame['_channel_offsets_enabled'] = True

    except Exception:
        return frame

    return frame


def _pollutant_adjustment_elapsed_hours(sess: Dict[str, Any], frame_ts_iso: Optional[str] = None) -> float:
    """Elapsed active-run hours used for additive pollutant drift adjustments."""
    try:
        blk = (sess.get("daq_runner") or {}) if isinstance(sess, dict) else {}
        runs = blk.get("runs") if isinstance(blk.get("runs"), list) else []
        if not runs:
            return 0.0
        idx = int(blk.get("active_run_index") or 0)
        idx = max(0, min(idx, len(runs) - 1))
        run = runs[idx] if 0 <= idx < len(runs) else {}
        if not isinstance(run, dict):
            return 0.0
        start_iso = str(run.get("start_iso") or "").strip()
        if not start_iso:
            return 0.0

        end_iso = str(run.get("end_iso") or "").strip()
        if end_iso:
            end_ref = end_iso
        elif str(frame_ts_iso or "").strip():
            end_ref = str(frame_ts_iso).strip()
        else:
            end_ref = _now_iso_z()

        start_dt = _parse_iso(_iso_to_utc_z(start_iso))
        end_dt = _parse_iso(_iso_to_utc_z(end_ref))
        return max(0.0, (end_dt - start_dt).total_seconds() / 3600.0)
    except Exception:
        return 0.0


def apply_pollutant_bias_drift(frame: Dict[str, Any], sess: Dict[str, Any]) -> Dict[str, Any]:
    """Apply per-pollutant additive bias and elapsed drift before derived calculations.

    Policy:
      adjusted = raw + bias + (drift_per_hr * elapsed_run_hr)

    - This layer is pollutant-oriented rather than generic channel scale/offset.
    - It is intended for explicit operator-entered post-processing corrections that must
      be visible in live audit output and downstream artifacts.
    """
    try:
        blk = (sess.get("daq_runner") or {}) if isinstance(sess, dict) else {}
        adj_blk = blk.get("pollutant_adjustments") or {}
        if (not isinstance(adj_blk, dict)) or (not bool(adj_blk.get("enabled"))):
            return frame
        ch = adj_blk.get("channels") or {}
        if not isinstance(ch, dict) or not ch:
            return frame

        elapsed_hr = _pollutant_adjustment_elapsed_hours(sess, str(frame.get("ts_iso") or "").strip() or None)
        raw_map: Dict[str, float] = {}
        applied: Dict[str, Dict[str, Any]] = {}
        out = dict(frame)
        for k, spec in ch.items():
            code = str(k or "").strip()
            if (not code) or (code not in out):
                continue
            try:
                if not isinstance(spec, dict):
                    continue
                if not bool(spec.get("enabled", True)):
                    continue
                v = out.get(code)
                if v in (None, ""):
                    continue
                raw_v = float(v)
                bias = float(spec.get("bias") or 0.0)
                drift_per_hr = float(spec.get("drift_per_hr") or 0.0)
                total_adj = bias + (drift_per_hr * float(elapsed_hr))
                raw_map[code] = raw_v
                out[code] = raw_v + total_adj
                applied[code] = {
                    "bias": bias,
                    "drift_per_hr": drift_per_hr,
                    "elapsed_hr": float(elapsed_hr),
                    "total_adjustment": total_adj,
                    "formula": "adjusted = raw + bias + (drift_per_hr * elapsed_run_hr)",
                }
            except Exception:
                continue

        if raw_map:
            try:
                out.setdefault("_pollutant_adjustment_raw_channels", {})
                if isinstance(out.get("_pollutant_adjustment_raw_channels"), dict):
                    out["_pollutant_adjustment_raw_channels"].update(raw_map)
            except Exception:
                out["_pollutant_adjustment_raw_channels"] = dict(raw_map)
            try:
                out.setdefault("_pollutant_adjustments", {})
                if isinstance(out.get("_pollutant_adjustments"), dict):
                    out["_pollutant_adjustments"].update(applied)
            except Exception:
                out["_pollutant_adjustments"] = dict(applied)
            out["_pollutant_adjustments_enabled"] = True
        return out
    except Exception:
        return frame


def _active_o2_pollutant_adjustment(sess: Dict[str, Any]) -> Dict[str, Any]:
    try:
        blk = (sess.get("daq_runner") or {}) if isinstance(sess, dict) else {}
        adj_blk = blk.get("pollutant_adjustments") or {}
        if (not isinstance(adj_blk, dict)) or (not bool(adj_blk.get("enabled"))):
            return {"active": False, "bias": 0.0, "drift_per_hr": 0.0}
        ch_map = adj_blk.get("channels") or {}
        if not isinstance(ch_map, dict):
            return {"active": False, "bias": 0.0, "drift_per_hr": 0.0}
        spec = ch_map.get("O2")
        if not isinstance(spec, dict):
            return {"active": False, "bias": 0.0, "drift_per_hr": 0.0}
        enabled = bool(spec.get("enabled", True))
        bias = _parse_float(spec.get("bias"), 0.0) or 0.0
        drift_per_hr = _parse_float(spec.get("drift_per_hr"), 0.0) or 0.0
        active = bool(enabled and (abs(float(bias)) > 1e-12 or abs(float(drift_per_hr)) > 1e-12))
        return {"active": active, "bias": float(bias), "drift_per_hr": float(drift_per_hr)}
    except Exception:
        return {"active": False, "bias": 0.0, "drift_per_hr": 0.0}


def _o2_correction_denominator_note(sess: Dict[str, Any]) -> str:
    if bool(_active_o2_pollutant_adjustment(sess).get("active")):
        return "Adjusted O2 is used as the EPA 3A / 7E corrected-concentration denominator when O2 bias / drift is active."
    return "O2 correction denominator uses the live O2 channel."


def apply_ftir_offset_recommendations(frame: Dict[str, Any], sess: Dict[str, Any]) -> Dict[str, Any]:
    """Apply approved carried-forward FTIR offsets as a separate correction layer."""
    try:
        if mole_ftir_offset_recommendations is None or not isinstance(sess, dict):
            return frame

        ref_cfg = sess.get("reference_audit")
        if not isinstance(ref_cfg, dict):
            ref_cfg = ((sess.get("daq_runner") or {}).get("reference_audit") or {})
        if not isinstance(ref_cfg, dict):
            return frame

        store = mole_ftir_offset_recommendations.load_store()
        policy = mole_ftir_offset_recommendations.normalize_project_policy(
            ref_cfg.get("offset_recommendations"),
            default_use_global=bool(store.get("auto_apply_future_projects")),
        )
        if not bool(policy.get("use_global")):
            return frame

        active = mole_ftir_offset_recommendations.get_active_set(store)
        if not isinstance(active, dict):
            return frame

        channel_map = mole_ftir_offset_recommendations.active_channel_map(store)
        if not isinstance(channel_map, dict) or not channel_map:
            return frame

        raw_map = {}
        applied = {}
        for code, spec in channel_map.items():
            if code not in frame:
                continue
            value = frame.get(code)
            try:
                if value is None or value == "":
                    continue
                fv = float(value)
            except Exception:
                continue

            try:
                off = float(spec.get("offset") or 0.0)
                scl = float(spec.get("scale") or 1.0)
            except Exception:
                off, scl = 0.0, 1.0

            raw_map[str(code)] = fv
            frame[code] = fv * scl + off
            applied[str(code)] = {
                "offset": off,
                "scale": scl,
                "units": str(spec.get("units") or ""),
                "set_id": str(spec.get("set_id") or ""),
                "generated_iso": str(spec.get("generated_iso") or ""),
            }

        if applied:
            try:
                frame.setdefault("_ftir_offset_raw_channels", {})
                if isinstance(frame.get("_ftir_offset_raw_channels"), dict):
                    frame["_ftir_offset_raw_channels"].update(raw_map)
            except Exception:
                frame["_ftir_offset_raw_channels"] = dict(raw_map)

            try:
                frame.setdefault("_ftir_offset_corrections", {})
                if isinstance(frame.get("_ftir_offset_corrections"), dict):
                    frame["_ftir_offset_corrections"].update(applied)
            except Exception:
                frame["_ftir_offset_corrections"] = dict(applied)

            frame["_ftir_offset_recommendations_enabled"] = True
            frame["_ftir_offset_recommendation_set_id"] = str(active.get("set_id") or "")

    except Exception:
        return frame

    return frame


