@dataclass
class ExecOutputs:
    """Paths for DAQ Runner evidence + exports.

    v10.0.12: The DAQ Runner writes into the canonical session folder contract:

      sessions/YYYY-MM-DD/session_id/
        meta/
        raw/
        processed/
        exports/

    The older (pre-v10.0.12) behavior wrote a standalone "mole_run_*" directory.
    We keep attribute names like out_dir/records_path for backward compatibility
    inside the runner UI and logging.
    """

    out_dir: Path
    meta_dir: Path
    raw_dir: Path
    processed_dir: Path
    exports_dir: Path

    # Canonical raw evidence files (engine-compatible)
    raw_samples_path: Path
    raw_events_path: Path
    comm_health_path: Path

    health_states_path: Path
    reference_audit_path: Path

    # Derived/operator-friendly exports (not canonical)
    records_path: Path
    tokens_path: Path
    weather_path: Path
    weather_pending_path: Path

    # Canonical meta artifacts
    build_path: Path
    manifest_path: Path


def _now_iso_z() -> str:
    try:
        from datetime import datetime, timezone
        return datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
    except Exception:
        return datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')


def _iso_to_utc_z(ts: str) -> str:
    """Convert an ISO timestamp (with or without offset) into UTC Z format."""
    try:
        from datetime import datetime, timezone
        s = str(ts).strip()
        if not s:
            return _now_iso_z()
        if s.endswith('Z'):
            s2 = s[:-1] + '+00:00'
        else:
            s2 = s
        dt = datetime.fromisoformat(s2)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
    except Exception:
        return _now_iso_z()



def _infer_session_dir(session: Dict[str, Any], cfg_path: Path, outdir_arg: Optional[str]) -> Path:
    """Infer the canonical session directory for this run.

    Preference order:
      1) paths.session_dir (written by wizard v10.0.12+)
      2) cfg_path.parent if cfg_path is runner_config.json inside a session folder
      3) paths.session_profile_path parent
      4) paths.sessions_dir + run_day + run_id
      5) outdir_arg (fallback)
      6) cfg_path.parent / mole_run_* (legacy)

    TRAINING mode hardening:
      - Force outputs under mole_das_data/training (functional separation)
      - Ignore explicit paths outside the training sandbox
    """
    pths = (session.get('paths') or {}) if isinstance(session, dict) else {}
    env = _mole_env_mode(session)

    train_root = _training_data_root().resolve()
    train_sessions = (train_root / "sessions").resolve()

    def _is_under_training(p: Path) -> bool:
        if env != "TRAINING":
            return True
        try:
            pr = p.resolve()
            try:
                return pr.is_relative_to(train_root)
            except Exception:
                # Py<3.9 fallback
                return str(pr).replace("\\", "/").startswith(str(train_root).replace("\\", "/"))
        except Exception:
            return False

    # 1) explicit session_dir
    try:
        sd = pths.get('session_dir')
        if sd:
            p = Path(str(sd)).expanduser().resolve()
            if _is_under_training(p):
                return p
    except Exception:
        pass

    # 2) runner_config.json location
    try:
        if cfg_path.name.lower() == 'runner_config.json':
            p = cfg_path.parent.resolve()
            if _is_under_training(p):
                return p
    except Exception:
        pass

    # 3) session_profile_path
    try:
        sp = pths.get('session_profile_path')
        if sp:
            p = Path(str(sp)).expanduser().resolve().parent
            if _is_under_training(p):
                return p
    except Exception:
        pass

    # 4) sessions_dir + run_day + run_id
    try:
        sessions_dir = pths.get('sessions_dir')
        run_day = session.get('run_day')
        run_id = session.get('run_id')
        if env == "TRAINING":
            sessions_dir = str(train_sessions)
        if sessions_dir and run_day and run_id:
            return Path(str(sessions_dir)).expanduser().resolve() / str(run_day) / str(run_id)
    except Exception:
        pass

    # 5) explicit outdir
    if outdir_arg:
        try:
            p = Path(str(outdir_arg)).expanduser().resolve()
            if _is_under_training(p):
                return p
        except Exception:
            pass

    # 6) legacy output next to config (forced into sandbox for TRAINING)
    job = (session.get('project', {}) or {}).get('job_id') or 'job'
    try:
        from datetime import datetime
        stamp = datetime.now().strftime('%Y%m%d_%H%M%S')
    except Exception:
        stamp = 'unknown'

    if env == "TRAINING":
        try:
            return train_sessions / "adhoc" / f"mole_train_{job}_{stamp}"
        except Exception:
            pass

    base = cfg_path.parent.resolve()
    return base / f"mole_run_{job}_{stamp}"

def init_outputs(session: Dict[str, Any], cfg_path: Path, outdir_arg: Optional[str]) -> ExecOutputs:
    session_dir = _infer_session_dir(session, cfg_path, outdir_arg)
    session_dir.mkdir(parents=True, exist_ok=True)

    meta_dir = session_dir / 'meta'
    raw_dir = session_dir / 'raw'
    processed_dir = session_dir / 'processed'
    exports_dir = session_dir / 'exports'

    for d in (meta_dir, raw_dir, processed_dir, exports_dir):
        try:
            d.mkdir(parents=True, exist_ok=True)
        except Exception:
            pass

    raw_samples = raw_dir / 'raw_samples.jsonl'
    raw_events = raw_dir / 'raw_events.jsonl'
    comm_health = raw_dir / 'comm_health.jsonl'

    health_states = raw_dir / 'health_states.jsonl'
    reference_audit = raw_dir / 'reference_audit.jsonl'

    # Touch canonical evidence files so downstream processors don't fail on missing paths.
    for fp in (raw_samples, raw_events, comm_health, health_states, reference_audit):
        try:
            fp.touch(exist_ok=True)
        except Exception:
            pass

    build_path = meta_dir / 'build.json'
    manifest_path = meta_dir / 'manifest.json'

    return ExecOutputs(
        out_dir=session_dir,
        meta_dir=meta_dir,
        raw_dir=raw_dir,
        processed_dir=processed_dir,
        exports_dir=exports_dir,
        raw_samples_path=raw_samples,
        raw_events_path=raw_events,
        comm_health_path=comm_health,
        health_states_path=health_states,
        reference_audit_path=reference_audit,
        records_path=exports_dir / 'records.csv',
        tokens_path=exports_dir / 'tokens.jsonl',
        weather_path=exports_dir / 'weather.jsonl',
        weather_pending_path=exports_dir / 'weather_pending.json',
        build_path=build_path,
        manifest_path=manifest_path,
    )

# ------------------------- canonical evidence helpers (shared contract) -------------------------

def _safe_write_json(path: Path, obj: dict) -> None:
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(obj, indent=2, ensure_ascii=False), encoding='utf-8')
    except Exception:
        # never fail acquisition due to metadata writes
        return


def _jsonl_write_line(f, obj: dict) -> None:
    try:
        f.write(json.dumps(obj, ensure_ascii=False) + "\n")
        f.flush()
    except Exception:
        return


def _session_id(session: Dict[str, Any], outputs: ExecOutputs) -> str:
    try:
        sid = session.get('session_id') or session.get('run_id')
        if sid:
            return str(sid)
    except Exception:
        pass
    try:
        return str(outputs.out_dir.name)
    except Exception:
        return 'unknown_session'


def _run_id(session: Dict[str, Any]) -> str:
    try:
        rid = session.get('run_id')
        if rid:
            return str(rid)
    except Exception:
        pass
    return 'run_001'


def _write_raw_event(f, session: Dict[str, Any], outputs: ExecOutputs, event: str, detail: Optional[Dict[str, Any]] = None) -> None:
    rec = {
        'ts_utc': _now_iso_z(),
        'session_id': _session_id(session, outputs),
        'run_id': _run_id(session),
        'event': str(event),
        'detail': detail or {},
    }
    _jsonl_write_line(f, rec)


def _safe_artifact_name(src: Path) -> str:
    stem = "".join(ch if (ch.isalnum() or ch in ("-", "_")) else "_" for ch in src.stem).strip("._")
    stem = stem or "artifact"
    suffix = src.suffix.lower()
    if len(suffix) > 12:
        suffix = ""
    return stem + suffix


def _copy_static_artifact(outputs: ExecOutputs, src_path: Path, category: str) -> Dict[str, Any]:
    ts = datetime.now().astimezone().strftime("%Y%m%d_%H%M%S")
    dest_dir = outputs.meta_dir / "static_artifacts" / str(category or "misc")
    dest_dir.mkdir(parents=True, exist_ok=True)
    safe_name = _safe_artifact_name(src_path)
    dest_path = dest_dir / f"{ts}_{safe_name}"
    i = 2
    while dest_path.exists():
        dest_path = dest_dir / f"{ts}_{src_path.stem}_{i}{src_path.suffix.lower()}"
        i += 1
    shutil.copy2(src_path, dest_path)
    rel_path = dest_path.relative_to(outputs.out_dir).as_posix()
    return {
        "label": src_path.name,
        "category": str(category or ""),
        "source_path": str(src_path),
        "stored_path": str(dest_path),
        "stored_rel_path": rel_path,
        "bytes": int(dest_path.stat().st_size),
        "sha256": _sha256_file(dest_path),
        "uploaded_iso": _now_iso(),
    }


def _delete_static_artifact(outputs: ExecOutputs, entry: Dict[str, Any]) -> None:
    try:
        rel = str(entry.get("stored_rel_path") or "").strip()
        if rel:
            candidate = (outputs.out_dir / rel).resolve()
        else:
            candidate = Path(str(entry.get("stored_path") or "")).resolve()
        if candidate.exists():
            candidate.unlink()
    except Exception:
        pass


def _iter_numeric_signals(frame: Dict[str, Any]):
    """Yield (key, float_value) for numeric-ish values."""
    for k, v in (frame or {}).items():
        if k in ('ts_iso', 'comm_ok', 'derived_ok'):
            continue
        if k.startswith('_'):
            continue
        if isinstance(v, bool):
            continue
        if isinstance(v, (int, float)):
            yield k, float(v)
            continue
        # attempt float parse for simple numeric strings
        try:
            s = str(v).strip()
            if s == '':
                continue
            fv = float(s)
            yield k, fv
        except Exception:
            continue


def _write_raw_samples_from_frame(f, frame: Dict[str, Any], session: Dict[str, Any], outputs: ExecOutputs, src_meta: Dict[str, Any]) -> None:
    ts_iso = frame.get('ts_iso') or _now_iso_z()
    ts_utc = _iso_to_utc_z(ts_iso)
    comm_ok = bool(frame.get('comm_ok', True))
    sid = _session_id(session, outputs)
    rid = _run_id(session)

    # One JSONL record per signal, matching the engine's raw_samples.jsonl convention.
    for ch, val in _iter_numeric_signals(frame):
        rec = {
            'ts_utc': ts_utc,
            'ts_mono_ns': time.monotonic_ns(),
            'session_id': sid,
            'run_id': rid,
            'channel_id': str(ch),
            'value_eng': val,
            'quality_flags': {
                'comm_ok': comm_ok,
                'decode_ok': True,
                'error': None,
            },
            'source': {
                'producer': 'DAQ_RUNNER',
                'field': str(ch),
            },
        }
        # Optional binding hints (instance binding is the v10.0.9+ contract)
        try:
            inst = (session.get('source', {}) or {}).get('instance_id')
            if inst:
                rec['instance_id'] = inst
        except Exception:
            pass
        _jsonl_write_line(f, rec)


def _write_comm_health(f, session: Dict[str, Any], outputs: ExecOutputs, ok: bool, note: str = '') -> None:
    rec = {
        'ts_utc': _now_iso_z(),
        'session_id': _session_id(session, outputs),
        'run_id': _run_id(session),
        'comm_ok': bool(ok),
        'note': str(note or ''),
    }
    _jsonl_write_line(f, rec)


def _write_reference_snapshot(
    f,
    frame: Dict[str, Any],
    session: Dict[str, Any],
    outputs: ExecOutputs,
    snapshot: Optional[Dict[str, Any]],
) -> None:
    if not isinstance(snapshot, dict):
        return

    try:
        ref_cfg = (
            (session.get("reference_audit") or {})
            if isinstance(session.get("reference_audit"), dict)
            else (((session.get("daq_runner") or {}).get("reference_audit")) or {})
        )
    except Exception:
        ref_cfg = {}

    seeded = False
    if isinstance(ref_cfg, dict):
        seeded = bool(
            ref_cfg.get("enabled")
            or ref_cfg.get("prn_path")
            or ref_cfg.get("column_overrides")
            or ref_cfg.get("units_overrides")
        )
    if (not seeded) and str(snapshot.get("status") or "").strip().upper() == "DISABLED":
        return

    frame_ts_iso = frame.get("ts_iso") or snapshot.get("ts_iso") or _now_iso_z()
    ts_utc = _iso_to_utc_z(str(frame_ts_iso))
    measurements = snapshot.get("measurements") if isinstance(snapshot.get("measurements"), dict) else {}

    primary_values: Dict[str, Any] = {}
    deltas: Dict[str, Any] = {}
    for code, rec in measurements.items():
        if not isinstance(rec, dict):
            continue
        ref_val = _parse_float(rec.get("value"))
        pri_val = _parse_float(frame.get(code))
        if pri_val is not None:
            primary_values[str(code)] = float(pri_val)
        if pri_val is not None and ref_val is not None:
            deltas[str(code)] = float(pri_val) - float(ref_val)

    rec = {
        "ts_utc": ts_utc,
        "frame_ts_iso": str(frame_ts_iso),
        "session_id": _session_id(session, outputs),
        "run_id": _run_id(session),
        "provider": str(snapshot.get("provider") or ""),
        "role": str(snapshot.get("role") or ""),
        "ok": bool(snapshot.get("ok")),
        "status": str(snapshot.get("status") or ""),
        "source_path": str(snapshot.get("source_path") or ""),
        "source_mtime_iso": str(snapshot.get("source_mtime_iso") or ""),
        "source_sha256": str(snapshot.get("source_sha256") or ""),
        "source_bytes": snapshot.get("source_bytes"),
        "age_s": snapshot.get("age_s"),
        "header_index": snapshot.get("header_index"),
        "row_index": snapshot.get("row_index"),
        "delimiter": str(snapshot.get("delimiter") or ""),
        "updated_value_count": snapshot.get("updated_value_count"),
        "error": str(snapshot.get("error") or ""),
        "notes": list(snapshot.get("notes") or []),
        "measurements": measurements,
        "primary_values": primary_values,
        "deltas": deltas,
        "config": {
            "enabled": bool(ref_cfg.get("enabled")) if isinstance(ref_cfg, dict) else False,
            "provider": str((ref_cfg or {}).get("provider") or ""),
            "role": str((ref_cfg or {}).get("role") or ""),
            "prn_path": str((ref_cfg or {}).get("prn_path") or ""),
            "file_pattern": str((ref_cfg or {}).get("file_pattern") or ""),
            "recursive": bool((ref_cfg or {}).get("recursive")) if isinstance(ref_cfg, dict) else False,
            "freshness_s": (ref_cfg or {}).get("freshness_s") if isinstance(ref_cfg, dict) else None,
            "column_overrides": dict((ref_cfg or {}).get("column_overrides") or {}) if isinstance(ref_cfg, dict) else {},
            "units_overrides": dict((ref_cfg or {}).get("units_overrides") or {}) if isinstance(ref_cfg, dict) else {},
        },
    }
    _jsonl_write_line(f, rec)



# ------------------------- health states (v10.0.23 step-2) -------------------------

HEALTH_OK = 'OK'
HEALTH_WARN = 'WARN'
HEALTH_FAIL = 'FAIL'


def _hf(v):
    try:
        if v is None:
            return None
        if isinstance(v, bool):
            return None
        if isinstance(v, (int, float)):
            return float(v)
        s = str(v).strip()
        if not s:
            return None
        return float(s)
    except Exception:
        return None


def _health_selected_codes(session: dict) -> list:
    try:
        poll = session.get('pollutants') or {}
        sel = poll.get('selected') or []
        if isinstance(sel, list) and sel:
            return [str(x) for x in sel if str(x).strip()]
        pres = poll.get('prescriptions') or {}
        if isinstance(pres, dict) and pres:
            return [str(k) for k in pres.keys()]
    except Exception:
        pass
    return []


def _health_prescriptions(session: dict) -> dict:
    try:
        poll = session.get('pollutants') or {}
        pres = poll.get('prescriptions') or {}
        if isinstance(pres, dict):
            return pres
    except Exception:
        pass
    return {}


class HealthMonitor:
    '''Lightweight health evaluation with simple hysteresis.

    - FAIL: comm_ok=False OR any channel grossly out-of-range
    - WARN: missing channels OR mild out-of-range
    - OK: everything looks nominal

    Uses pollutant prescriptions expected_max (and optional expected_min if present).
    '''

    def __init__(self, session: dict, *, warn_n: int = 2, fail_n: int = 3, recover_n: int = 3):
        self.warn_n = max(1, int(warn_n))
        self.fail_n = max(1, int(fail_n))
        self.recover_n = max(1, int(recover_n))
        self.state = HEALTH_OK
        self._bad = 0
        self._good = 0
        self._last_note = ''
        self.codes = _health_selected_codes(session)
        self.pres = _health_prescriptions(session)

    def evaluate_once(self, frame: dict) -> tuple[str, dict]:
        issues = {
            'missing': [],
            'over': [],
            'under': [],
            'gross_over': [],
            'gross_under': [],
        }

        comm_ok = bool(frame.get('comm_ok', True))
        if not comm_ok:
            return HEALTH_FAIL, {'comm_ok': False, 'issues': issues, 'note': 'comm_ok=false'}

        for code in self.codes:
            v = _hf(frame.get(code))
            if v is None:
                issues['missing'].append(code)
                continue
            p = self.pres.get(code) or {}
            vmax = _hf(p.get('expected_max'))
            vmin = _hf(p.get('expected_min'))
            if vmin is None:
                vmin = 0.0

            # thresholds (generic):
            #  - WARN when > 110% of expected_max
            #  - FAIL when > 125% of expected_max
            if vmax is not None and vmax > 0:
                if v > 1.25 * vmax:
                    issues['gross_over'].append(code)
                elif v > 1.10 * vmax:
                    issues['over'].append(code)
            if v < vmin:
                # gross under if substantially negative or far below min
                if v < (vmin - max(1e-9, 0.25 * abs(vmax or 1.0))):
                    issues['gross_under'].append(code)
                else:
                    issues['under'].append(code)

        if issues['gross_over'] or issues['gross_under']:
            note = ''
            if issues['gross_over']:
                note += 'gross_over:' + ','.join(issues['gross_over'])
            if issues['gross_under']:
                note += (' ' if note else '') + 'gross_under:' + ','.join(issues['gross_under'])
            return HEALTH_FAIL, {'comm_ok': True, 'issues': issues, 'note': note.strip()}

        if issues['missing'] or issues['over'] or issues['under']:
            parts = []
            if issues['missing']:
                parts.append('missing:' + ','.join(issues['missing'][:6]))
            if issues['over']:
                parts.append('over:' + ','.join(issues['over'][:6]))
            if issues['under']:
                parts.append('under:' + ','.join(issues['under'][:6]))
            return HEALTH_WARN, {'comm_ok': True, 'issues': issues, 'note': ' '.join(parts)}

        return HEALTH_OK, {'comm_ok': True, 'issues': issues, 'note': 'nominal'}

    def update(self, frame: dict) -> tuple[str, dict]:
        new_state, detail = self.evaluate_once(frame)

        # hysteresis
        if new_state == HEALTH_OK:
            self._good += 1
            self._bad = 0
            if self.state != HEALTH_OK and self._good >= self.recover_n:
                self.state = HEALTH_OK
        elif new_state == HEALTH_WARN:
            self._bad += 1
            self._good = 0
            if self.state == HEALTH_FAIL:
                # allow fail -> warn only after recover_n good-ish ticks
                if self._bad >= self.warn_n:
                    self.state = HEALTH_WARN
            else:
                if self._bad >= self.warn_n:
                    self.state = HEALTH_WARN
        else:  # FAIL
            self._bad += 1
            self._good = 0
            if self._bad >= self.fail_n:
                self.state = HEALTH_FAIL

        self._last_note = str(detail.get('note') or '')
        return self.state, detail

    def record(self, frame: dict, session: dict, outputs: 'ExecOutputs', note: str = '') -> dict:
        st, detail = self.update(frame)
        return {
            'ts_utc': _now_iso_z(),
            'session_id': _session_id(session, outputs),
            'run_id': _run_id(session),
            'health_state': st,
            'comm_ok': bool(frame.get('comm_ok', True)),
            'note': str(note or detail.get('note') or ''),
            'issues': detail.get('issues') or {},
        }

    def record_note(self, session: dict, outputs: 'ExecOutputs', note: str) -> dict:
        return {
            'ts_utc': _now_iso_z(),
            'session_id': _session_id(session, outputs),
            'run_id': _run_id(session),
            'health_state': self.state,
            'comm_ok': True,
            'note': str(note or ''),
            'issues': {},
        }


def _write_build_meta(outputs: ExecOutputs, session: Dict[str, Any], cfg_path: Path, status: str, extra: Optional[Dict[str, Any]] = None) -> None:
    meta = {
        'app_title': APP_TITLE,
        'app_version': APP_VERSION,
        'status': str(status),
        'updated_utc': _now_iso_z(),
        'config_path': str(cfg_path),
        'session_id': _session_id(session, outputs),
        'run_id': _run_id(session),
    }
    try:
        meta['python'] = sys.version
        meta['platform'] = sys.platform
    except Exception:
        pass
    if isinstance(extra, dict):
        meta.update(extra)
    _safe_write_json(outputs.build_path, meta)


def _sha256_file(path: Path) -> str:
    import hashlib
    h = hashlib.sha256()
    with path.open('rb') as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b''):
            h.update(chunk)
    return h.hexdigest()


def _write_manifest(outputs: ExecOutputs, session: Dict[str, Any]) -> None:
    try:
        base = outputs.out_dir
        files = []
        for p in base.rglob('*'):
            if not p.is_file():
                continue
            rel = p.relative_to(base).as_posix()
            if rel == 'meta/manifest.json':
                continue
            try:
                files.append({
                    'path': rel,
                    'bytes': int(p.stat().st_size),
                    'sha256': _sha256_file(p),
                })
            except Exception:
                files.append({'path': rel})
        man = {
            'session_id': _session_id(session, outputs),
            'run_id': _run_id(session),
            'written_utc': _now_iso_z(),
            'files': files,
        }
        _safe_write_json(outputs.manifest_path, man)
    except Exception:
        return


def acquire_loop(
    session: Dict[str, Any],
    cfg_path: Path,
    site_active: SiteConditionsActive,
    sample_period_s: float,
    site_refresh_s: float,
    outputs: ExecOutputs,
) -> None:
    sm = session.get("session_mode", {}) or {}
    record_data = bool(sm.get("record_data"))
    tokenize = bool(sm.get("tokenize"))

    fuel_model = build_fuel_model(session)

    # Weather compilation stream (optional)
    sc0 = session.get("site_conditions") or {}
    wc0 = sc0.get("weather_compile") or {}
    weather_enabled = bool(wc0.get("enabled"))
    weather_interval_s = float(wc0.get("interval_s") or 300.0)
    wx_comp: Optional[WeatherCompiler] = None
    if weather_enabled:
        wx_comp = WeatherCompiler(
            enabled=True,
            interval_s=weather_interval_s,
            weather_path=outputs.weather_path,
            pending_path=outputs.weather_pending_path,
            session=session,
        )
        try:
            wx_comp.record_site(site_active, kind="INIT", requested_ts_iso=_now_iso(), note="Initial site conditions")
        except Exception:
            pass
        wx_comp.try_backfill()

    ref_reader = None
    try:
        if mole_ftir_reference is not None:
            ref_cfg = (session.get("reference_audit") or ((session.get("daq_runner") or {}).get("reference_audit") or {}))
            ref_reader = mole_ftir_reference.MG2000PrnIngestor(ref_cfg if isinstance(ref_cfg, dict) else {})
    except Exception:
        ref_reader = None

    driver = build_driver(session, ui=False)
    driver.connect()

    last_site_refresh = time.time()
    last_tick = time.time()

    # Exports
    csv_f = None
    csv_w = None
    tok_f = None

    try:
        # Canonical evidence streams
        with outputs.raw_samples_path.open('a', encoding='utf-8') as raw_f, \
             outputs.raw_events_path.open('a', encoding='utf-8') as ev_f, \
             outputs.comm_health_path.open('a', encoding='utf-8') as health_f, \
             outputs.reference_audit_path.open('a', encoding='utf-8') as ref_f:

            # Start markers
            _write_raw_event(ev_f, session, outputs, 'RUN_START', {
                'producer': 'DAQ_RUNNER',
                'config': str(cfg_path),
            })
            _write_comm_health(health_f, session, outputs, ok=True, note='acquire_start')

            if record_data:
                csv_f = outputs.records_path.open('w', newline='', encoding='utf-8')
                csv_w = csv.writer(csv_f)
                # Deterministic header (kept intentionally simple)
                csv_w.writerow(['ts_iso'] + ['dummy_signal'] + ['comm_ok'])

            if tokenize:
                tok_f = outputs.tokens_path.open('w', encoding='utf-8')

            while True:
                now = time.time()

                # periodic site refresh
                if (now - last_site_refresh) >= max(1.0, float(site_refresh_s)):
                    try:
                        site_active.refresh_from_session(session)
                        last_site_refresh = now
                        if wx_comp is not None:
                            try:
                                wx_comp.record_site(site_active, kind='REFRESH', requested_ts_iso=_now_iso(), note='Periodic refresh')
                            except Exception:
                                pass
                            wx_comp.try_backfill()
                    except Exception:
                        last_site_refresh = now

                # acquisition tick
                raw = driver.read_all()
                corr = apply_site_corrections(raw, site_active)
                corr = apply_channel_offsets(corr, session)
                corr = apply_ftir_offset_recommendations(corr, session)
                corr = apply_pollutant_bias_drift(corr, session)
                derived = compute_derived_channels(corr)
                derived = fuel_model.apply(derived)

                ref_snapshot = None
                try:
                    if ref_reader is not None:
                        ref_snapshot = ref_reader.read_snapshot()
                except Exception as e:
                    ref_snapshot = {
                        "ok": False,
                        "status": "ERROR",
                        "provider": "MG2000_FTIR_PRN",
                        "role": "",
                        "source_path": "",
                        "source_mtime_iso": "",
                        "source_sha256": "",
                        "source_bytes": None,
                        "age_s": None,
                        "header_index": None,
                        "row_index": None,
                        "delimiter": "",
                        "measurements": {},
                        "notes": [],
                        "updated_value_count": 0,
                        "ts_iso": _now_iso(),
                        "error": str(e),
                    }
                if isinstance(ref_snapshot, dict):
                    derived["_reference_snapshot"] = ref_snapshot
                    try:
                        if mole_ftir_reference is not None:
                            derived.update(mole_ftir_reference.snapshot_frame_fields(ref_snapshot, prefix="REF"))
                    except Exception:
                        pass

                # canonical evidence write (always)
                _write_raw_samples_from_frame(raw_f, derived, session, outputs, session.get('source', {}) or {})
                _write_reference_snapshot(ref_f, derived, session, outputs, ref_snapshot)

                # legacy exports (optional)
                if record_data and csv_w is not None:
                    try:
                        csv_w.writerow([derived.get('ts_iso'), derived.get('dummy_signal'), bool(derived.get('comm_ok', True))])
                    except Exception:
                        pass

                if tokenize and tok_f is not None:
                    try:
                        tok_f.write(json.dumps(tokenize_frame(derived), ensure_ascii=False) + "\n")
                        tok_f.flush()
                    except Exception:
                        pass

                # weather compile tick (non-blocking)
                if wx_comp is not None:
                    try:
                        wx_comp.maybe_fetch_and_record(_now_iso())
                    except Exception:
                        pass

                # sleep to maintain period
                elapsed = time.time() - last_tick
                last_tick = time.time()
                dt = max(0.0, float(sample_period_s) - elapsed)
                time.sleep(dt)

    except KeyboardInterrupt:
        # graceful stop
        pass
    finally:
        try:
            # append end markers + manifest/build
            with outputs.raw_events_path.open('a', encoding='utf-8') as ev_f2:
                _write_raw_event(ev_f2, session, outputs, 'RUN_END', {'producer': 'DAQ_RUNNER'})
            with outputs.comm_health_path.open('a', encoding='utf-8') as hf2:
                _write_comm_health(hf2, session, outputs, ok=True, note='acquire_stop')
        except Exception:
            pass

        try:
            if csv_f:
                csv_f.close()
        except Exception:
            pass
        try:
            if tok_f:
                tok_f.close()
        except Exception:
            pass

        try:
            driver.close()
        except Exception:
            pass



def run_master(
    session: Dict[str, Any],
    cfg_path: Path,
    run_acquisition: bool,
    sample_period_s: float,
    site_refresh_s: float,
    outdir_arg: Optional[str],
    auto_start: bool = False,
) -> None:
    """Entry point for non-UI (console) mode."""

    state = RunnerState.INIT

    # Prepare outputs (canonical session dir)
    outputs = init_outputs(session, cfg_path, outdir_arg)

    # Update session paths so downstream tools are consistent
    try:
        session.setdefault('paths', {})
        session['paths']['session_dir'] = str(outputs.out_dir)
        session['paths']['daq_run_dir'] = str(outputs.out_dir)
    except Exception:
        pass

    # Emit build meta early
    try:
        _write_build_meta(outputs, session, cfg_path, status='START')
    except Exception:
        pass

    # Ensure site conditions active values are hydrated
    site_active = SiteConditionsActive()
    site_active.refresh_from_session(session)

    # Optional interactive prompt
    if run_acquisition and (not auto_start):
        try:
            ans = input('Press ENTER to start acquisition (or type NO to cancel): ').strip().lower()
            if ans in ('n', 'no', 'cancel', 'stop'):
                run_acquisition = False
        except Exception:
            pass

    if not run_acquisition:
        print('\n[DAQ Runner] Acquisition not started (--run not set or cancelled).')
        try:
            _write_build_meta(outputs, session, cfg_path, status='NO_RUN')
            _write_manifest(outputs, session)
        except Exception:
            pass
        return

    state = RunnerState.ACQUIRE
    print('\n[DAQ Runner] Writing session evidence to:')
    print(f'  {outputs.out_dir}')

    try:
        acquire_loop(
            session=session,
            cfg_path=cfg_path,
            site_active=site_active,
            sample_period_s=sample_period_s,
            site_refresh_s=site_refresh_s,
            outputs=outputs,
        )
        state = RunnerState.DONE
        try:
            _write_build_meta(outputs, session, cfg_path, status='DONE')
            _write_manifest(outputs, session)
        except Exception:
            pass
    except Exception as e:
        state = RunnerState.ERROR
        try:
            _write_build_meta(outputs, session, cfg_path, status='ERROR', extra={'error': str(e)})
            _write_manifest(outputs, session)
        except Exception:
            pass
        raise



def main() -> None:
    # --- v10.0.24C preflight (stability hardening) ---
    try:
        from mole_preflight import run_preflight, format_preflight_report
        pf = run_preflight(app="daq_runner", code_dir=Path(__file__).resolve().parent, strict_hash=False)
        rpt = format_preflight_report(pf)
        if pf.get("errors"):
            # If UI mode, attempt a dialog; otherwise print.
            if "--ui" in sys.argv or "--window" in sys.argv:
                try:
                    import tkinter as _tk
                    from tkinter import messagebox as _mb
                    _r = _tk.Tk()
                    _r.withdraw()
                    _mb.showerror("MOLE Preflight — DAQ Runner", rpt)
                    _r.destroy()
                except Exception:
                    print(rpt)
            else:
                print(rpt)
            raise SystemExit(2)
        elif pf.get("warnings"):
            # Non-fatal: print once (also logged to mole_das_data/logs)
            print(rpt)
    except SystemExit:
        raise
    except Exception:
        # Preflight should never block startup if it fails internally.
        pass
    # --------------------------------------------------

    ap = argparse.ArgumentParser()
    ap.add_argument("--config", required=False, default=None, help="Path to session config JSON (runner_config.json or legacy session JSON)")
    ap.add_argument("--session", default=None, help="Path to session_profile.json (written by MOLE DAS; optional)")
    ap.add_argument("--run", action="store_true", help="Start acquisition loop after QA/QC gate")
    ap.add_argument("--auto-start", action="store_true", help="Do not prompt; immediately start acquisition loop when --run is set")
    ap.add_argument("--ui", action="store_true", help="Launch DAQ Runner UI controller window")
    ap.add_argument("--driver", default=None, help="Override acquisition driver (SIM, UI_DUMMY, DUMMY, or PY plugin via config)")
    ap.add_argument("--sim-seed", default=None, help="SIM seed (int or string)")
    ap.add_argument("--sim-dt", type=float, default=None, help="SIM timestep seconds (default: sample-period)")
    ap.add_argument("--sim-base-ts", default=None, help="SIM base timestamp ISO (default: 2020-01-01T00:00:00Z)")
    ap.add_argument("--sim-profile", default=None, help="SIM profile (ENGINE_TRANSIENT, BOILER_STEADY, FLARE_SPIKY, CAL_CYCLE)")
    ap.add_argument("--sim-tau", type=float, default=None, help="SIM profile param: load lag time constant seconds (optional)")
    ap.add_argument("--sim-initial-load", type=float, default=None, help="SIM profile param: initial load 0..1 (optional)")
    ap.add_argument("--sim-dropout-every", type=int, default=0, help="SIM fault: every Nth sample comm_ok=False (0 disables)")
    ap.add_argument("--sim-stuck-after", type=int, default=-1, help="SIM fault: freeze channels after N samples (-1 disables)")
    ap.add_argument("--sim-drift-per-k", type=float, default=0.0, help="SIM fault: additive drift per sample")
    ap.add_argument("--sample-period", type=float, default=1.0, help="Acquisition sample period (seconds)")
    ap.add_argument("--site-refresh", type=float, default=300.0, help="Site conditions refresh period (seconds)")
    ap.add_argument("--outdir", default=None, help="Output run folder (default: use session_profile.paths.daq_run_dir or create under config folder)")
    args = ap.parse_args()

    session_profile = None
    session_profile_path = None
    if getattr(args, "session", None):
        try:
            session_profile_path = Path(str(args.session)).expanduser().resolve()
            if session_profile_path.exists():
                session_profile = json.loads(session_profile_path.read_text(encoding="utf-8"))
        except Exception:
            session_profile = None
            session_profile_path = None

    cfg_path = None
    if getattr(args, "config", None):
        try:
            cfg_path = Path(str(args.config)).expanduser().resolve()
        except Exception:
            cfg_path = None
    if cfg_path is None and isinstance(session_profile, dict):
        try:
            pths = session_profile.get("paths") or {}
            cand = pths.get("runner_config_path") or pths.get("session_config_path")
            if cand:
                cfg_path = Path(str(cand)).expanduser().resolve()
        except Exception:
            cfg_path = None

    if cfg_path is None or not cfg_path.exists():
        raise ConfigError(f"Config not found (provide --config or --session): {cfg_path}")

    session = ensure_session_schema(json.loads(cfg_path.read_text(encoding="utf-8")), actor="runner_cli_load")
    if isinstance(session_profile, dict):
        try:
            session.setdefault("paths", {})
            session["paths"].update(session_profile.get("paths") or {})
            if session_profile.get("run_id"):
                session["run_id"] = session_profile.get("run_id")
        except Exception:
            pass


    # Driver override (CLI convenience for SIM demos and regression runs)
    if getattr(args, "driver", None):
        try:
            dtype = str(args.driver).strip().upper()
            if dtype:
                if dtype in ("SIM", "SIMULATOR"):
                    sim_dt = args.sim_dt if args.sim_dt is not None else float(getattr(args, "sample_period", 1.0) or 1.0)
                    session["daq_driver"] = {
                        "type": "SIM",
                        "sim": {
                            "seed": args.sim_seed if args.sim_seed is not None else 1337,
                            "dt_s": sim_dt,
                            "base_ts_iso": args.sim_base_ts or "2020-01-01T00:00:00Z",
                            "profile": (args.sim_profile or "ENGINE_TRANSIENT"),
                            "profile_params": {
                                "tau_s": (args.sim_tau if args.sim_tau is not None else None),
                                "initial_load": (args.sim_initial_load if args.sim_initial_load is not None else None),
                            },
                            "faults": {
                                "dropout_every": int(args.sim_dropout_every or 0),
                                "stuck_after": int(args.sim_stuck_after if args.sim_stuck_after is not None else -1),
                                "drift_per_k": float(args.sim_drift_per_k or 0.0),
                            },
                        },
                    }
                else:
                    session["daq_driver"] = dtype
        except Exception:
            pass

    # If deterministic run folder exists, prefer it unless user explicitly provided --outdir
    if getattr(args, "outdir", None) in (None, "", "None"):
        try:
            pths = session.get("paths") or {}
            od = pths.get("daq_run_dir")
            if od:
                args.outdir = str(od)
        except Exception:
            pass

    if bool(getattr(args, 'ui', False)):
        # UI controller mode (no console prompts here).
        # When launched via pythonw.exe (Wizard), failures can appear silent — so persist a crash log.
        try:
            # If UI mode and driver override is set, write a temporary config with the override applied.
            ui_cfg = cfg_path
            if getattr(args, "driver", None):
                try:
                    tmp_dir = Path(session.get("paths", {}).get("logs_dir") or cfg_path.parent).expanduser().resolve()
                    tmp_dir.mkdir(parents=True, exist_ok=True)
                    ts = datetime.now().astimezone().strftime("%Y%m%d_%H%M%S")
                    ui_cfg = tmp_dir / f"runner_config_ui_override_{ts}.json"
                    ui_cfg.write_text(json.dumps(ensure_session_schema(session, actor="runner_ui_bootstrap"), indent=2), encoding="utf-8")
                except Exception:
                    ui_cfg = cfg_path
            run_ui_shell(str(ui_cfg), auto_start=bool(args.run))
        except Exception:
            try:
                ts = datetime.now().astimezone().strftime("%Y%m%d_%H%M%S")
            except Exception:
                ts = 'unknown_time'
            try:
                log_dir = Path(((session.get('paths') or {}).get('logs_dir') or (cfg_path.parent / 'mole_das_logs'))).expanduser().resolve()
                log_dir.mkdir(parents=True, exist_ok=True)
                log_path = log_dir / f"mole_daq_runner_ui_crash_{cfg_path.stem}_{ts}.log"
                log_path.write_text(traceback.format_exc(), encoding='utf-8')
            except Exception:
                log_path = None

            # Try to alert the operator even if this was launched without a console window.
            try:
                import tkinter as tk
                from tkinter import messagebox
                r = tk.Tk()
                r.withdraw()
                msg = 'DAQ Runner UI failed to start.'
                if log_path:
                    msg += f"\n\nCrash log:\n{log_path}"
                messagebox.showerror('MOLE DAQ Runner', msg)
                r.destroy()
            except Exception:
                pass

            raise
        return

    proj = session.get("project", {}) or {}
    sm = session.get("session_mode", {}) or {}
    src = session.get("source", {}) or {}
    fuel = session.get("fuel", {}) or {}

    print("\n==============================")
    print("MOLE DAQ RUN PLAN (v10.0.12)")
    print("==============================")
    print(f"Config: {cfg_path}")
    print(f"Job: {proj.get('job_id')}")
    print(f"Mode: {sm.get('mode')} | Record: {sm.get('record_data')} | Token: {sm.get('tokenize')} | DiagOnly: {sm.get('diagnostic_only')}")
    print("")
    print("SOURCE:")
    print(f"  Category : {src.get('source_category')}")
    print("")
    print("FUEL:")
    print(f"  {(fuel.get('fuel_button_code','') + ' ' + fuel.get('fuel_category','')).strip()}")
    print("")

    print_test_matrix(session)
    print("")
    run_master(
        session=session,
        cfg_path=cfg_path,
        run_acquisition=bool(args.run),
        sample_period_s=float(args.sample_period),
        site_refresh_s=float(args.site_refresh),
        outdir_arg=args.outdir,
        auto_start=bool(getattr(args, 'auto_start', False)),
    )


# ------------------------- optional UI shell (arcade logo) -------------------------

def _ui_logo_frame(parent, bg: str = "#0b1118"):
    # Prefer a pre-sized PNG to avoid resample jaggies and alpha fringes.
    try:
        from PIL import Image, ImageTk, ImageEnhance, ImageOps  # type: ignore
        _have_pil = True
    except Exception:
        _have_pil = False

    import tkinter as tk
    import math, random
    from pathlib import Path

    base_dir = Path(__file__).resolve().parent
    branding_dir = (base_dir.parent / "mole_assets" / "branding").resolve()
    search_dirs = [base_dir, branding_dir]

    names = [
        "mole_logo_130.png", "MOLE_logo_130.png",
        "mole_logo.png", "MOLE_logo.png",
        "mole_logo.PNG", "MOLE_logo.PNG",
        "mole.png", "MOLE.png",
    ]

    logo_path = None
    for d in search_dirs:
        for nm in names:
            p = d / nm
            if p.exists():
                logo_path = p
                break
        if logo_path:
            break

    if not logo_path:
        return tk.Label(parent, text="[mole_logo.png missing]", fg="#ff4d4d", bg=bg, font=("Consolas", 9))

    if not _have_pil:
        # Tk fallback (static logo; no CRT animation) — avoids Pillow dependency.
        try:
            img = tk.PhotoImage(file=str(logo_path))
        except Exception as e:
            return tk.Label(parent, text=f"[Logo load failed: {e}]", fg="#ff4d4d", bg=bg, font=("Consolas", 9))

        frame = tk.Frame(parent, bg=bg, highlightthickness=3,
                         highlightbackground="#00ff66", highlightcolor="#00ff66")
        frame.pack(pady=(10, 4), padx=12, anchor="w")

        lbl = tk.Label(frame, image=img, bg=bg, bd=0)
        lbl.image = img  # prevent GC
        lbl.pack(padx=7, pady=7)
        return frame

    base_img = Image.open(logo_path).convert("RGBA")
    target_h = 130
    if base_img.height != target_h:
        w_px = int(base_img.width * (target_h / base_img.height))
        base_img = base_img.resize((w_px, target_h), Image.LANCZOS)

    canvas = tk.Canvas(parent, width=base_img.width, height=base_img.height, highlightthickness=0, bd=0, bg=bg)
    canvas.pack(pady=(10, 4), padx=12, anchor="w")

    state = {"phase": 0.0, "scan": 0, "hold": 0, "imgtk": None, "img_id": None}

    def render(first=False):
        r, g, b, a = base_img.split()
        lum = ImageOps.grayscale(Image.merge("RGB", (r, g, b)))
        green = ImageOps.colorize(lum, black="#001400", white="#66ff66").convert("RGBA")
        gr, gg, gb, _ = green.split()
        green = Image.merge("RGBA", (gr, gg, gb, a))

        breath = 1.02 + 0.22 * math.sin(state["phase"])
        green = ImageEnhance.Brightness(green).enhance(max(0.6, breath))

        if state["hold"] > 0:
            green = ImageEnhance.Brightness(green).enhance(random.uniform(0.82, 1.18))
            state["hold"] -= 1
        else:
            if random.random() < 0.06:
                state["hold"] = random.randint(2, 6)

        w_px, h_px = green.size
        overlay = Image.new("RGBA", (w_px, h_px), (0, 0, 0, 0))
        pitch = 4
        alpha_base = 38
        offset = int(state["scan"]) % pitch
        for y in range(offset, h_px, pitch):
            band_alpha = alpha_base + (5 if (y // pitch) % 2 == 0 else 0)
            row = [(0, 0, 0, band_alpha)] * w_px
            overlay.putdata(row, offset=y * w_px)

        composed = Image.alpha_composite(green, overlay)
        composed = ImageEnhance.Contrast(composed).enhance(1.05)

        state["imgtk"] = ImageTk.PhotoImage(composed)
        if first or state["img_id"] is None:
            state["img_id"] = canvas.create_image(0, 0, anchor="nw", image=state["imgtk"])
        else:
            canvas.itemconfigure(state["img_id"], image=state["imgtk"])

    def tick():
        state["phase"] += 0.14
        state["scan"] += 1
        render(False)
        canvas.after(70, tick)

    render(True)
    canvas.after(70, tick)
    return canvas

def _ui_mole_anim_frame(
    parent,
    bg: str = "#0b1118",
    *,
    max_px: int = 128,
    scale: float | None = None,
    fit_frac: float = 0.72,
    idle_fps: float = 12.0,
    dig_fps: float = 12.0,
    waiting_text: str = "Mole is Waiting...",
    digging_text: str = "Mole is Digging...",
):
    """Arcade-style mole animation widget for the DAQ Runner UI.

    Asset support (first match wins):
      - PNG spritesheet (horizontal frames; square tiles assumed)
      - Animated GIF
      - Single-frame PNG/GIF fallback

    Rendering goals:
      - Crisp pixel art (integer-ish scaling + nearest-neighbor)
      - Automatic "safe framing" so no limbs/tools clip against the bezel
      - Stable bezel dimensions across modes (idle vs dig)
    """
    try:
        from dataclasses import dataclass
        from PIL import Image, ImageTk, ImageDraw, ImageSequence  # type: ignore
    except Exception:
        import tkinter as tk

        tk.Label(
            parent,
            text="[Pillow missing: mole animations disabled]",
            fg="#ff4d4d",
            bg=bg,
            font=("Consolas", 9),
        ).pack(anchor="w", pady=(4, 0))

        class _Null:
            def set_recording(self, *_a, **_k):
                return

            def stop(self):
                return

        return _Null()

    import math
    import tkinter as tk
    from pathlib import Path

    base_dir = _app_base_dir()

    def _candidate_paths(stems: list[str]) -> list[Path]:
        """Return candidate asset paths.

        Search order is intentional:
          1) hi-res sheets (128) for crisp pixel art at 1:1
          2) 64 sheets (scaled up to fit)
          3) 192 sheets (scaled down to fit)
          4) non-suffixed (single-frame PNG/GIF or sheet)
        """
        # Asset search dirs (in order):
        #   1) bundle root mole_assets/sprites  (recommended canonical location)
        #   2) legacy per-script assets/sprites
        #   3) legacy flat sprites/ next to script
        #   4) legacy assets/ next to script
        search_dirs = [
            (base_dir.parent / "mole_assets" / "sprites"),
            base_dir / "assets" / "sprites",
            base_dir / "sprites",
            base_dir / "assets",
            base_dir,
        ]

        exts = (".png", ".gif")
        out: list[Path] = []
        # Choose size suffixes based on the MoleCam render box.
        # Prefer the largest size that does not require downscaling (crisper pixel art).
        sizes_all = (64, 128, 192)
        sizes_le = [s for s in sizes_all if s <= int(max_px)]
        sizes_le.sort(reverse=True)
        sizes_gt = [s for s in sizes_all if s > int(max_px)]
        sizes_gt.sort()
        sizes_order = tuple(sizes_le + sizes_gt) if (sizes_le or sizes_gt) else sizes_all

        # spritesheets first
        for d in search_dirs:
            for stem in stems:
                for ext in exts:
                    for sz in sizes_order:
                        out.append(d / f"{stem}_{sz}{ext}")
        # then non-suffixed
        for d in search_dirs:
            for stem in stems:
                for ext in exts:
                    out.append(d / f"{stem}{ext}")
        return out

    idle_candidates = _candidate_paths(
        [
            "mole_idle_watch_sheet",
            "mole_idle_sheet",
            "mole_idle_wave_spritesheet",
            "mole_idle_watch_spritesheet",
            "mole_idle_spritesheet",
            "mole_idle_wave",
            "mole_idle_watch",
            "mole_idle",
            # fallbacks from prior "Fuel Binding Fix Update" asset pack
            "mole_sprite_framed_128_transparent",
            "mole_sprite_framed_256_transparent",
            "mole_sprite_framed_512_transparent",
            "mole_sprite_tight_transparent",
        ]
    )

    dig_candidates = _candidate_paths(
        [
            "mole_dig_loop_sheet",
            "mole_dig_sheet",
            "mole_dig_dust_spritesheet",
            "mole_dig_loop_spritesheet",
            "mole_dig_spritesheet",
            "mole_dig_dust",
            "mole_dig_loop",
            "mole_dig",
            # fallbacks from prior "Fuel Binding Fix Update" asset pack
            "mole_sprite_framed_128_transparent",
            "mole_sprite_framed_256_transparent",
            "mole_sprite_framed_512_transparent",
            "mole_sprite_tight_transparent",
        ]
    )

    idle_path = next((p for p in idle_candidates if p.exists()), None)
    dig_path = next((p for p in dig_candidates if p.exists()), None)

    class _Null:
        def set_recording(self, *_a, **_k):
            return

        def stop(self):
            return

    if not idle_path or not dig_path:
        missing = []
        if not idle_path:
            missing.append("idle sprites")
        if not dig_path:
            missing.append("dig sprites")
        tk.Label(
            parent,
            text="[mole sprites missing: " + ", ".join(missing) + "]",
            fg="#ff4d4d",
            bg=bg,
            font=("Consolas", 9),
        ).pack(anchor="w", pady=(4, 0))
        return _Null()

    @dataclass
    class FrameSet:
        frames: list[ImageTk.PhotoImage]
        delays_ms: list[int]

    def _apply_scanlines(img: Image.Image, *, spacing: int = 4, alpha: float = 0.08) -> Image.Image:
        """Very light CRT scanlines; keeps pixel art readable."""
        try:
            overlay = Image.new("RGBA", img.size, (0, 0, 0, 0))
            draw = ImageDraw.Draw(overlay)
            a = int(max(0, min(1.0, float(alpha))) * 255)
            for y in range(0, img.height, int(max(1, spacing))):
                draw.line((0, y, img.width, y), fill=(0, 0, 0, a))
            return Image.alpha_composite(img, overlay)
        except Exception:
            return img

    def _union_bbox(bboxes: list[tuple[int, int, int, int]], w: int, h: int) -> tuple[int, int, int, int]:
        if not bboxes:
            return (0, 0, w, h)
        x0 = min(b[0] for b in bboxes)
        y0 = min(b[1] for b in bboxes)
        x1 = max(b[2] for b in bboxes)
        y1 = max(b[3] for b in bboxes)
        x0 = max(0, min(w, x0))
        y0 = max(0, min(h, y0))
        x1 = max(0, min(w, x1))
        y1 = max(0, min(h, y1))
        if x1 <= x0 or y1 <= y0:
            return (0, 0, w, h)
        return (x0, y0, x1, y1)

    def _safe_frame_square(frames_rgba: list[Image.Image]) -> list[Image.Image]:
        """Normalize frames into a shared, padded, square canvas (prevents clipping + jitter)."""
        if not frames_rgba:
            return []

        bbs: list[tuple[int, int, int, int]] = []
        for fr in frames_rgba:
            try:
                bb = fr.split()[-1].getbbox()
                if bb:
                    bbs.append(bb)
            except Exception:
                pass

        union = _union_bbox(bbs, frames_rgba[0].width, frames_rgba[0].height)
        uw = max(1, union[2] - union[0])
        uh = max(1, union[3] - union[1])

        # Extra safety margin so shovels/arms never kiss the bezel.
        margin = max(2, int(round(0.10 * max(uw, uh))))
        side = max(1, int(max(uw, uh) + 2 * margin))

        out: list[Image.Image] = []
        for fr in frames_rgba:
            try:
                crop = fr.crop(union)
            except Exception:
                crop = fr
            canvas = Image.new("RGBA", (side, side), (0, 0, 0, 0))
            ox = (side - crop.width) // 2
            oy = (side - crop.height) // 2
            try:
                canvas.alpha_composite(crop, (ox, oy))
            except Exception:
                canvas.paste(crop, (ox, oy))
            out.append(canvas)
        return out

    def _fit_square(side: int) -> tuple[int, float]:
        """Fit a square side length to the available UI area using pixel-friendly scaling."""
        if side <= 0:
            return 1, 1.0

        max_dim = max(16, int(max_px))
        fit = max(0.40, min(0.98, float(fit_frac)))
        max_fit = max(16, int(round(max_dim * fit)))

        if scale is not None:
            sf = float(scale)
            out = max(1, int(round(side * sf)))
            return out, (out / side)

        if side <= max_fit:
            s = max(1, max_fit // side)
            out = side * s
            return out, float(s)

        div = max(1, int(math.ceil(side / max_fit)))
        out = max(1, int(round(side / div)))
        return out, (out / side)

    def _load_frames(path: Path, *, fps_default: float) -> FrameSet:
        """Load animation frames as PhotoImages + per-frame delays (ms)."""
        p = Path(path)
        ext = p.suffix.lower()

        frames_rgba: list[Image.Image] = []
        delays_ms: list[int] = []

        if ext == ".gif":
            im = Image.open(p)
            for fr in ImageSequence.Iterator(im):
                fr_rgba = fr.convert("RGBA")
                frames_rgba.append(fr_rgba)
                d = fr.info.get("duration", None)
                if d is None:
                    d = im.info.get("duration", None)
                try:
                    d_ms = int(d) if d is not None else int(round(1000.0 / max(1.0, float(fps_default))))
                except Exception:
                    d_ms = int(round(1000.0 / max(1.0, float(fps_default))))
                delays_ms.append(max(30, d_ms))
        else:
            sheet = Image.open(p).convert("RGBA")
            frame_h = sheet.height
            frame_w = frame_h if frame_h > 0 else max(1, min(64, sheet.width))
            if sheet.width < frame_w:
                frame_w = max(1, sheet.width)
            n = max(1, sheet.width // frame_w)

            frames_rgba = [sheet.crop((i * frame_w, 0, (i + 1) * frame_w, frame_h)) for i in range(n)]
            delay = int(round(1000.0 / max(1.0, float(fps_default))))
            delays_ms = [max(30, delay)] * max(1, len(frames_rgba))

        # Normalize to square, pad, and apply scanlines before scaling.
        frames_rgba = _safe_frame_square(frames_rgba)

        target_side, sf = _fit_square(frames_rgba[0].width if frames_rgba else 1)
        scan_spacing = max(2, int(round(max(1.0, sf))))

        out_frames: list[ImageTk.PhotoImage] = []
        for fr in frames_rgba:
            if fr.width != target_side or fr.height != target_side:
                fr = fr.resize((target_side, target_side), Image.NEAREST)
            fr = _apply_scanlines(fr, spacing=scan_spacing, alpha=0.0)
            out_frames.append(ImageTk.PhotoImage(fr))

        if not out_frames:
            out_frames = [ImageTk.PhotoImage(Image.new("RGBA", (max(1, target_side), max(1, target_side)), (0, 0, 0, 0)))]
            delays_ms = [int(round(1000.0 / max(1.0, float(fps_default))))]

        # Ensure delays list is same length as frames
        if len(delays_ms) != len(out_frames):
            if delays_ms:
                delays_ms = (delays_ms * (len(out_frames) // len(delays_ms) + 1))[: len(out_frames)]
            else:
                delays_ms = [int(round(1000.0 / max(1.0, float(fps_default))))] * len(out_frames)

        return FrameSet(frames=out_frames, delays_ms=delays_ms)

    idle_set = _load_frames(idle_path, fps_default=idle_fps)
    dig_set = _load_frames(dig_path, fps_default=dig_fps)

    # Lock the bezel size so the mole never clips (and layout doesn't jitter between modes).
    try:
        _w = max(idle_set.frames[0].width() if idle_set.frames else 0, dig_set.frames[0].width() if dig_set.frames else 0)
        _h = max(idle_set.frames[0].height() if idle_set.frames else 0, dig_set.frames[0].height() if dig_set.frames else 0)
    except Exception:
        _w, _h = 0, 0

    bezel = tk.Frame(parent, bg=bg, highlightthickness=1, highlightbackground="#1b2b38")
    if _w and _h:
        bezel.configure(width=_w + 12, height=_h + 12)
        bezel.pack_propagate(False)
    bezel.pack(anchor="w", pady=(2, 0))

    lbl = tk.Label(bezel, bg=bg, bd=0, highlightthickness=0)
    lbl.pack(expand=True, fill="both", padx=6, pady=6)

    status_lbl = tk.Label(parent, text=waiting_text, fg="#d7f9ff", bg=bg, font=("Consolas", 9, "bold"))
    status_lbl.pack(anchor="w", pady=(2, 0))

    class MoleAnimator:
        def __init__(self):
            self.mode = "idle"
            self._idx = 0
            self._after_id = None
            self._running = True

            try:
                if idle_set.frames:
                    lbl.configure(image=idle_set.frames[0])
            except Exception:
                pass

            self._schedule()

        def _current_set(self) -> FrameSet:
            return dig_set if self.mode == "dig" else idle_set

        def _schedule(self):
            if (not self._running) or (not lbl.winfo_exists()):
                return

            fs = self._current_set()
            if not fs.frames:
                return

            try:
                delay_ms = int(fs.delays_ms[self._idx % len(fs.delays_ms)])
            except Exception:
                delay_ms = int(round(1000.0 / max(1.0, float(dig_fps if self.mode == "dig" else idle_fps))))

            delay_ms = max(15, delay_ms)
            try:
                self._after_id = lbl.after(delay_ms, self._tick)
            except Exception:
                self._after_id = None

        def _tick(self):
            if (not self._running) or (not lbl.winfo_exists()):
                return

            fs = self._current_set()
            if not fs.frames:
                self._schedule()
                return

            self._idx = (self._idx + 1) % len(fs.frames)
            try:
                lbl.configure(image=fs.frames[self._idx])
            except Exception:
                pass

            self._schedule()

        def set_recording(self, recording: bool):
            new_mode = "dig" if bool(recording) else "idle"
            if new_mode == self.mode:
                try:
                    status_lbl.configure(text=(digging_text if new_mode == "dig" else waiting_text))
                except Exception:
                    pass
                return

            self.mode = new_mode
            self._idx = 0
            fs = self._current_set()

            try:
                status_lbl.configure(text=(digging_text if self.mode == "dig" else waiting_text))
            except Exception:
                pass
            try:
                if fs.frames:
                    lbl.configure(image=fs.frames[0])
            except Exception:
                pass

        def stop(self):
            self._running = False
            try:
                if self._after_id is not None:
                    lbl.after_cancel(self._after_id)
            except Exception:
                pass
            self._after_id = None

    return MoleAnimator()


def run_ui_shell(config_path: str | None = None, auto_start: bool = False) -> int:
    """Full DAQ Runner UI (operator panel).

    This UI is intended to be launched by the Wizard when the DAQ Runner tab is selected.

    Key goals (first "fleshed-out" pass):
      - Always show: Pollutants, Site Conditions, Fuel (computed/theoretical), Regulatory Limits, Test Matrix, Source Details.
      - Provide run-count driven Method Inputs capture (per-run fields).
      - Provide a live "acquisition" view (dummy driver for now) that updates pollutant values in the UI.
      - Persist operator edits (runs, method inputs, test status) back into the same session JSON file.

    Notes:
      - QA/QC execution remains available as a console process (because the existing QA/QC engine is CLI).
      - The in-UI acquisition loop is a deterministic thread with a stop event (no Tk calls from the worker thread).
    """
    import tkinter as tk
    from tkinter import ttk, messagebox, filedialog
    import threading
    import queue as _queue
    import math
    import random
    import statistics
    from collections import deque

    BG = "#0b1118"
    FG = "#c7d0d9"
    FG_DIM = "#7f8b96"
    ACC = "#66ff66"
    ACC2 = "#ffb000"
    # Alias color names used by some UI panels
    ACCENT = ACC
    ACCENT2 = ACC2
    BAD = "#ff4d4d"
    OK = ACC  # ok/in-spec foreground
    PANEL_BG = "#0f1620"
    BTN_BG = "#1a2633"
    BTN_BG_HOVER = "#223040"  # hover/active button bg
    # Font/theme helpers used by the Worksteps grid
    FONT = ("Consolas", 9)
    FONT_HDR = ("Consolas", 9, "bold")

    # Worksteps status colors
    FG_OK = ACC
    FG_WARN = BAD

    # Editable entry background (targets)
    ENTRY_BG = PANEL_BG


    # Value readouts (no boxes; arcade contrast)
    VAL_FG = ACC       # arcade green for numeric readouts
    VAL_FG2 = ACC2     # arcade yellow for status/text readouts

    def _ro_entry(parent, var, width=22, fg=VAL_FG, justify='left'):
        """Create a read-only Entry that visually behaves like a label (no rectangle).

        Keeps text-select/copy behavior while matching the panel background.
        """
        e = tk.Entry(
            parent,
            textvariable=var,
            bg=BG,
            fg=fg,
            insertbackground=fg,
            readonlybackground=BG,
            disabledbackground=BG,
            relief='flat',
            bd=0,
            highlightthickness=0,
            font=('Consolas', 9, 'bold'),
            width=int(width),
            justify=justify,
            state='readonly',
        )
        try:
            e.configure(takefocus=0)
        except Exception:
            pass
        return e

    # Arcade value field styling (read-only display fields)
    # On Windows, Entry(state="readonly") ignores `bg` and uses `readonlybackground`,
    # so we set both to blend with the panel and remove borders to avoid white rectangles.
    def _value_entry(parent, var, width=24, fg=None, justify="left"):
        color = fg if fg is not None else ACC
        e = tk.Entry(
            parent,
            textvariable=var,
            width=width,
            justify=justify,
            state="readonly",
            bg=BG,
            readonlybackground=BG,
            disabledbackground=BG,
            fg=color,
            insertbackground=color,
            relief="flat",
            bd=0,
            highlightthickness=0,
            font=("Consolas", 9, "bold"),
        )
        try:
            e.configure(takefocus=0)
        except Exception:
            pass
        return e


    cfg_path = Path(config_path).resolve() if config_path else None
    if cfg_path is None or (not cfg_path.exists()):
        raise ConfigError(f"Config not found: {cfg_path}")

    # -------------------------------
    # Session IO + schema helpers
    # -------------------------------

    def _load_session() -> Dict[str, Any]:
        try:
            return ensure_session_schema(json.loads(cfg_path.read_text(encoding="utf-8")), actor="runner_load")
        except Exception as e:
            raise ConfigError(f"Failed to load config JSON: {e}")

    def _save_session(sess: Dict[str, Any]) -> None:
        try:
            cfg_path.write_text(json.dumps(ensure_session_schema(sess, actor="runner_save"), indent=2), encoding="utf-8")
        except Exception as e:
            raise ConfigError(f"Failed to write config JSON: {e}")

    def _ensure_daq_schema(sess: Dict[str, Any]) -> Dict[str, Any]:
        ensure_session_schema(sess, actor="runner_schema")
        blk = sess.get("daq_runner")
        if not isinstance(blk, dict):
            blk = {}
            sess["daq_runner"] = blk

        blk.setdefault("runs", [])
        blk.setdefault("active_run_index", 0)

        # Acquisition config (UI and CLI runner)
        acq_cfg = blk.get("acq")
        if not isinstance(acq_cfg, dict):
            acq_cfg = {}
            blk["acq"] = acq_cfg
        acq_cfg.setdefault("enabled", False)
        acq_cfg.setdefault("sample_period_s", 1.0)
        acq_cfg.setdefault("site_refresh_s", 300.0)
        # 'recording' is a UI-phase flag (IDLE vs RECORDING). It does not override session_mode.record_data.
        acq_cfg.setdefault("recording", False)

        diag_verify = blk.get("diagnostics_verification")
        if not isinstance(diag_verify, dict):
            diag_verify = {}
            blk["diagnostics_verification"] = diag_verify
        diag_verify.setdefault("technician", "")
        diag_verify.setdefault("worksheet_ref", "")
        diag_verify.setdefault("gas_ids", "")
        diag_verify.setdefault("attachment_path", "")
        diag_verify.setdefault("notes", "")
        diag_verify.setdefault("history", [])
        pretest = diag_verify.get("pretest")
        if not isinstance(pretest, dict):
            pretest = {}
            diag_verify["pretest"] = pretest
        pretest.setdefault("completed", False)
        pretest.setdefault("timestamp_iso", "")
        pretest.setdefault("by", "")
        pretest.setdefault("worksheet_ref", "")
        pretest.setdefault("gas_ids", "")
        pretest.setdefault("attachment_path", "")
        pretest.setdefault("notes", "")
        posttest = diag_verify.get("posttest")
        if not isinstance(posttest, dict):
            posttest = {}
            diag_verify["posttest"] = posttest
        posttest.setdefault("completed", False)
        posttest.setdefault("timestamp_iso", "")
        posttest.setdefault("by", "")
        posttest.setdefault("worksheet_ref", "")
        posttest.setdefault("gas_ids", "")
        posttest.setdefault("attachment_path", "")
        posttest.setdefault("notes", "")

        # Optional reference / audit instrument ingest (for example MG2000 FTIR PRN files).
        proj_ref_cfg = sess.get("reference_audit")
        if not isinstance(proj_ref_cfg, dict):
            proj_ref_cfg = {}
        ref_cfg = blk.get("reference_audit")
        if not isinstance(ref_cfg, dict):
            ref_cfg = {}

        def _ref_cfg_is_seeded(cfg_local: Dict[str, Any]) -> bool:
            try:
                return bool(
                    cfg_local.get("enabled")
                    or str(cfg_local.get("prn_path") or "").strip()
                    or bool(cfg_local.get("column_overrides"))
                    or bool(cfg_local.get("units_overrides"))
                )
            except Exception:
                return False

        ref_cfg = dict(proj_ref_cfg if _ref_cfg_is_seeded(proj_ref_cfg) else ref_cfg)
        if mole_ftir_reference is not None:
            try:
                ref_cfg = mole_ftir_reference.normalize_config(ref_cfg if isinstance(ref_cfg, dict) else {})
            except Exception:
                pass
        if not isinstance(ref_cfg, dict):
            ref_cfg = {}
        ref_cfg.setdefault("enabled", False)
        ref_cfg.setdefault("provider", "MG2000_FTIR_PRN")
        ref_cfg.setdefault("role", "AUDIT")
        if mole_ftir_methods is not None:
            try:
                ref_cfg["method_standard"] = mole_ftir_methods.normalize_method(ref_cfg.get("method_standard"))
            except Exception:
                ref_cfg["method_standard"] = mole_ftir_methods.DEFAULT_METHOD
        else:
            ref_cfg.setdefault("method_standard", "ASTM_D6348_12")
        ref_cfg.setdefault("prn_path", "")
        ref_cfg.setdefault("file_pattern", "*.prn")
        ref_cfg.setdefault("recursive", False)
        ref_cfg.setdefault("freshness_s", 120.0)
        if not isinstance(ref_cfg.get("column_overrides"), dict):
            ref_cfg["column_overrides"] = {}
        if not isinstance(ref_cfg.get("units_overrides"), dict):
            ref_cfg["units_overrides"] = {}
        if mole_ftir_offset_recommendations is not None:
            try:
                store = mole_ftir_offset_recommendations.load_store()
                ref_cfg["offset_recommendations"] = mole_ftir_offset_recommendations.normalize_project_policy(
                    ref_cfg.get("offset_recommendations"),
                    default_use_global=bool(store.get("auto_apply_future_projects")),
                )
            except Exception:
                ref_cfg["offset_recommendations"] = dict(mole_ftir_offset_recommendations.DEFAULT_PROJECT_POLICY)
        else:
            off = ref_cfg.get("offset_recommendations") if isinstance(ref_cfg.get("offset_recommendations"), dict) else {}
            ref_cfg["offset_recommendations"] = {
                "use_global": bool(off.get("use_global")),
                "promote_latest_for_future_projects": bool(off.get("promote_latest_for_future_projects")),
            }
        blk["reference_audit"] = dict(ref_cfg)
        sess["reference_audit"] = dict(ref_cfg)

        side_cfg = blk.get("side_by_side")
        if not isinstance(side_cfg, dict):
            side_cfg = sess.get("side_by_side") if isinstance(sess.get("side_by_side"), dict) else {}
        side_cfg.setdefault("enabled", False)
        side_cfg.setdefault("bias_valve_interval_min", 20)
        side_cfg.setdefault("ambient_purge_required", True)
        side_cfg.setdefault("project_drift_required", True)
        side_cfg.setdefault("notes", "")
        side_cfg.setdefault("events", [])
        side_cfg.setdefault("latest_sync_marker", {})
        side_cfg.setdefault("bias_due_after_run_no", None)
        side_cfg.setdefault("bias_due_after_iso", "")
        side_cfg.setdefault("bias_schedule_source", "")
        side_cfg.setdefault("bias_schedule_minutes", None)
        blk["side_by_side"] = dict(side_cfg)
        sess["side_by_side"] = dict(side_cfg)

        spike_cfg = blk.get("spike_recovery")
        if not isinstance(spike_cfg, dict):
            spike_cfg = sess.get("spike_recovery") if isinstance(sess.get("spike_recovery"), dict) else {}
        if mole_spike_recovery is not None:
            try:
                spike_cfg = mole_spike_recovery.normalize_config(
                    spike_cfg if isinstance(spike_cfg, dict) else {},
                    ftir_enabled=bool(ref_cfg.get("enabled")),
                    ftir_role=str(ref_cfg.get("role") or "AUDIT"),
                    ftir_method=ref_cfg.get("method_standard"),
                )
            except Exception:
                pass
        if not isinstance(spike_cfg, dict):
            spike_cfg = {}
        spike_cfg.setdefault("enabled", False)
        spike_cfg.setdefault("mandatory", False)
        spike_cfg.setdefault("applies_to_mole", True)
        spike_cfg.setdefault("applies_to_ftir", False)
        spike_cfg.setdefault("recovery_pct_min", 70.0)
        spike_cfg.setdefault("recovery_pct_max", 130.0)
        spike_cfg.setdefault("criterion_summary", "Optional spike recovery disabled.")
        blk["spike_recovery"] = dict(spike_cfg)
        sess["spike_recovery"] = dict(spike_cfg)

        spec_engine = blk.get("spec_engine")
        if not isinstance(spec_engine, dict):
            spec_engine = {}
            blk["spec_engine"] = spec_engine
        spec_engine.setdefault("enabled", True)
        spec_engine.setdefault("shadow_mode", True)
        spec_engine.setdefault("capture_logging", True)
        spec_engine.setdefault(
            "formula_version",
            (
                getattr(mole_spec_engine, "SPEC_ENGINE_FORMULA_VERSION", "spec_engine_v1")
                if mole_spec_engine is not None
                else "spec_engine_v1"
            ),
        )

        # Channel offsets / gain corrections (drift compensation)
        ch_off = blk.get("channel_offsets")
        if not isinstance(ch_off, dict):
            ch_off = {}
            blk["channel_offsets"] = ch_off
        ch_off.setdefault("enabled", False)
        ch_map = ch_off.get("channels")
        if not isinstance(ch_map, dict):
            ch_map = {}
            ch_off["channels"] = ch_map

        # Explicit per-pollutant bias + elapsed drift adjustments
        pol_adj = blk.get("pollutant_adjustments")
        if not isinstance(pol_adj, dict):
            pol_adj = {}
            blk["pollutant_adjustments"] = pol_adj
        pol_adj.setdefault("enabled", False)
        pol_adj.setdefault("drift_basis", "ACTIVE_RUN_HR")
        pol_adj.setdefault("formula", "adjusted = raw + bias + (drift_per_hr * elapsed_run_hr)")
        pol_adj_map = pol_adj.get("channels")
        if not isinstance(pol_adj_map, dict):
            pol_adj_map = {}
            pol_adj["channels"] = pol_adj_map
        for _code, _spec in list(pol_adj_map.items()):
            if not isinstance(_spec, dict):
                pol_adj_map[_code] = {"enabled": True, "bias": 0.0, "drift_per_hr": 0.0, "note": "", "updated_by": "", "updated_iso": ""}
                continue
            _spec.setdefault("enabled", True)
            _spec.setdefault("bias", 0.0)
            _spec.setdefault("drift_per_hr", 0.0)
            _spec.setdefault("note", "")
            _spec.setdefault("updated_by", "")
            _spec.setdefault("updated_iso", "")

        static_art = blk.get("static_artifacts")
        if not isinstance(static_art, dict):
            static_art = sess.get("static_artifacts") if isinstance(sess.get("static_artifacts"), dict) else {}
        if not isinstance(static_art, dict):
            static_art = {}
        site_photos = static_art.get("site_photos")
        if not isinstance(site_photos, list):
            site_photos = []
        field_documents = static_art.get("field_documents")
        if not isinstance(field_documents, list):
            field_documents = []
        static_art["site_photos"] = site_photos
        static_art["field_documents"] = field_documents
        blk["static_artifacts"] = static_art
        sess["static_artifacts"] = static_art

        # Worksteps / QAQC captures (operator workflow)
        ws = blk.get("worksteps")
        if not isinstance(ws, dict):
            ws = {}
            blk["worksteps"] = ws

        ws_cfg = ws.get("config")
        if not isinstance(ws_cfg, dict):
            ws_cfg = {}
            ws["config"] = ws_cfg

        # Reasonable defaults (operator can override in UI)
        ws_cfg.setdefault("capture_window_s", 10)
        ws_cfg.setdefault("stability_window_s", 15)
        ws_cfg.setdefault("purge_mult_t90", 2.0)       # ~99% equilibration for 1st-order response (2*T90)
        ws_cfg.setdefault("min_purge_s", 60)
        ws_cfg.setdefault("span_tol_pct", 2.0)         # ±% recovery window
        ws_cfg.setdefault("zero_tol_abs_default", 2.0)  # default abs zero tolerance for ppm-ish channels
        ws_cfg.setdefault("zero_tol_abs_o2", 0.2)      # default abs zero tolerance for O2 (%)
        ws_cfg.setdefault("mdc_mode", "lowest_observed")  # lowest_observed | 3sigma (future)
        ws_cfg.setdefault("apply_mdc_floor", False)

        ws_q = ws.get("qaqc")
        if not isinstance(ws_q, dict):
            ws_q = {}
            ws["qaqc"] = ws_q
        ws_q.setdefault("zero", {})         # per pollutant capture dicts
        ws_q.setdefault("mid", {})          # per pollutant capture dicts (3-pt CAL)
        ws_q.setdefault("span", {})         # per pollutant capture dicts
        ws_q.setdefault("mdc", {})          # per pollutant MDC values
        ws_q.setdefault("response", {})     # per pollutant response time estimates
        ws_q.setdefault("channel_valid", {})  # per pollutant validity flags
        ws_q.setdefault("transitions", {})    # start markers for response calculations

        ws_q.setdefault("post_runs", {})     # per-run post-cal captures (bias/drift checks)
        conv = ws.get("converter_eff")
        if not isinstance(conv, dict):
            conv = {}
            ws["converter_eff"] = conv
        conv.setdefault("applicable", False)
        conv.setdefault("enabled", _nox_converter_enabled(sess))
        conv.setdefault("target", None)
        conv.setdefault("tol_min_pct", 90.0)
        conv.setdefault("tol_max_pct", 110.0)
        conv.setdefault("method_profile", "")
        conv.setdefault("method_basis", "")
        conv.setdefault("procedure", "GENERIC_PERCENT")
        conv.setdefault("criteria_locked", False)
        conv.setdefault("bag_active", False)
        conv.setdefault("bag_start_iso", "")
        conv.setdefault("bag_start_epoch", None)
        conv.setdefault("bag_duration_min", 30.0)
        conv.setdefault("bag_max_drop_pct", 2.0)
        conv.setdefault("last_capture", {})
        conv.setdefault("history", [])
        conv["applicable"] = bool(_derived_nox_applicable(sess))
        if not conv["applicable"]:
            conv["enabled"] = False
            conv["bag_active"] = False

        # Backfill per-run containers for forward-compatible schema
        try:
            for _rn, _pr in (ws_q.get("post_runs") or {}).items():
                if isinstance(_pr, dict):
                    _pr.setdefault("zero", {})
                    _pr.setdefault("mid", {})
                    _pr.setdefault("span", {})
                    _pr.setdefault("channel_valid", {})
                    _pr.setdefault("transitions", {})
        except Exception:
            pass
        # Backfill per-run containers for forward-compatible schema
        try:
            for _rn, _pr in (ws_q.get("post_runs") or {}).items():
                if isinstance(_pr, dict):
                    _pr.setdefault("zero", {})
                    _pr.setdefault("mid", {})
                    _pr.setdefault("span", {})
                    _pr.setdefault("channel_valid", {})
                    _pr.setdefault("transitions", {})
        except Exception:
            pass

        postcal = ws.get("postcal")
        if not isinstance(postcal, dict):
            postcal = {}
            ws["postcal"] = postcal
        postcal.setdefault("required", False)
        postcal.setdefault("run_no", None)
        postcal.setdefault("completed_runs", {})

        ws.setdefault("steps", {})          # step status bookkeeping (future)
        ws.setdefault("events_path", "")
        if not str(ws.get("events_path") or "").strip():
            job = str(
                (sess.get("project") or {}).get("job_id")
                or (sess.get("project_session") or {}).get("job_id")
                or sess.get("job_id")
                or "session"
            ).strip() or "session"
            ws["events_path"] = str(cfg_path.parent / f"mole_worksteps_{job}.jsonl")

        ftir_ws = ws.get("ftir_audit")
        if not isinstance(ftir_ws, dict):
            ftir_ws = {}
            ws["ftir_audit"] = ftir_ws
        if mole_ftir_methods is not None:
            try:
                ftir_ws["method_standard"] = mole_ftir_methods.normalize_method(
                    ftir_ws.get("method_standard") or ref_cfg.get("method_standard")
                )
            except Exception:
                ftir_ws["method_standard"] = mole_ftir_methods.DEFAULT_METHOD
        else:
            ftir_ws["method_standard"] = str(
        ftir_ws.get("method_standard") or ref_cfg.get("method_standard") or "ASTM_D6348_12"
    ).strip() or "ASTM_D6348_12"
        if not isinstance(ftir_ws.get("by_method"), dict):
            ftir_ws["by_method"] = {}

        spike_state = ws.get("spike_recovery")
        if not isinstance(spike_state, dict):
            spike_state = {}
        if mole_spike_recovery is not None:
            try:
                spike_state = mole_spike_recovery.normalize_state(spike_state)
            except Exception:
                pass
        if not isinstance(spike_state, dict):
            spike_state = {"active_phase": "IDLE", "channels": {}, "history": []}
        spike_state.setdefault("active_phase", "IDLE")
        if not isinstance(spike_state.get("channels"), dict):
            spike_state["channels"] = {}
        if not isinstance(spike_state.get("history"), list):
            spike_state["history"] = []
        ws["spike_recovery"] = spike_state

        # Arcade soundtrack (optional)
        try:
            st = sess.get("soundtrack")
            if not isinstance(st, dict):
                st = {}
                sess["soundtrack"] = st
            st.setdefault("enabled", False)
            st.setdefault("volume", 0.20)
            st.setdefault("track", "audio/mole_8bit_theme.wav")
            st.setdefault("auto_mode", "ALWAYS")
        except Exception:
            pass

        # Seed QA/QC workstep targets from project config (non-destructive).
        # This ensures the Worksteps table is populated immediately in both TEST and TRAINING modes.
        try:
            sel = _selected_pollutants(sess)
            pres = _pollutant_prescriptions(sess)
            resolved_by = (((sess.get("pollutants") or {}).get("resolved") or {}).get("resolved_by_analyte") or {})
            cal_pts = int(_cal_points_effective(sess) or 2)

            def _same_target(a: Any, b: Any) -> bool:
                aa = _parse_float(a, default=None)
                bb = _parse_float(b, default=None)
                if aa is None or bb is None:
                    return False
                return abs(float(aa) - float(bb)) <= 1e-9

            for code in sel:
                code_u = str(code or "").strip().upper()
                if not code_u:
                    continue
                p = pres.get(code_u) or {}
                rr = resolved_by.get(code_u) or {}
                auth = _prescription_cal_targets(p, rr if isinstance(rr, dict) else None)

                # ZERO target: this architecture uses 100% N2 zero gas for every channel.
                z = (ws_q.get("zero") or {}).get(code_u)
                if not isinstance(z, dict):
                    z = {}
                    ws_q.setdefault("zero", {})[code_u] = z
                z["target"] = float(auth.get("zero") or 0.0)

                # SPAN target: use only the project-specific wizard inputs, and repair stale
                # suggestion-seeded targets from older sessions when they still match the generic suggestion.
                s = (ws_q.get("span") or {}).get(code_u)
                if not isinstance(s, dict):
                    s = {}
                    ws_q.setdefault("span", {})[code_u] = s
                span_auth = auth.get("span")
                span_cur = _parse_float(s.get("target"), default=None)
                span_sug = _parse_float((rr.get("span_suggestion") if isinstance(rr, dict) else None), default=None)
                if span_auth is not None:
                    if span_cur is None or _same_target(span_cur, span_sug):
                        s["target"] = float(span_auth)

                # MID target (3-pt CAL)
                if cal_pts >= 3:
                    m = (ws_q.get("mid") or {}).get(code_u)
                    if not isinstance(m, dict):
                        m = {}
                        ws_q.setdefault("mid", {})[code_u] = m
                    mid_auth = auth.get("mid")
                    mid_cur = _parse_float(m.get("target"), default=None)
                    mid_sug = _parse_float((rr.get("mid_suggestion") if isinstance(rr, dict) else None), default=None)
                    if mid_auth is not None:
                        if mid_cur is None or _same_target(mid_cur, mid_sug):
                            m["target"] = float(mid_auth)

                # Default channel validity
                ws_q.setdefault("channel_valid", {})
                if code_u not in ws_q["channel_valid"]:
                    ws_q["channel_valid"][code_u] = True
        except Exception:
            pass



        return blk

    def _side_by_side_block(sess: Dict[str, Any]) -> Dict[str, Any]:
        _ensure_daq_schema(sess)
        daq = sess.get("daq_runner") if isinstance(sess.get("daq_runner"), dict) else {}
        side = daq.get("side_by_side")
        if not isinstance(side, dict):
            side = {}
            daq["side_by_side"] = side
            sess["daq_runner"] = daq
        return side

    def _side_bias_schedule(sess: Dict[str, Any], run_no: Optional[int] = None) -> Dict[str, Any]:
        side = _side_by_side_block(sess)
        daq = sess.get("daq_runner") if isinstance(sess.get("daq_runner"), dict) else {}
        if run_no is None:
            try:
                runs = daq.get("runs") if isinstance(daq.get("runs"), list) else []
                idx = int(daq.get("active_run_index") or 0)
                idx = max(0, min(idx, len(runs) - 1))
                run = runs[idx] if runs and 0 <= idx < len(runs) and isinstance(runs[idx], dict) else {}
                run_no = int(run.get("run_no") or (idx + 1)) if run else None
            except Exception:
                run_no = None
        planned_min, source = _tm_planned_run_minutes(sess, run_no)
        if planned_min is None:
            planned_min = float(_parse_float(side.get("bias_valve_interval_min"), default=20.0) or 20.0)
            source = "SIDE_BY_SIDE"
        source_label = {
            "TEST_MATRIX_RUN": "TEST_MATRIX_RUN",
            "TEST_MATRIX": "TEST_MATRIX",
            "SIDE_BY_SIDE": "SIDE_BY_SIDE",
            "NONE": "SIDE_BY_SIDE",
        }.get(str(source or "").strip().upper(), "SIDE_BY_SIDE")
        if source_label in ("TEST_MATRIX_RUN", "TEST_MATRIX"):
            sched_txt = f"Bias after each run ({_fmt_minutes_m(float(planned_min))} planned from Test Matrix)"
        else:
            sched_txt = f"Bias every {_fmt_minutes_m(float(planned_min))}"
        due_run_no = side.get("bias_due_after_run_no")
        try:
            due_run_no_i = int(due_run_no) if due_run_no not in (None, "") else None
        except Exception:
            due_run_no_i = None
        due_iso = str(side.get("bias_due_after_iso") or "").strip()
        return {
            "run_no": run_no,
            "planned_minutes": float(planned_min),
            "source": source_label,
            "schedule_label": sched_txt,
            "bias_due": bool(due_run_no_i is not None),
            "bias_due_after_run_no": due_run_no_i,
            "bias_due_after_iso": due_iso,
        }

    def _side_bias_gate(sess: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        side = _side_by_side_block(sess)
        daq = sess.get("daq_runner") if isinstance(sess.get("daq_runner"), dict) else {}
        ref = daq.get("reference_audit") if isinstance(daq.get("reference_audit"), dict) else {}
        events = side.get("events") if isinstance(side.get("events"), list) else []
        if not (bool(ref.get("enabled")) or bool(side.get("enabled")) or bool(events)):
            return None
        sched = _side_bias_schedule(sess)
        if not bool(sched.get("bias_due")):
            return None
        return sched

    def _now_iso_local() -> str:
        try:
            return datetime.now().astimezone().isoformat(timespec="seconds")
        except Exception:
            return _now_iso()

    # -------------------------------
    # Extractors (config -> display)
    # -------------------------------

    def _selected_pollutants(sess: Dict[str, Any]) -> list[str]:
        poll = sess.get("pollutants") or {}
        sel = poll.get("selected") or []
        out = []
        for x in sel:
            s = str(x or "").strip().upper()
            if s:
                out.append(s)
        return out

    def _derived_nox_applicable(sess: Dict[str, Any]) -> bool:
        sel = set(_selected_pollutants(sess))
        return ("NO" in sel) and ("NO2" in sel)

    def _display_selected_pollutants(sess: Dict[str, Any]) -> list[str]:
        out = list(_selected_pollutants(sess))
        if _derived_nox_applicable(sess) and "NOX" not in out:
            if "NO2" in out:
                idx = out.index("NO2") + 1
                out.insert(idx, "NOX")
            elif "NO" in out:
                idx = out.index("NO") + 1
                out.insert(idx, "NOX")
            else:
                out.append("NOX")
        return out

    def _augment_prescriptions_with_derived_nox(sess: Dict[str, Any], pres: Dict[str, Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
        out: Dict[str, Dict[str, Any]] = {}
        try:
            out = {str(k).strip().upper(): (dict(v) if isinstance(v, dict) else {}) for k, v in (pres or {}).items()}
        except Exception:
            out = {}
        if not _derived_nox_applicable(sess):
            return out
        if "NOX" in out and isinstance(out.get("NOX"), dict):
            return out
        seed = out.get("NO") or out.get("NO2") or {}
        units = str((seed or {}).get("expected_units") or (seed or {}).get("units") or "ppm").strip() or "ppm"
        out["NOX"] = {
            "enabled": True,
            "units": units,
            "expected_units": units,
            "channel_id": "NOX",
            "instrument_channel": "NOX_DERIVED",
            "notes": "Derived live NOx = NO + NO2 for runner display and FTIR comparison.",
        }
        return out

    def _augment_frame_with_derived_nox(frame: Dict[str, Any]) -> Dict[str, Any]:
        if not isinstance(frame, dict):
            return frame
        out = dict(frame)
        try:
            no_v = _parse_float(out.get("NO"))
            no2_v = _parse_float(out.get("NO2"))
            if no_v is not None and no2_v is not None:
                out["NOX"] = round(float(no_v) + float(no2_v), 6)
                derived = out.get("_derived_pollutants")
                if not isinstance(derived, dict):
                    derived = {}
                derived["NOX"] = {"formula": "NO + NO2", "components": ["NO", "NO2"]}
                out["_derived_pollutants"] = derived
        except Exception:
            pass
        return out

    def _nox_converter_enabled(sess: Dict[str, Any]) -> bool:
        if not _derived_nox_applicable(sess):
            return False
        try:
            qa = sess.get("qa_qc") or {}
            if bool(qa.get("nox_converter_eff_enabled")):
                return True
            opts = qa.get("secondary_test_options") if isinstance(qa.get("secondary_test_options"), dict) else {}
            if bool(opts.get("CONVERTER_EFF")):
                return True
            req = qa.get("secondary_required_tests") or []
            return "CONVERTER_EFF" in [str(x or "").strip().upper() for x in req]
        except Exception:
            return False

    _CONVERTER_EFF_PROCEDURE_LABELS = {
        "GENERIC_PERCENT": "Generic Percent Check",
        "DIRECT_NO2_CYLINDER": "EPA 7E Direct NO2 Cylinder",
        "ALT_BAG_30MIN": "EPA 7E Alt. Bag (30 min)",
    }

    def _converter_eff_procedure_label(proc: Any) -> str:
        code = str(proc or "").strip().upper()
        return _CONVERTER_EFF_PROCEDURE_LABELS.get(code, code or "Generic Percent Check")

    def _converter_eff_procedure_from_display(value: Any) -> str:
        text = str(value or "").strip()
        if not text:
            return "GENERIC_PERCENT"
        if text in _CONVERTER_EFF_PROCEDURE_LABELS:
            return text
        for code, label in _CONVERTER_EFF_PROCEDURE_LABELS.items():
            if text == label:
                return code
        text_u = text.upper()
        for code, label in _CONVERTER_EFF_PROCEDURE_LABELS.items():
            if text_u == label.upper():
                return code
        return text_u

    def _converter_eff_method_profile(sess: Dict[str, Any]) -> Dict[str, Any]:
        generic = {
            "code": "GENERIC_NOX",
            "label": "Generic NOx Converter Check",
            "basis": "Project-defined converter efficiency check using derived NOx = NO + NO2 and user-defined percent acceptance limits.",
            "default_procedure": "GENERIC_PERCENT",
            "procedures": ["GENERIC_PERCENT"],
            "direct_min_eff_pct": None,
            "direct_max_eff_pct": None,
            "bag_duration_min": None,
            "bag_max_drop_pct": None,
        }
        if not _derived_nox_applicable(sess):
            return generic
        try:
            qa = sess.get("qa_qc") or {}
            poll = sess.get("pollutants") or {}
            resolved = poll.get("resolved") if isinstance(poll.get("resolved"), dict) else {}
            resolved_by_analyte = resolved.get("resolved_by_analyte") if isinstance(resolved.get("resolved_by_analyte"), dict) else {}
            method_map = resolved.get("method_map") if isinstance(resolved.get("method_map"), dict) else (qa.get("method_map") if isinstance(qa.get("method_map"), dict) else {})
            profile_map = resolved.get("profile_map") if isinstance(resolved.get("profile_map"), dict) else (qa.get("profile_map") if isinstance(qa.get("profile_map"), dict) else {})
            candidates: List[str] = []
            for code in ("NO", "NO2", "NOX"):
                row = resolved_by_analyte.get(code) if isinstance(resolved_by_analyte.get(code), dict) else {}
                for key in ("profile_id", "method_effective", "method_selected", "method_recommended"):
                    val = str(row.get(key) or "").strip()
                    if val:
                        candidates.append(val.upper())
                for mapping in (method_map, profile_map):
                    val = str((mapping or {}).get(code) or "").strip()
                    if val:
                        candidates.append(val.upper())
            for key in ("method_id", "profile_effective"):
                val = str(qa.get(key) or "").strip()
                if val:
                    candidates.append(val.upper())
            joined = " ".join(candidates)
            if "EPA_7E" in joined:
                return {
                    "code": "EPA_7E_NOX",
                    "label": "EPA Method 7E NO2-to-NO Conversion Efficiency",
                    "basis": (
                        "EPA Method 7E Sections 8.2.4, 13.5, and 16.2.2 apply. "
                        "Direct converter efficiency must be >= 90 percent. "
                        "The 30-minute bag alternative must not decrease more than 2.0 percent absolute from NOxPeak. "
                        "Due to EPA protocol-gas stability guidance for NO2, the bag alternative is the default workflow."
                    ),
                    "default_procedure": "ALT_BAG_30MIN",
                    "procedures": ["ALT_BAG_30MIN", "DIRECT_NO2_CYLINDER"],
                    "direct_min_eff_pct": 90.0,
                    "direct_max_eff_pct": None,
                    "bag_duration_min": 30.0,
                    "bag_max_drop_pct": 2.0,
                }
        except Exception:
            pass
        return generic

    def _converter_eff_criteria_text(conv: Dict[str, Any], profile: Optional[Dict[str, Any]] = None) -> str:
        profile = profile if isinstance(profile, dict) else {}
        proc = str(conv.get("procedure") or "").strip().upper()
        if proc == "ALT_BAG_30MIN":
            dur_min = _parse_float(conv.get("bag_duration_min"), default=_parse_float(profile.get("bag_duration_min"), default=30.0))
            max_drop = _parse_float(conv.get("bag_max_drop_pct"), default=_parse_float(profile.get("bag_max_drop_pct"), default=2.0))
            return f"Drop <= {_fmt_num(max_drop, 1, '2.0')}% after {_fmt_num(dur_min, 0, '30')} min"
        if proc == "DIRECT_NO2_CYLINDER" and str(profile.get("code") or "").strip().upper() == "EPA_7E_NOX":
            min_eff = _parse_float(conv.get("tol_min_pct"), default=_parse_float(profile.get("direct_min_eff_pct"), default=90.0))
            return f"EffNO2 >= {_fmt_num(min_eff, 1, '90.0')}%"
        tol_min = _parse_float(conv.get("tol_min_pct"), default=90.0)
        tol_max = _parse_float(conv.get("tol_max_pct"), default=110.0)
        return f"{_fmt_num(tol_min, 1, '90.0')}% to {_fmt_num(tol_max, 1, '110.0')}%"


    def _cal_points_effective(sess: Dict[str, Any]) -> int:
        """Return effective CAL point count (2 or 3) for this session."""
        # Prefer resolved policy from the wizard
        try:
            qa = sess.get("qa_qc") or {}
            pp = qa.get("points_policy") or {}
            v = pp.get("cal_points_effective")
            if v:
                return int(v)
        except Exception:
            pass

        # Fallback: Test Matrix CAL test
        try:
            tm = sess.get("test_matrix") or {}
            for t in (tm.get("tests") or []):
                if str(t.get("id") or "").upper() == "CAL":
                    v = t.get("points") or t.get("pts") or t.get("points_expected")
                    if v:
                        return int(v)
        except Exception:
            pass

        # Last-resort: QA/QC global default
        try:
            qa = sess.get("qa_qc") or {}
            v = qa.get("cal_points")
            if v:
                return int(v)
        except Exception:
            pass

        return 2

    def _mid_fraction_from_resolved_row(row: Any) -> float:
        frac = _parse_float((row or {}).get("mid_fraction"), default=0.5) if isinstance(row, dict) else 0.5
        try:
            frac_f = float(frac)
        except Exception:
            return 0.5
        return frac_f if 0.0 < frac_f < 1.0 else 0.5

    def _prescription_cal_targets(pres_row: Dict[str, Any], resolved_row: Optional[Dict[str, Any]] = None) -> Dict[str, Optional[float]]:
        span_target = _parse_float((pres_row or {}).get("span_target"), default=None)
        if span_target is None:
            span_target = _parse_float((pres_row or {}).get("span_cylinder_id"), default=None)

        mid_target = _parse_float((pres_row or {}).get("mid_target"), default=None)
        if mid_target is None:
            mid_target = _parse_float((pres_row or {}).get("mid_cylinder_id"), default=None)
        if mid_target is None and span_target is not None:
            mid_target = float(span_target) * _mid_fraction_from_resolved_row(resolved_row)

        return {
            "zero": 0.0,
            "mid": float(mid_target) if mid_target is not None else None,
            "span": float(span_target) if span_target is not None else None,
        }
    def _pollutant_prescriptions(sess: Dict[str, Any]) -> Dict[str, Dict[str, Any]]:
        """Return pollutant prescription dict keyed by pollutant code (upper-case).

        Also normalizes common fields used by the DAQ runner UI (e.g., units).
        """
        poll = sess.get("pollutants") or {}
        pres = poll.get("prescriptions") or {}
        resolved_by = (((poll.get("resolved") or {}).get("resolved_by_analyte") or {}) if isinstance(poll, dict) else {})
        out: Dict[str, Dict[str, Any]] = {}
        if isinstance(pres, dict):
            for k, v in pres.items():
                kk = str(k or "").strip().upper()
                if not kk:
                    continue
                vv: Dict[str, Any] = dict(v) if isinstance(v, dict) else {}

                # Normalize units:
                # Prefer explicit 'units' (wizard), then 'expected_units' (schema),
                # then a conservative heuristic.
                units = str(vv.get("units") or vv.get("expected_units") or vv.get("unit") or "").strip()
                if not units:
                    if kk in ("O2", "CO2", "H2O", "RH"):
                        units = "%"
                    else:
                        units = "ppm"
                vv["units"] = units
                targets = _prescription_cal_targets(vv, resolved_by.get(kk) if isinstance(resolved_by, dict) else None)
                vv["zero_target"] = targets["zero"]
                vv["mid_target"] = targets["mid"]
                vv["span_target"] = targets["span"]
                out[kk] = vv
        return out

    def _limits_by_pollutant(sess: Dict[str, Any]) -> Dict[str, list[Dict[str, Any]]]:
        reg = sess.get("regulatory") or {}
        lims = reg.get("limits") or []
        out: Dict[str, list[Dict[str, Any]]] = {}
        if isinstance(lims, list):
            for r in lims:
                if not isinstance(r, dict):
                    continue
                p = str(r.get("pollutant") or "").strip().upper()
                if not p:
                    continue
                out.setdefault(p, []).append(r)
        return out

    def _fuel_combustion(sess: Dict[str, Any]) -> Dict[str, Any]:
        """Return the combustion-model dict used for Method 19 crosswalk / moisture estimation.

        The wizard typically stores a pre-computed combustion model into the session.
        However, SIM sessions (and some older configs) may not include that model.

        In those cases, we build a *minimal* combustion model using EPA Method 19
        Table 19-2 average F-factors (Fd/Fw/Fc) plus typical HHV defaults.

        This fallback is intentionally conservative: it enables the Method 19
        crosswalk (Qd↔R↔Qf) and moisture estimation, but it should be replaced by
        a project-specific fuel analysis whenever available.
        """
        fuel = sess.get("fuel") or {}
        analysis = fuel.get("analysis") or {}
        comb = analysis.get("combustion") or analysis.get("combustion_model") or {}
        if isinstance(comb, dict) and comb:
            return comb

        # --- Fallback: build a minimal combustion model from fuel selection ---
        # EPA Method 19 Table 19-2 average F-factors (scf/10^6 Btu).
        # Values shown here are the *US customary* columns (dscf/10^6 Btu etc).
        EPA_M19_F: Dict[str, Dict[str, float]] = {
            # Gas
            "NATURAL": {"Fd": 8710.0, "Fw": 10610.0, "Fc": 1040.0},
            "PROPANE": {"Fd": 8710.0, "Fw": 10200.0, "Fc": 1190.0},
            "BUTANE": {"Fd": 8710.0, "Fw": 10390.0, "Fc": 1250.0},
            # Oil (crude, residual, or distillate)
            "OIL": {"Fd": 9190.0, "Fw": 10320.0, "Fc": 1420.0},
            # Wood (Fw not provided in the EPA table)
            "WOOD": {"Fd": 9240.0, "Fw": None, "Fc": 1830.0},
        }

        # Typical HHV defaults (only used if session combustion model is missing).
        # These are *placeholders* until a project-specific fuel analysis is applied.
        HHV_DEFAULTS: Dict[str, Dict[str, float]] = {
            "NATURAL": {"HHV_Btu_scf": 1020.0},
            "PROPANE": {"HHV_Btu_scf": 2516.0},
            "BUTANE": {"HHV_Btu_scf": 3260.0},
            "OIL": {"HHV_Btu_gal": 140000.0},
            "WOOD": {"HHV_Btu_lb": 8600.0},
        }

        fuel_code = str(
            fuel.get("fuel_button_code")
            or fuel.get("fuel_code")
            or fuel.get("code")
            or fuel.get("fuel_type")
            or ""
        ).strip().upper()
        fuel_cat = str(
            fuel.get("fuel_category")
            or fuel.get("category")
            or fuel.get("fuel")
            or ""
        ).strip().upper()

        tag = f"{fuel_code} {fuel_cat}".strip()

        key: Optional[str] = None
        family = ""
        if any(k in tag for k in ["NATURAL", "NG"]):
            key = "NATURAL"
            family = "NG"
        elif "PROPANE" in tag:
            key = "PROPANE"
            family = "GAS"
        elif "BUTANE" in tag:
            key = "BUTANE"
            family = "GAS"
        elif any(k in tag for k in ["OIL", "DIESEL", "DISTILLATE", "RESIDUAL", "GASOLINE"]):
            key = "OIL"
            family = "LIQUID"
        elif "WOOD" in tag:
            key = "WOOD"
            family = "SOLID"
        else:
            # Unknown fuel category: leave combustion model empty.
            return {}

        f = EPA_M19_F.get(key) or {}
        h = HHV_DEFAULTS.get(key) or {}

        # Derive baseline mol fractions from F-factors.
        # CO2_dry ~ Fc/Fd, CO2_wet ~ Fc/Fw, H2O_wet ~ 1 - Fd/Fw.
        dry_mol: Dict[str, float] = {}
        wet_mol: Dict[str, float] = {}
        try:
            fd = float(f.get("Fd")) if f.get("Fd") is not None else None
            fw = float(f.get("Fw")) if f.get("Fw") is not None else None
            fc = float(f.get("Fc")) if f.get("Fc") is not None else None

            if fd and fc:
                dry_mol["CO2"] = max(0.0, min(1.0, fc / fd))
            # Stoichiometric baseline (no excess air) oxygen is ~0 on a dry basis.
            dry_mol["O2"] = 0.0

            if fw and fc:
                wet_mol["CO2"] = max(0.0, min(1.0, fc / fw))
            if fw and fd:
                wet_mol["H2O"] = max(0.0, min(0.35, 1.0 - fd / fw))
        except Exception:
            pass

        comb_fallback: Dict[str, Any] = {
            "family": family,
            "source": "EPA_M19_TABLE19_2_DEFAULTS",
            "Fd_HHV_dscf_per_MMBtu": f.get("Fd"),
            "Fw_HHV_wscf_per_MMBtu": f.get("Fw"),
            "Fc_HHV_scfCO2_per_MMBtu": f.get("Fc"),
            "dry_mol_fracs": dry_mol,
            "wet_mol_fracs": wet_mol,
        }
        comb_fallback.update(h)
        return comb_fallback

    def _estimate_h2o_wet_frac(
        sess: Dict[str, Any],
        o2_meas_pct: Optional[float] = None,
        co2_meas_pct: Optional[float] = None,
        co_meas_pct: Optional[float] = None,
    ) -> Optional[float]:
        """Estimate stack H2O wet mol fraction from fuel-theoretical stoichiometry and measured dry O2/CO2.

        This is an approximation intended for operator guidance / normalization (e.g., Method 19 helpers).
        It is not a regulatory proof or substitute for compliant moisture testing.

        Model:
          - Start from fuel-theoretical wet H2O mol fraction at stoichiometric combustion.
          - Infer excess-air dilution from measured dry O2 and/or dry CO2.
          - Dilution adds (O2 + 3.761 N2) per extra O2 mol (air basis).

        Notes:
          - If CO is materially non-zero (in %), CO2-based inference is de-weighted.
        """
        comb = _fuel_combustion(sess) or {}
        wet_fr = comb.get("wet_mol_fracs") or {}
        dry_fr = comb.get("dry_mol_fracs") or {}

        base_h2o = None
        if isinstance(wet_fr, dict):
            base_h2o = _parse_float(wet_fr.get("H2O"))
        if base_h2o is None or base_h2o <= 0 or base_h2o >= 0.95:
            return None

        n_h2o0 = float(base_h2o)
        n_dry0 = 1.0 - n_h2o0
        if n_dry0 <= 1e-9:
            return base_h2o

        k = 4.761  # 1 O2 + 3.761 N2

        def _delta_from_o2(o2pct: float) -> Optional[float]:
            try:
                y = max(0.0, min(0.209, float(o2pct) / 100.0))
                denom = 1.0 - y * k
                if denom <= 1e-9:
                    return None
                return (y * n_dry0) / denom
            except Exception:
                return None

        def _delta_from_co2(co2pct: float) -> Optional[float]:
            try:
                z = max(1e-6, min(0.25, float(co2pct) / 100.0))
                base_co2_dry = None
                if isinstance(dry_fr, dict):
                    base_co2_dry = _parse_float(dry_fr.get("CO2"))
                if base_co2_dry is None or base_co2_dry <= 0 or base_co2_dry >= 0.95:
                    return None

                # At stoich (scaled wet_total=1), dry_total = n_dry0 and CO2_moles = CO2_dry_frac * n_dry0
                n_co2_0 = float(base_co2_dry) * n_dry0
                total_dry = n_co2_0 / z
                delta = (total_dry - n_dry0) / k
                if delta < 0:
                    delta = 0.0
                return delta
            except Exception:
                return None

        d_o2 = _delta_from_o2(o2_meas_pct) if o2_meas_pct is not None else None
        d_co2 = _delta_from_co2(co2_meas_pct) if co2_meas_pct is not None else None

        # If CO is materially non-zero, CO2 can be biased low (carbon split into CO), so de-weight CO2.
        co_bias = False
        try:
            if co_meas_pct is not None and float(co_meas_pct) >= 0.1:
                co_bias = True
        except Exception:
            pass

        if d_o2 is None and d_co2 is None:
            return base_h2o

        if d_o2 is not None and (d_co2 is None or co_bias):
            delta = d_o2
        elif d_o2 is None and d_co2 is not None:
            delta = d_co2
        else:
            # Blend, favor O2 (typically more robust in field service)
            delta = 0.7 * float(d_o2) + 0.3 * float(d_co2)

        wet_total = 1.0 + k * float(delta)
        if wet_total <= 1e-9:
            return base_h2o

        est = n_h2o0 / wet_total
        return max(0.0, min(0.95, est))


    def _wet_to_dry_factor(h2o_wet_frac: Optional[float]) -> Optional[float]:
        if h2o_wet_frac is None:
            return None
        try:
            f = float(h2o_wet_frac)
            if f <= 0:
                return 1.0
            if f >= 0.95:
                return None
            return 1.0 / (1.0 - f)
        except Exception:
            return None

    # -------------------------------
    # Exhaust/Fuel crosswalk (Method 19 solver)
    # -------------------------------

    def _canon_units(u: Any) -> str:
        return str(u or "").strip().lower().replace(" ", "").replace("/", "_")

    def _unit_kind(u: Any) -> Optional[str]:
        uu = _canon_units(u)
        if not uu:
            return None
        if "mmbtu" in uu or uu in ("mmbtu_hr", "mmbtu_h", "mmbtu_per_hr", "mmbtuh"):
            return "mmbtu"
        if "scf" in uu or uu in ("scfh", "scfm", "scfd"):
            return "scf"
        if "gal" in uu or uu in ("gph", "gpm", "gpd", "gal_hr", "gal_h", "galperhr"):
            return "gal"
        if "lb" in uu or uu in ("lbhr", "lb_hr", "lb_h", "lbmin", "lb_min", "lbday", "lb_day"):
            return "lb"
        return None

    def _rate_to_per_hr(value: Optional[float], units: Any) -> Optional[float]:
        if value is None:
            return None
        u = _canon_units(units)
        if not u:
            return float(value)
        try:
            v = float(value)
        except Exception:
            return None

        # per-hour harmonization
        if u in ("scfh", "scf_hr", "scf_h", "scfperhr"):
            return v
        if u in ("scfm", "scf_min", "scf_m", "scfpermin"):
            return v * 60.0
        if u in ("scfd", "scf_day", "scf_d", "scfperday"):
            return v / 24.0

        if u in ("gph", "gal_hr", "gal_h", "galperhr"):
            return v
        if u in ("gpm", "gal_min", "gal_m", "galpermin"):
            return v * 60.0
        if u in ("gpd", "gal_day", "gal_d", "galperday"):
            return v / 24.0

        if u in ("lbhr", "lb_hr", "lb_h", "lbperhr"):
            return v
        if u in ("lbmin", "lb_min", "lb_m", "lbpermin"):
            return v * 60.0
        if u in ("lbday", "lb_day", "lb_d", "lbperday"):
            return v / 24.0

        if u in ("mmbtu_hr", "mmbtu_h", "mmbtuperhr", "mmbtuh"):
            return v

        # fall back: treat as already per-hr
        return v

    def _per_hr_to_units(value_per_hr: Optional[float], units: Any) -> Optional[float]:
        if value_per_hr is None:
            return None
        u = _canon_units(units)
        try:
            v = float(value_per_hr)
        except Exception:
            return None

        if not u:
            return v

        if u in ("scfh", "scf_hr", "scf_h", "scfperhr"):
            return v
        if u in ("scfm", "scf_min", "scf_m", "scfpermin"):
            return v / 60.0
        if u in ("scfd", "scf_day", "scf_d", "scfperday"):
            return v * 24.0

        if u in ("gph", "gal_hr", "gal_h", "galperhr"):
            return v
        if u in ("gpm", "gal_min", "gal_m", "galpermin"):
            return v / 60.0
        if u in ("gpd", "gal_day", "gal_d", "galperday"):
            return v * 24.0

        if u in ("lbhr", "lb_hr", "lb_h", "lbperhr"):
            return v
        if u in ("lbmin", "lb_min", "lb_m", "lbpermin"):
            return v / 60.0
        if u in ("lbday", "lb_day", "lb_d", "lbperday"):
            return v * 24.0

        if u in ("mmbtu_hr", "mmbtu_h", "mmbtuperhr", "mmbtuh"):
            return v

        return v

    def _o2_factor(o2_dry_pct: Optional[float]) -> Optional[float]:
        try:
            if mole_spec_engine is not None and hasattr(mole_spec_engine, "method19_o2_factor"):
                return mole_spec_engine.method19_o2_factor(o2_dry_pct)
        except Exception:
            pass
        if o2_dry_pct is None:
            return None
        try:
            o2 = float(o2_dry_pct)
        except Exception:
            return None
        if o2 < 0:
            o2 = 0.0
        if o2 >= 20.9:
            return None
        denom = 20.9 - o2
        if denom <= 1e-9:
            return None
        return 20.9 / denom

    def _pick_fd(comb: Dict[str, Any]) -> Optional[float]:
        try:
            if mole_spec_engine is not None and hasattr(mole_spec_engine, "method19_pick_fd"):
                return mole_spec_engine.method19_pick_fd(comb)
        except Exception:
            pass
        if not isinstance(comb, dict):
            return None
        for k in ("F_selected", "Fd_sel_dscf_per_MMBtu", "F_HHV", "Fd_HHV_dscf_per_MMBtu"):
            v = _parse_float(comb.get(k))
            if v is not None and v > 0:
                return float(v)
        return None

    def _pick_heat_value(comb: Dict[str, Any], kind: Optional[str]) -> tuple[Optional[float], Optional[str], Optional[str]]:
        """Return (heating value, base kind, basis code) aligned to the selected F-factor basis."""
        try:
            if mole_spec_engine is not None and hasattr(mole_spec_engine, "method19_pick_heat_value"):
                return mole_spec_engine.method19_pick_heat_value(comb, kind)
        except Exception:
            pass
        if not isinstance(comb, dict):
            return None, None, None

        basis = str(comb.get("basis_sel") or "HHV").strip().upper()
        value_key_map = {
            "HHV": {
                "scf": "HHV_Btu_scf",
                "gal": "HHV_Btu_gal",
                "lb": "HHV_Btu_lb",
            },
            "LHV": {
                "scf": "LHV_Btu_scf",
                "gal": "LHV_Btu_gal",
                "lb": "LHV_Btu_lb",
            },
        }

        requested = value_key_map.get(basis) or value_key_map["HHV"]
        opposite_basis = "LHV" if basis == "HHV" else "HHV"
        opposite = value_key_map.get(opposite_basis) or {}

        # honor the requested kind first, using the selected basis
        if kind in requested:
            v = _parse_float(comb.get(requested[kind]))
            if v is not None and v > 0:
                return float(v), kind, basis
            # If the selected basis is unavailable, fall back to the opposite basis rather than dropping out.
            v = _parse_float(comb.get(opposite.get(kind)))
            if v is not None and v > 0:
                return float(v), kind, opposite_basis

        # fallback preference by fuel family
        fam = str(comb.get("family") or "").strip().upper()
        if fam in ("GAS", "NG", "NATURAL_GAS"):
            v = _parse_float(comb.get(requested["scf"]))
            if v is not None and v > 0:
                return float(v), "scf", basis
        if fam in ("LIQUID", "OIL", "DIESEL", "GASOLINE"):
            v = _parse_float(comb.get(requested["gal"]))
            if v is not None and v > 0:
                return float(v), "gal", basis
        # last resorts: selected basis first, then opposite basis
        for k, kk in ((requested["scf"], "scf"), (requested["gal"], "gal"), (requested["lb"], "lb"),
                      (opposite.get("scf"), "scf"), (opposite.get("gal"), "gal"), (opposite.get("lb"), "lb")):
            if not k:
                continue
            v = _parse_float(comb.get(k))
            if v is not None and v > 0:
                use_basis = basis if k in requested.values() else opposite_basis
                return float(v), kk, use_basis
        return None, None, None

    def _method19_heat_input_from_fuel_flow(rate_per_hr: Optional[float], heating_value_btu_per_unit: Optional[float]) -> Optional[float]:
        try:
            if mole_spec_engine is not None and hasattr(mole_spec_engine, "method19_heat_input_from_fuel_flow"):
                return mole_spec_engine.method19_heat_input_from_fuel_flow(rate_per_hr, heating_value_btu_per_unit)
        except Exception:
            pass
        try:
            if rate_per_hr is None or heating_value_btu_per_unit is None:
                return None
            rate = float(rate_per_hr)
            heating_value = float(heating_value_btu_per_unit)
            if rate <= 0 or heating_value <= 0:
                return None
            return (rate * heating_value) / 1_000_000.0
        except Exception:
            return None

    def _method19_qd_from_heat_input(
        heat_input_mmbtu_hr: Optional[float],
        fd_dscf_per_mmbtu: Optional[float],
        *,
        o2_dry_pct: Optional[float] = None,
        o2_factor_value: Optional[float] = None,
    ) -> Optional[float]:
        try:
            if mole_spec_engine is not None and hasattr(mole_spec_engine, "method19_qd_from_heat_input"):
                return mole_spec_engine.method19_qd_from_heat_input(
                    heat_input_mmbtu_hr,
                    fd_dscf_per_mmbtu,
                    o2_dry_pct=o2_dry_pct,
                    o2_factor=o2_factor_value,
                )
        except Exception:
            pass
        try:
            heat_input = float(heat_input_mmbtu_hr) if heat_input_mmbtu_hr is not None else None
            fd_val = float(fd_dscf_per_mmbtu) if fd_dscf_per_mmbtu is not None else None
            fac_val = float(o2_factor_value) if o2_factor_value is not None else _o2_factor(o2_dry_pct)
            if heat_input is None or fd_val is None or fac_val is None:
                return None
            if heat_input <= 0 or fd_val <= 0 or fac_val <= 0:
                return None
            return heat_input * fd_val * fac_val
        except Exception:
            return None

    def _method19_heat_input_from_qd(
        qd_dscfh: Optional[float],
        fd_dscf_per_mmbtu: Optional[float],
        *,
        o2_dry_pct: Optional[float] = None,
        o2_factor_value: Optional[float] = None,
    ) -> Optional[float]:
        try:
            if mole_spec_engine is not None and hasattr(mole_spec_engine, "method19_heat_input_from_qd"):
                return mole_spec_engine.method19_heat_input_from_qd(
                    qd_dscfh,
                    fd_dscf_per_mmbtu,
                    o2_dry_pct=o2_dry_pct,
                    o2_factor=o2_factor_value,
                )
        except Exception:
            pass
        try:
            qd_val = float(qd_dscfh) if qd_dscfh is not None else None
            fd_val = float(fd_dscf_per_mmbtu) if fd_dscf_per_mmbtu is not None else None
            fac_val = float(o2_factor_value) if o2_factor_value is not None else _o2_factor(o2_dry_pct)
            if qd_val is None or fd_val is None or fac_val is None:
                return None
            denom = fd_val * fac_val
            if qd_val <= 0 or denom <= 0:
                return None
            return qd_val / denom
        except Exception:
            return None

    def _method19_fuel_flow_from_heat_input(
        heat_input_mmbtu_hr: Optional[float],
        heating_value_btu_per_unit: Optional[float],
    ) -> Optional[float]:
        try:
            if mole_spec_engine is not None and hasattr(mole_spec_engine, "method19_fuel_flow_from_heat_input"):
                return mole_spec_engine.method19_fuel_flow_from_heat_input(heat_input_mmbtu_hr, heating_value_btu_per_unit)
        except Exception:
            pass
        try:
            heat_input = float(heat_input_mmbtu_hr) if heat_input_mmbtu_hr is not None else None
            heating_value = float(heating_value_btu_per_unit) if heating_value_btu_per_unit is not None else None
            if heat_input is None or heating_value is None:
                return None
            if heat_input <= 0 or heating_value <= 0:
                return None
            return (heat_input * 1_000_000.0) / heating_value
        except Exception:
            return None

    def _dual_selected_shares(sess: Dict[str, Any], comb: Dict[str, Any]) -> tuple[float, float]:
        liq_share_pct = _parse_float((comb or {}).get("dual_liquid_share_pct_selected"))
        if liq_share_pct is None:
            liq_share_pct = _parse_float((((sess.get("fuel") or {}).get("dg") or {}).get("liquid_fraction_volpct")))
        liq_share_pct = max(0.0, min(100.0, liq_share_pct if liq_share_pct is not None else 0.0))
        liquid_share = liq_share_pct / 100.0
        return 1.0 - liquid_share, liquid_share

    def _acfm_to_dscfh(sess: Dict[str, Any], acfm: Optional[float], t_act_F: Optional[float], p_act_psia: Optional[float]) -> Optional[float]:
        if acfm is None:
            return None
        try:
            q_acfm = float(acfm)
        except Exception:
            return None
        if q_acfm < 0:
            return None
        t_std_F, p_std = _site_std_defaults(sess)
        try:
            t_std_R = float(t_std_F) + 459.67
        except Exception:
            t_std_R = 60.0 + 459.67
        try:
            t_act_R = float(t_act_F if t_act_F is not None else t_std_F) + 459.67
        except Exception:
            t_act_R = t_std_R
        try:
            p_std_psia = float(p_std)
        except Exception:
            p_std_psia = 14.696
        try:
            p_act = float(p_act_psia if p_act_psia is not None else p_std_psia)
        except Exception:
            p_act = p_std_psia

        if t_act_R <= 1e-6 or t_std_R <= 1e-6 or p_std_psia <= 1e-9 or p_act <= 1e-9:
            return None

        # Ideal gas conversion: Q_std = Q_act * (P_act/P_std) * (T_std/T_act)
        q_acfh = q_acfm * 60.0
        return q_acfh * (p_act / p_std_psia) * (t_std_R / t_act_R)


    # --- Stack / duct geometry + Method 2 helpers (used for STACK_MEASURED exhaust flow) ---

    def _to_float(v: Any) -> Optional[float]:
        try:
            if v is None:
                return None
            if isinstance(v, (int, float)):
                return float(v)
            s = str(v).strip()
            if s == "":
                return None
            return float(s)
        except Exception:
            return None

    def _stack_geom(sess: Dict[str, Any]) -> Dict[str, Any]:
        src = sess.get("source") or {}
        st = src.get("stack") or {}
        if not isinstance(st, dict):
            st = {}
        shape = str(st.get("shape") or "ROUND").strip().upper()
        d_in = _to_float(st.get("diameter_in"))
        w_in = _to_float(st.get("width_in"))
        h_in = _to_float(st.get("height_in"))
        upD = _to_float(st.get("upstream_diameters"))
        dnD = _to_float(st.get("downstream_diameters"))
        pitot_type = str(st.get("pitot_type") or "TYPE_S").strip().upper()
        pitot_cp = _to_float(st.get("pitot_cp"))
        if pitot_cp is None:
            pitot_cp = 1.0 if pitot_type.startswith("STANDARD") else 0.84
        tpts = st.get("traverse_points_per_line")
        try:
            tpts_i = int(tpts) if tpts is not None else None
        except Exception:
            tpts_i = None

        de_in: Optional[float] = None
        area_ft2: Optional[float] = None
        if shape.startswith("ROUND"):
            if d_in and d_in > 0:
                de_in = d_in
                area_ft2 = math.pi * ((d_in / 12.0) ** 2) / 4.0
        else:
            if w_in and h_in and w_in > 0 and h_in > 0:
                area_ft2 = (w_in / 12.0) * (h_in / 12.0)
                de_in = (2.0 * w_in * h_in / (w_in + h_in)) if (w_in + h_in) else None

        return {
            "shape": shape,
            "diameter_in": d_in,
            "width_in": w_in,
            "height_in": h_in,
            "De_in": de_in,
            "area_ft2": area_ft2,
            "upstream_D": upD,
            "downstream_D": dnD,
            "pitot_type": pitot_type,
            "pitot_cp": pitot_cp,
            "traverse_points_per_line": tpts_i,
        }

    def _suggest_traverse_points_per_line(
        de_in: Optional[float],
        upstream_D: Optional[float] = None,
        downstream_D: Optional[float] = None,
    ) -> Optional[int]:
        # If location meets common straight-run criteria, allow the minimum 4 pts/line (8 total for circular).
        if upstream_D is not None and downstream_D is not None:
            if upstream_D >= 8.0 and downstream_D >= 2.0:
                return 4

        if de_in is None or de_in <= 0:
            return None
        if de_in < 6.0:
            return 6
        if de_in < 12.0:
            return 8
        if de_in < 24.0:
            return 10
        return 12

    def _method1_offsets_from_wall_frac(points_per_line: Optional[int]) -> List[float]:
        n = points_per_line
        if n is None or n < 4 or (n % 2) != 0:
            return []
        m = n // 2
        out: List[float] = []
        for j in range(1, m + 1):
            # Equal-area annuli; distance from wall as fraction of diameter
            frac = (1.0 - math.sqrt(1.0 - (j - 0.5) / m)) / 2.0
            out.append(frac)
        return out

    def _inh2o_to_psia(inh2o: Optional[float]) -> Optional[float]:
        if inh2o is None:
            return None
        return float(inh2o) * 0.0360912  # psi per inH2O (approx)

    def _inh2o_to_psf(inh2o: Optional[float]) -> Optional[float]:
        if inh2o is None:
            return None
        return float(inh2o) * 5.202  # lb/ft^2 per inH2O (approx)

    def _mw_dry_from_o2_co2(
        o2_dry_pct: Optional[float],
        co2_dry_pct: Optional[float],
        co_dry_pct: Optional[float] = None,
    ) -> Optional[float]:
        """Approximate dry molecular weight (lb/lbmol) from dry O2/CO2/CO balance."""
        if o2_dry_pct is None or co2_dry_pct is None:
            return None
        o2 = max(0.0, min(100.0, float(o2_dry_pct)))
        co2 = max(0.0, min(100.0, float(co2_dry_pct)))
        co = 0.0 if co_dry_pct is None else max(0.0, min(100.0, float(co_dry_pct)))
        n2 = max(0.0, 100.0 - o2 - co2 - co)
        return (o2 * 32.0 + co2 * 44.01 + co * 28.01 + n2 * 28.0134) / 100.0

    def _mw_wet_from_dry(mw_dry: Optional[float], h2o_wet_frac: Optional[float]) -> Optional[float]:
        if mw_dry is None:
            return None
        f = 0.0 if h2o_wet_frac is None else float(h2o_wet_frac)
        f = max(0.0, min(1.0, f))
        return float(mw_dry) * (1.0 - f) + 18.015 * f

    def _pitot_velocity_fps(
        dp_inh2o: Optional[float],
        pitot_cp: Optional[float],
        t_stack_F: Optional[float],
        p_stack_psia: Optional[float],
        mw_wet: Optional[float],
    ) -> Optional[float]:
        if dp_inh2o is None or t_stack_F is None or p_stack_psia is None or mw_wet is None:
            return None
        dp = abs(float(dp_inh2o))
        cp = float(pitot_cp) if pitot_cp is not None else 1.0
        dp_psf = _inh2o_to_psf(dp)
        if dp_psf is None:
            return None
        T_R = float(t_stack_F) + 459.67
        if T_R <= 0:
            return None
        P_psia = float(p_stack_psia)
        if P_psia <= 0:
            return None
        # Ideal gas density: rho(lb/ft3) = (P*MW)/(R*T), R=10.7316 (psia*ft3)/(lbmol*R)
        R_gas = 10.7316
        rho = (P_psia * float(mw_wet)) / (R_gas * T_R)
        if rho <= 0:
            return None
        # Bernoulli (English units): VP(lbf/ft2) = rho(lbm/ft3) * v^2 / (2*gc)
        # so v = sqrt(2*VP*gc/rho).  gc converts between lbm and lbf.
        gc = 32.174  # lbm*ft/(lbf*s^2)
        v = math.sqrt((2.0 * dp_psf * gc) / rho)
        return cp * v


    def _dscfh_to_acfm(sess: dict, q_dscfh: float, t_F: float, p_abs_psia: float) -> float:
        """Inverse of _acfm_to_dscfh.

        Interprets q_dscfh as *standard* volumetric flow (dscfh) at (P_std,T_std).
        Returns *actual* volumetric flow (acfm) at (p_abs_psia,t_F).

        Note: if your q_dscfh is *dry* standard, convert to *wet* standard before calling
        (i.e., q_wet_std = q_dry_std / (1 - y_H2O_wet)).
        """
        try:
            q_dscfh = float(q_dscfh)
            t_F = float(t_F)
            p_abs_psia = float(p_abs_psia)
        except Exception:
            return float('nan')

        if q_dscfh <= 0 or p_abs_psia <= 0:
            return 0.0

        std = _site_std_defaults(sess)
        P_std = float(std.get('P_std_psia') or 14.696)
        T_std_F = float(std.get('T_std_F') or 68.0)
        T_std_R = T_std_F + 459.67
        T_R = t_F + 459.67

        # compressibility (if available) - mirror _acfm_to_dscfh behavior
        z = 1.0
        try:
            sca = (sess.get('site_conditions') or {}).get('active') or {}
            if isinstance(sca, dict) and sca.get('z') is not None:
                z = float(sca.get('z') or 1.0)
        except Exception:
            z = 1.0

        q_dscfm = q_dscfh / 60.0
        q_acfm = q_dscfm * (P_std / p_abs_psia) * (T_R / T_std_R) * z
        return float(q_acfm)

    def _flow_acfm_from_velocity(area_ft2: Optional[float], vel_fps: Optional[float]) -> Optional[float]:
        if area_ft2 is None or vel_fps is None:
            return None
        return float(area_ft2) * float(vel_fps) * 60.0

    def _solve_exhaust_fuel_crosswalk(
        sess: Dict[str, Any],
        method_inputs: Dict[str, Any],
        o2_live_pct: Optional[float],
        site_active: Optional[SiteConditionsActive],
    ) -> Dict[str, Any]:
        """Compute a Method-19-style crosswalk between fuel flow, heat input, and dry standard exhaust flow.

        This implements the relationship sketched by the operator:

            Qd(dscf/hr) = R(MMBtu/hr) * Fd(dscf/MMBtu) * 20.9/(20.9 - O2_dry%)

        The solver supports two primary "directions":
          - STOICH_FUEL: fuel flow -> R -> Qd
          - STACK_MEASURED: stack flow (acfm + T + P) -> Qd -> R -> fuel flow

        Manufacturer mode uses heat input directly when available.
        """
        src = sess.get("source") or {}
        ex = src.get("exhaust_flow") or {}
        raw_method = str(ex.get("method") or "").strip().upper()
        method = _effective_exhaust_flow_method(sess, raw_method)
        comb = _fuel_combustion(sess) or {}

        # O2 used for the crosswalk (prefer method input override, then live)
        o2_src = "LIVE"
        o2_used = _parse_float((method_inputs or {}).get("o2_dry_pct"))
        if o2_used is None:
            o2_used = o2_live_pct
        else:
            o2_src = "RUN_INPUT"
        if o2_used is None:
            o2_used = 0.0
            o2_src = "ASSUMED_0"

        fac = _o2_factor(o2_used)

        fd = _pick_fd(comb)

        # Estimate moisture for wet->dry adjustments (used when stack flow is wet)
        co2_used = _parse_float((method_inputs or {}).get("co2_dry_pct"))
        co_used = _parse_float((method_inputs or {}).get("co_dry_pct"))
        h2o_wet = _estimate_h2o_wet_frac(sess, o2_used, co2_used, co_used)
        dry_fac = _wet_to_dry_factor(h2o_wet)

        out: Dict[str, Any] = {
            "method": method or "(unset)",
            "o2_used_pct": float(o2_used) if o2_used is not None else None,
            "o2_source": o2_src,
            "o2_factor": fac,
            "fd_dscf_per_mmbtu": fd,
            "h2o_wet_frac_est": h2o_wet,
            "dry_factor": dry_fac,
            "heat_input_mmbtu_hr": None,
            "heat_input_basis": None,
            "heat_input_source": None,
            "exh_flow_dscfh": None,
            "exh_flow_dscfm": None,
            "exh_flow_source": None,
            "fuel_flow_value": None,
            "fuel_flow_units": None,
            "fuel_flow_source": None,
            "fuel_flow_scfh": None,
            "fuel_flow_scfm": None,
            "note": "",
        }

        notes: list[str] = []

        if method != raw_method:
            notes.append("Diagnostics mode excludes EPA Method 2 / STACK_MEASURED; using Method 19 stoichiometric inputs")

        # If the session has no computed fuel/combustion model, we fall back to EPA Method 19 Table 19-2 defaults.
        # This is good for a usable baseline, but users should supply a fuel analysis/HHV when precision matters.
        if isinstance(comb, dict) and comb.get("source") == "EPA_M19_TABLE19_2_DEFAULTS":
            notes.append("Fuel defaults in use (EPA M19 Table 19-2); set fuel analysis for site-specific HHV/F-factors")

        # --- Manufacturer: heat input is direct / derived from nameplate basis
        if method == "MANUFACTURER":
            r_in = _parse_float((method_inputs or {}).get("heat_input_mmbtu_hr"))
            if r_in is not None and r_in > 0:
                out["heat_input_mmbtu_hr"] = float(r_in)
                out["heat_input_basis"] = "DIRECT_MMBTU"
                out["heat_input_source"] = "RUN_INPUT"
            else:
                mf = ex.get("manufacturer") or {}
                basis = str(mf.get("basis") or "").strip().upper()
                rated_hp = _parse_float(mf.get("rated_power_hp"))
                load_frac = _parse_float((method_inputs or {}).get("load_fraction"))
                hp = _parse_float((method_inputs or {}).get("actual_hp"))
                if hp is None and rated_hp is not None and load_frac is not None:
                    hp = float(rated_hp) * float(load_frac)

                if basis == "HEAT_RATE":
                    heat_rate = _parse_float(mf.get("heat_rate_btu_hp_hr"))
                    if hp is not None and heat_rate is not None and heat_rate > 0:
                        out["heat_input_mmbtu_hr"] = (float(hp) * float(heat_rate)) / 1_000_000.0
                        out["heat_input_basis"] = "HEAT_RATE_BTU_HP_HR"
                        out["heat_input_source"] = "HEAT_RATE"
                    else:
                        notes.append("Manufacturer HEAT_RATE basis missing hp/heat_rate")
                elif basis == "BSFC":
                    bsfc = _parse_float(mf.get("bsfc_lb_hp_hr"))
                    heat_value_lb, _, heat_basis_lb = _pick_heat_value(comb, "lb")
                    if hp is not None and bsfc is not None and bsfc > 0 and heat_value_lb is not None and heat_value_lb > 0:
                        fuel_lb_hr = float(hp) * float(bsfc)
                        out["heat_input_mmbtu_hr"] = _method19_heat_input_from_fuel_flow(fuel_lb_hr, heat_value_lb)
                        out["heat_input_basis"] = heat_basis_lb or str(comb.get("basis_sel") or "").strip().upper() or None
                        out["heat_input_source"] = "BSFC"
                        out["fuel_flow_value"] = fuel_lb_hr
                        out["fuel_flow_units"] = "lb/hr"
                        out["fuel_flow_source"] = "BSFC"
                    else:
                        notes.append("Manufacturer BSFC basis missing hp/bsfc/heating value (lb)")
                elif basis == "HEAT_INPUT":
                    # fall back to nameplate heat input if provided
                    r_np = _parse_float(mf.get("heat_input_mmbtu_hr"))
                    if r_np is not None and r_np > 0:
                        out["heat_input_mmbtu_hr"] = float(r_np)
                        out["heat_input_basis"] = "DIRECT_MMBTU"
                        out["heat_input_source"] = "NAMEPLATE"
                    else:
                        notes.append("Manufacturer HEAT_INPUT basis not provided")
                else:
                    notes.append("Manufacturer basis unset")

        # --- Stoichiometric via fuel input
        elif method == "STOICH_FUEL":
            ff_val = _parse_float((method_inputs or {}).get("fuel_flow_value"))
            ff_units = str((method_inputs or {}).get("fuel_flow_units") or "").strip() or "scfh"
            out["fuel_flow_units"] = ff_units
            out["fuel_flow_source"] = "RUN_INPUT"
            dual_family = str((comb or {}).get("family") or "").strip().upper() == "DUAL"
            dual_gas_share, dual_liquid_share = _dual_selected_shares(sess, comb if isinstance(comb, dict) else {})

            kind = _unit_kind(ff_units)
            if kind == "mmbtu":
                # operator entered heat input directly
                if ff_val is not None and ff_val > 0:
                    out["heat_input_mmbtu_hr"] = float(ff_val)
                    out["heat_input_basis"] = "DIRECT_MMBTU"
                    out["heat_input_source"] = "RUN_INPUT_MMBTU"
                    out["fuel_flow_value"] = float(ff_val)
                    notes.append("Fuel flow units are MMBtu/hr (heat input provided)")
                else:
                    notes.append("Missing fuel heat input (MMBtu/hr)")
            else:
                heat_value, base_kind, heat_basis = _pick_heat_value(comb, kind)
                if heat_value is None or heat_value <= 0:
                    notes.append("Heating value unavailable for fuel-flow units")
                v_per_hr = _rate_to_per_hr(ff_val, ff_units)
                if v_per_hr is None:
                    notes.append("Fuel flow value missing")
                else:
                    out["fuel_flow_value"] = float(ff_val) if ff_val is not None else None
                    if heat_value is not None and heat_value > 0:
                        stream_heat_input = _method19_heat_input_from_fuel_flow(v_per_hr, heat_value)
                        total_heat_input = stream_heat_input
                        total_source = "FUEL_FLOW"
                        if dual_family and stream_heat_input is not None:
                            if kind == "scf":
                                if dual_gas_share > 0:
                                    total_heat_input = stream_heat_input / dual_gas_share
                                    total_source = "FUEL_FLOW_DUAL_GAS_SHARE"
                                    notes.append(f"DG share applied: gas stream scaled by {dual_gas_share:.3f} selected-basis share")
                                else:
                                    total_heat_input = None
                                    notes.append("DG gas share is zero; cannot infer total heat input from gas flow")
                            elif kind in ("gal", "lb"):
                                if dual_liquid_share > 0:
                                    total_heat_input = stream_heat_input / dual_liquid_share
                                    total_source = "FUEL_FLOW_DUAL_LIQUID_SHARE"
                                    notes.append(f"DG share applied: liquid stream scaled by {dual_liquid_share:.3f} selected-basis share")
                                else:
                                    total_heat_input = None
                                    notes.append("DG liquid share is zero; cannot infer total heat input from liquid flow")
                        out["heat_input_mmbtu_hr"] = total_heat_input
                        out["heat_input_source"] = total_source if total_heat_input is not None else None
                        if heat_basis and total_heat_input is not None:
                            out["heat_input_basis"] = heat_basis
                    else:
                        out["heat_input_mmbtu_hr"] = None

        # --- Stack measured (EPA Method 2 style) -> infer heat input and fuel flow
        elif method == "STACK_MEASURED":
            # Stack measured (EPA Method 2-style) flow handling.
            #
            # Accepts (in priority order):
            #   1) qd_dscfh (direct dry standard flow, scfh)
            #   2) stack_flow_acfm + stack_temp_F (+ optional moisture and pressure)
            #   3) stack_velocity_fps (+ stack geometry) + stack_temp_F
            #   4) pitot_dp_inh2o (+ Cp, stack geometry, stack_temp_F, pressure, MW/moisture)  [preferred for EPA_M2 workflows]
            geom = _stack_geom(sess)
            area_ft2 = geom.get("area_ft2")
            de_in = geom.get("De_in")

            # Optional overrides from UI
            qd_direct = _parse_float((method_inputs or {}).get("qd_dscfh"))
            if qd_direct is None:
                qd_direct = _parse_float((method_inputs or {}).get("Qd_dscfh"))

            # Stack temperature is required for ACFM->standard conversion and for pitot velocity computation
            t_stack = _parse_float((method_inputs or {}).get("stack_temp_F"))

            # Barometric pressure (psia): allow override, else use live site conditions
            p_bar = _parse_float((method_inputs or {}).get("baro_psia"))
            if p_bar is None:
                p_bar = _parse_float((method_inputs or {}).get("p_bar_psia"))
            if p_bar is None:
                try:
                    p_bar = float(site_active.P_bar_psia) if site_active is not None else None
                except Exception:
                    p_bar = None

            # Static pressure (inH2O, optional): convert to psia and add to baro to get stack absolute
            p_static_inh2o = _parse_float((method_inputs or {}).get("stack_static_inh2o"))
            if p_static_inh2o is None:
                p_static_inh2o = _parse_float((method_inputs or {}).get("stack_static_inH2O"))
            p_stack_psia = p_bar
            if p_stack_psia is not None and p_static_inh2o is not None:
                dp_psi = _inh2o_to_psia(p_static_inh2o)
                if dp_psi is not None:
                    p_stack_psia = p_stack_psia + dp_psi

            # Moisture (wet): allow override; else estimate from fuel
            h2o_wet_frac = None
            h2o_user_frac = None  # non-None when operator provides an override
            h2o_wet_pct = _parse_float((method_inputs or {}).get("h2o_wet_pct"))
            if h2o_wet_pct is None:
                h2o_wet_pct = _parse_float((method_inputs or {}).get("h2o_wet_percent"))
            if h2o_wet_pct is not None:
                h2o_wet_frac = max(0.0, min(1.0, h2o_wet_pct / 100.0))
                h2o_user_frac = h2o_wet_frac
                notes.append("H2O(wet) override")
            else:
                h2o_wet_frac_in = _parse_float((method_inputs or {}).get("h2o_wet_frac"))
                if h2o_wet_frac_in is not None:
                    h2o_wet_frac = max(0.0, min(1.0, h2o_wet_frac_in))
                    h2o_user_frac = h2o_wet_frac
                    notes.append("H2O(wet) override")
                else:
                    h2o_wet_frac = h2o_wet  # use crosswalk moisture estimate (fuel-theoretical + O2)
                    if h2o_wet_frac is not None:
                        notes.append("H2O(wet) estimated")
            # Precompute EPA Method 2 calculated fields (for UI display) even when Qd is entered directly.
            # This lets operators compare pitot/stack-derived results vs direct-entry Qd and use the
            # "Use calculated → Direct Entry" button when desired.
            try:
                q_acfm_calc_tmp = None

                # Prefer pitot ΔP path if available (closest to EPA Method 2)
                dp_inh2o_tmp = _parse_float((method_inputs or {}).get("pitot_dp_inh2o"))
                if dp_inh2o_tmp is None:
                    dp_inh2o_tmp = _parse_float((method_inputs or {}).get("pitot_dp_inH2O"))

                if dp_inh2o_tmp is not None and area_ft2 is not None and t_stack is not None:
                    p_use = p_stack_psia or 14.696

                    pitot_cp = _parse_float((method_inputs or {}).get("pitot_cp"))
                    if pitot_cp is None:
                        pitot_cp = geom.get("pitot_cp") or 0.84

                    o2 = _parse_float((method_inputs or {}).get("o2_dry_pct"))
                    co = _parse_float((method_inputs or {}).get("co_dry_pct"))
                    co2 = _parse_float((method_inputs or {}).get("co2_dry_pct"))

                    mw_dry = _parse_float((method_inputs or {}).get("mw_dry"))
                    if mw_dry is None:
                        mw_dry = _mw_dry_from_o2_co2(o2, co2, co)
                    if mw_dry is None:
                        mw_dry = 28.96  # fallback: air-like dry MW

                    mw_wet = _mw_wet_from_dry(mw_dry, h2o_wet_frac) or mw_dry

                    v_mag = _pitot_velocity_fps(dp_inh2o_tmp, pitot_cp, t_stack, p_use, mw_wet)
                    if v_mag is not None:
                        v_ax = v_mag

                        # Optional swirl correction: use axial component (v * cos(alpha)) when avg swirl is provided
                        alpha_avg_local = _parse_float((method_inputs or {}).get("swirl_alpha_deg"))
                        if alpha_avg_local is None:
                            alpha_avg_local = _parse_float((method_inputs or {}).get("alpha_avg_deg"))

                        if alpha_avg_local is not None:
                            try:
                                import math
                                v_ax = float(v_mag) * float(math.cos(math.radians(float(alpha_avg_local))))
                                out["stack_swirl_alpha_deg"] = float(alpha_avg_local)
                            except Exception:
                                v_ax = v_mag

                        q_acfm_calc_tmp = _flow_acfm_from_velocity(area_ft2, v_ax)

                        out["stack_velocity_fps_calc_mag"] = float(v_mag)
                        out["stack_velocity_fps_calc"] = float(v_ax)
                        out["stack_flow_acfm_calc"] = float(q_acfm_calc_tmp) if q_acfm_calc_tmp is not None else None
                        out["stack_mw_dry"] = float(mw_dry)
                        out["stack_mw_wet"] = float(mw_wet)
                        out["stack_pressure_psia_used"] = float(p_use)
                        notes.append("M2 calc: pitot ΔP")

                # Fallback: operator-provided ACFM or velocity inputs
                if q_acfm_calc_tmp is None:
                    q_acfm_in = _parse_float((method_inputs or {}).get("stack_flow_acfm"))
                    if q_acfm_in is not None:
                        q_acfm_calc_tmp = q_acfm_in
                        out["stack_flow_acfm_calc"] = float(q_acfm_calc_tmp)
                        if area_ft2 is not None and float(area_ft2) > 0:
                            out["stack_velocity_fps_calc"] = float(q_acfm_calc_tmp) / (float(area_ft2) * 60.0)
                        notes.append("M2 calc: from ACFM")

                if q_acfm_calc_tmp is None:
                    v_in = _parse_float((method_inputs or {}).get("stack_velocity_fps"))
                    if v_in is not None and area_ft2 is not None:
                        q_acfm_calc_tmp = _flow_acfm_from_velocity(area_ft2, v_in)
                        out["stack_velocity_fps_calc"] = float(v_in)
                        out["stack_flow_acfm_calc"] = float(q_acfm_calc_tmp) if q_acfm_calc_tmp is not None else None
                        notes.append("M2 calc: from velocity")

                if q_acfm_calc_tmp is not None and t_stack is not None:
                    q_std_wet_dscfh = _acfm_to_dscfh(sess, q_acfm_calc_tmp, t_stack, p_stack_psia)
                    if q_std_wet_dscfh is not None:
                        out["qd_dscfh_calc"] = float(q_std_wet_dscfh * (1.0 - (h2o_wet_frac or 0.0)))
            except Exception:
                pass

            # Build Qd
            q_dscfh: Optional[float] = None

            if qd_direct is not None and qd_direct > 0:
                q_dscfh = qd_direct
                notes.append("Qd direct")
            else:
                q_acfm = _parse_float((method_inputs or {}).get("stack_flow_acfm"))

                # Path: velocity -> ACFM (requires geometry)
                v_fps = _parse_float((method_inputs or {}).get("stack_velocity_fps"))
                if q_acfm is not None and v_fps is None and area_ft2 is not None:
                    try:
                        out["stack_velocity_fps_calc"] = float(q_acfm) / (float(area_ft2) * 60.0)
                        notes.append("Velocity from ACFM")
                    except Exception:
                        pass

                if q_acfm is None and v_fps is not None:
                    if area_ft2 is None:
                        raise CrosswalkError("STACK_MEASURED velocity path requires stack geometry (area).")
                    q_acfm = _flow_acfm_from_velocity(area_ft2, v_fps)
                    notes.append("ACFM from velocity")

                # Path: pitot ΔP -> velocity -> ACFM (requires geometry + stack conditions)
                dp_inh2o = _parse_float((method_inputs or {}).get("pitot_dp_inh2o"))
                if dp_inh2o is None:
                    dp_inh2o = _parse_float((method_inputs or {}).get("pitot_dp_inH2O"))

                if q_acfm is None and dp_inh2o is not None:
                    if area_ft2 is None:
                        raise CrosswalkError("STACK_MEASURED pitot path requires stack geometry (area).")
                    if t_stack is None:
                        raise CrosswalkError("STACK_MEASURED pitot path requires stack_temp_F.")
                    p_use = p_stack_psia or 14.696

                    pitot_cp = _parse_float((method_inputs or {}).get("pitot_cp"))
                    if pitot_cp is None:
                        pitot_cp = geom.get("pitot_cp") or 0.84

                    o2 = _parse_float((method_inputs or {}).get("o2_dry_pct"))
                    co = _parse_float((method_inputs or {}).get("co_dry_pct"))
                    co2 = _parse_float((method_inputs or {}).get("co2_dry_pct"))

                    mw_dry = _parse_float((method_inputs or {}).get("mw_dry"))
                    if mw_dry is None:
                        mw_dry = _mw_dry_from_o2_co2(o2, co2, co)
                    if mw_dry is None:
                        mw_dry = 28.96  # fallback: air-like dry MW

                    mw_wet = _mw_wet_from_dry(mw_dry, h2o_wet_frac) or mw_dry

                    v_calc = _pitot_velocity_fps(dp_inh2o, pitot_cp, t_stack, p_use, mw_wet)
                    if v_calc is None:
                        raise CrosswalkError("STACK_MEASURED: failed to compute pitot velocity.")

                    # Optional swirl correction: use axial component (v * cos(alpha)) when avg swirl is provided
                    alpha_avg_local = _parse_float((method_inputs or {}).get("swirl_alpha_deg"))
                    if alpha_avg_local is None:
                        alpha_avg_local = _parse_float((method_inputs or {}).get("alpha_avg_deg"))
                    v_axial = v_calc
                    if alpha_avg_local is not None:
                        try:
                            import math
                            v_axial = float(v_calc) * float(math.cos(math.radians(float(alpha_avg_local))))
                            out["stack_swirl_alpha_deg"] = float(alpha_avg_local)
                        except Exception:
                            v_axial = v_calc

                    q_acfm = _flow_acfm_from_velocity(area_ft2, v_axial)
                    notes.append("ACFM from pitot ΔP")

                    # Store intermediate calcs
                    out["stack_velocity_fps_calc_mag"] = v_calc
                    out["stack_velocity_fps_calc"] = v_axial
                    out["stack_mw_dry"] = mw_dry
                    out["stack_mw_wet"] = mw_wet
                    out["stack_pressure_psia_used"] = p_use

                if q_acfm is None or t_stack is None:
                    raise CrosswalkError(
                        "STACK_MEASURED requires either qd_dscfh, OR (stack_flow_acfm + stack_temp_F), "
                        "OR stack_velocity_fps (+ geometry) + stack_temp_F, OR pitot_dp_inh2o (+ geometry) + stack_temp_F."
                    )

                q_std_wet_dscfh = _acfm_to_dscfh(sess, q_acfm, t_stack, p_stack_psia)
                if q_std_wet_dscfh is None:
                    notes.append("ACFM->DSCFH failed")
                    raise CrosswalkError("Failed ACFM->DSCFH conversion.")
                q_dscfh = q_std_wet_dscfh * (1.0 - (h2o_wet_frac or 0.0))

                # Save calculated ACFM if we derived it from velocity/pitot
                out["stack_flow_acfm_calc"] = q_acfm

            if q_dscfh is None:
                raise CrosswalkError("STACK_MEASURED: unable to determine Qd.")

            # Expose geometry context (useful for operator confidence + debugging)
            out["stack_area_ft2"] = area_ft2
            out["stack_De_in"] = de_in
            if de_in is not None and de_in < 6.0:
                notes.append("Small stack (<6in): consider M2C/standard pitot")

            out["mode"] = "STACK"
            out["o2_used"] = _parse_float((method_inputs or {}).get("o2_dry_pct"))
            out["o2_factor"] = None
            out["heat_input_mmbtu_hr"] = None
            out["q_dscfh"] = q_dscfh
            out["exh_flow_dscfh"] = q_dscfh
            out["exh_flow_dscfm"] = (float(q_dscfh) / 60.0) if q_dscfh is not None else None
            out["exh_flow_source"] = "RUN_INPUT" if qd_direct is not None else ("M2_CALC" if q_dscfh is not None else None)
            # Preserve any earlier EPA Method 2 calculation (pitot/ACFM/velocity path).
            # If none was computed, fall back to the Qd value being used for the run.
            if out.get("qd_dscfh_calc") is None:
                out["qd_dscfh_calc"] = q_dscfh
            out["q_dscfm"] = q_dscfh / 60.0
            # H2O / dry-factor bookkeeping (used for conversions; override wins)
            out["h2o_wet_frac_used"] = h2o_wet_frac
            out["h2o_wet_source"] = "OVERRIDE" if h2o_user_frac is not None else ("ESTIMATE" if h2o_wet_frac is not None else None)
            if h2o_wet_frac is not None:
                _dry_frac = max(1e-6, 1.0 - float(h2o_wet_frac))
                out["dry_frac_used"] = _dry_frac
                out["wet_to_dry_factor_used"] = 1.0 / _dry_frac
            else:
                out["dry_frac_used"] = None
                out["wet_to_dry_factor_used"] = None

            # Swirl α suggestion (degrees). Not applied automatically; shown for operator context.
            alpha_suggested = None
            try:
                src_cat = ((sess.get("source") or {}).get("source_category") or "").lower()
                base = 5.0
                if "engine" in src_cat or "turbine" in src_cat:
                    base = 10.0
                elif "flare" in src_cat:
                    base = 0.0
                elif "boiler" in src_cat or "heater" in src_cat:
                    base = 5.0
                up = geom.get("upstream_D") if isinstance(geom, dict) else None
                dn = geom.get("downstream_D") if isinstance(geom, dict) else None
                add = 0.0
                if up is not None:
                    if up < 8.0:
                        add += 3.0
                    if up < 4.0:
                        add += 4.0
                if dn is not None:
                    if dn < 2.0:
                        add += 3.0
                    if dn < 1.0:
                        add += 4.0
                alpha_suggested = min(25.0, max(0.0, base + add))
            except Exception:
                alpha_suggested = None
            out["swirl_alpha_suggested_deg"] = alpha_suggested

            # Qd→ACFM back-calc (for display / direct-entry support)
            # Stored separately from Method 2 calculated values so the two views don't trample each other.
            if q_dscfh is not None and q_dscfh > 0 and area_ft2:
                try:
                    # Temperature: prefer stack temp; else (last resort) ambient.
                    t_use = float(t_stack) if t_stack is not None else None
                    t_assumed = False
                    if t_use is None and site_active is not None:
                        try:
                            t_use = float(site_active.T_amb_F)
                            t_assumed = True
                        except Exception:
                            t_use = None

                    # Pressure: prefer stack psia; else baro; else standard.
                    p_use = float(p_stack_psia) if p_stack_psia is not None else None
                    p_assumed = False
                    if p_use is None and site_active is not None:
                        try:
                            p_use = float(site_active.P_bar_psia)
                            p_assumed = True
                        except Exception:
                            p_use = None
                    if p_use is None:
                        p_use = 14.696
                        p_assumed = True

                    if t_use is None:
                        raise ValueError('missing temperature')

                    h2o_use = float(h2o_wet_frac) if h2o_wet_frac is not None else 0.0
                    dry_frac = max(1e-6, 1.0 - h2o_use)
                    q_std_wet_dscfh = float(q_dscfh) / dry_frac
                    q_acfm_from_qd = _dscfh_to_acfm(sess, q_std_wet_dscfh, float(t_use), float(p_use))
                    if q_acfm_from_qd is not None:
                        out['stack_flow_acfm_from_qd_calc'] = float(q_acfm_from_qd)
                        out['stack_velocity_fps_from_qd_calc'] = float(q_acfm_from_qd) / (float(area_ft2) * 60.0)
                        out['stack_pressure_psia_used'] = float(p_use)
                        if t_assumed:
                            notes.append('Qd→ACFM used ambient T (assumed)')
                        if p_assumed:
                            notes.append('Qd→ACFM used baro/standard P (assumed)')
                except Exception:
                    # Convenience calc: never hard-fail the solve
                    notes.append('Qd→ACFM back-calc unavailable')

            # If we have both a pitot magnitude velocity and a Qd-derived axial velocity, suggest swirl α (deg).
            try:
                v_mag = _parse_float(out.get('stack_velocity_fps_calc_mag'))
                v_ax = _parse_float(out.get('stack_velocity_fps_from_qd_calc'))
                if v_mag is not None and v_ax is not None and v_mag > 0 and v_ax > 0:
                    import math
                    ratio = max(0.0, min(1.0, float(v_ax) / float(v_mag)))
                    alpha_mismatch = math.degrees(math.acos(ratio))
                    # Use mismatch-based suggestion when it's meaningfully non-zero
                    if alpha_mismatch >= 0.5:
                        out['swirl_alpha_suggested_deg'] = float(alpha_mismatch)
                        notes.append('Swirl α suggested from pitot vs Qd mismatch')
            except Exception:
                pass
            out["fuel_flow_value"] = None

            # Optional Method 2 swirl / cyclonic flow check (alpha, degrees)
            alpha_avg = _parse_float((method_inputs or {}).get("swirl_alpha_deg"))
            if alpha_avg is None:
                alpha_avg = _parse_float((method_inputs or {}).get("alpha_avg_deg"))
            if alpha_avg is not None:
                if abs(alpha_avg) > 20.0:
                    notes.append(f"CYCLONIC FLOW (avg α={_fmt_num(alpha_avg)}° >20°)")
                else:
                    notes.append(f"Swirl OK (avg α={_fmt_num(alpha_avg)}°)")

            if (method_inputs or {}).get("stack_flow_acfm"):
                notes.append("ACFM direct")
            if qd_direct is not None and qd_direct > 0:
                notes.append("Qd direct")
            if (method_inputs or {}).get("pitot_dp_inh2o") or (method_inputs or {}).get("pitot_dp_inH2O"):
                notes.append("Pitot ΔP provided")
            if (method_inputs or {}).get("stack_velocity_fps"):
                notes.append("Velocity provided")

            out["note"] = " | ".join([n for n in notes if n]) if notes else ""

        # ---- Finalize results (all methods) ----
        try:
            fd_use = out.get("fd_dscf_per_mmbtu") if out.get("fd_dscf_per_mmbtu") is not None else fd
            fac_use = out.get("o2_factor") if out.get("o2_factor") is not None else fac

            # If operator provided O2 in method inputs, prefer it for the oxygen correction factor
            try:
                o2_for_fac = out.get("o2_used")
                if out.get("o2_factor") is None and o2_for_fac is not None:
                    fac_use = _o2_factor(float(o2_for_fac))
            except Exception:
                pass

            if fd_use is not None:
                out["fd_dscf_per_mmbtu"] = fd_use
            if fac_use is not None:
                out["o2_factor"] = fac_use

            # If exhaust flow missing, compute from heat input
            if out.get("exh_flow_dscfh") is None and out.get("heat_input_mmbtu_hr") is not None and fd_use is not None and fac_use is not None:
                qd = _method19_qd_from_heat_input(
                    out.get("heat_input_mmbtu_hr"),
                    fd_use,
                    o2_factor_value=fac_use,
                )
                out["exh_flow_dscfh"] = qd
                if qd is not None:
                    out["exh_flow_dscfm"] = qd / 60.0
                    out["exh_flow_source"] = out.get("exh_flow_source") or "FROM_R"

            # If heat input missing, compute from exhaust flow
            if out.get("heat_input_mmbtu_hr") is None and out.get("exh_flow_dscfh") is not None and fd_use is not None and fac_use is not None:
                heat_input = _method19_heat_input_from_qd(
                    out.get("exh_flow_dscfh"),
                    fd_use,
                    o2_factor_value=fac_use,
                )
                if heat_input is not None:
                    out["heat_input_mmbtu_hr"] = heat_input
                    out["heat_input_basis"] = str(comb.get("basis_sel") or "").strip().upper() or out.get("heat_input_basis")
                    out["heat_input_source"] = out.get("heat_input_source") or "FROM_STACK"

            # Compute fuel flow (scfh/scfm) from heat input when HHV is known
            if out.get("heat_input_mmbtu_hr") is not None:
                dual_family = str((comb or {}).get("family") or "").strip().upper() == "DUAL"
                dual_gas_share, dual_liquid_share = _dual_selected_shares(sess, comb if isinstance(comb, dict) else {})
                heat_value_scf, _, heat_basis_scf = _pick_heat_value(comb, "scf")
                if heat_value_scf is not None and heat_value_scf > 0:
                    heat_for_gas = float(out["heat_input_mmbtu_hr"]) * dual_gas_share if dual_family else out.get("heat_input_mmbtu_hr")
                    scfh = _method19_fuel_flow_from_heat_input(heat_for_gas, heat_value_scf)
                    out["fuel_flow_scfh"] = scfh
                    if scfh is not None:
                        out["fuel_flow_scfm"] = scfh / 60.0
                    if out.get("heat_input_basis") is None and heat_basis_scf:
                        out["heat_input_basis"] = heat_basis_scf
                    if dual_family and scfh is not None:
                        out["fuel_flow_gas_scfh"] = scfh
                        out["fuel_flow_gas_scfm"] = scfh / 60.0
                    if scfh is not None and out.get("fuel_flow_value") is None and not dual_family:
                        out["fuel_flow_value"] = scfh
                        out["fuel_flow_units"] = "scfh"
                        out["fuel_flow_source"] = out.get("fuel_flow_source") or "FROM_R"
                else:
                    # propagate scfh/scfm if operator already entered in scfh
                    if str(out.get("fuel_flow_units") or "").strip().lower() == "scfh" and out.get("fuel_flow_value") is not None:
                        try:
                            scfh = float(out["fuel_flow_value"])
                            out["fuel_flow_scfh"] = scfh
                            out["fuel_flow_scfm"] = scfh / 60.0
                        except Exception:
                            pass

                if dual_family:
                    heat_for_liquid = float(out["heat_input_mmbtu_hr"]) * dual_liquid_share
                    heat_value_gal, _, _ = _pick_heat_value(comb, "gal")
                    heat_value_lb, _, _ = _pick_heat_value(comb, "lb")
                    if heat_value_gal is not None and heat_value_gal > 0 and dual_liquid_share > 0:
                        out["fuel_flow_liquid_gal_hr"] = _method19_fuel_flow_from_heat_input(heat_for_liquid, heat_value_gal)
                    if heat_value_lb is not None and heat_value_lb > 0 and dual_liquid_share > 0:
                        out["fuel_flow_liquid_lb_hr"] = _method19_fuel_flow_from_heat_input(heat_for_liquid, heat_value_lb)
                    if out.get("fuel_flow_value") is None:
                        parts = []
                        gas_scfh = out.get("fuel_flow_gas_scfh")
                        liq_gph = out.get("fuel_flow_liquid_gal_hr")
                        if gas_scfh is not None:
                            parts.append(f"{_fmt_num(gas_scfh, 2)} scfh gas")
                        if liq_gph is not None:
                            parts.append(f"{_fmt_num(liq_gph, 3)} gal/hr liquid")
                        if parts:
                            out["fuel_flow_value"] = " | ".join(parts)
                            out["fuel_flow_units"] = "DG_STREAMS"
                            out["fuel_flow_source"] = out.get("fuel_flow_source") or "FROM_R_DUAL"

            # Ensure note formatting
            out["note"] = str(out.get("note") or "")
        except Exception as _e:
            # never fail UI due to crosswalk helper
            pass

        return out


    # -------------------------------
    # Compatibility wrapper: Method-19 crosswalk solver name
    # -------------------------------
    def _solve_m19_crosswalk(
        sess: Dict[str, Any],
        method_inputs: Dict[str, Any],
        o2_live_pct: Optional[float],
        site_active: Optional[SiteConditionsActive],
    ) -> Dict[str, Any]:
        """Backward-compatible wrapper for crosswalk solver.

        Earlier UI blocks call `_solve_m19_crosswalk(...)`. The primary implementation
        lives in `_solve_exhaust_fuel_crosswalk(...)`.

        This wrapper also normalizes a couple of field names so the UI/logging
        remains stable across patches.
        """
        try:
            out = _solve_exhaust_fuel_crosswalk(sess, method_inputs, o2_live_pct, site_active) or {}
        except CrosswalkError as e:
            out = {'note': str(e), 'mode': 'NEEDS_INPUT'}
        except Exception as e:
            out = {'note': 'Compute error: ' + type(e).__name__ + ': ' + str(e), 'mode': 'ERROR'}
        if not isinstance(out, dict):
            out = {}

        # Provide a simple 'mode' label for display/logging (non-critical).
        if out.get("mode") in (None, ""):
            meth = str(out.get("method") or "").strip()
            if (out.get("heat_input_source") or "").startswith("FROM_FUEL"):
                out["mode"] = f"{meth}:R_from_fuel"
            elif (out.get("heat_input_source") or "").startswith("FROM_STACK"):
                out["mode"] = f"{meth}:R_from_stack"
            elif (out.get("fuel_flow_source") or "").startswith("FROM_R"):
                out["mode"] = f"{meth}:Qf_from_R"
            else:
                out["mode"] = meth or "(unset)"

        # Logging expects h2o_wet_frac; UI uses h2o_wet_frac_est.
        if out.get("h2o_wet_frac") is None:
            out["h2o_wet_frac"] = out.get("h2o_wet_frac_est")
        if out.get("h2o_wet_frac_est") is None:
            out["h2o_wet_frac_est"] = out.get("h2o_wet_frac")

        # Horsepower / utilization (engine)
        # Used for g/bhp-hr conversions and to display "Current horsepower utilization" per run.
        try:
            src_cfg = sess.get("source", {}) if isinstance(sess, dict) else {}
            ex_cfg = (src_cfg.get("exhaust_flow") or {}) if isinstance(src_cfg.get("exhaust_flow"), dict) else {}
            mf_cfg = (ex_cfg.get("manufacturer") or {}) if isinstance(ex_cfg.get("manufacturer"), dict) else {}

            rated_hp = _parse_float(
                src_cfg.get("site_rated_power")
                or src_cfg.get("max_power")
                or mf_cfg.get("rated_power_hp")
                or mf_cfg.get("rated_hp")
                or src_cfg.get("rated_power_hp"),
                None,
            )

            hp_used: float | None = None
            hp_util: float | None = None
            hp_source: str | None = None

            hp_mode = str((method_inputs or {}).get("hp_mode") or "").upper().strip()
            actual_hp = _parse_float((method_inputs or {}).get("actual_hp"), None)
            load_frac = _parse_float((method_inputs or {}).get("load_fraction"), None)

            imap_val = _parse_float((method_inputs or {}).get("imap_value"), None)
            imap_idle = _parse_float((method_inputs or {}).get("imap_idle"), None)
            imap_full = _parse_float((method_inputs or {}).get("imap_full"), None)
            imap_mid = _parse_float((method_inputs or {}).get("imap_mid"), None)
            imap_mid_util = _parse_float((method_inputs or {}).get("imap_mid_util"), None)
            imap_units = str((method_inputs or {}).get("imap_units") or "kPa")

            # Infer mode if not set
            if not hp_mode:
                if actual_hp is not None:
                    hp_mode = "DIRECT_HP"
                elif load_frac is not None:
                    hp_mode = "LOAD_FRACTION"
                elif imap_val is not None and imap_idle is not None and imap_full is not None:
                    hp_mode = "IMAP"

            if hp_mode == "DIRECT_HP":
                if actual_hp is not None and actual_hp > 0:
                    hp_used = actual_hp
                    hp_source = "DIRECT_HP"
                    if rated_hp is not None and rated_hp > 0:
                        hp_util = hp_used / rated_hp

            elif hp_mode == "LOAD_FRACTION":
                if load_frac is None:
                    load_frac = _parse_float(mf_cfg.get("load_fraction"), None)
                if load_frac is not None:
                    hp_util = load_frac
                    hp_source = "LOAD_FRACTION"
                    if rated_hp is not None and rated_hp > 0:
                        hp_used = rated_hp * load_frac

            elif hp_mode == "IMAP":
                # Piecewise linear map (2-point or optional 3-point):
                #   2-point: IMAP_idle -> 0.0, IMAP_full -> 1.0
                #   3-point (optional): IMAP_mid -> mid_util (accepts 0-1 or 0-100%)
                if imap_idle is None:
                    imap_idle = _parse_float(mf_cfg.get("imap_idle"), None)
                if imap_full is None:
                    imap_full = _parse_float(mf_cfg.get("imap_full"), None)
                if imap_mid is None:
                    imap_mid = _parse_float(mf_cfg.get("imap_mid"), None)
                if imap_mid_util is None:
                    imap_mid_util = _parse_float(mf_cfg.get("imap_mid_util"), None)
                if not imap_units:
                    imap_units = str(mf_cfg.get("imap_units") or "kPa")

                def _pressure_to_kpa(v: float, units: str) -> float:
                    u = str(units or "").strip().lower()
                    u = u.replace("(", "").replace(")", "")
                    # normalize
                    u = u.replace("kpag", "kpa").replace("kpaa", "kpa").replace("kpa(a)", "kpa").replace("kpa(g)", "kpa")
                    u = u.replace("psig", "psi").replace("psia", "psi")
                    if u in ("kpa",):
                        return v
                    if u in ("psi", "psia", "psig"):
                        return v * 6.894757293168361
                    if u in ("bar",):
                        return v * 100.0
                    if u in ("inh2o", "in_h2o", "inwc", "in-wc"):
                        return v * 0.24908891
                    if u in ("inhg", "in_hg"):
                        return v * 3.386389
                    if u in ("mmhg",):
                        return v * 0.133322
                    return v

                def _norm_mid_util(x: float | None) -> float | None:
                    if x is None:
                        return None
                    # accept percent
                    if x > 1.5:
                        x = x / 100.0
                    if x <= 0.0:
                        return None
                    if x >= 1.0:
                        x = 1.0
                    return x

                if imap_val is not None and imap_idle is not None and imap_full is not None:
                    v = _pressure_to_kpa(imap_val, imap_units)
                    lo = _pressure_to_kpa(imap_idle, imap_units)
                    hi = _pressure_to_kpa(imap_full, imap_units)

                    # tolerate swapped idle/full
                    if hi < lo:
                        lo, hi = hi, lo

                    if hi != lo:
                        use_mid = False
                        mid = None
                        mid_util = _norm_mid_util(imap_mid_util)

                        if imap_mid is not None:
                            mid = _pressure_to_kpa(imap_mid, imap_units)
                            if mid_util is None:
                                mid_util = 0.5  # default midpoint utilization
                            # validate midpoint
                            if mid is not None and (lo < mid < hi) and (0.0 < mid_util < 1.0) and (mid != lo) and (mid != hi):
                                use_mid = True

                        if use_mid and mid is not None and (mid != lo) and (mid != hi):
                            if v <= mid:
                                hp_util = (v - lo) / (mid - lo) * mid_util
                            else:
                                hp_util = mid_util + (v - mid) / (hi - mid) * (1.0 - mid_util)
                            hp_source = f"IMAP3({imap_units})"
                        else:
                            hp_util = (v - lo) / (hi - lo)
                            hp_source = f"IMAP2({imap_units})"

                        # clamp to sane bounds
                        if hp_util < 0.0:
                            hp_util = 0.0
                        if hp_util > 1.5:
                            hp_util = 1.5
                        if rated_hp is not None and rated_hp > 0:
                            hp_used = rated_hp * hp_util


            if rated_hp is not None:
                out["hp_rated"] = rated_hp
            if hp_used is not None:
                out["hp_used"] = hp_used
            if hp_util is not None:
                out["hp_util_frac"] = hp_util
                out["hp_util_pct"] = hp_util * 100.0
            if hp_source:
                out["hp_source"] = hp_source
        except Exception:
            pass

        return out


    def _format_source_summary(sess: Dict[str, Any]) -> str:
        src = sess.get("source") or {}
        ex = src.get("exhaust_flow") or {}
        raw_method = str(ex.get("method") or "").strip()
        method = _effective_exhaust_flow_method(sess, raw_method)
        bits = []
        bits.append(f"Category: {src.get('source_category')}")
        bits.append(f"Application: {src.get('application')}")
        if src.get("service_class"):
            bits.append(f"Service: {src.get('service_class')}")
        if src.get("output_type"):
            bits.append(f"Output: {src.get('output_type')}")
        if method != str(raw_method or "").strip().upper():
            bits.append("Exhaust Flow Method: METHOD 19 STOICH_FUEL (diagnostics override)")
            bits.append(f"Source Config Method: {raw_method or '(unset)'}")
            bits.append("Method 2 / STACK_MEASURED is disabled in diagnostics mode")
        else:
            bits.append(f"Exhaust Flow Method: {method or '(unset)'}")
        if method == "STOICH_FUEL":
            sf = ex.get("stoich_fuel") or {}
            bits.append(f"Fuel flow (base): {sf.get('fuel_flow_value') or '(deferred)'} {sf.get('fuel_flow_units') or ''}".strip())
        elif method == "STACK_MEASURED":
            sm = ex.get("stack_measured") or {}
            bits.append(f"EPA Method: {sm.get('epa_method')}")
            geom = _stack_geom(sess)
            if str(geom.get("shape") or "").startswith("ROUND") and geom.get("diameter_in") is not None:
                bits.append(f"Stack: ROUND D={_fmt_num(geom.get('diameter_in'))} in")
            elif geom.get("width_in") is not None and geom.get("height_in") is not None:
                bits.append(f"Stack: RECT {_fmt_num(geom.get('width_in'))}×{_fmt_num(geom.get('height_in'))} in")
            if geom.get("area_ft2") is not None:
                bits.append(f"Area: {_fmt_num(geom.get('area_ft2'))} ft²")
            if geom.get("De_in") is not None:
                bits.append(f"De: {_fmt_num(geom.get('De_in'))} in")
        elif method == "MANUFACTURER":
            mf = ex.get("manufacturer") or {}
            bits.append(f"Basis: {mf.get('basis')}")
        return "\n".join([str(x) for x in bits if str(x).strip()])

    def _format_mode_summary(sess: Dict[str, Any]) -> str:
        sm = sess.get("session_mode") or {}
        proj = sess.get("project") or {}
        bits = []
        bits.append(f"Job: {proj.get('job_id')}")
        bits.append(f"Mode: {sm.get('mode')} | Record={sm.get('record_data')} | Token={sm.get('tokenize')} | DiagOnly={sm.get('diagnostic_only')}")
        if _diagnostics_ui_active(sess):
            bits.append("UI=DIAGNOSTICS")
        return " | ".join([str(x) for x in bits if str(x).strip()])

    # -------------------------------
    # Acquisition thread (dummy)
    # -------------------------------

    class _UIDummyDriver:
        def __init__(self, poll_codes: list[str], pres: Dict[str, Dict[str, Any]]):
            self._t0 = time.time()
            self._poll_codes = list(poll_codes)
            self._pres = pres or {}

        def connect(self) -> None:
            return

        def close(self) -> None:
            return

        def read_all(self) -> Dict[str, Any]:
            t = time.time() - self._t0
            out: Dict[str, Any] = {"ts_iso": _now_iso(), "comm_ok": True}
            # Create stable, bounded dummy values per pollutant
            for i, code in enumerate(self._poll_codes):
                p = self._pres.get(code) or {}
                vmax = p.get("expected_max")
                try:
                    vmax_f = float(vmax) if vmax not in (None, "", 0) else 100.0
                except Exception:
                    vmax_f = 100.0
                # 0–~60% of expected max with a smooth oscillation + tiny jitter
                base = 0.30 + 0.25 * math.sin(0.23 * t + (i * 0.7))
                jitter = random.uniform(-0.015, 0.015)
                val = max(0.0, (base + jitter) * vmax_f)
                out[code] = round(val, 3)

            # Convenience channels (common for combustion normalization)
            if "O2" not in out:
                out["O2"] = round(6.0 + 1.25 * math.sin(0.11 * t), 3)
            if "CO2" not in out:
                out["CO2"] = round(8.5 + 0.75 * math.sin(0.09 * t + 1.0), 3)

            return out

