    def _runner_form_grid_contracts() -> Dict[str, Dict[str, Any]]:
        return {
            "runner_default": {
                "spec": {0: 160, 1: 240},
                "weighted": (1,),
            },
            "runner_single_pair": {
                "spec": {0: 160, 1: 240},
                "weighted": (1,),
            },
            "runner_single_pair_wide": {
                "spec": {0: 180, 1: 420},
                "weighted": (1,),
            },
            "runner_two_pair": {
                "spec": {0: 160, 1: 220, 2: 160, 3: 240},
                "weighted": (1, 3),
            },
            "runner_three_pair_compact": {
                "spec": {0: 130, 1: 90, 2: 150, 3: 90, 4: 160, 5: 90},
                "weighted": (1, 3, 5),
            },
            "runner_combustion_triples": {
                "spec": {0: 150, 1: 120, 2: 140, 3: 120, 4: 100, 5: 120},
                "weighted": (1, 3, 5),
            },
            "runner_spike_flow": {
                "spec": {0: 150, 1: 110, 2: 140, 3: 110, 4: 320},
                "weighted": (4,),
            },
            "runner_channel_offsets": {
                "spec": {0: 90, 1: 180, 2: 70, 3: 90, 4: 70, 5: 90},
                "weighted": (1,),
            },
            "runner_pollutant_adjustments": {
                "spec": {0: 90, 1: 180, 2: 70, 3: 90, 4: 110, 5: 110},
                "weighted": (1,),
            },
            "runner_hp_load": {
                "spec": {0: 150, 1: 150, 2: 150, 3: 150},
                "weighted": (1, 3),
            },
        }

    def _resolve_runner_form_grid_contract(
        minspec: Optional[Union[Dict[int, int], str]] = None,
        weighted_cols: Optional[Tuple[int, ...]] = None,
    ) -> Tuple[Dict[int, int], Tuple[int, ...]]:
        contracts = _runner_form_grid_contracts()
        if isinstance(minspec, str):
            base = contracts.get(minspec) or contracts["runner_default"]
            spec = dict(base.get("spec") or {})
            weights = tuple(weighted_cols if weighted_cols is not None else tuple(base.get("weighted") or ()))
            return spec, weights
        spec = dict(minspec or contracts["runner_default"]["spec"])
        weights = tuple(weighted_cols or ())
        return spec, weights

    def _configure_runner_form_grid(
        frame: tk.Widget,
        minspec: Optional[Union[Dict[int, int], str]] = None,
        weighted_cols: Optional[Tuple[int, ...]] = None,
    ) -> None:
        spec, weights = _resolve_runner_form_grid_contract(minspec=minspec, weighted_cols=weighted_cols)
        try:
            contract_name = str(minspec) if isinstance(minspec, str) else "EXPLICIT"
            setattr(frame, "_mole_form_grid_contract", contract_name)
            setattr(frame, "_mole_form_grid_spec", dict(spec))
            setattr(frame, "_mole_form_grid_weighted", tuple(weights))
        except Exception:
            pass
        for col, minsize in spec.items():
            try:
                frame.grid_columnconfigure(col, minsize=int(minsize), weight=(1 if col in weights else 0))
            except Exception:
                pass

    def _mark_runner_form_grid_exempt(frame: tk.Widget, reason: str) -> None:
        try:
            setattr(frame, "_mole_form_grid_exempt", True)
            setattr(
                frame,
                "_mole_form_grid_exempt_reason",
                str(reason or "Intentional custom layout.").strip() or "Intentional custom layout.",
            )
        except Exception:
            pass

    def _runner_alignment_widget_label(widget: tk.Widget) -> str:
        try:
            txt = str(widget.cget("text") or "").strip()
        except Exception:
            txt = ""
        cls = str(widget.winfo_class() or widget.__class__.__name__)
        if txt:
            return f"{cls}: {txt}"
        try:
            name = str(widget.winfo_name() or "").strip()
        except Exception:
            name = ""
        return f"{cls}: {name}" if name else cls

    def _runner_alignment_frame_metrics(frame: tk.Widget) -> Dict[str, Any]:
        children = []
        try:
            children = [c for c in frame.winfo_children() if str(c.winfo_manager() or "") == "grid"]
        except Exception:
            children = []
        cols: set[int] = set()
        label_count = 0
        input_count = 0
        input_classes = {"Entry", "TEntry", "Combobox", "TCombobox", "Checkbutton", "TCheckbutton", "Radiobutton", "TRadiobutton", "Spinbox", "Text"}
        label_classes = {"Label", "TLabel", "Checkbutton", "TCheckbutton", "Radiobutton", "TRadiobutton"}
        for child in children:
            try:
                info = child.grid_info() or {}
                cols.add(int(info.get("column", 0)))
            except Exception:
                pass
            try:
                cls = str(child.winfo_class() or "")
            except Exception:
                cls = ""
            if cls in label_classes:
                label_count += 1
            if cls in input_classes:
                input_count += 1
        return {
            "children": children,
            "child_count": len(children),
            "columns": sorted(cols),
            "column_count": len(cols),
            "label_count": label_count,
            "input_count": input_count,
        }

    def _runner_alignment_is_contract_candidate(frame: tk.Widget) -> bool:
        metrics = _runner_alignment_frame_metrics(frame)
        return bool(
            metrics["child_count"] >= 4
            and 2 <= metrics["column_count"] <= 6
            and metrics["label_count"] >= 1
            and metrics["input_count"] >= 1
        )

    def _collect_runner_alignment_findings(root_widget: tk.Widget) -> Dict[str, Any]:
        findings: List[Dict[str, Any]] = []
        contracts: List[Dict[str, Any]] = []
        exemptions: List[Dict[str, Any]] = []
        visited: set[str] = set()

        def _walk(widget: tk.Widget) -> None:
            try:
                wid = str(widget)
            except Exception:
                wid = repr(widget)
            if wid in visited:
                return
            visited.add(wid)

            is_frame = isinstance(widget, (tk.Frame, tk.LabelFrame, ttk.Frame, ttk.LabelFrame))
            if not is_frame:
                for child in list(getattr(widget, "winfo_children", lambda: [])()):
                    _walk(child)
                return

            try:
                if bool(getattr(widget, "_mole_form_grid_exempt", False)):
                    metrics = _runner_alignment_frame_metrics(widget)
                    exemptions.append(
                        {
                            "widget": _runner_alignment_widget_label(widget),
                            "reason": str(getattr(widget, "_mole_form_grid_exempt_reason", "") or "Intentional custom layout."),
                            "columns": metrics["columns"],
                            "child_count": metrics["child_count"],
                        }
                    )
                    return
            except Exception:
                pass

            for child in list(getattr(widget, "winfo_children", lambda: [])()):
                _walk(child)

            metrics = _runner_alignment_frame_metrics(widget)
            contract = str(getattr(widget, "_mole_form_grid_contract", "") or "").strip()
            if contract:
                contracts.append(
                    {
                        "widget": _runner_alignment_widget_label(widget),
                        "contract": contract,
                        "columns": metrics["columns"],
                        "child_count": metrics["child_count"],
                    }
                )
                return

            if _runner_alignment_is_contract_candidate(widget):
                findings.append(
                    {
                        "widget": _runner_alignment_widget_label(widget),
                        "columns": metrics["columns"],
                        "child_count": metrics["child_count"],
                        "label_count": metrics["label_count"],
                        "input_count": metrics["input_count"],
                    }
                )

        _walk(root_widget)
        return {"contracts": contracts, "findings": findings, "exemptions": exemptions}

    def _format_runner_alignment_report(report: Dict[str, Any]) -> str:
        contracts = list(report.get("contracts") or [])
        findings = list(report.get("findings") or [])
        exemptions = list(report.get("exemptions") or [])
        lines = [
            "DAQ RUNNER ALIGNMENT AUDIT",
            "",
            f"Registered form-grid contracts: {len(contracts)}",
            f"Explicit custom-grid exemptions: {len(exemptions)}",
            f"Potential contract gaps: {len(findings)}",
            "",
        ]
        if findings:
            lines.append("Potential gaps:")
            for item in findings:
                lines.append(
                    f"  {item.get('widget')} | cols={item.get('columns')} | grid_children={item.get('child_count')}"
                )
            lines.append("")
        else:
            lines.extend(["Potential gaps:", "  none", ""])
        lines.append("Explicit exemptions:")
        if exemptions:
            for item in exemptions:
                lines.append(
                    f"  {item.get('widget')} | cols={item.get('columns')} | reason={item.get('reason')}"
                )
        else:
            lines.append("  none")
        lines.append("")
        lines.append("Registered contracts:")
        if contracts:
            for item in contracts:
                lines.append(
                    f"  {item.get('widget')} -> {item.get('contract')} | cols={item.get('columns')}"
                )
        else:
            lines.append("  none")
        lines.extend(["", "Note: This audit flags standard grid-based runner forms. Custom tables, graph tiles, and purpose-built engineering editors may remain intentionally explicit when marked exempt."])
        return "\n".join(lines)

