    def _runner_collect_text_audit_entries(root_widget: tk.Widget, surface: str) -> List[Dict[str, str]]:
        entries: List[Dict[str, str]] = []
        visited: set[str] = set()

        def _widget_label(widget: tk.Widget) -> str:
            try:
                txt = str(widget.cget("text") or "").strip()
            except Exception:
                txt = ""
            cls = str(widget.winfo_class() or widget.__class__.__name__)
            if txt:
                return f"{cls}: {txt}"
            try:
                name = str(widget.winfo_name() or "").strip()
            except Exception:
                name = ""
            return f"{cls}: {name}" if name else cls

        def _add(source: str, text: str) -> None:
            txt = str(text or "").strip()
            if txt:
                entries.append({"surface": surface, "source": source, "text": txt})

        def _walk(widget: tk.Widget) -> None:
            try:
                wid = str(widget)
            except Exception:
                wid = repr(widget)
            if wid in visited:
                return
            visited.add(wid)

            source = _widget_label(widget)
            try:
                txt = str(widget.cget("text") or "").strip()
            except Exception:
                txt = ""
            if txt:
                _add(source, txt)
            try:
                text_var = str(widget.cget("textvariable") or "").strip()
            except Exception:
                text_var = ""
            if text_var:
                try:
                    var_text = str(widget.getvar(text_var) or "").strip()
                except Exception:
                    var_text = ""
                if var_text:
                    _add(f"{source} [var]", var_text)
            if isinstance(widget, ttk.Treeview):
                try:
                    cols = list(widget["columns"] or [])
                except Exception:
                    cols = []
                for col in cols:
                    try:
                        heading_text = str((widget.heading(col) or {}).get("text") or "").strip()
                    except Exception:
                        heading_text = ""
                    if heading_text:
                        _add(f"{source} [heading:{col}]", heading_text)
            for child in list(getattr(widget, "winfo_children", lambda: [])()):
                _walk(child)

        _walk(root_widget)
        return entries

