    def _graph_window_s() -> float:
        try:
            v = float(var_graphs_window_s.get() or "300")
        except Exception:
            v = 300.0
        return max(30.0, min(3600.0, v))

    def _graph_metric_color(category: str) -> str:
        return str(GRAPH_CATEGORY_COLORS.get(category) or ACC)

    def _graph_safe_overlay_text(
        canvas: Any,
        x: float,
        y: float,
        text: str,
        *,
        anchor: str,
        fill: str,
        font: Tuple[str, int],
    ) -> None:
        try:
            text_id = canvas.create_text(x, y, anchor=anchor, text=str(text or ""), fill=fill, font=font)
            bbox = canvas.bbox(text_id)
            if bbox:
                bg = str(canvas.cget("bg") or PANEL_BG)
                rect_id = canvas.create_rectangle(
                    bbox[0] - GRAPH_AXIS_TEXT_BG_PAD_X,
                    bbox[1] - GRAPH_AXIS_TEXT_BG_PAD_Y,
                    bbox[2] + GRAPH_AXIS_TEXT_BG_PAD_X,
                    bbox[3] + GRAPH_AXIS_TEXT_BG_PAD_Y,
                    fill=bg,
                    outline="",
                )
                canvas.tag_lower(rect_id, text_id)
        except Exception:
            pass

    def _graph_sync_tile_layout(metric_id: str) -> None:
        tile = graph_runtime["tiles"].get(metric_id)
        if tile is None:
            return
        try:
            frame = tile.get("frame")
            width = max(int(frame.winfo_width() or 260), GRAPH_TILE_MIN_WIDTH)
            header_wrap = max(120, width - 124)
            meta_wrap = max(140, width - (GRAPH_TILE_CANVAS_PAD_X * 2))
            tile["label_widget"].configure(wraplength=header_wrap, justify="left")
            tile["meta_widget"].configure(wraplength=meta_wrap, justify="left")
        except Exception:
            pass

    def _graph_pretty_label(key: str) -> str:
        label = str(key or "").strip()
        special = {
            "site_T_amb_F": "Ambient Temp",
            "site_P_bar_psia": "Barometric Pressure",
            "site_RH_frac": "Relative Humidity",
            "site_z": "Compressibility z",
            "heat_input_mmbtu_hr": "Heat Input",
            "exh_flow_dscfh": "Exhaust Flow (dscfh)",
            "exh_flow_dscfm": "Exhaust Flow (dscfm)",
            "stack_flow_acfm_from_qd_calc": "Stack Flow (acfm)",
            "stack_velocity_fps_from_qd_calc": "Stack Velocity",
            "fuel_flow_scfh": "Fuel Flow (scfh)",
            "fuel_flow_scfm": "Fuel Flow (scfm)",
            "hp_used": "Horsepower",
            "hp_util_pct": "HP Utilization",
        }
        if label in special:
            return special[label]
        if label.isupper() and len(label) <= 6:
            return label
        label = label.replace("_", " ").replace("-", " ")
        return " ".join(part for part in label.split()).title()

    def _graph_infer_units(key: str, default_units: str = "") -> str:
        lk = str(key or "").lower()
        if default_units:
            return default_units
        if "humidity" in lk or lk.endswith("rh_frac"):
            return "%"
        if "temp" in lk or "temperature" in lk:
            return "F" if lk.endswith("_f") or "_f_" in lk else ""
        if "psia" in lk:
            return "psia"
        if "pressure" in lk or lk.startswith("press") or "_pressure" in lk:
            return ""
        if "velocity" in lk or lk.endswith("_fps"):
            return "ft/s"
        return ""

    def _graph_toggle_state() -> None:
        try:
            if bool(var_graphs_enabled.get()):
                graph_status_var.set(f"Graphs: ON | {_fmt_num(_graph_window_s(), 0, '300')} s history")
                if not graph_groups_host.winfo_ismapped():
                    graph_groups_host.pack(fill="x")
            else:
                graph_status_var.set("Graphs: OFF")
                if graph_groups_host.winfo_ismapped():
                    graph_groups_host.pack_forget()
        except Exception:
            pass

    def _graph_clear_history() -> None:
        try:
            graph_runtime["history"].clear()
            graph_runtime["last_sample_ts"] = 0.0
            for tile in graph_runtime["tiles"].values():
                try:
                    tile["value_var"].set("(n/a)")
                    tile["meta_var"].set("")
                    tile["canvas"].delete("all")
                    tile["canvas"].create_text(
                        max(40, int(tile["canvas"].winfo_width() or 260) // 2),
                        max(30, int(tile["canvas"].winfo_height() or GRAPH_TILE_MIN_HEIGHT) // 2),
                        text="Awaiting samples",
                        fill=FG_DIM,
                        font=("Consolas", 9),
                    )
                except Exception:
                    pass
        except Exception:
            pass

    def _graph_ensure_group(category: str) -> Dict[str, Any]:
        groups = graph_runtime["groups"]
        grp = groups.get(category)
        if grp is not None:
            return grp

        lf = tk.LabelFrame(graph_groups_host, text=category, bg=BG, fg=FG, font=("Consolas", 9, "bold"))
        lf.pack(fill="x", pady=(6, 0))
        body = tk.Frame(lf, bg=BG)
        body.pack(fill="x", padx=8, pady=8)
        for col in range(3):
            body.grid_columnconfigure(col, weight=1, uniform=f"graph_{category}")
        grp = {"frame": lf, "body": body, "order": []}
        groups[category] = grp
        return grp

    def _graph_draw_metric(metric_id: str) -> None:
        tile = graph_runtime["tiles"].get(metric_id)
        meta = graph_runtime["meta"].get(metric_id) or {}
        hist = graph_runtime["history"].get(metric_id)
        if tile is None:
            return

        canvas = tile["canvas"]
        try:
            canvas.delete("all")
            width = max(int(canvas.winfo_width() or 260), GRAPH_TILE_MIN_WIDTH)
            height = max(int(canvas.winfo_height() or GRAPH_TILE_MIN_HEIGHT), GRAPH_TILE_MIN_HEIGHT)
            canvas.create_rectangle(1, 1, width - 1, height - 1, outline="#223040")
            if not hist:
                canvas.create_text(width / 2, height / 2, text="Awaiting samples", fill=FG_DIM, font=("Consolas", 9))
                return

            pts = list(hist)
            if len(pts) < 2:
                canvas.create_text(width / 2, height / 2, text="Collecting trend", fill=FG_DIM, font=("Consolas", 9))
                return

            if len(pts) > 120:
                stride = max(1, int(round(len(pts) / 120.0)))
                pts = pts[::stride]

            values = [float(v) for _, v in pts]
            v_min = min(values)
            v_max = max(values)
            if not math.isfinite(v_min) or not math.isfinite(v_max):
                canvas.create_text(width / 2, height / 2, text="Invalid samples", fill=BAD, font=("Consolas", 9))
                return
            if abs(v_max - v_min) < 1e-9:
                pad = max(1.0, abs(v_max) * 0.05)
                v_min -= pad
                v_max += pad

            left = GRAPH_PLOT_PAD_LEFT
            right = width - GRAPH_PLOT_PAD_RIGHT
            top = GRAPH_PLOT_PAD_TOP
            bottom = height - GRAPH_PLOT_PAD_BOTTOM
            coords: List[float] = []
            span_x = max(1, len(pts) - 1)
            span_y = max(1e-9, v_max - v_min)
            for idx, (_, val) in enumerate(pts):
                x = left + (right - left) * (idx / span_x)
                frac = (float(val) - v_min) / span_y
                y = bottom - (bottom - top) * frac
                coords.extend((x, y))

            is_pollutant = str(meta.get("category") or "") == "Pollutants"
            if is_pollutant:
                axis_max = _fmt_pollutant_measurement(v_max, "", meta.get("label"))
                axis_min = _fmt_pollutant_measurement(v_min, "", meta.get("label"))
            else:
                axis_max = _fmt_num(v_max, fallback="")
                axis_min = _fmt_num(v_min, fallback="")
            canvas.create_line(*coords, fill=str(meta.get("color") or ACC), width=2, smooth=True)
            _graph_safe_overlay_text(
                canvas,
                GRAPH_AXIS_TEXT_X,
                GRAPH_AXIS_TEXT_TOP_Y,
                axis_max,
                anchor="nw",
                fill=FG_DIM,
                font=("Consolas", 8),
            )
            _graph_safe_overlay_text(
                canvas,
                GRAPH_AXIS_TEXT_X,
                height - GRAPH_AXIS_TEXT_BOTTOM_Y,
                axis_min,
                anchor="sw",
                fill=FG_DIM,
                font=("Consolas", 8),
            )
        except Exception:
            pass

    def _graph_ensure_tile(metric_id: str, label: str, units: str, category: str, color: str) -> None:
        if metric_id in graph_runtime["tiles"]:
            tile = graph_runtime["tiles"][metric_id]
            try:
                tile["label_var"].set(label)
                tile["meta_var"].set(units)
            except Exception:
                pass
            return

        grp = _graph_ensure_group(category)
        order = grp["order"]
        idx = len(order)
        order.append(metric_id)
        row = idx // 3
        col = idx % 3

        frame = tk.Frame(grp["body"], bg=PANEL_BG, highlightthickness=1, highlightbackground="#223040", bd=0)
        frame.grid(row=row, column=col, sticky="nsew", padx=6, pady=6)
        grp["body"].grid_rowconfigure(row, weight=1)

        label_var = tk.StringVar(value=label)
        value_var = tk.StringVar(value="(n/a)")
        meta_var = tk.StringVar(value=units)

        hdr = tk.Frame(frame, bg=PANEL_BG)
        hdr.pack(fill="x", padx=GRAPH_TILE_HEADER_PAD_X, pady=(GRAPH_TILE_HEADER_PAD_Y, 4))
        hdr.grid_columnconfigure(0, weight=1)
        hdr.grid_columnconfigure(1, weight=0, minsize=88)
        label_widget = tk.Label(
            hdr,
            textvariable=label_var,
            fg=FG,
            bg=PANEL_BG,
            font=("Consolas", 9, "bold"),
            anchor="w",
            justify="left",
        )
        label_widget.grid(row=0, column=0, sticky="w")
        value_widget = tk.Label(
            hdr,
            textvariable=value_var,
            fg=color,
            bg=PANEL_BG,
            font=("Consolas", 9, "bold"),
            anchor="e",
            justify="right",
        )
        value_widget.grid(row=0, column=1, sticky="e", padx=(12, 0))

        canvas = tk.Canvas(frame, bg=PANEL_BG, highlightthickness=0, bd=0, height=GRAPH_TILE_MIN_HEIGHT)
        canvas.pack(fill="x", expand=True, padx=GRAPH_TILE_CANVAS_PAD_X, pady=(0, GRAPH_TILE_CANVAS_PAD_Y))
        meta_widget = tk.Label(
            frame,
            textvariable=meta_var,
            fg=FG_DIM,
            bg=PANEL_BG,
            font=("Consolas", 8),
            anchor="w",
            justify="left",
        )
        meta_widget.pack(anchor="w", fill="x", padx=GRAPH_TILE_HEADER_PAD_X, pady=(0, GRAPH_TILE_META_PAD_Y))

        graph_runtime["tiles"][metric_id] = {
            "frame": frame,
            "canvas": canvas,
            "label_var": label_var,
            "value_var": value_var,
            "meta_var": meta_var,
            "label_widget": label_widget,
            "value_widget": value_widget,
            "meta_widget": meta_widget,
        }
        try:
            frame.bind("<Configure>", lambda _evt, _mid=metric_id: _graph_sync_tile_layout(_mid))
            canvas.bind("<Configure>", lambda _evt, _mid=metric_id: _graph_draw_metric(_mid))
        except Exception:
            pass
        _graph_sync_tile_layout(metric_id)
        _graph_draw_metric(metric_id)

    def _graph_append_metric(metric_id: str, label: str, category: str, units: str, value: float, now_ep: float) -> None:
        if value is None or (not isinstance(value, (int, float))) or (not math.isfinite(float(value))):
            return

        color = _graph_metric_color(category)
        graph_runtime["meta"][metric_id] = {
            "label": label,
            "category": category,
            "units": units,
            "color": color,
        }
        _graph_ensure_tile(metric_id, label, units, category, color)

        hist = graph_runtime["history"].setdefault(metric_id, deque(maxlen=1800))
        hist.append((float(now_ep), float(value)))
        cutoff = float(now_ep) - _graph_window_s()
        try:
            while hist and float(hist[0][0]) < cutoff:
                hist.popleft()
        except Exception:
            pass

        tile = graph_runtime["tiles"].get(metric_id)
        if tile is not None:
            try:
                if category == "Pollutants":
                    disp_value = _fmt_pollutant_measurement(value, "", label)
                else:
                    disp_value = _fmt_num(value, fallback="")
                tile["value_var"].set(f"{disp_value} {units}".strip())
                tile["meta_var"].set(f"{units or 'unitless'} | {category}")
            except Exception:
                pass
        _graph_draw_metric(metric_id)

    def _graph_collect_live_metrics(
        frame: Dict[str, Any],
        raw_map: Dict[str, Optional[float]],
        dry_map: Dict[str, Optional[float]],
        corr_map: Dict[str, Optional[float]],
        units_map: Dict[str, str],
    ) -> None:
        if not bool(var_graphs_enabled.get()):
            return

        now_ep = time.time()
        last_sample = float(graph_runtime.get("last_sample_ts") or 0.0)
        if last_sample and (now_ep - last_sample) < 1.0:
            return
        graph_runtime["last_sample_ts"] = now_ep

        metric_count = 0
        pollutant_codes = [code for code in poll_iids.keys() if code != "__none__"]
        for code in pollutant_codes:
            value = corr_map.get(code)
            basis = "corr"
            if value is None:
                value = dry_map.get(code)
                basis = "dry"
            if value is None:
                value = raw_map.get(code)
                basis = "raw"
            if value is None:
                continue
            units = str(units_map.get(code) or "")
            units_label = units
            if code not in ("O2", "CO2"):
                if basis == "corr" and units:
                    units_label = f"{units} corr"
                elif basis == "dry" and units:
                    units_label = f"{units} dry"
            _graph_append_metric(f"poll:{code}", code, "Pollutants", units_label, float(value), now_ep)
            metric_count += 1

        site_temp = _parse_float(frame.get("site_T_amb_F"), None)
        if site_temp is None and last_site_active is not None:
            site_temp = _parse_float(getattr(last_site_active, "T_amb_F", None), None)
        if site_temp is not None:
            _graph_append_metric("site:temp", "Ambient Temp", "Weather / Site", "F", float(site_temp), now_ep)
            metric_count += 1

        site_press = _parse_float(frame.get("site_P_bar_psia"), None)
        if site_press is None and last_site_active is not None:
            site_press = _parse_float(getattr(last_site_active, "P_bar_psia", None), None)
        if site_press is not None:
            _graph_append_metric("site:press", "Barometric Pressure", "Weather / Site", "psia", float(site_press), now_ep)
            metric_count += 1

        site_rh = _parse_float(frame.get("site_RH_frac"), None)
        if site_rh is None and last_site_active is not None:
            site_rh = _parse_float(getattr(last_site_active, "RH_frac", None), None)
        if site_rh is not None:
            _graph_append_metric("site:rh", "Relative Humidity", "Weather / Site", "%", float(site_rh) * 100.0, now_ep)
            metric_count += 1

        site_z = _parse_float(frame.get("site_z"), None)
        if site_z is None and last_site_active is not None:
            site_z = _parse_float(getattr(last_site_active, "z", None), None)
        if site_z is not None:
            _graph_append_metric("site:z", "Compressibility z", "Weather / Site", "z", float(site_z), now_ep)
            metric_count += 1

        m19 = last_m19_res if isinstance(last_m19_res, dict) else {}

        def _m19_num(*keys: str) -> Optional[float]:
            for key in keys:
                val = _parse_float(m19.get(key), None)
                if val is not None:
                    return float(val)
            return None

        flow_defs = [
            ("m19:heat_input", "Heat Input", "Flow / Heat", "MMBtu/hr", _m19_num("heat_input_mmbtu_hr", "heat_input_R_mmbtu_hr", "R_mmbtu_hr")),
            ("m19:qd_dscfm", "Exhaust Flow (dscfm)", "Flow / Heat", "dscfm", _m19_num("exh_flow_dscfm", "q_dscfm")),
            ("m19:qd_dscfh", "Exhaust Flow (dscfh)", "Flow / Heat", "dscfh", _m19_num("exh_flow_dscfh", "q_dscfh", "qd_dscfh_calc")),
            ("m19:acfm", "Stack Flow (acfm)", "Flow / Heat", "acfm", _m19_num("stack_flow_acfm_from_qd_calc", "stack_flow_acfm_calc")),
            ("m19:velocity", "Stack Velocity", "Flow / Heat", "ft/s", _m19_num("stack_velocity_fps_from_qd_calc", "stack_velocity_fps_calc")),
            ("m19:fuel_scfh", "Fuel Flow (scfh)", "Flow / Heat", "scfh", _m19_num("fuel_flow_scfh")),
            ("m19:fuel_scfm", "Fuel Flow (scfm)", "Flow / Heat", "scfm", _m19_num("fuel_flow_scfm")),
            ("m19:hp_used", "Horsepower", "Flow / Heat", "bhp", _m19_num("hp_used", "bhp_used", "actual_hp")),
            ("m19:hp_util", "HP Utilization", "Flow / Heat", "%", _m19_num("hp_util_pct")),
        ]
        for metric_id, label, category, units, val in flow_defs:
            if val is None:
                continue
            _graph_append_metric(metric_id, label, category, units, float(val), now_ep)
            metric_count += 1

        skip_keys = set(pollutant_codes) | {"O2", "CO2", "NOX", "site_T_amb_F", "site_P_bar_psia", "site_RH_frac", "site_z"}
        for key, val in (frame or {}).items():
            key_s = str(key)
            if key_s in skip_keys or key_s.startswith("_"):
                continue
            num = _parse_float(val, None)
            if num is None:
                continue
            lk = key_s.lower()
            if "temp" in lk or "temperature" in lk:
                _graph_append_metric(f"frame:{key_s}", _graph_pretty_label(key_s), "Temps / Pressures", _graph_infer_units(key_s, ""), float(num), now_ep)
                metric_count += 1
            elif "pressure" in lk or lk.startswith("press") or "_pressure" in lk or "psia" in lk:
                _graph_append_metric(f"frame:{key_s}", _graph_pretty_label(key_s), "Temps / Pressures", _graph_infer_units(key_s, ""), float(num), now_ep)
                metric_count += 1
            elif ("humid" in lk or "humidity" in lk) and key_s not in {"site_RH_frac"}:
                _graph_append_metric(f"frame:{key_s}", _graph_pretty_label(key_s), "Weather / Site", _graph_infer_units(key_s, ""), float(num), now_ep)
                metric_count += 1

                graph_status_var.set(f"Graphs: ON | {metric_count} metric(s) | {_fmt_num(_graph_window_s(), 0, '300')} s history")

