    def _set_section_title(section_inner: Any, title: str) -> None:
        try:
            host = getattr(section_inner, "master", None)
            if host is not None:
                host.configure(text=title)
        except Exception:
            pass

    def _set_section_visible(section_inner: Any, visible: bool) -> None:
        try:
            host = getattr(section_inner, "master", None)
            if host is None:
                return
            if visible:
                if str(host.winfo_manager() or "").strip() != "pack":
                    host.pack(fill="x", padx=12, pady=(10, 0))
            else:
                host.pack_forget()
        except Exception:
            pass

    def _scroll_to_runner_section(section_inner: Any) -> None:
        try:
            host = getattr(section_inner, "master", None)
            if host is None:
                return
            root.update_idletasks()
            bbox = canvas.bbox("all")
            if not bbox:
                return
            top_y = int(host.winfo_y() or 0)
            total_h = max(1, int(bbox[3] - bbox[1]))
            view_h = max(1, int(canvas.winfo_height() or 1))
            denom = max(1, total_h - view_h)
            frac = max(0.0, min(1.0, float(top_y) / float(denom)))
            canvas.yview_moveto(frac)
        except Exception:
            pass

    def _apply_diagnostics_layout() -> None:
        if not diagnostics_ui:
            return
        _set_section_title(sec_poll, "Diagnostics Measurements (Live)")
        _set_section_title(sec_graphs, "Live Graphs")
        _set_section_title(sec_site, "Weather / Site Conditions")
        _set_section_title(sec_fuel, "Fuel Basis / Method 19 Reference")
        _set_section_title(sec_runs, "Method 19 Operator Inputs / Derived Outputs")
        _set_section_title(sec_diag_verify, TEXT_DIAG_VERIFICATION_ATTESTATION)
        _set_section_title(sec_calc_audit, "Calculation Audit / Provenance")
        _set_section_title(sec_log, "Diagnostics Runner Log")

        visible = {"poll", "graphs", "site", "fuel", "runs", "diag_verify", "audit", "log"}
        for key, section_inner in runner_sections.items():
            _set_section_visible(section_inner, key in visible)

        try:
            log("Diagnostics layout active: live pollutants, graphs, Method 19 inputs, weather, trim, and print snapshot tools only.")
        except Exception:
            pass

