    def _static_artifact_state() -> Dict[str, List[Dict[str, Any]]]:
        blk = _ensure_daq_schema(sess)
        st = blk.get("static_artifacts") if isinstance(blk.get("static_artifacts"), dict) else {}
        site = st.get("site_photos")
        docs = st.get("field_documents")
        if not isinstance(site, list):
            site = []
            st["site_photos"] = site
        if not isinstance(docs, list):
            docs = []
            st["field_documents"] = docs
        sess["static_artifacts"] = st
        return {"site_photos": site, "field_documents": docs}

    def _refresh_static_artifacts_ui() -> None:
        state = _static_artifact_state()
        try:
            site_photo_list.delete(0, "end")
            for rec in state["site_photos"]:
                label = str(rec.get("label") or Path(str(rec.get("stored_path") or "")).name or "photo")
                site_photo_list.insert("end", label)
            site_photo_status_var.set(f"{len(state['site_photos'])} photo(s)")
        except Exception:
            pass
        try:
            field_doc_list.delete(0, "end")
            for rec in state["field_documents"]:
                label = str(rec.get("label") or Path(str(rec.get("stored_path") or "")).name or "document")
                field_doc_list.insert("end", label)
            field_doc_status_var.set(f"{len(state['field_documents'])} document(s)")
        except Exception:
            pass

    def _open_path_best_effort(path_str: str) -> None:
        if not path_str:
            return
        try:
            if os.name == "nt":
                os.startfile(path_str)  # type: ignore
            else:
                subprocess.Popen(["xdg-open", path_str])
        except Exception as exc:
            try:
                messagebox.showwarning("Artifacts", f"Unable to open path:\n{path_str}\n\n{exc}")
            except Exception:
                pass

    def _add_static_artifacts(category: str) -> None:
        nonlocal ui_outputs
        if category == "site_photos":
            filetypes = [
                ("Images", "*.png *.jpg *.jpeg *.bmp *.gif *.tif *.tiff"),
                ("All files", "*.*"),
            ]
            title = "Select site photo(s)"
        else:
            filetypes = [
                ("PDF files", "*.pdf"),
                ("All files", "*.*"),
            ]
            title = "Select scanned field artifact PDF(s)"
        picked = filedialog.askopenfilenames(title=title, filetypes=filetypes)
        if not picked:
            return
        state = _static_artifact_state()
        added = 0
        for item in picked:
            src = Path(str(item)).expanduser()
            if not src.exists() or not src.is_file():
                continue
            try:
                ui_outputs = init_outputs(sess, cfg_path, None)
                rec = _copy_static_artifact(ui_outputs, src, category)
                state[category].append(rec)
                with ui_outputs.raw_events_path.open("a", encoding="utf-8") as ev_f:
                    _write_raw_event(ev_f, sess, ui_outputs, "STATIC_ARTIFACT_ADDED", {
                        "category": category,
                        "label": rec.get("label"),
                        "stored_rel_path": rec.get("stored_rel_path"),
                        "sha256": rec.get("sha256"),
                    })
                added += 1
            except Exception as exc:
                log(f"Static artifact add failed for {src.name}: {exc}")
        if added:
            _save_session(sess)
            _write_manifest(ui_outputs, sess)
            _refresh_static_artifacts_ui()
            log(f"Attached {added} static artifact(s) to {category}.")

    def _open_selected_static_artifact(category: str) -> None:
        state = _static_artifact_state()
        listbox = site_photo_list if category == "site_photos" else field_doc_list
        try:
            sel = listbox.curselection()
            if not sel:
                return
            rec = state[category][int(sel[0])]
        except Exception:
            return
        _open_path_best_effort(str(rec.get("stored_path") or rec.get("source_path") or ""))

    def _remove_selected_static_artifact(category: str) -> None:
        nonlocal ui_outputs
        state = _static_artifact_state()
        listbox = site_photo_list if category == "site_photos" else field_doc_list
        try:
            sel = listbox.curselection()
            if not sel:
                return
            idx = int(sel[0])
            rec = state[category][idx]
        except Exception:
            return
        if not messagebox.askyesno("Remove Artifact", f"Remove '{rec.get('label') or 'artifact'}' from {category}?"):
            return
        try:
            ui_outputs = init_outputs(sess, cfg_path, None)
            _delete_static_artifact(ui_outputs, rec if isinstance(rec, dict) else {})
            del state[category][idx]
            with ui_outputs.raw_events_path.open("a", encoding="utf-8") as ev_f:
                _write_raw_event(ev_f, sess, ui_outputs, "STATIC_ARTIFACT_REMOVED", {
                    "category": category,
                    "label": rec.get("label") if isinstance(rec, dict) else "",
                    "stored_rel_path": rec.get("stored_rel_path") if isinstance(rec, dict) else "",
                })
            _save_session(sess)
            _write_manifest(ui_outputs, sess)
            _refresh_static_artifacts_ui()
            log(f"Removed static artifact from {category}.")
        except Exception as exc:
            try:
                messagebox.showwarning("Artifacts", f"Failed to remove artifact:\n\n{exc}")
            except Exception:
                pass

    btn_site_photo_add.configure(command=lambda: _add_static_artifacts("site_photos"))
    btn_site_photo_open.configure(command=lambda: _open_selected_static_artifact("site_photos"))
    btn_site_photo_remove.configure(command=lambda: _remove_selected_static_artifact("site_photos"))
    btn_field_doc_add.configure(command=lambda: _add_static_artifacts("field_documents"))
    btn_field_doc_open.configure(command=lambda: _open_selected_static_artifact("field_documents"))
    btn_field_doc_remove.configure(command=lambda: _remove_selected_static_artifact("field_documents"))
    _refresh_static_artifacts_ui()

    # Arcade soundtrack (optional)
    soundtrack_var = tk.BooleanVar(value=False)      # master enable
    soundtrack_auto_var = tk.StringVar(value="ALWAYS")  # ALWAYS | IDLE | TESTING | OFF
    soundtrack_vol_pct_var = tk.IntVar(value=20)     # 0..100
    soundtrack_state_var = tk.StringVar(value="")

    soundtrack_player = None
    soundtrack_vol_after_id = None
    soundtrack_last_should = {"val": None}

    def _soundtrack_track_abs(_sess: Dict[str, Any]) -> str:
        try:
            st = (_sess.get("soundtrack") or {}) if isinstance(_sess, dict) else {}
        except Exception:
            st = {}
        try:
            track = str(st.get("track") or "audio/mole_8bit_theme.wav").strip()
        except Exception:
            track = "audio/mole_8bit_theme.wav"
        if not track:
            track = "audio/mole_8bit_theme.wav"
        try:
            if os.path.isabs(track) and Path(track).exists():
                return str(Path(track).resolve())
        except Exception:
            pass
        # Prefer assets_dir (wizard sets absolute)
        try:
            assets_dir = ((_sess.get("paths") or {}) if isinstance(_sess, dict) else {}).get("assets_dir")
            if assets_dir:
                cand = Path(str(assets_dir)).expanduser() / track
                if cand.exists():
                    return str(cand.resolve())
        except Exception:
            pass
        # Fallbacks: script dir, then project root
        try:
            here = Path(__file__).resolve().parent
            cand = here / track
            if cand.exists():
                return str(cand.resolve())
        except Exception:
            pass
        try:
            rootp = Path(__file__).resolve().parent.parent
            cand = rootp / track
            if cand.exists():
                return str(cand.resolve())
        except Exception:
            pass
        return ""

    def _soundtrack_is_playing() -> bool:
        try:
            p = soundtrack_player
            if p is None:
                return False
            st = getattr(p, "status", None)
            return bool(st is not None and getattr(st, "started", False))
        except Exception:
            return False

    def _soundtrack_backend() -> str:
        try:
            p = soundtrack_player
            if p is None:
                return ""
            st = getattr(p, "status", None)
            return str(getattr(st, "backend", "") or "")
        except Exception:
            return ""

    def _soundtrack_refresh_btn() -> None:
        try:
            if btn_soundtrack is not None:
                btn_soundtrack.configure(text=('Arcade Soundtrack Off' if bool(soundtrack_var.get()) else 'Arcade Soundtrack On'))
        except Exception:
            pass

    def _soundtrack_refresh_state_label(testing: bool = False) -> None:
        try:
            enabled = bool(soundtrack_var.get())
        except Exception:
            enabled = False
        try:
            am = str(soundtrack_auto_var.get() or "ALWAYS").strip().upper()
        except Exception:
            am = "ALWAYS"
        if am not in ("ALWAYS", "IDLE", "TESTING", "OFF"):
            am = "ALWAYS"
            try:
                soundtrack_auto_var.set(am)
            except Exception:
                pass

        playing = _soundtrack_is_playing()
        backend = _soundtrack_backend()

        if (not enabled) or am == "OFF":
            msg = "Soundtrack: OFF"
        else:
            if playing:
                msg = "Soundtrack: PLAYING" + (f" ({backend})" if backend else "")
            else:
                # Standby explains why it may be quiet
                if am == "IDLE":
                    msg = "Soundtrack: STANDBY (Auto=IDLE)" if testing else "Soundtrack: READY (Auto=IDLE)"
                elif am == "TESTING":
                    msg = "Soundtrack: READY (Auto=TESTING)" if testing else "Soundtrack: STANDBY (Auto=TESTING)"
                else:
                    msg = f"Soundtrack: STANDBY (Auto={am})"
        try:
            soundtrack_state_var.set(msg)
        except Exception:
            pass

    def _soundtrack_should_play(testing: bool) -> bool:
        try:
            enabled = bool(soundtrack_var.get())
        except Exception:
            enabled = False
        if not enabled:
            return False
        try:
            am = str(soundtrack_auto_var.get() or "ALWAYS").strip().upper()
        except Exception:
            am = "ALWAYS"
        if am not in ("ALWAYS", "IDLE", "TESTING", "OFF"):
            am = "ALWAYS"
        if am == "OFF":
            return False
        if am == "ALWAYS":
            return True
        if am == "IDLE":
            return (not bool(testing))
        if am == "TESTING":
            return bool(testing)
        return True

    def _soundtrack_start() -> None:
        nonlocal soundtrack_player
        try:
            if soundtrack_player is not None:
                try:
                    if getattr(soundtrack_player, 'status', None) and getattr(soundtrack_player.status, 'started', False):
                        return
                except Exception:
                    pass
        except Exception:
            pass

        try:
            wav = _soundtrack_track_abs(sess)
            if not wav:
                return
            try:
                vol = float(soundtrack_vol_pct_var.get()) / 100.0
            except Exception:
                # fall back to session
                try:
                    st = (sess.get("soundtrack") or {})
                    vol = float(st.get("volume", 0.20) or 0.20)
                except Exception:
                    vol = 0.20

            try:
                from mole_soundtrack import SoundtrackPlayer  # type: ignore
            except Exception:
                SoundtrackPlayer = None  # type: ignore
            if SoundtrackPlayer is None:
                return

            p = SoundtrackPlayer(wav, volume=vol, loop=True, backend='auto', quiet=True)
            ok = bool(p.start())
            if ok:
                soundtrack_player = p
        except Exception:
            pass

    def _soundtrack_stop() -> None:
        nonlocal soundtrack_player
        try:
            if soundtrack_player is not None:
                try:
                    soundtrack_player.stop()
                except Exception:
                    pass
        finally:
            soundtrack_player = None

    def _soundtrack_apply_policy(testing: bool = False) -> None:
        """Idempotent policy enforcement: start/stop based on testing/idle + auto mode."""
        should = False
        try:
            should = bool(_soundtrack_should_play(bool(testing)))
        except Exception:
            should = False

        playing = _soundtrack_is_playing()
        try:
            if should and not playing:
                _soundtrack_start()
            elif (not should) and _soundtrack_is_playing():
                _soundtrack_stop()
        except Exception:
            pass

        try:
            _soundtrack_refresh_btn()
        except Exception:
            pass
        try:
            _soundtrack_refresh_state_label(testing=bool(testing))
        except Exception:
            pass

    def _soundtrack_persist() -> None:
        """Persist current soundtrack prefs into session JSON."""
        nonlocal sess
        try:
            sess = _load_session()
            _ensure_daq_schema(sess)
            st = sess.get("soundtrack")
            if not isinstance(st, dict):
                st = {}
                sess["soundtrack"] = st
            st["enabled"] = bool(soundtrack_var.get())
            st["track"] = str(st.get("track") or "audio/mole_8bit_theme.wav")
            try:
                st["volume"] = float(soundtrack_vol_pct_var.get()) / 100.0
            except Exception:
                st["volume"] = float(st.get("volume", 0.20) or 0.20)
            try:
                am = str(soundtrack_auto_var.get() or "ALWAYS").strip().upper()
            except Exception:
                am = "ALWAYS"
            if am not in ("ALWAYS", "IDLE", "TESTING", "OFF"):
                am = "ALWAYS"
            st["auto_mode"] = am
            _save_session(sess)
        except Exception:
            pass

    def toggle_soundtrack() -> None:
        nonlocal sess
        try:
            new_state = (not bool(soundtrack_var.get()))
            soundtrack_var.set(bool(new_state))
        except Exception:
            new_state = False

        try:
            _soundtrack_persist()
        except Exception:
            pass

        # Apply policy using current acquisition state (testing/idle)
        try:
            _is_testing = False
            try:
                _is_testing = bool(str(acq_var.get()).strip().upper() == "RUNNING")
            except Exception:
                _is_testing = False
            _soundtrack_apply_policy(testing=_is_testing)
        except Exception:
            pass

        _soundtrack_refresh_btn()

    def _on_soundtrack_auto_change(*_args) -> None:
        try:
            _soundtrack_persist()
        except Exception:
            pass
        try:
            _is_testing = bool(str(acq_var.get()).strip().upper() == "RUNNING")
        except Exception:
            _is_testing = False
        try:
            _soundtrack_apply_policy(testing=_is_testing)
        except Exception:
            pass

    def _on_soundtrack_volume_change(v=None) -> None:
        nonlocal soundtrack_vol_after_id
        try:
            pct = int(float(v)) if v is not None else int(soundtrack_vol_pct_var.get())
        except Exception:
            try:
                pct = int(soundtrack_vol_pct_var.get())
            except Exception:
                pct = 20
        if pct < 0:
            pct = 0
        if pct > 100:
            pct = 100
        try:
            soundtrack_vol_pct_var.set(int(pct))
        except Exception:
            pass

        # Persist preference
        try:
            _soundtrack_persist()
        except Exception:
            pass

        # Update percent label if present
        try:
            if lbl_soundtrack_volpct is not None:
                lbl_soundtrack_volpct.configure(text=f"{int(pct)}%")
        except Exception:
            pass

        # Debounce backend restart for winsound/simpleaudio
        try:
            if soundtrack_vol_after_id is not None:
                try:
                    root.after_cancel(soundtrack_vol_after_id)  # type: ignore
                except Exception:
                    pass
        except Exception:
            pass

        vol = float(pct) / 100.0

        def _apply():
            nonlocal soundtrack_vol_after_id
            soundtrack_vol_after_id = None
            try:
                p = soundtrack_player
                if p is not None:
                    try:
                        p.set_volume(vol)
                    except Exception:
                        pass
            except Exception:
                pass
            try:
                _is_testing = bool(str(acq_var.get()).strip().upper() == "RUNNING")
            except Exception:
                _is_testing = False
            try:
                _soundtrack_refresh_state_label(testing=_is_testing)
            except Exception:
                pass

        try:
            soundtrack_vol_after_id = root.after(200, _apply)  # type: ignore
        except Exception:
            _apply()

    # Prime initial state from session
    try:
        st0 = (sess.get("soundtrack") or {})
        soundtrack_var.set(bool(st0.get("enabled", False)))
        try:
            soundtrack_vol_pct_var.set(int(round(float(st0.get("volume", 0.20) or 0.20) * 100)))
        except Exception:
            soundtrack_vol_pct_var.set(20)
        try:
            _am0 = str(st0.get("auto_mode", "ALWAYS") or "ALWAYS").strip().upper()
        except Exception:
            _am0 = "ALWAYS"
        if _am0 not in ("ALWAYS", "IDLE", "TESTING", "OFF"):
            _am0 = "ALWAYS"
        soundtrack_auto_var.set(_am0)
    except Exception:
        pass

    # state: acquisition
    q_frames: _queue.Queue = _queue.Queue(maxsize=50)
    acq = {
        "thread": None,
        "stop": None,
        "record_evt": None,
        "driver": None,
        "outputs": None,
        "header": None,
        "writer": None,
        "csv_file": None,
        "tok_file": None,
        "last_error": None,
        "last_error_detail": None,
        "last_error_token": None,
        "last_error_seen": None,
        "reference_snapshot": None,
    }

    # Live frame cache (for worksteps captures)
    last_frame: Dict[str, Any] = {}
    frame_hist = deque(maxlen=3000)  # (~50 min @ 1 Hz)
    fps_hist = deque(maxlen=400)     # rolling timestamps for FPS estimate
    last_site_active: Optional[SiteConditionsActive] = None

    def _populate_pollutants(sess: Dict[str, Any]) -> None:
        nonlocal poll_iids
        poll_tree.delete(*poll_tree.get_children())
        poll_iids = {}

        sel = _display_selected_pollutants(sess)
        sel_set = set(sel)
        pres = _augment_prescriptions_with_derived_nox(sess, _pollutant_prescriptions(sess))
        lim_map = _limits_by_pollutant(sess)

        # Display *all* configured pollutants (from prescriptions), with non-selected shown but greyed.
        all_codes = list((pres or {}).keys())
        if not all_codes and not sel:
            iid = poll_tree.insert("", "end", values=("—", "(none)", "", "", "", "", "", "", "", ""))
            poll_iids["__none__"] = iid
            return

        # Preserve the user's selected order; append remaining prescriptions alphabetically.
        order: list[str] = []
        for c in sel:
            if c not in order:
                order.append(c)
        for c in sorted(all_codes):
            if c not in order:
                order.append(c)

        default_o2_ref = (var_norm_o2_ref.get() or "").strip()

        for code in order:
            p = pres.get(code) or {}
            units = str(p.get("expected_units") or p.get("units") or "").strip()

            lims = lim_map.get(code) or []
            lim_val = ""
            lim_units = ""
            o2_ref = ""

            if lims:
                lim_val = _fmt_num(lims[0].get("value"), 3, "")
                lim_units = str(lims[0].get("units") or "").strip()
                # O2 reference can be provided by the limit itself
                for k in ("o2_ref_pct", "o2_ref", "o2"):
                    if lims[0].get(k) not in (None, "", 0):
                        o2_ref = _fmt_num(lims[0].get(k), 3, "")
                        break

            # Otherwise, fall back to the UI default (if set)
            if (not o2_ref) and default_o2_ref and code not in ("O2",):
                o2_ref = default_o2_ref

            tag = "sel" if code in sel_set else "dim"

            iid = poll_tree.insert(
                "",
                "end",
                tags=(tag,),
                values=(code, "(n/a)", "(n/a)", "(n/a)", units, o2_ref, lim_val, lim_units, "(n/a)", ""),
            )
            poll_iids[code] = iid

    def _reference_cfg_block(sess_local: Dict[str, Any]) -> Dict[str, Any]:
        blk = _ensure_daq_schema(sess_local)
        ref_cfg = blk.get("reference_audit")
        if not isinstance(ref_cfg, dict):
            ref_cfg = {}
            blk["reference_audit"] = ref_cfg
        if mole_ftir_reference is not None:
            try:
                ref_cfg = mole_ftir_reference.normalize_config(ref_cfg)
                blk["reference_audit"] = ref_cfg
            except Exception:
                pass
        if mole_ftir_offset_recommendations is not None:
            try:
                store = mole_ftir_offset_recommendations.load_store()
                ref_cfg["offset_recommendations"] = mole_ftir_offset_recommendations.normalize_project_policy(
                    ref_cfg.get("offset_recommendations"),
                    default_use_global=bool(store.get("auto_apply_future_projects")),
                )
                blk["reference_audit"] = ref_cfg
            except Exception:
                ref_cfg["offset_recommendations"] = dict(mole_ftir_offset_recommendations.DEFAULT_PROJECT_POLICY)
        return ref_cfg

    def _reference_display_codes(sess_local: Dict[str, Any], snapshot: Optional[Dict[str, Any]] = None) -> list[str]:
        codes: list[str] = []
        for code in _display_selected_pollutants(sess_local):
            if code not in codes:
                codes.append(code)
        try:
            ref_cfg = _reference_cfg_block(sess_local)
            for code in sorted((ref_cfg.get("column_overrides") or {}).keys()):
                code_u = str(code or "").strip().upper()
                if code_u and code_u not in codes:
                    codes.append(code_u)
        except Exception:
            pass
        try:
            for code in sorted(((snapshot or {}).get("measurements") or {}).keys()):
                code_u = str(code or "").strip().upper()
                if code_u and code_u not in codes:
                    codes.append(code_u)
        except Exception:
            pass
        for extra in ("O2", "CO2"):
            if extra not in codes:
                codes.append(extra)
        return codes

    def _populate_reference_table(sess_local: Dict[str, Any], snapshot: Optional[Dict[str, Any]] = None) -> None:
        nonlocal ref_iids
        try:
            ref_tree.delete(*ref_tree.get_children())
        except Exception:
            pass
        ref_iids = {}
        for code in _reference_display_codes(sess_local, snapshot):
            iid = ref_tree.insert("", "end", tags=("dim",), values=(code, "(n/a)", "(n/a)", "", "", ""))
            ref_iids[code] = iid

    def _ensure_worksteps_events_path(sess_local: Dict[str, Any]) -> str:
        blk = _ensure_daq_schema(sess_local)
        ws = blk.get("worksteps")
        if not isinstance(ws, dict):
            ws = {}
            blk["worksteps"] = ws
        p = str(ws.get("events_path") or "").strip()
        if p:
            return p
        job = str(
            (sess_local.get("project") or {}).get("job_id")
            or (sess_local.get("project_session") or {}).get("job_id")
            or sess_local.get("job_id")
            or "session"
        ).strip() or "session"
        p = str(cfg_path.parent / f"mole_worksteps_{job}.jsonl")
        ws["events_path"] = p
        return p

    def _ftir_method_meta(method_value: Any) -> Dict[str, Any]:
        if mole_ftir_methods is not None:
            try:
                return mole_ftir_methods.method_meta(method_value)
            except Exception:
                pass
        code = str(method_value or "ASTM_D6348_12").strip() or "ASTM_D6348_12"
        return {
            "code": code,
            "label": code.replace("_", " "),
            "summary": "FTIR audit/reference checklist",
            "basis": "Project FTIR method selection",
            "steps": [],
        }

    def _ensure_ftir_method_state(sess_local: Dict[str, Any], method_value: Any) -> Tuple[Dict[str, Any], Dict[str, Any], Dict[str, Any]]:
        blk = _ensure_daq_schema(sess_local)
        ws = blk.get("worksteps")
        if not isinstance(ws, dict):
            ws = {}
            blk["worksteps"] = ws
        ftir_ws = ws.get("ftir_audit")
        if not isinstance(ftir_ws, dict):
            ftir_ws = {}
            ws["ftir_audit"] = ftir_ws
        meta = _ftir_method_meta(method_value)
        method_code = str(meta.get("code") or "ASTM_D6348_12").strip() or "ASTM_D6348_12"
        ftir_ws["method_standard"] = method_code
        by_method = ftir_ws.get("by_method")
        if not isinstance(by_method, dict):
            by_method = {}
            ftir_ws["by_method"] = by_method
        state = by_method.get(method_code)
        if not isinstance(state, dict):
            state = {}
            by_method[method_code] = state
        completed = state.get("completed")
        if not isinstance(completed, dict):
            completed = {}
            state["completed"] = completed
        history = state.get("history")
        if not isinstance(history, list):
            history = []
            state["history"] = history
        valid_ids = [str((step or {}).get("id") or "").strip() for step in (meta.get("steps") or []) if str((step or {}).get("id") or "").strip()]
        invalid_ids = [sid for sid in list(completed.keys()) if sid not in valid_ids]
        for sid in invalid_ids:
            completed.pop(sid, None)
        active_step_id = str(state.get("active_step_id") or "").strip()
        if active_step_id in completed or active_step_id not in valid_ids:
            active_step_id = next((sid for sid in valid_ids if sid not in completed), "")
            state["active_step_id"] = active_step_id
        return ftir_ws, state, meta

    def _populate_ftir_method_worksteps(sess_local: Dict[str, Any]) -> None:
        nonlocal ftir_ws_iids
        try:
            ftir_ws_tree.delete(*ftir_ws_tree.get_children())
        except Exception:
            pass
        ftir_ws_iids = {}

        ref_cfg = _reference_cfg_block(sess_local)
        meta = _ftir_method_meta(ref_cfg.get("method_standard"))
        _, state, meta = _ensure_ftir_method_state(sess_local, meta.get("code"))
        steps = [dict(step) for step in (meta.get("steps") or []) if isinstance(step, dict)]
        completed = state.get("completed") if isinstance(state.get("completed"), dict) else {}
        active_step_id = str(state.get("active_step_id") or "").strip()

        enabled = bool(ref_cfg.get("enabled"))
        role = str(ref_cfg.get("role") or "AUDIT").strip().upper() or "AUDIT"
        active_workflow = bool(enabled and role == "AUDIT")
        done_count = sum(1 for rec in completed.values() if isinstance(rec, dict) and str(rec.get("status") or "").strip().upper() == "DONE")
        skipped_count = sum(1 for rec in completed.values() if isinstance(rec, dict) and str(rec.get("status") or "").strip().upper() == "SKIPPED")

        ftir_ws_summary_var.set(f"{meta.get('label')}: {meta.get('summary')}")
        ftir_ws_basis_var.set(f"Basis: {meta.get('basis')}")
        if not enabled:
            ftir_ws_status_var.set("FTIR audit workflow: inactive | enable MG2000 FTIR ingest to use method worksteps")
        elif role != "AUDIT":
            ftir_ws_status_var.set(f"FTIR audit workflow: preview only | role={role} | {done_count} done, {skipped_count} skipped")
        else:
            remaining = max(0, len(steps) - len(completed))
            ftir_ws_status_var.set(f"FTIR audit workflow: active | {done_count} done, {skipped_count} skipped, {remaining} remaining")

        for idx, step in enumerate(steps, start=1):
            sid = str(step.get("id") or "").strip()
            if not sid:
                continue
            rec = completed.get(sid) if isinstance(completed, dict) else None
            status_txt = "PENDING"
            tag = "pending"
            if isinstance(rec, dict):
                saved_status = str(rec.get("status") or "").strip().upper()
                if saved_status == "DONE":
                    status_txt = "DONE"
                    tag = "done"
                elif saved_status == "SKIPPED":
                    status_txt = "SKIPPED"
                    tag = "skipped"
            elif active_workflow and sid == active_step_id:
                status_txt = "ACTIVE"
                tag = "active"
            elif not active_workflow:
                status_txt = "INACTIVE"
                tag = "inactive"
            iid = ftir_ws_tree.insert(
                "",
                "end",
                tags=(tag,),
                values=(f"{idx}. {str(step.get('label') or sid)}", status_txt, str(step.get("criterion") or "")),
            )
            ftir_ws_iids[sid] = iid

    def _ftir_method_selected_step_id() -> str:
        try:
            sel = ftir_ws_tree.selection()
        except Exception:
            sel = ()
        if sel:
            iid = str(sel[0])
            for sid, row_iid in ftir_ws_iids.items():
                if row_iid == iid:
                    return sid
        return ""

    def _ftir_method_mark(step_status: str) -> None:
        nonlocal sess
        status_norm = str(step_status or "").strip().upper() or "DONE"
        try:
            sess = _load_session()
            ref_cfg = _reference_cfg_block(sess)
            enabled = bool(ref_cfg.get("enabled"))
            role = str(ref_cfg.get("role") or "AUDIT").strip().upper() or "AUDIT"
            if (not enabled) or role != "AUDIT":
                messagebox.showwarning("FTIR Worksteps", "FTIR method worksteps are only actionable when the FTIR module is enabled in AUDIT mode.")
                return
            ftir_ws, state, meta = _ensure_ftir_method_state(sess, ref_cfg.get("method_standard"))
            completed = state.get("completed") if isinstance(state.get("completed"), dict) else {}
            history = state.get("history") if isinstance(state.get("history"), list) else []
            step_ids = [str((step or {}).get("id") or "").strip() for step in (meta.get("steps") or []) if str((step or {}).get("id") or "").strip()]
            sid = _ftir_method_selected_step_id() or str(state.get("active_step_id") or "").strip()
            if not sid:
                messagebox.showinfo("FTIR Worksteps", "No remaining FTIR method step is available to mark.")
                return
            step_map = {
                str((step or {}).get("id") or "").strip(): dict(step)
                for step in (meta.get("steps") or [])
                if isinstance(step, dict) and str((step or {}).get("id") or "").strip()
            }
            if sid not in step_map:
                messagebox.showwarning("FTIR Worksteps", "The selected FTIR step is not valid for the current method.")
                return
            ts_iso = datetime.now().astimezone().isoformat(timespec="seconds")
            completed[sid] = {
                "status": status_norm,
                "timestamp_iso": ts_iso,
                "label": str((step_map.get(sid) or {}).get("label") or sid),
            }
            history.append(
                {
                    "event": "STEP_MARKED",
                    "status": status_norm,
                    "step_id": sid,
                    "step_label": str((step_map.get(sid) or {}).get("label") or sid),
                    "timestamp_iso": ts_iso,
                }
            )
            if len(history) > 500:
                del history[:-500]
            state["active_step_id"] = next((step_id for step_id in step_ids if step_id not in completed), "")
            _ensure_worksteps_events_path(sess)
            _save_session(sess)
            try:
                _ws_log_event(
                    sess,
                    "FTIR_METHOD_STEP",
                    {
                        "method_standard": str(meta.get("code") or ""),
                        "method_label": str(meta.get("label") or ""),
                        "step_id": sid,
                        "step_label": str((step_map.get(sid) or {}).get("label") or sid),
                        "status": status_norm,
                    },
                )
            except Exception:
                pass
            _populate_ftir_method_worksteps(sess)
            _update_reference_panel(None, sess)
            log(f"FTIR method step marked {status_norm}: {str((step_map.get(sid) or {}).get('label') or sid)}")
        except Exception as e:
            messagebox.showerror("FTIR Worksteps", str(e))

    def _ftir_method_reset() -> None:
        nonlocal sess
        if not messagebox.askyesno("FTIR Worksteps", "Reset FTIR method worksteps for the currently selected method?", default="no"):
            return
        try:
            sess = _load_session()
            ref_cfg = _reference_cfg_block(sess)
            ftir_ws, state, meta = _ensure_ftir_method_state(sess, ref_cfg.get("method_standard"))
            history = state.get("history") if isinstance(state.get("history"), list) else []
            ts_iso = datetime.now().astimezone().isoformat(timespec="seconds")
            state["completed"] = {}
            first_step = next(
                (
                    str((step or {}).get("id") or "").strip()
                    for step in (meta.get("steps") or [])
                    if str((step or {}).get("id") or "").strip()
                ),
                "",
            )
            state["active_step_id"] = first_step
            history.append(
                {
                    "event": "RESET",
                    "method_standard": str(meta.get("code") or ""),
                    "timestamp_iso": ts_iso,
                }
            )
            if len(history) > 500:
                del history[:-500]
            _ensure_worksteps_events_path(sess)
            _save_session(sess)
            try:
                _ws_log_event(
                    sess,
                    "FTIR_METHOD_RESET",
                    {
                        "method_standard": str(meta.get("code") or ""),
                        "method_label": str(meta.get("label") or ""),
                    },
                )
            except Exception:
                pass
            _populate_ftir_method_worksteps(sess)
            _update_reference_panel(None, sess)
            log(f"FTIR method worksteps reset for {str(meta.get('label') or meta.get('code') or 'method')}.")
        except Exception as e:
            messagebox.showerror("FTIR Worksteps", str(e))

    def _spike_cfg_block(sess_local: Dict[str, Any]) -> Dict[str, Any]:
        blk = _ensure_daq_schema(sess_local)
        ref_cfg = _reference_cfg_block(sess_local)
        cfg = blk.get("spike_recovery")
        if not isinstance(cfg, dict):
            cfg = sess_local.get("spike_recovery") if isinstance(sess_local.get("spike_recovery"), dict) else {}
        if mole_spike_recovery is not None:
            try:
                cfg = mole_spike_recovery.normalize_config(
                    cfg if isinstance(cfg, dict) else {},
                    ftir_enabled=bool(ref_cfg.get("enabled")),
                    ftir_role=str(ref_cfg.get("role") or "AUDIT"),
                    ftir_method=ref_cfg.get("method_standard"),
                )
            except Exception:
                pass
        if not isinstance(cfg, dict):
            cfg = {
                "enabled": False,
                "mandatory": False,
                "applies_to_mole": True,
                "applies_to_ftir": False,
                "recovery_pct_min": 70.0,
                "recovery_pct_max": 130.0,
                "criterion_summary": "Optional spike recovery disabled.",
            }
        blk["spike_recovery"] = dict(cfg)
        sess_local["spike_recovery"] = dict(cfg)
        return cfg

    def _ensure_spike_state(sess_local: Dict[str, Any]) -> Dict[str, Any]:
        blk = _ensure_daq_schema(sess_local)
        ws = blk.get("worksteps")
        if not isinstance(ws, dict):
            ws = {}
            blk["worksteps"] = ws
        state = ws.get("spike_recovery")
        if not isinstance(state, dict):
            state = {}
        if mole_spike_recovery is not None:
            try:
                state = mole_spike_recovery.normalize_state(state)
            except Exception:
                pass
        if not isinstance(state, dict):
            state = {"active_phase": "IDLE", "channels": {}, "history": []}
        state.setdefault("active_phase", "IDLE")
        if not isinstance(state.get("channels"), dict):
            state["channels"] = {}
        if not isinstance(state.get("history"), list):
            state["history"] = []

        pres = _pollutant_prescriptions(sess_local)
        for code in _selected_pollutants(sess_local):
            row = state["channels"].get(code)
            if not isinstance(row, dict):
                row = {}
                state["channels"][code] = row
            if row.get("spike_amount") in (None, ""):
                try:
                    seed = _parse_float((pres.get(code) or {}).get("span_target"))
                    if seed is None:
                        seed = _parse_float((pres.get(code) or {}).get("span_cylinder_id"))
                    row["spike_amount"] = seed
                except Exception:
                    row["spike_amount"] = None
            row["units"] = str((pres.get(code) or {}).get("expected_units") or (pres.get(code) or {}).get("units") or row.get("units") or "").strip()

        ws["spike_recovery"] = state
        return state

    def _current_reference_snapshot(sess_local: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        snap = acq.get("reference_snapshot")
        if isinstance(snap, dict):
            return snap
        if mole_ftir_reference is None:
            return None
        try:
            cfg = _reference_cfg_block(sess_local)
            if cfg.get("enabled") and str(cfg.get("prn_path") or "").strip():
                return mole_ftir_reference.MG2000PrnIngestor(cfg).read_snapshot()
        except Exception:
            return None
        return None

    def _reference_snapshot_value(snapshot: Optional[Dict[str, Any]], code: str) -> Optional[float]:
        try:
            rec = (((snapshot or {}).get("measurements") or {}).get(code) or {})
            return _parse_float(rec.get("value")) if isinstance(rec, dict) else None
        except Exception:
            return None

    def _frame_channel_value(frame_obj: Optional[Dict[str, Any]], key: str) -> Any:
        try:
            if not isinstance(frame_obj, dict):
                return None
            canon = str(key or "").strip()
            if not canon:
                return None
            raw_channels = frame_obj.get("_raw_channels")
            if isinstance(raw_channels, dict) and canon in raw_channels:
                return raw_channels.get(canon)
            return frame_obj.get(canon)
        except Exception:
            return None

    def _infer_sample_flow_units(sess_local: Dict[str, Any], channel_name: str = "") -> str:
        try:
            ss = sess_local.get("sample_system") if isinstance(sess_local.get("sample_system"), dict) else {}
            thresholds = ss.get("thresholds") if isinstance(ss.get("thresholds"), dict) else {}
            flow_thr = thresholds.get("sample_flow") if isinstance(thresholds.get("sample_flow"), dict) else {}
            units = str(flow_thr.get("units") or "").strip()
            if units:
                return units
        except Exception:
            pass
        canon = str(channel_name or "").strip().upper()
        if "SCFM" in canon:
            return "scfm"
        if "SCFH" in canon:
            return "scfh"
        if "SLM" in canon:
            return "slm"
        if "LPM" in canon:
            return "lpm"
        if "ACFM" in canon:
            return "acfm"
        return ""

    def _resolve_spike_flow_context(
        sess_local: Dict[str, Any],
        *,
        cfg_local: Optional[Dict[str, Any]] = None,
        state_local: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        cfg_use = cfg_local if isinstance(cfg_local, dict) else _spike_cfg_block(sess_local)
        state_use = state_local if isinstance(state_local, dict) else _ensure_spike_state(sess_local)

        role_channel = ""
        try:
            ss = sess_local.get("sample_system") if isinstance(sess_local.get("sample_system"), dict) else {}
            roles = ss.get("roles") if isinstance(ss.get("roles"), dict) else {}
            role_channel = str(roles.get("sample_flow") or "").strip()
        except Exception:
            role_channel = ""

        live_value = None
        live_source = ""
        live_units = _infer_sample_flow_units(sess_local, role_channel)
        candidate_keys: List[str] = []
        if role_channel:
            candidate_keys.append(role_channel)
        for key in ("SAMPLE_FLOW", "SAMPLE_FLOW_SLM", "SAMPLE_FLOW_SCFM", "FLOW", "FLOW_SCFM"):
            if key not in candidate_keys:
                candidate_keys.append(key)
        for key in candidate_keys:
            raw_val = _frame_channel_value(last_frame, key)
            num = _parse_float(raw_val)
            if num is None:
                continue
            live_value = float(num)
            live_source = f"live:{key}"
            if not live_units:
                live_units = _infer_sample_flow_units(sess_local, key)
            break

        override_value = _parse_float(state_use.get("sample_flow_override"))
        resolved_value = live_value
        resolved_source = live_source
        if override_value is not None and float(override_value) > 0.0:
            resolved_value = float(override_value)
            resolved_source = "manual override"

        flow_result: Dict[str, Any]
        if mole_spike_recovery is not None:
            flow_result = mole_spike_recovery.evaluate_flow_restriction(
                resolved_value,
                state_use.get("spike_flow_value"),
                cfg_use,
            )
        else:
            pct = 10.0
            try:
                pct = float(cfg_use.get("flow_restriction_pct") or 10.0)
            except Exception:
                pct = 10.0
            target = (float(resolved_value) * (pct / 100.0)) if resolved_value is not None else None
            status = "NOT_REQUIRED"
            reason = "Flow restriction is not required for this project."
            if bool(cfg_use.get("requires_flow_restriction")):
                if resolved_value is None or float(resolved_value) <= 0.0:
                    status = "SAMPLE_FLOW_REQUIRED"
                    reason = "Sample flow is missing or invalid."
                elif _parse_float(state_use.get("spike_flow_value")) is None:
                    status = "SPIKE_FLOW_REQUIRED"
                    reason = "Calibration spike flow is missing."
                elif float(_parse_float(state_use.get("spike_flow_value"))) <= float(target):
                    status = "PASS"
                    reason = "Spike flow is within the restriction target."
                else:
                    status = "FAIL"
                    reason = "Spike flow exceeds the restriction target."
            flow_result = {
                "sample_flow_value": resolved_value,
                "spike_flow_value": _parse_float(state_use.get("spike_flow_value")),
                "flow_restriction_pct": pct,
                "target_spike_flow_value": target,
                "status": status,
                "reason": reason,
            }

        return {
            "role_channel": role_channel,
            "live_sample_flow_value": live_value,
            "live_sample_flow_source": live_source,
            "sample_flow_override": override_value,
            "resolved_sample_flow_value": resolved_value,
            "resolved_sample_flow_source": resolved_source,
            "units": live_units,
            "flow_result": flow_result if isinstance(flow_result, dict) else {},
        }

    def _refresh_spike_flow_status(sess_local: Dict[str, Any]) -> None:
        cfg = _spike_cfg_block(sess_local)
        state = _ensure_spike_state(sess_local)
        ctx = _resolve_spike_flow_context(sess_local, cfg_local=cfg, state_local=state)
        flow_result = ctx.get("flow_result") if isinstance(ctx.get("flow_result"), dict) else {}
        units = str(ctx.get("units") or "").strip()
        pct = _parse_float(flow_result.get("flow_restriction_pct"))
        target = _parse_float(flow_result.get("target_spike_flow_value"))
        resolved_val = _parse_float(ctx.get("resolved_sample_flow_value"))
        live_val = _parse_float(ctx.get("live_sample_flow_value"))
        override_val = _parse_float(ctx.get("sample_flow_override"))
        resolved_source = str(ctx.get("resolved_sample_flow_source") or "")
        live_source = str(ctx.get("live_sample_flow_source") or "")
        suffix = f" {units}" if units else ""

        if cfg.get("requires_flow_restriction"):
            pct_txt = _fmt_num(pct, fallback="10")
            spike_flow_rule_var.set(
                str(cfg.get("flow_restriction_summary") or f"Mandatory: spike calibration flow must not exceed {pct_txt}% of the sample flow rate.")
            )
        else:
            spike_flow_rule_var.set(str(cfg.get("flow_restriction_summary") or "Flow restriction: not required for this project."))

        if resolved_val is not None:
            bits = [f"Resolved sample flow: {_fmt_num(resolved_val)}{suffix}"]
            if resolved_source:
                bits.append(f"[{resolved_source}]")
            if override_val is not None and live_val is not None and resolved_source == "manual override":
                bits.append(f"live {_fmt_num(live_val)}{suffix}")
            elif live_val is not None and live_source and resolved_source != "manual override":
                bits.append(f"[{live_source}]")
            spike_flow_resolved_var.set(" ".join(bits))
        elif live_val is not None:
            spike_flow_resolved_var.set(f"Resolved sample flow: {_fmt_num(live_val)}{suffix} [{live_source or 'live'}]")
        else:
            spike_flow_resolved_var.set("Resolved sample flow: (n/a) | map Sample System flow or enter override")

        if target is not None and pct is not None:
            spike_flow_target_var.set(f"Target spike flow ({_fmt_num(pct, fallback='10')}%): <= {_fmt_num(target)}{suffix}")
        elif cfg.get("requires_flow_restriction"):
            spike_flow_target_var.set(f"Target spike flow ({_fmt_num(pct, fallback='10')}%): (pending sample flow)")
        else:
            spike_flow_target_var.set("Target spike flow: not required")

        status = str(flow_result.get("status") or "").strip().upper()
        reason = str(flow_result.get("reason") or "").strip()
        if status == "PASS":
            spike_flow_eval_var.set(f"Spike flow status: PASS | {reason}")
            try:
                lbl_spike_flow_eval.configure(fg=OK)
            except Exception:
                pass
        elif status in ("FAIL", "SAMPLE_FLOW_REQUIRED", "SPIKE_FLOW_REQUIRED", "CRITERIA_REQUIRED"):
            spike_flow_eval_var.set(f"Spike flow status: {status} | {reason}")
            try:
                lbl_spike_flow_eval.configure(fg=BAD if status == "FAIL" else ACC2)
            except Exception:
                pass
        else:
            spike_flow_eval_var.set(f"Spike flow status: {reason or '(pending)'}")
            try:
                lbl_spike_flow_eval.configure(fg=ACC2)
            except Exception:
                pass

    def _spike_status_text(row: Dict[str, Any], applies_to_ftir: bool) -> str:
        mole_status = str(((row.get("mole_result") or {}).get("status")) or "").strip().upper()
        ftir_status = str(((row.get("ftir_result") or {}).get("status")) or "").strip().upper()
        if applies_to_ftir:
            parts = []
            if mole_status:
                parts.append(f"MOLE {mole_status}")
            if ftir_status:
                parts.append(f"FTIR {ftir_status}")
            return " / ".join(parts) if parts else "(pending)"
        return f"MOLE {mole_status}" if mole_status else "(pending)"

    def _spike_save_state_from_ui(sess_local: Dict[str, Any]) -> Dict[str, Any]:
        state = _ensure_spike_state(sess_local)
        try:
            state["sample_flow_override"] = _parse_float(var_spike_sample_flow_override.get())
        except Exception:
            pass
        try:
            state["spike_flow_value"] = _parse_float(var_spike_cal_flow.get())
        except Exception:
            pass
        for code, row_vars in spike_row_vars.items():
            try:
                state["channels"].setdefault(code, {})
                state["channels"][code]["spike_amount"] = _parse_float((row_vars.get("spike_amount") or tk.StringVar()).get())
            except Exception:
                pass
        return state

    def _save_spike_setup() -> None:
        nonlocal sess
        try:
            sess = _load_session()
            _ensure_daq_schema(sess)
            _spike_save_state_from_ui(sess)
            _save_session(sess)
            _populate_spike_recovery(sess)
            log("Saved spike recovery setup.")
        except Exception as e:
            messagebox.showerror("Spike Recovery", str(e))

    def _populate_spike_recovery(sess_local: Dict[str, Any]) -> None:
        for child in spike_rows_container.winfo_children():
            try:
                child.destroy()
            except Exception:
                pass
        spike_row_vars.clear()

        cfg = _spike_cfg_block(sess_local)
        state = _ensure_spike_state(sess_local)
        applies_to_ftir = bool(cfg.get("applies_to_ftir"))
        selected = list(_selected_pollutants(sess_local) or [])

        spike_summary_var.set(str(cfg.get("criterion_summary") or "Spike recovery: inactive"))
        spike_basis_var.set(str(cfg.get("method_basis") or cfg.get("notes") or ""))
        if not cfg.get("enabled"):
            spike_status_var.set("Spike recovery: optional and currently disabled")
        elif cfg.get("mandatory"):
            spike_status_var.set("Spike recovery: mandatory | applies to MOLE + FTIR channels")
        elif applies_to_ftir:
            spike_status_var.set("Spike recovery: enabled | applies to MOLE + FTIR channels")
        else:
            spike_status_var.set("Spike recovery: enabled | MOLE channels only")
        var_spike_sample_flow_override.set(_fmt_num(state.get("sample_flow_override"), fallback=""))
        var_spike_cal_flow.set(_fmt_num(state.get("spike_flow_value"), fallback=""))
        _refresh_spike_flow_status(sess_local)

        hdr = tk.Frame(spike_rows_container, bg=BG)
        hdr.pack(fill="x", pady=(0, 4))
        headers = [
            ("Pollutant", 12, "w"),
            ("Spike Amt", 10, "e"),
            ("Units", 8, "w"),
            ("Native", 10, "e"),
            ("Spiked", 10, "e"),
            ("MOLE %", 9, "e"),
            ("FTIR Native", 11, "e"),
            ("FTIR Spiked", 11, "e"),
            ("FTIR %", 9, "e"),
            ("Status", 24, "w"),
        ]
        for idx, (label, width, anchor) in enumerate(headers):
            tk.Label(hdr, text=label, fg=FG_DIM, bg=BG, font=("Consolas", 9, "bold"), width=width, anchor=anchor).grid(row=0, column=idx, sticky="w", padx=(0, 4))

        for ridx, code in enumerate(selected, start=1):
            row = state["channels"].get(code) if isinstance(state.get("channels"), dict) else {}
            if not isinstance(row, dict):
                row = {}
            row_fr = tk.Frame(spike_rows_container, bg=BG)
            row_fr.pack(fill="x", pady=(0, 2))
            var_spike_amt = tk.StringVar(value=_fmt_pollutant_measurement(row.get("spike_amount"), "", code))
            var_native_mole = tk.StringVar(value=_fmt_pollutant_measurement(row.get("native_mole"), "(n/a)", code))
            var_spike_mole = tk.StringVar(value=_fmt_pollutant_measurement(row.get("spike_mole"), "(n/a)", code))
            var_mole_pct = tk.StringVar(value=_fmt_num((row.get("mole_result") or {}).get("recovery_pct"), 1, "(n/a)"))
            var_native_ftir = tk.StringVar(value=_fmt_pollutant_measurement(row.get("native_ftir"), "(n/a)", code))
            var_spike_ftir = tk.StringVar(value=_fmt_pollutant_measurement(row.get("spike_ftir"), "(n/a)", code))
            var_ftir_pct = tk.StringVar(value=_fmt_num((row.get("ftir_result") or {}).get("recovery_pct"), 1, "(n/a)"))
            status_text = _spike_status_text(row, applies_to_ftir)
            status_fg = FG
            if "FAIL" in status_text:
                status_fg = BAD
            elif "PASS" in status_text:
                status_fg = OK

            tk.Label(row_fr, text=code, fg=FG, bg=BG, font=("Consolas", 9), width=12, anchor="w").grid(row=0, column=0, sticky="w", padx=(0, 4))
            tk.Entry(row_fr, textvariable=var_spike_amt, bg=PANEL_BG, fg=FG, insertbackground=FG, relief="flat", width=10, font=("Consolas", 9)).grid(row=0, column=1, sticky="w", padx=(0, 4))
            tk.Label(row_fr, text=str(row.get("units") or ""), fg=FG_DIM, bg=BG, font=("Consolas", 9), width=8, anchor="w").grid(row=0, column=2, sticky="w", padx=(0, 4))
            tk.Label(row_fr, textvariable=var_native_mole, fg=FG, bg=BG, font=("Consolas", 9), width=10, anchor="e").grid(row=0, column=3, sticky="w", padx=(0, 4))
            tk.Label(row_fr, textvariable=var_spike_mole, fg=FG, bg=BG, font=("Consolas", 9), width=10, anchor="e").grid(row=0, column=4, sticky="w", padx=(0, 4))
            tk.Label(row_fr, textvariable=var_mole_pct, fg=FG, bg=BG, font=("Consolas", 9), width=9, anchor="e").grid(row=0, column=5, sticky="w", padx=(0, 4))
            tk.Label(row_fr, textvariable=var_native_ftir, fg=FG if applies_to_ftir else FG_DIM, bg=BG, font=("Consolas", 9), width=11, anchor="e").grid(row=0, column=6, sticky="w", padx=(0, 4))
            tk.Label(row_fr, textvariable=var_spike_ftir, fg=FG if applies_to_ftir else FG_DIM, bg=BG, font=("Consolas", 9), width=11, anchor="e").grid(row=0, column=7, sticky="w", padx=(0, 4))
            tk.Label(row_fr, textvariable=var_ftir_pct, fg=FG if applies_to_ftir else FG_DIM, bg=BG, font=("Consolas", 9), width=9, anchor="e").grid(row=0, column=8, sticky="w", padx=(0, 4))
            tk.Label(row_fr, text=status_text, fg=status_fg, bg=BG, font=("Consolas", 9), width=24, anchor="w").grid(row=0, column=9, sticky="w")

            spike_row_vars[code] = {
                "spike_amount": var_spike_amt,
            }

        if not selected:
            tk.Label(spike_rows_container, text="No pollutants selected for spike recovery.", fg=FG_DIM, bg=BG, font=("Consolas", 9)).pack(anchor="w")

    def _capture_spike_phase(phase: str) -> None:
        nonlocal sess
        phase_norm = str(phase or "").strip().upper() or "NATIVE"
        if not last_frame:
            messagebox.showwarning("Spike Recovery", "No live frame yet. Start acquisition (UI) and wait for data.")
            return
        try:
            sess = _load_session()
            _ensure_daq_schema(sess)
            _ws_save_cfg_from_ui(sess)
            cfg = _spike_cfg_block(sess)
            if not cfg.get("enabled"):
                messagebox.showwarning("Spike Recovery", "Spike recovery is not enabled for this project.")
                return
            ws, ws_cfg, _ws_q = _ws_get_cfg(sess)
            state = _spike_save_state_from_ui(sess)
            snapshot = _current_reference_snapshot(sess)
            selected = list(_selected_pollutants(sess) or [])
            if not selected:
                messagebox.showinfo("Spike Recovery", "No pollutants are selected for spike recovery.")
                return
            window_s = float(ws_cfg.get("capture_window_s") or 10.0)
            ts_iso = _iso_now()
            history = state.get("history") if isinstance(state.get("history"), list) else []
            state["history"] = history
            flow_ctx = _resolve_spike_flow_context(sess, cfg_local=cfg, state_local=state)
            flow_result = flow_ctx.get("flow_result") if isinstance(flow_ctx.get("flow_result"), dict) else {}
            state["sample_flow_value"] = _parse_float(flow_ctx.get("resolved_sample_flow_value"))
            state["sample_flow_units"] = str(flow_ctx.get("units") or "").strip()
            state["sample_flow_source"] = str(flow_ctx.get("resolved_sample_flow_source") or "")
            state["target_spike_flow_value"] = _parse_float((flow_result or {}).get("target_spike_flow_value"))
            state["flow_result"] = dict(flow_result) if isinstance(flow_result, dict) else {}
            problems: List[str] = []
            captured = 0
            for code in selected:
                avg, _std, _n = _ws_avg_std(code, window_s)
                if avg is None:
                    problems.append(f"{code}: no valid readings in last {_fmt_num(window_s, 0, '0')}s")
                    continue
                row = state["channels"].setdefault(code, {})
                row["units"] = str(row.get("units") or ((_pollutant_prescriptions(sess).get(code) or {}).get("units") or "")).strip()
                ftir_value = _reference_snapshot_value(snapshot, code) if cfg.get("applies_to_ftir") else None
                if phase_norm == "NATIVE":
                    row["native_mole"] = float(avg)
                    row["native_ftir"] = ftir_value
                    row["native_timestamp_iso"] = ts_iso
                    row["mole_result"] = {}
                    row["ftir_result"] = {}
                    state["active_phase"] = "NATIVE_CAPTURED"
                else:
                    row["spike_mole"] = float(avg)
                    row["spike_ftir"] = ftir_value
                    row["spike_timestamp_iso"] = ts_iso
                    if mole_spike_recovery is not None:
                        row["mole_result"] = mole_spike_recovery.evaluate_capture(
                            row.get("native_mole"),
                            row.get("spike_mole"),
                            row.get("spike_amount"),
                            cfg,
                        )
                        if cfg.get("applies_to_ftir"):
                            row["ftir_result"] = mole_spike_recovery.evaluate_capture(
                                row.get("native_ftir"),
                                row.get("spike_ftir"),
                                row.get("spike_amount"),
                                cfg,
                            )
                        else:
                            row["ftir_result"] = {}
                    state["active_phase"] = "SPIKE_CAPTURED"
                history.append(
                    {
                        "event": f"{phase_norm}_CAPTURE",
                        "pollutant": code,
                        "timestamp_iso": ts_iso,
                        "mole_value": float(avg),
                        "ftir_value": ftir_value,
                        "spike_amount": row.get("spike_amount"),
                        "sample_flow_value": state.get("sample_flow_value"),
                        "sample_flow_units": state.get("sample_flow_units"),
                        "sample_flow_source": state.get("sample_flow_source"),
                        "spike_flow_value": state.get("spike_flow_value"),
                        "target_spike_flow_value": state.get("target_spike_flow_value"),
                        "flow_status": (state.get("flow_result") or {}).get("status"),
                    }
                )
                captured += 1
            if len(history) > 1000:
                del history[:-1000]
            _ws_log_event(
                sess,
                f"SPIKE_RECOVERY_{phase_norm}",
                {
                    "capture_window_s": float(window_s),
                    "captured_count": int(captured),
                    "problems": list(problems),
                    "applies_to_ftir": bool(cfg.get("applies_to_ftir")),
                    "mandatory": bool(cfg.get("mandatory")),
                    "sample_flow_value": state.get("sample_flow_value"),
                    "sample_flow_units": state.get("sample_flow_units"),
                    "sample_flow_source": state.get("sample_flow_source"),
                    "spike_flow_value": state.get("spike_flow_value"),
                    "target_spike_flow_value": state.get("target_spike_flow_value"),
                    "flow_status": (state.get("flow_result") or {}).get("status"),
                },
            )
            _save_session(sess)
            _populate_spike_recovery(sess)
            if problems:
                messagebox.showwarning("Spike Recovery", "\n".join(problems[:8]))
        except Exception as e:
            messagebox.showerror("Spike Recovery", str(e))

    def _reset_spike_recovery() -> None:
        nonlocal sess
        if not messagebox.askyesno("Spike Recovery", "Reset all spike recovery captures for the current project?", default="no"):
            return
        try:
            sess = _load_session()
            state = _ensure_spike_state(sess)
            for code, row in list((state.get("channels") or {}).items()):
                if not isinstance(row, dict):
                    continue
                spike_amount = row.get("spike_amount")
                units = row.get("units")
                state["channels"][code] = {
                    "spike_amount": spike_amount,
                    "units": units,
                    "native_mole": None,
                    "spike_mole": None,
                    "native_ftir": None,
                    "spike_ftir": None,
                    "mole_result": {},
                    "ftir_result": {},
                    "native_timestamp_iso": "",
                    "spike_timestamp_iso": "",
                }
            state["active_phase"] = "IDLE"
            state["sample_flow_value"] = None
            state["sample_flow_units"] = str(state.get("sample_flow_units") or "")
            state["sample_flow_source"] = ""
            state["target_spike_flow_value"] = None
            state["flow_result"] = {}
            history = state.get("history") if isinstance(state.get("history"), list) else []
            history.append({"event": "RESET", "timestamp_iso": _iso_now()})
            if len(history) > 1000:
                del history[:-1000]
            _ws_log_event(sess, "SPIKE_RECOVERY_RESET", {})
            _save_session(sess)
            _populate_spike_recovery(sess)
        except Exception as e:
            messagebox.showerror("Spike Recovery", str(e))

    def _refresh_side_by_side_panel(sess_local: Optional[Dict[str, Any]] = None) -> None:
        sess_use = sess_local if isinstance(sess_local, dict) else _load_session()
        side = _side_by_side_block(sess_use)
        events = side.get("events") if isinstance(side.get("events"), list) else []
        latest = side.get("latest_sync_marker") if isinstance(side.get("latest_sync_marker"), dict) else {}
        sched = _side_bias_schedule(sess_use)
        purge_txt = "required" if bool(side.get("ambient_purge_required", True)) else "optional"
        drift_txt = "required" if bool(side.get("project_drift_required", True)) else "optional"
        bias_sched_txt = str(sched.get("schedule_label") or f"Bias every {int(_parse_float(side.get('bias_valve_interval_min'), default=20) or 20)} min")
        if bool(sched.get("bias_due")):
            due_run = sched.get("bias_due_after_run_no")
            due_txt = f"BIAS DUE after Run {due_run}" if due_run not in (None, "") else "BIAS DUE"
            side_enabled_txt = "enabled" if bool(side.get('enabled')) else "tracking available"
            side_status_var.set(
                f"Side-by-side alignment: {side_enabled_txt} | {bias_sched_txt} | {due_txt} | Ambient purge {purge_txt} | Project drift {drift_txt}"
            )
        else:
            side_status_var.set(
                f"Side-by-side alignment: {'enabled' if bool(side.get('enabled')) else 'tracking available'} | "
                f"{bias_sched_txt} | Ambient purge {purge_txt} | Project drift {drift_txt}"
            )
        note_txt = str(side.get("notes") or "").strip()
        try:
            if note_txt != str(var_side_note.get() or "").strip():
                var_side_note.set(note_txt)
        except Exception:
            pass
        base_detail = f"{bias_sched_txt}. Log a bias valve event after each completed run to align MOLE with FTIR output, then complete ambient purge and project drift steps as required."
        side_detail_var.set(f"{base_detail} Operator note: {note_txt}" if note_txt else base_detail)
        latest_ts = str(latest.get("timestamp_iso") or "").strip()
        latest_label = str(latest.get("label") or "").strip()
        latest_note = str(latest.get("note") or "").strip()
        latest_summary = latest_ts or "(none)"
        if latest_label:
            latest_summary += f" | {latest_label}"
        if latest_note:
            latest_summary += f" | {latest_note}"
        side_last_sync_var.set(f"Latest sync marker: {latest_summary}")

        lines: List[str] = []
        for ev in events[-20:]:
            if not isinstance(ev, dict):
                continue
            ts = str(ev.get("timestamp_iso") or "").strip() or "(no time)"
            ev_type = str(ev.get("event_type") or "").strip() or "EVENT"
            label = str(ev.get("label") or "").strip() or ev_type
            note = str(ev.get("note") or "").strip()
            run_id_txt = str(ev.get("run_id") or "").strip()
            suffix = f" | run={run_id_txt}" if run_id_txt else ""
            if note:
                suffix += f" | note={note}"
            lines.append(f"{ts} | {ev_type} | {label}{suffix}")
        history_txt = "\n".join(lines) if lines else "No side-by-side events logged yet."
        try:
            side_history.configure(state="normal")
            side_history.delete("1.0", "end")
            side_history.insert("1.0", history_txt)
            side_history.configure(state="disabled")
        except Exception:
            pass

    def _append_side_by_side_event(event_type: str, label: str) -> None:
        nonlocal sess
        try:
            sess = _load_session()
            side = _side_by_side_block(sess)
            note_txt = str(var_side_note.get() or "").strip()
            if note_txt:
                side["notes"] = note_txt
            daq_local = sess.get("daq_runner") if isinstance(sess.get("daq_runner"), dict) else {}
            ref_local = daq_local.get("reference_audit") if isinstance(daq_local.get("reference_audit"), dict) else {}
            run_no_val = None
            try:
                runs_local = daq_local.get("runs") if isinstance(daq_local.get("runs"), list) else []
                idx_local = int(daq_local.get("active_run_index") or 0)
                if runs_local:
                    idx_local = max(0, min(idx_local, len(runs_local) - 1))
                    run_local = runs_local[idx_local] if 0 <= idx_local < len(runs_local) and isinstance(runs_local[idx_local], dict) else {}
                    run_no_val = run_local.get("run_no")
            except Exception:
                run_no_val = None
            payload = {
                "timestamp_iso": _now_iso_local(),
                "event_type": str(event_type or "").strip().upper() or "EVENT",
                "label": str(label or "").strip() or "Side-by-side event",
                "note": note_txt,
                "run_id": _run_id(sess),
                "active_run_index": daq_local.get("active_run_index"),
                "run_no": run_no_val,
                "reference_enabled": bool(ref_local.get("enabled")),
                "reference_role": str(ref_local.get("role") or ""),
                "method_standard": str(ref_local.get("method_standard") or ""),
            }
            events = side.get("events") if isinstance(side.get("events"), list) else []
            events.append(dict(payload))
            side["events"] = events[-500:]
            side["enabled"] = True
            if payload["event_type"] == "SYNC_MARK":
                side["latest_sync_marker"] = dict(payload)
            if payload["event_type"] == "BIAS_VALVE":
                side["bias_due_after_run_no"] = None
                side["bias_due_after_iso"] = ""
            sess["side_by_side"] = dict(side)
            daq_local["side_by_side"] = dict(side)
            sess["daq_runner"] = daq_local
            _apply_ftir_validation_side_event(sess, payload)
            _save_session(sess)
            _ws_log_event(sess, "SIDE_BY_SIDE_EVENT", dict(payload))
            _refresh_side_by_side_panel(sess)
            log(f"Side-by-side event logged: {payload['label']}")
        except Exception as e:
            messagebox.showerror("Side-by-Side Alignment", str(e))

    def _converter_eff_state_block(sess_local: Dict[str, Any]) -> Dict[str, Any]:
        blk = _ensure_daq_schema(sess_local)
        ws = blk.get("worksteps")
        if not isinstance(ws, dict):
            ws = {}
            blk["worksteps"] = ws
        conv = ws.get("converter_eff")
        if not isinstance(conv, dict):
            conv = {}
            ws["converter_eff"] = conv
        profile = _converter_eff_method_profile(sess_local)
        allowed = [str(x or "").strip().upper() for x in (profile.get("procedures") or ["GENERIC_PERCENT"]) if str(x or "").strip()]
        default_proc = str(profile.get("default_procedure") or (allowed[0] if allowed else "GENERIC_PERCENT")).strip().upper() or "GENERIC_PERCENT"
        conv.setdefault("enabled", _nox_converter_enabled(sess_local))
        conv.setdefault("target", None)
        conv.setdefault("tol_min_pct", 90.0)
        conv.setdefault("tol_max_pct", 110.0)
        conv.setdefault("method_profile", str(profile.get("code") or ""))
        conv.setdefault("method_basis", str(profile.get("basis") or ""))
        conv.setdefault("procedure", default_proc)
        conv.setdefault("criteria_locked", False)
        conv.setdefault("bag_active", False)
        conv.setdefault("bag_start_iso", "")
        conv.setdefault("bag_start_epoch", None)
        conv.setdefault("bag_duration_min", _parse_float(profile.get("bag_duration_min"), default=30.0))
        conv.setdefault("bag_max_drop_pct", _parse_float(profile.get("bag_max_drop_pct"), default=2.0))
        conv.setdefault("last_capture", {})
        conv.setdefault("history", [])
        conv["applicable"] = bool(_derived_nox_applicable(sess_local))
        conv["method_profile"] = str(profile.get("code") or "")
        conv["method_basis"] = str(profile.get("basis") or "")
        proc = str(conv.get("procedure") or "").strip().upper()
        if proc not in allowed:
            proc = default_proc
        conv["procedure"] = proc
        conv["criteria_locked"] = bool(str(profile.get("code") or "").strip().upper() == "EPA_7E_NOX")
        if conv["criteria_locked"]:
            conv["tol_min_pct"] = _parse_float(profile.get("direct_min_eff_pct"), default=90.0)
            conv["tol_max_pct"] = None
            conv["bag_duration_min"] = _parse_float(profile.get("bag_duration_min"), default=30.0)
            conv["bag_max_drop_pct"] = _parse_float(profile.get("bag_max_drop_pct"), default=2.0)
        if not conv.get("applicable"):
            conv["enabled"] = False
            conv["bag_active"] = False
        if str(conv.get("procedure") or "").strip().upper() != "ALT_BAG_30MIN":
            conv["bag_active"] = False
        return conv

    def _converter_eff_seed_target(sess_local: Dict[str, Any]) -> Optional[float]:
        pres = _pollutant_prescriptions(sess_local)
        for code in ("NO2", "NOX", "NO"):
            row = pres.get(code) or {}
            tgt = _parse_float(row.get("span_target"))
            if tgt is None:
                tgt = _parse_float(row.get("span_cylinder_id"))
            if tgt is not None and tgt > 0:
                return float(tgt)
        return None

    def _converter_eff_save_from_ui(sess_local: Dict[str, Any]) -> Dict[str, Any]:
        conv = _converter_eff_state_block(sess_local)
        profile = _converter_eff_method_profile(sess_local)
        allowed = [str(x or "").strip().upper() for x in (profile.get("procedures") or ["GENERIC_PERCENT"]) if str(x or "").strip()]
        default_proc = str(profile.get("default_procedure") or (allowed[0] if allowed else "GENERIC_PERCENT")).strip().upper() or "GENERIC_PERCENT"
        prior_proc = str(conv.get("procedure") or "").strip().upper()
        bag_active = bool(conv.get("bag_active"))
        proc = _converter_eff_procedure_from_display(var_conv_procedure.get())
        if proc not in allowed:
            proc = default_proc
        if bag_active and prior_proc == "ALT_BAG_30MIN" and proc != "ALT_BAG_30MIN":
            proc = "ALT_BAG_30MIN"
        conv["enabled"] = bool(var_conv_enabled.get()) and bool(conv.get("applicable"))
        conv["method_profile"] = str(profile.get("code") or "")
        conv["method_basis"] = str(profile.get("basis") or "")
        conv["procedure"] = proc
        conv["criteria_locked"] = bool(str(profile.get("code") or "").strip().upper() == "EPA_7E_NOX")
        conv["target"] = _parse_float(var_conv_target.get())
        if proc == "ALT_BAG_30MIN":
            conv["bag_duration_min"] = _parse_float(profile.get("bag_duration_min"), default=30.0)
            conv["bag_max_drop_pct"] = _parse_float(profile.get("bag_max_drop_pct"), default=2.0)
            conv["tol_min_pct"] = _parse_float(profile.get("direct_min_eff_pct"), default=90.0)
            conv["tol_max_pct"] = None
        elif proc == "DIRECT_NO2_CYLINDER" and str(profile.get("code") or "").strip().upper() == "EPA_7E_NOX":
            conv["tol_min_pct"] = _parse_float(profile.get("direct_min_eff_pct"), default=90.0)
            conv["tol_max_pct"] = None
            conv["bag_active"] = False
        else:
            conv["tol_min_pct"] = _parse_float(var_conv_min.get(), default=90.0)
            conv["tol_max_pct"] = _parse_float(var_conv_max.get(), default=110.0)
            if conv.get("tol_min_pct") is None:
                conv["tol_min_pct"] = 90.0
            if conv.get("tol_max_pct") is None:
                conv["tol_max_pct"] = 110.0
            conv["bag_active"] = False
        qa = sess_local.get("qa_qc")
        if not isinstance(qa, dict):
            qa = {}
            sess_local["qa_qc"] = qa
        opts = qa.get("secondary_test_options")
        if not isinstance(opts, dict):
            opts = {}
            qa["secondary_test_options"] = opts
        opts["CONVERTER_EFF"] = bool(conv.get("enabled"))
        req = [str(x or "").strip().upper() for x in (qa.get("secondary_required_tests") or []) if str(x or "").strip()]
        if conv.get("enabled"):
            if "CONVERTER_EFF" not in req:
                req.append("CONVERTER_EFF")
        else:
            req = [x for x in req if x != "CONVERTER_EFF"]
        qa["secondary_required_tests"] = req
        qa["nox_converter_eff_enabled"] = bool(conv.get("enabled"))
        qa["nox_converter_eff_applicable"] = bool(conv.get("applicable"))
        return conv

    def _populate_converter_eff(sess_local: Dict[str, Any]) -> None:
        for child in conv_rows_container.winfo_children():
            try:
                child.destroy()
            except Exception:
                pass

        conv = _converter_eff_state_block(sess_local)
        profile = _converter_eff_method_profile(sess_local)
        allowed = [str(x or "").strip().upper() for x in (profile.get("procedures") or ["GENERIC_PERCENT"]) if str(x or "").strip()]
        proc = str(conv.get("procedure") or (allowed[0] if allowed else "GENERIC_PERCENT")).strip().upper() or "GENERIC_PERCENT"
        applicable = bool(conv.get("applicable"))
        enabled = bool(conv.get("enabled")) and applicable
        bag_mode = (proc == "ALT_BAG_30MIN")
        direct_mode = not bag_mode
        criteria_locked = bool(conv.get("criteria_locked"))
        seeded_target = _converter_eff_seed_target(sess_local)
        target_val = conv.get("target")
        if target_val in (None, "") and seeded_target is not None:
            target_val = seeded_target

        var_conv_enabled.set(bool(enabled))
        try:
            conv_proc_combo.configure(values=[_converter_eff_procedure_label(x) for x in allowed])
        except Exception:
            pass
        var_conv_procedure.set(_converter_eff_procedure_label(proc))
        var_conv_target.set(_fmt_num(target_val, 3, ""))
        var_conv_min.set(_fmt_num(conv.get("tol_min_pct"), 1, "90.0"))
        var_conv_max.set("" if conv.get("tol_max_pct") in (None, "") else _fmt_num(conv.get("tol_max_pct"), 1, "110.0"))
        conv_basis_var.set(str(profile.get("basis") or ""))

        if not applicable:
            conv_summary_var.set("NOx converter efficiency: unavailable")
            conv_status_var.set("Select both NO and NO2 to enable the optional CONVERTER_EFF workflow.")
            try:
                chk_conv_enabled.configure(state="disabled")
                conv_proc_combo.configure(state="disabled")
                ent_conv_target.configure(state="disabled")
                ent_conv_min.configure(state="disabled")
                ent_conv_max.configure(state="disabled")
                btn_conv_save.configure(state="disabled")
                btn_conv_capture.configure(state="disabled")
                btn_conv_bag_start.configure(state="disabled")
                btn_conv_bag_finalize.configure(state="disabled")
                btn_conv_reset.configure(state="disabled")
            except Exception:
                pass
            tk.Label(conv_rows_container, text="NOx converter efficiency is only available when both NO and NO2 are selected.", fg=FG_DIM, bg=BG, font=("Consolas", 9)).pack(anchor="w")
            return

        if str(profile.get("code") or "").strip().upper() == "EPA_7E_NOX":
            conv_summary_var.set(f"NOx converter efficiency: {str(profile.get('label') or 'EPA Method 7E')}")
        else:
            conv_summary_var.set("NOx converter efficiency: optional workflow for NO + NO2 projects")
        if enabled and bag_mode and bool(conv.get("bag_active")):
            started = str(conv.get("bag_start_iso") or "").strip() or "(n/a)"
            conv_status_var.set(
                f"Bag alternative active. Hold the bag test for {_fmt_num(conv.get('bag_duration_min'), 0, '30')} min, then finalize. Started: {started}."
            )
        elif enabled and bag_mode:
            conv_status_var.set(
                f"Bag alternative selected. Start bag test, wait {_fmt_num(conv.get('bag_duration_min'), 0, '30')} min, then finalize. Derived NOx remains NO + NO2."
            )
        elif enabled and proc == "DIRECT_NO2_CYLINDER":
            conv_status_var.set("Direct NO2-cylinder check enabled. Capture after applying NO2 check gas to evaluate derived NOx efficiency.")
        elif enabled:
            conv_status_var.set("Generic converter-efficiency worksteps enabled. Derived NOx is calculated as NO + NO2.")
        else:
            conv_status_var.set("Converter-efficiency worksteps bypassed. Derived NOx is still calculated as NO + NO2.")
        try:
            chk_conv_enabled.configure(state="normal")
            conv_proc_combo.configure(state="readonly")
            ent_conv_target.configure(state=("normal" if (enabled and direct_mode) else "disabled"))
            ent_conv_min.configure(state=("normal" if (enabled and direct_mode and not criteria_locked) else "disabled"))
            ent_conv_max.configure(state=("normal" if (enabled and direct_mode and not criteria_locked) else "disabled"))
            btn_conv_save.configure(state="normal")
            btn_conv_capture.configure(state=("normal" if (enabled and direct_mode) else "disabled"))
            btn_conv_bag_start.configure(state=("normal" if (enabled and bag_mode) else "disabled"))
            btn_conv_bag_finalize.configure(state=("normal" if (enabled and bag_mode) else "disabled"))
            btn_conv_reset.configure(state="normal")
        except Exception:
            pass

        cap = conv.get("last_capture") if isinstance(conv.get("last_capture"), dict) else {}
        criteria_txt = str(cap.get("criteria_text") or _converter_eff_criteria_text(conv, profile))
        status = str(cap.get("status") or ("ACTIVE" if conv.get("bag_active") else ("BYPASSED" if not enabled else "(pending)")))
        status_fg = FG
        if "FAIL" in status.upper():
            status_fg = BAD
        elif "PASS" in status.upper() or "ACTIVE" in status.upper():
            status_fg = OK
        if str(cap.get("procedure") or proc).strip().upper() == "ALT_BAG_30MIN":
            elapsed_s_val = _parse_float(cap.get("elapsed_s"))
            result_txt = (
                f"Peak={_fmt_pollutant_measurement(cap.get('peak_nox'), '(n/a)')} | "
                f"Final={_fmt_pollutant_measurement(cap.get('final_nox'), '(n/a)')} | "
                f"Drop={_fmt_num(cap.get('drop_pct'), 2, '(n/a)')}%"
            )
            notes_txt = (
                f"Elapsed={_fmt_num((elapsed_s_val / 60.0) if elapsed_s_val is not None else None, 1, '(n/a)')} min | "
                f"Samples={_fmt_num(cap.get('n_samples'), 0, '(n/a)')} | "
                f"Start={str(cap.get('bag_start_iso') or conv.get('bag_start_iso') or '')}"
            )
        else:
            result_txt = (
                f"NO={_fmt_pollutant_measurement(cap.get('no_avg'), '(n/a)')} | "
                f"NO2={_fmt_pollutant_measurement(cap.get('no2_avg'), '(n/a)')} | "
                f"NOx={_fmt_pollutant_measurement(cap.get('nox_avg'), '(n/a)')} | "
                f"Eff={_fmt_num(cap.get('efficiency_pct'), 1, '(n/a)')}%"
            )
            notes_txt = (
                f"Target={_fmt_pollutant_measurement(cap.get('target') if cap.get('target') is not None else target_val, '(n/a)')} | "
                f"Window={_fmt_num(cap.get('window_s'), 0, '(n/a)')} s"
            )
        ts_txt = str(cap.get("ts_iso") or conv.get("bag_start_iso") or "")
        hdr = tk.Frame(conv_rows_container, bg=BG)
        hdr.pack(fill="x", pady=(0, 4))
        headers = [
            ("Procedure", 24, "w"),
            ("Result", 48, "w"),
            ("Criteria", 22, "w"),
            ("Status", 12, "w"),
            ("Notes", 34, "w"),
            ("Captured", 22, "w"),
        ]
        for idx, (label, width, anchor) in enumerate(headers):
            tk.Label(hdr, text=label, fg=FG_DIM, bg=BG, font=("Consolas", 9, "bold"), width=width, anchor=anchor).grid(row=0, column=idx, sticky="w", padx=(0, 4))

        row_fr = tk.Frame(conv_rows_container, bg=BG)
        row_fr.pack(fill="x", pady=(0, 2))
        for idx, (txt, width, anchor, fg_color) in enumerate([
            (_converter_eff_procedure_label(cap.get("procedure") or proc), 24, "w", FG),
            (result_txt, 48, "w", FG),
            (criteria_txt, 22, "w", FG),
            (status, 12, "w", status_fg),
            (notes_txt, 34, "w", FG_DIM),
            (ts_txt, 22, "w", FG_DIM),
        ]):
            tk.Label(row_fr, text=txt, fg=fg_color, bg=BG, font=("Consolas", 9), width=width, anchor=anchor).grid(row=0, column=idx, sticky="w", padx=(0, 4))

    def _save_converter_eff_setup() -> None:
        nonlocal sess
        try:
            sess = _load_session()
            _ensure_daq_schema(sess)
            _converter_eff_save_from_ui(sess)
            _save_session(sess)
            _populate_converter_eff(sess)
            log("Saved NOx converter efficiency setup.")
        except Exception as e:
            messagebox.showerror("NOx Converter Efficiency", str(e))

    def _capture_converter_eff() -> None:
        nonlocal sess
        if not last_frame:
            messagebox.showwarning("NOx Converter Efficiency", "No live frame yet. Start acquisition (UI) and wait for data.")
            return
        try:
            sess = _load_session()
            _ensure_daq_schema(sess)
            _ws_save_cfg_from_ui(sess)
            conv = _converter_eff_save_from_ui(sess)
            profile = _converter_eff_method_profile(sess)
            proc = str(conv.get("procedure") or "").strip().upper()
            if not conv.get("applicable"):
                messagebox.showinfo("NOx Converter Efficiency", "This workflow requires both NO and NO2 to be selected.")
                return
            if not conv.get("enabled"):
                messagebox.showinfo("NOx Converter Efficiency", "Enable the CONVERTER_EFF workflow first.")
                return
            if proc == "ALT_BAG_30MIN":
                messagebox.showinfo("NOx Converter Efficiency", "The selected procedure is the 30-minute bag alternative. Use Start Bag Test and Finalize Bag Test.")
                return
            target = _parse_float(conv.get("target"))
            if target is None or target <= 0:
                messagebox.showwarning("NOx Converter Efficiency", "Enter a valid non-zero target concentration before capture.")
                return
            ws, ws_cfg, ws_q = _ws_get_cfg(sess)
            window_s = float(ws_cfg.get("capture_window_s") or 10.0)
            no_avg, no_std, no_n = _ws_avg_std("NO", window_s)
            no2_avg, no2_std, no2_n = _ws_avg_std("NO2", window_s)
            if no_avg is None or no2_avg is None:
                messagebox.showwarning("NOx Converter Efficiency", f"Need valid NO and NO2 data over the last {_fmt_num(window_s, 0, '0')}s before capture.")
                return
            nox_avg = float(no_avg) + float(no2_avg)
            eff_pct = (float(nox_avg) / float(target)) * 100.0
            if proc == "DIRECT_NO2_CYLINDER" and str(profile.get("code") or "").strip().upper() == "EPA_7E_NOX":
                tol_min = _parse_float(conv.get("tol_min_pct"), default=_parse_float(profile.get("direct_min_eff_pct"), default=90.0))
                tol_max = None
                passed = bool(eff_pct >= float(tol_min or 90.0))
            else:
                tol_min = float(conv.get("tol_min_pct") or 90.0)
                tol_max = float(conv.get("tol_max_pct") or 110.0)
                passed = bool(tol_min <= eff_pct <= tol_max)
            status = "PASS" if passed else "FAIL"
            cap = {
                "ts_iso": _iso_now(),
                "window_s": float(window_s),
                "procedure": proc,
                "procedure_label": _converter_eff_procedure_label(proc),
                "method_profile": str(profile.get("code") or ""),
                "method_basis": str(profile.get("basis") or ""),
                "result_type": "DIRECT",
                "no_avg": float(no_avg),
                "no_std": float(no_std) if no_std is not None else None,
                "no_n": int(no_n),
                "no2_avg": float(no2_avg),
                "no2_std": float(no2_std) if no2_std is not None else None,
                "no2_n": int(no2_n),
                "nox_avg": float(nox_avg),
                "target": float(target),
                "efficiency_pct": float(eff_pct),
                "tol_min_pct": None if tol_min is None else float(tol_min),
                "tol_max_pct": None if tol_max is None else float(tol_max),
                "criteria_text": _converter_eff_criteria_text(conv, profile),
                "pass": bool(passed),
                "status": status,
            }
            conv["bag_active"] = False
            conv["last_capture"] = cap
            hist = conv.get("history") if isinstance(conv.get("history"), list) else []
            hist.append(dict(cap))
            if len(hist) > 1000:
                del hist[:-1000]
            conv["history"] = hist
            ws_q.setdefault("channel_valid", {})
            ws_q["channel_valid"]["NOX"] = bool(passed)
            _ws_log_event(sess, "CONVERTER_EFF_CAPTURE", dict(cap))
            _save_session(sess)
            refresh_all()
        except Exception as e:
            messagebox.showerror("NOx Converter Efficiency", str(e))

    def _start_converter_eff_bag() -> None:
        nonlocal sess
        try:
            sess = _load_session()
            _ensure_daq_schema(sess)
            _ws_save_cfg_from_ui(sess)
            conv = _converter_eff_save_from_ui(sess)
            profile = _converter_eff_method_profile(sess)
            proc = str(conv.get("procedure") or "").strip().upper()
            if not conv.get("applicable"):
                messagebox.showinfo("NOx Converter Efficiency", "This workflow requires both NO and NO2 to be selected.")
                return
            if not conv.get("enabled"):
                messagebox.showinfo("NOx Converter Efficiency", "Enable the CONVERTER_EFF workflow first.")
                return
            if proc != "ALT_BAG_30MIN":
                messagebox.showinfo("NOx Converter Efficiency", "Select the EPA 7E bag-alternative procedure before starting a bag test.")
                return
            if bool(conv.get("bag_active")):
                if not messagebox.askyesno("NOx Converter Efficiency", "A bag-alternative test is already active. Restart it?", default="no"):
                    return
            start_epoch = time.time()
            start_iso = _iso_now()
            conv["bag_active"] = True
            conv["bag_start_epoch"] = float(start_epoch)
            conv["bag_start_iso"] = str(start_iso)
            conv["bag_duration_min"] = _parse_float(profile.get("bag_duration_min"), default=30.0)
            conv["bag_max_drop_pct"] = _parse_float(profile.get("bag_max_drop_pct"), default=2.0)
            conv["last_capture"] = {
                "procedure": proc,
                "procedure_label": _converter_eff_procedure_label(proc),
                "method_profile": str(profile.get("code") or ""),
                "method_basis": str(profile.get("basis") or ""),
                "result_type": "BAG",
                "bag_start_iso": str(start_iso),
                "bag_start_epoch": float(start_epoch),
                "duration_min": float(conv.get("bag_duration_min") or 30.0),
                "max_drop_pct": float(conv.get("bag_max_drop_pct") or 2.0),
                "criteria_text": _converter_eff_criteria_text(conv, profile),
                "status": "ACTIVE",
                "pass": None,
                "ts_iso": str(start_iso),
            }
            _ws_log_event(
                sess,
                "CONVERTER_EFF_BAG_START",
                {
                    "procedure": proc,
                    "procedure_label": _converter_eff_procedure_label(proc),
                    "bag_start_iso": str(start_iso),
                    "bag_duration_min": float(conv.get("bag_duration_min") or 30.0),
                    "max_drop_pct": float(conv.get("bag_max_drop_pct") or 2.0),
                    "criteria_text": _converter_eff_criteria_text(conv, profile),
                },
            )
            _save_session(sess)
            refresh_all()
        except Exception as e:
            messagebox.showerror("NOx Converter Efficiency", str(e))

    def _finalize_converter_eff_bag() -> None:
        nonlocal sess
        try:
            sess = _load_session()
            _ensure_daq_schema(sess)
            _ws_save_cfg_from_ui(sess)
            conv = _converter_eff_save_from_ui(sess)
            profile = _converter_eff_method_profile(sess)
            proc = str(conv.get("procedure") or "").strip().upper()
            if not conv.get("applicable"):
                messagebox.showinfo("NOx Converter Efficiency", "This workflow requires both NO and NO2 to be selected.")
                return
            if not conv.get("enabled"):
                messagebox.showinfo("NOx Converter Efficiency", "Enable the CONVERTER_EFF workflow first.")
                return
            if proc != "ALT_BAG_30MIN":
                messagebox.showinfo("NOx Converter Efficiency", "The selected procedure is not the 30-minute bag alternative.")
                return
            start_epoch = _parse_float(conv.get("bag_start_epoch"))
            if not bool(conv.get("bag_active")) or start_epoch is None:
                messagebox.showinfo("NOx Converter Efficiency", "Start the bag test first.")
                return
            duration_min = _parse_float(conv.get("bag_duration_min"), default=_parse_float(profile.get("bag_duration_min"), default=30.0))
            duration_s = float(duration_min or 30.0) * 60.0
            elapsed_s = max(0.0, time.time() - float(start_epoch))
            if elapsed_s + 1e-9 < duration_s:
                remain_min = max(0.0, (duration_s - elapsed_s) / 60.0)
                messagebox.showinfo(
                    "NOx Converter Efficiency",
                    f"EPA 7E bag alternative requires at least {_fmt_num(duration_min, 0, '30')} minutes. About {_fmt_num(remain_min, 1, '0.0')} minute(s) remain.",
                )
                return
            series: List[float] = []
            for ts, fr in list(frame_hist):
                if float(ts) < float(start_epoch):
                    continue
                fr_use = _augment_frame_with_derived_nox(fr)
                val = _parse_float((fr_use or {}).get("NOX"))
                if val is not None:
                    series.append(float(val))
            if len(series) < 2:
                messagebox.showwarning("NOx Converter Efficiency", "Not enough derived NOx data were collected during the bag test window.")
                return
            peak_nox = max(series)
            final_nox = series[-1]
            if peak_nox <= 0:
                messagebox.showwarning("NOx Converter Efficiency", "Peak derived NOx was not positive; cannot evaluate bag-alternative drop.")
                return
            drop_pct = max(0.0, ((float(peak_nox) - float(final_nox)) / float(peak_nox)) * 100.0)
            max_drop_pct = _parse_float(conv.get("bag_max_drop_pct"), default=_parse_float(profile.get("bag_max_drop_pct"), default=2.0))
            passed = bool(drop_pct <= float(max_drop_pct or 2.0))
            status = "PASS" if passed else "FAIL"
            cap = {
                "ts_iso": _iso_now(),
                "procedure": proc,
                "procedure_label": _converter_eff_procedure_label(proc),
                "method_profile": str(profile.get("code") or ""),
                "method_basis": str(profile.get("basis") or ""),
                "result_type": "BAG",
                "bag_start_iso": str(conv.get("bag_start_iso") or ""),
                "bag_start_epoch": float(start_epoch),
                "elapsed_s": float(elapsed_s),
                "duration_min": float(duration_min or 30.0),
                "peak_nox": float(peak_nox),
                "final_nox": float(final_nox),
                "drop_pct": float(drop_pct),
                "max_drop_pct": float(max_drop_pct or 2.0),
                "n_samples": int(len(series)),
                "criteria_text": _converter_eff_criteria_text(conv, profile),
                "pass": bool(passed),
                "status": status,
            }
            conv["bag_active"] = False
            conv["last_capture"] = cap
            hist = conv.get("history") if isinstance(conv.get("history"), list) else []
            hist.append(dict(cap))
            if len(hist) > 1000:
                del hist[:-1000]
            conv["history"] = hist
            ws, ws_cfg, ws_q = _ws_get_cfg(sess)
            ws_q.setdefault("channel_valid", {})
            ws_q["channel_valid"]["NOX"] = bool(passed)
            _ws_log_event(sess, "CONVERTER_EFF_BAG_FINALIZE", dict(cap))
            _save_session(sess)
            refresh_all()
        except Exception as e:
            messagebox.showerror("NOx Converter Efficiency", str(e))

    def _reset_converter_eff() -> None:
        nonlocal sess
        if not messagebox.askyesno("NOx Converter Efficiency", "Reset converter-efficiency captures for this project?", default="no"):
            return
        try:
            sess = _load_session()
            conv = _converter_eff_state_block(sess)
            keep_enabled = bool(conv.get("enabled"))
            keep_target = conv.get("target")
            keep_min = conv.get("tol_min_pct")
            keep_max = conv.get("tol_max_pct")
            keep_proc = str(conv.get("procedure") or "")
            keep_profile = str(conv.get("method_profile") or "")
            keep_basis = str(conv.get("method_basis") or "")
            keep_duration = conv.get("bag_duration_min")
            keep_max_drop = conv.get("bag_max_drop_pct")
            conv.clear()
            conv["enabled"] = keep_enabled and bool(_derived_nox_applicable(sess))
            conv["applicable"] = bool(_derived_nox_applicable(sess))
            conv["target"] = keep_target
            conv["tol_min_pct"] = keep_min if keep_min is not None else 90.0
            conv["tol_max_pct"] = keep_max
            conv["procedure"] = keep_proc or "GENERIC_PERCENT"
            conv["method_profile"] = keep_profile
            conv["method_basis"] = keep_basis
            conv["criteria_locked"] = bool(str(keep_profile or "").strip().upper() == "EPA_7E_NOX")
            conv["bag_active"] = False
            conv["bag_start_iso"] = ""
            conv["bag_start_epoch"] = None
            conv["bag_duration_min"] = keep_duration if keep_duration is not None else 30.0
            conv["bag_max_drop_pct"] = keep_max_drop if keep_max_drop is not None else 2.0
            conv["last_capture"] = {}
            conv["history"] = []
            _converter_eff_state_block(sess)
            try:
                _ensure_daq_schema(sess)
                ws_q = (((sess.get("daq_runner") or {}).get("worksteps") or {}).get("qaqc") or {})
                if isinstance(ws_q.get("channel_valid"), dict):
                    ws_q["channel_valid"].pop("NOX", None)
            except Exception:
                pass
            _ws_log_event(sess, "CONVERTER_EFF_RESET", {})
            _save_session(sess)
            refresh_all()
        except Exception as e:
            messagebox.showerror("NOx Converter Efficiency", str(e))

    def _load_reference_config(sess_local: Dict[str, Any]) -> None:
        ref_cfg = _reference_cfg_block(sess_local)
        var_ref_enabled.set(bool(ref_cfg.get("enabled")))
        var_ref_role.set(str(ref_cfg.get("role") or "AUDIT"))
        if mole_ftir_methods is not None:
            try:
                var_ref_method_standard.set(mole_ftir_methods.method_display_label(ref_cfg.get("method_standard")))
            except Exception:
                var_ref_method_standard.set(str(ref_cfg.get("method_standard") or "ASTM D6348-12"))
        else:
            var_ref_method_standard.set(str(ref_cfg.get("method_standard") or "ASTM D6348-12"))
        var_ref_path.set(str(ref_cfg.get("prn_path") or ""))
        var_ref_pattern.set(str(ref_cfg.get("file_pattern") or "*.prn"))
        try:
            var_ref_fresh.set(f"{float(ref_cfg.get('freshness_s') or 0.0):g}")
        except Exception:
            var_ref_fresh.set("120")
        try:
            if mole_ftir_reference is not None:
                var_ref_overrides.set(mole_ftir_reference.format_overrides_text(ref_cfg.get("column_overrides") or {}))
            else:
                var_ref_overrides.set("")
        except Exception:
            var_ref_overrides.set("")
        off_cfg = ref_cfg.get("offset_recommendations") if isinstance(ref_cfg.get("offset_recommendations"), dict) else {}
        var_ref_offset_use_global.set(bool(off_cfg.get("use_global")))
        var_ref_offset_promote_future.set(bool(off_cfg.get("promote_latest_for_future_projects")))
        if mole_ftir_offset_recommendations is not None:
            try:
                store_summary = mole_ftir_offset_recommendations.summarize_store(mole_ftir_offset_recommendations.load_store())
                active_set_id = str(store_summary.get("active_set_id") or "").strip()
                active_count = int(store_summary.get("active_channel_count") or 0)
                if active_set_id:
                    ref_offset_store_var.set(
                        f"FTIR offsets: {active_set_id} | {active_count} channel(s) | Auto-apply future: {'Y' if store_summary.get('auto_apply_future_projects') else 'N'}"
                    )
                else:
                    ref_offset_store_var.set("FTIR offsets: no carried-forward set approved")
            except Exception:
                ref_offset_store_var.set("FTIR offsets: unavailable")
        _populate_ftir_method_worksteps(sess_local)

    def _browse_reference_file() -> None:
        try:
            current = str(var_ref_path.get() or "").strip()
            initial_dir = current if Path(current).is_dir() else str(Path(current).parent if current else cfg_path.parent)
            picked = filedialog.askopenfilename(
                title="Select MG2000 PRN file",
                initialdir=initial_dir,
                filetypes=[("PRN files", "*.prn"), ("All files", "*.*")],
            )
            if picked:
                var_ref_path.set(picked)
        except Exception as e:
            messagebox.showerror("FTIR Config", str(e))

    def _browse_reference_dir() -> None:
        try:
            current = str(var_ref_path.get() or "").strip()
            initial_dir = current if Path(current).is_dir() else str(Path(current).parent if current else cfg_path.parent)
            picked = filedialog.askdirectory(title="Select folder containing MG2000 PRN files", initialdir=initial_dir)
            if picked:
                var_ref_path.set(picked)
        except Exception as e:
            messagebox.showerror("FTIR Config", str(e))

    def _save_reference_config() -> None:
        nonlocal sess
        try:
            sess = _load_session()
            ref_cfg = _reference_cfg_block(sess)
            ref_cfg["enabled"] = bool(var_ref_enabled.get())
            ref_cfg["role"] = str(var_ref_role.get() or "AUDIT").strip().upper() or "AUDIT"
            ref_cfg["method_standard"] = (
                mole_ftir_methods.code_from_display(var_ref_method_standard.get())
                if mole_ftir_methods is not None
        else (str(var_ref_method_standard.get() or "ASTM_D6348_12").strip() or "ASTM_D6348_12")
            )
            ref_cfg["prn_path"] = str(var_ref_path.get() or "").strip()
            ref_cfg["file_pattern"] = str(var_ref_pattern.get() or "*.prn").strip() or "*.prn"
            try:
                ref_cfg["freshness_s"] = max(0.0, float(var_ref_fresh.get() or 0.0))
            except Exception:
                ref_cfg["freshness_s"] = 120.0
            ref_cfg["offset_recommendations"] = {
                "use_global": bool(var_ref_offset_use_global.get()),
                "promote_latest_for_future_projects": bool(var_ref_offset_promote_future.get()),
            }
            if mole_ftir_reference is not None:
                ref_cfg["column_overrides"] = mole_ftir_reference.parse_overrides_text(var_ref_overrides.get() or "")
                ref_cfg = mole_ftir_reference.normalize_config(ref_cfg)
            if mole_ftir_offset_recommendations is not None:
                store = mole_ftir_offset_recommendations.load_store()
                ref_cfg["offset_recommendations"] = mole_ftir_offset_recommendations.normalize_project_policy(
                    ref_cfg.get("offset_recommendations"),
                    default_use_global=bool(store.get("auto_apply_future_projects")),
                )
            blk = _ensure_daq_schema(sess)
            blk["reference_audit"] = dict(ref_cfg)
            sess["reference_audit"] = dict(ref_cfg)
            blk["spike_recovery"] = dict(_spike_cfg_block(sess))
            sess["spike_recovery"] = dict(blk.get("spike_recovery") or {})
            _save_session(sess)
            _load_reference_config(sess)
            _populate_reference_table(sess)
            _populate_spike_recovery(sess)
            _update_reference_panel(None, sess)
            log("Saved FTIR reference/audit ingest configuration.")
        except Exception as e:
            messagebox.showerror("FTIR Config", str(e))

    def _update_reference_panel(frame: Optional[Dict[str, Any]] = None, sess_local: Optional[Dict[str, Any]] = None) -> None:
        sess_use = sess_local if isinstance(sess_local, dict) else sess
        snapshot = None
        if isinstance(frame, dict):
            snapshot = frame.get("_reference_snapshot")
        if snapshot is None:
            snapshot = acq.get("reference_snapshot")
        if snapshot is None and mole_ftir_reference is not None:
            try:
                cfg = _reference_cfg_block(sess_use)
                if cfg.get("enabled") and str(cfg.get("prn_path") or "").strip():
                    snapshot = mole_ftir_reference.MG2000PrnIngestor(cfg).read_snapshot()
            except Exception:
                snapshot = None

        ref_cfg = _reference_cfg_block(sess_use)
        meta = _ftir_method_meta(ref_cfg.get("method_standard"))
        status = str((snapshot or {}).get("status") or ("DISABLED" if not ref_cfg.get("enabled") else "IDLE")).strip().upper()
        meas = ((snapshot or {}).get("measurements") or {}) if isinstance(snapshot, dict) else {}
        ref_status_var.set(f"FTIR: {status}" + (f" ({len(meas)} values)" if isinstance(meas, dict) and meas else ""))
        ref_method_status_var.set(f"FTIR method: {str(meta.get('label') or ref_cfg.get('method_standard') or 'ASTM D6348-12')}")
        ref_detail_var.set(
            "PRN path: "
            + (str((snapshot or {}).get("source_path") or ref_cfg.get("prn_path") or "(not configured)"))
            + f"   Role: {str(ref_cfg.get('role') or 'AUDIT')}"
        )
        age_v = (snapshot or {}).get("age_s") if isinstance(snapshot, dict) else None
        mtime_v = str((snapshot or {}).get("source_mtime_iso") or "").strip() if isinstance(snapshot, dict) else ""
        if age_v is not None:
            ref_age_var.set(f"File age: {_fmt_num(age_v, 1, '(n/a)')} s" + (f"   Updated: {mtime_v}" if mtime_v else ""))
        else:
            ref_age_var.set("File age: (n/a)")
        if mole_ftir_offset_recommendations is not None:
            try:
                store_summary = mole_ftir_offset_recommendations.summarize_store(mole_ftir_offset_recommendations.load_store())
                active_set_id = str(store_summary.get("active_set_id") or "").strip()
                active_count = int(store_summary.get("active_channel_count") or 0)
                using_offsets = bool(((ref_cfg.get("offset_recommendations") or {}).get("use_global")))
                if active_set_id:
                    ref_offset_store_var.set(
                        f"FTIR offsets: {'ON' if using_offsets else 'OFF'} | Set {active_set_id} | {active_count} channel(s)"
                    )
                else:
                    ref_offset_store_var.set(f"FTIR offsets: {'ON' if using_offsets else 'OFF'} | no carried-forward set approved")
            except Exception:
                ref_offset_store_var.set("FTIR offsets: unavailable")

        desired = _reference_display_codes(sess_use, snapshot if isinstance(snapshot, dict) else None)
        if set(desired) != set(ref_iids.keys()):
            _populate_reference_table(sess_use, snapshot if isinstance(snapshot, dict) else None)

        pres = _pollutant_prescriptions(sess_use)
        for code in desired:
            iid = ref_iids.get(code)
            if not iid:
                continue
            primary_v = _parse_float((frame or {}).get(code)) if isinstance(frame, dict) else None
            rec = (meas.get(code) or {}) if isinstance(meas, dict) else {}
            ref_v = _parse_float(rec.get("value")) if isinstance(rec, dict) else None
            units = str((rec.get("units") if isinstance(rec, dict) else "") or (pres.get(code) or {}).get("units") or "").strip()
            delta_v = None
            if primary_v is not None and ref_v is not None:
                try:
                    delta_v = float(primary_v) - float(ref_v)
                except Exception:
                    delta_v = None
            source_col = str((rec.get("source_column") if isinstance(rec, dict) else "") or "")
            tags = ("dim",)
            if ref_v is not None:
                tags = ("ok",) if status not in ("READ_FAIL", "PARSE_FAIL", "MISSING") else ("fail",)
            elif status in ("READ_FAIL", "PARSE_FAIL", "MISSING"):
                tags = ("fail",)
            ref_tree.item(
                iid,
                values=(
                    code,
                    _fmt_pollutant_measurement(primary_v, "(n/a)", code),
                    _fmt_pollutant_measurement(ref_v, "(n/a)", code),
                    units,
                    _fmt_pollutant_measurement(delta_v, "", code),
                    source_col,
                ),
                tags=tags,
            )

    btn_ref_browse_file.configure(command=_browse_reference_file)
    btn_ref_browse_dir.configure(command=_browse_reference_dir)
    btn_ref_save.configure(command=_save_reference_config)
    btn_ftir_ws_done.configure(command=lambda: _ftir_method_mark("DONE"))
    btn_ftir_ws_skip.configure(command=lambda: _ftir_method_mark("SKIPPED"))
    btn_ftir_ws_reset.configure(command=_ftir_method_reset)
    btn_spike_capture_native.configure(command=lambda: _capture_spike_phase("NATIVE"))
    btn_spike_capture_spike.configure(command=lambda: _capture_spike_phase("SPIKE"))
    btn_spike_save.configure(command=_save_spike_setup)
    btn_spike_reset.configure(command=_reset_spike_recovery)
    btn_side_sync.configure(command=lambda: _append_side_by_side_event("SYNC_MARK", "Manual sync marker"))
    btn_side_bias.configure(command=lambda: _append_side_by_side_event("BIAS_VALVE", "Bias valve opened"))
    btn_side_purge.configure(command=lambda: _append_side_by_side_event("AMBIENT_PURGE", "Ambient purge completed"))
    btn_side_drift.configure(command=lambda: _append_side_by_side_event("PROJECT_DRIFT", "Project drift check completed"))
    btn_conv_save.configure(command=_save_converter_eff_setup)
    btn_conv_capture.configure(command=_capture_converter_eff)
    btn_conv_bag_start.configure(command=_start_converter_eff_bag)
    btn_conv_bag_finalize.configure(command=_finalize_converter_eff_bag)
    btn_conv_reset.configure(command=_reset_converter_eff)

    def _populate_worksteps(sess: Dict[str, Any]) -> None:
        """Render the Worksteps & QA/QC panel (pretest ZERO / MID / SPAN capture)."""
        for child in ws_frame.winfo_children():
            try:
                child.destroy()
            except Exception:
                pass

        ws_row_vars.clear()
        ws_readonly_row_vars.clear()

        ws = (sess.get("daq_runner") or {}).get("worksteps") or {}
        ws_cfg = (ws.get("config") or {})
        ws_q = (ws.get("qaqc") or {})

        cal_pts = _cal_points_effective(sess)
        show_mid = bool(int(cal_pts or 2) >= 3)

        selected = _selected_pollutants(sess)
        pres = _pollutant_prescriptions(sess)

        resolved_by = (((sess.get("pollutants") or {}).get("resolved") or {}).get("resolved_by_analyte") or {})

        def _resolved_span_mid(code: str) -> tuple[float | None, float | None, float]:
            ra = resolved_by.get(code) or {}
            p = pres.get(code) or {}
            ss = _parse_float((p or {}).get("span_target"), default=None)
            if ss is None:
                ss = _parse_float((p or {}).get("span_cylinder_id"), default=None)
            ms = _parse_float((p or {}).get("mid_target"), default=None)
            if ms is None:
                ms = _parse_float((p or {}).get("mid_cylinder_id"), default=None)
            mf = ra.get("mid_fraction")
            mid_frac = 0.5
            try:
                if mf is not None:
                    mid_frac = float(mf)
                if not (0.0 < float(mid_frac) < 1.0):
                    mid_frac = 0.5
            except Exception:
                mid_frac = 0.5

            try:
                if ms is None and ss is not None:
                    ms = float(ss) * float(mid_frac)
            except Exception:
                pass
            return (ss, ms, float(mid_frac))

        def fmt_target(v: Any) -> str:
            if v is None:
                return ""
            try:
                vf = float(v)
                return _fmt_num(vf, fallback=str(v))
            except Exception:
                return str(v)

        def fmt_pct(num: Any) -> str:
            try:
                nf = float(num)
                text = _fmt_num(nf, fallback="")
                return f"{text}%" if text else ""
            except Exception:
                return ""

        # Dynamic columns: MID shown when session uses 3-pt CAL
        cols: list[str] = ["Pollutant", "Units", "Zero tgt", "Capture ZERO", "Zero avg", "Zero ok", "MDC"]
        if show_mid:
            cols += ["Mid tgt", "Capture MID", "Mid avg", "Recov%", "Mid ok"]
        cols += ["Span tgt", "Capture SPAN", "Span avg", "Recov%", "Span ok", "T90(s)", "Valid"]

        for c, name in enumerate(cols):
            tk.Label(ws_frame, text=name, bg=PANEL_BG, fg=FG_DIM, font=FONT_HDR).grid(row=0, column=c, sticky="w", padx=4, pady=(0, 2))

        row = 1
        for code in selected:
            p = pres.get(code) or {}
            units = p.get("units") or ""

            zblock = (ws_q.get("zero") or {}).get(code) or {}
            mblock = (ws_q.get("mid") or {}).get(code) or {}
            sblock = (ws_q.get("span") or {}).get(code) or {}
            mdc_val = (ws_q.get("mdc") or {}).get(code)

            resp = (ws_q.get("response") or {}).get(code) or {}
            t90 = resp.get("t90_s")

            valid_latch = (ws_q.get("channel_valid") or {}).get(code, True)
            validity = _ws_derive_validity(sess, code, zblock, sblock, valid_latch)
            valid_state = str((validity or {}).get("state") or ("VALID" if valid_latch else "INVALID")).strip().upper()
            valid_fg = FG_OK if valid_state == "VALID" else (ACC2 if valid_state == "DEGRADED" else BAD)

            # Targets: prefer existing session targets; otherwise suggest from resolved values
            zero_tgt = zblock.get("target")
            if zero_tgt in (None, ""):
                zero_tgt = 0.0
            mid_tgt = mblock.get("target")
            span_tgt = sblock.get("target")

            ss, ms, mf = _resolved_span_mid(code)

            # If no explicit target yet, prefill suggestions (non-destructive; stored on capture)
            if span_tgt in (None, "") and ss is not None:
                span_tgt = ss
            if show_mid and mid_tgt in (None, ""):
                # Prefer half of current span target if numeric, else resolved mid suggestion
                try:
                    if span_tgt not in (None, ""):
                        mid_tgt = float(span_tgt) * float(mf)
                    else:
                        mid_tgt = ms
                except Exception:
                    mid_tgt = ms

            zero_pass_state = _ws_row_pass_state(zblock)
            mid_pass_state = _ws_row_pass_state(mblock) if show_mid else None
            span_pass_state = _ws_row_pass_state(sblock)

            # --- build per-row vars ---
            ws_vars: Dict[str, Any] = {
                "zero_tgt": tk.StringVar(value=fmt_target(zero_tgt)),
                "zero_avg": tk.StringVar(value=fmt_target(_ws_row_display_value(zblock, "avg", "avg", "meas"))),
                "zero_ok": tk.StringVar(value=_ws_row_status_text(zblock, pass_text="OK")),
                "zero_ok_fg": (FG_OK if zero_pass_state is True else (BAD if zero_pass_state is False else FG_DIM)),
                "mdc": tk.StringVar(value=fmt_target(mdc_val)),
                "span_tgt": tk.StringVar(value=fmt_target(span_tgt)),
                "span_avg": tk.StringVar(value=fmt_target(_ws_row_display_value(sblock, "avg", "avg", "meas"))),
                "span_recov": tk.StringVar(value=fmt_pct(_ws_row_display_value(sblock, "recovery_pct", "recovery_pct"))),
                "span_ok": tk.StringVar(value=_ws_row_status_text(sblock, pass_text="OK")),
                "span_ok_fg": (FG_OK if span_pass_state is True else (BAD if span_pass_state is False else FG_DIM)),
                "t90": tk.StringVar(value=fmt_target(t90)),
                "valid": tk.StringVar(value=valid_state),
                "valid_fg": valid_fg,
            }
            if show_mid:
                ws_vars.update({
                    "mid_tgt": tk.StringVar(value=fmt_target(mid_tgt)),
                    "mid_avg": tk.StringVar(value=fmt_target(_ws_row_display_value(mblock, "avg", "avg", "meas"))),
                    "mid_recov": tk.StringVar(value=fmt_pct(_ws_row_display_value(mblock, "recovery_pct", "recovery_pct"))),
                    "mid_ok": tk.StringVar(value=_ws_row_status_text(mblock, pass_text="OK")),
                    "mid_ok_fg": (FG_OK if mid_pass_state is True else (BAD if mid_pass_state is False else FG_DIM)),
                })

            ws_row_vars[code] = ws_vars

            ws_readonly_row_vars[code] = {
                "zero_avg": ws_vars["zero_avg"],
                "zero_ok": ws_vars["zero_ok"],
                "mdc": ws_vars["mdc"],
                "span_avg": ws_vars["span_avg"],
                "span_recov": ws_vars["span_recov"],
                "span_ok": ws_vars["span_ok"],
                "t90": ws_vars["t90"],
                "valid": ws_vars["valid"],
            }
            if show_mid:
                ws_readonly_row_vars[code].update({
                    "mid_avg": ws_vars["mid_avg"],
                    "mid_recov": ws_vars["mid_recov"],
                    "mid_ok": ws_vars["mid_ok"],
                })

            # --- render row widgets ---
            col = 0

            tk.Label(ws_frame, text=code, bg=PANEL_BG, fg=FG, font=FONT).grid(row=row, column=col, sticky="w", padx=4); col += 1
            tk.Label(ws_frame, text=units, bg=PANEL_BG, fg=FG_DIM, font=FONT).grid(row=row, column=col, sticky="w", padx=4); col += 1

            e0 = tk.Entry(ws_frame, textvariable=ws_vars["zero_tgt"], width=8, bg=ENTRY_BG, fg=FG, insertbackground=FG, relief="flat")
            e0.grid(row=row, column=col, sticky="w", padx=4); col += 1

            b0 = tk.Button(ws_frame, text="Capture", command=lambda c=code: ws_capture_zero(c), bg=BTN_BG, fg=FG, relief="flat")
            b0.grid(row=row, column=col, sticky="w", padx=4); col += 1

            tk.Label(ws_frame, textvariable=ws_vars["zero_avg"], bg=PANEL_BG, fg=ws_vars["zero_ok_fg"], font=FONT).grid(row=row, column=col, sticky="w", padx=4); col += 1
            tk.Label(ws_frame, textvariable=ws_vars["zero_ok"], bg=PANEL_BG, fg=ws_vars["zero_ok_fg"], font=FONT).grid(row=row, column=col, sticky="w", padx=4); col += 1

            tk.Label(ws_frame, textvariable=ws_vars["mdc"], bg=PANEL_BG, fg=FG_DIM, font=FONT).grid(row=row, column=col, sticky="w", padx=4); col += 1

            if show_mid:
                em = tk.Entry(ws_frame, textvariable=ws_vars["mid_tgt"], width=8, bg=ENTRY_BG, fg=FG, insertbackground=FG, relief="flat")
                em.grid(row=row, column=col, sticky="w", padx=4); col += 1

                bm = tk.Button(ws_frame, text="Capture", command=lambda c=code: ws_capture_mid(c), bg=BTN_BG, fg=FG, relief="flat")
                bm.grid(row=row, column=col, sticky="w", padx=4); col += 1

                tk.Label(ws_frame, textvariable=ws_vars["mid_avg"], bg=PANEL_BG, fg=ws_vars["mid_ok_fg"], font=FONT).grid(row=row, column=col, sticky="w", padx=4); col += 1
                tk.Label(ws_frame, textvariable=ws_vars["mid_recov"], bg=PANEL_BG, fg=ws_vars["mid_ok_fg"], font=FONT).grid(row=row, column=col, sticky="w", padx=4); col += 1
                tk.Label(ws_frame, textvariable=ws_vars["mid_ok"], bg=PANEL_BG, fg=ws_vars["mid_ok_fg"], font=FONT).grid(row=row, column=col, sticky="w", padx=4); col += 1

            es = tk.Entry(ws_frame, textvariable=ws_vars["span_tgt"], width=8, bg=ENTRY_BG, fg=FG, insertbackground=FG, relief="flat")
            es.grid(row=row, column=col, sticky="w", padx=4); col += 1

            bs = tk.Button(ws_frame, text="Capture", command=lambda c=code: ws_capture_span(c), bg=BTN_BG, fg=FG, relief="flat")
            bs.grid(row=row, column=col, sticky="w", padx=4); col += 1

            tk.Label(ws_frame, textvariable=ws_vars["span_avg"], bg=PANEL_BG, fg=ws_vars["span_ok_fg"], font=FONT).grid(row=row, column=col, sticky="w", padx=4); col += 1
            tk.Label(ws_frame, textvariable=ws_vars["span_recov"], bg=PANEL_BG, fg=ws_vars["span_ok_fg"], font=FONT).grid(row=row, column=col, sticky="w", padx=4); col += 1
            tk.Label(ws_frame, textvariable=ws_vars["span_ok"], bg=PANEL_BG, fg=ws_vars["span_ok_fg"], font=FONT).grid(row=row, column=col, sticky="w", padx=4); col += 1

            tk.Label(ws_frame, textvariable=ws_vars["t90"], bg=PANEL_BG, fg=FG_DIM, font=FONT).grid(row=row, column=col, sticky="w", padx=4); col += 1
            tk.Label(ws_frame, textvariable=ws_vars["valid"], bg=PANEL_BG, fg=ws_vars["valid_fg"], font=FONT).grid(row=row, column=col, sticky="w", padx=4); col += 1

            row += 1

    def _populate_postcal(sess: Dict[str, Any]) -> None:
        """Populate post-run bias/post-cal section for the active required run (or latest completed)."""
        # clear container
        try:
            for w in ws_post_rows_container.winfo_children():
                try:
                    w.destroy()
                except Exception:
                    pass
        except Exception:
            pass
        ws_post_row_vars.clear()

        blk = sess.get("daq_runner") or {}
        ws = (blk.get("worksteps") or {})
        ws_q = (ws.get("qaqc") or {})
        postcal = ws.get("postcal") or {}
        required = bool(postcal.get("required"))

        run_no = postcal.get("run_no")
        # fallback to active run_no if not specified
        if run_no in (None, ""):
            try:
                runs = blk.get("runs") or []
                idx = int(blk.get("active_run_index") or 0)
                if isinstance(runs, list) and runs and 0 <= idx < len(runs):
                    run_no = (runs[idx] or {}).get("run_no")
            except Exception:
                run_no = None

        try:
            run_no_i = int(run_no) if run_no not in (None, "") else None
        except Exception:
            run_no_i = None

        # choose display run (required run preferred; else latest completed)
        display_run = run_no_i
        if not required:
            try:
                comp = postcal.get("completed_runs") or {}
                keys = []
                if isinstance(comp, dict):
                    for k in comp.keys():
                        try:
                            keys.append(int(str(k)))
                        except Exception:
                            pass
                if keys:
                    display_run = max(keys)
            except Exception:
                pass

        ws_runtime["post_required"] = bool(required)
        ws_runtime["post_run_no"] = display_run

        if display_run is None:
            ws_post_status_var.set("Post-Cal: (idle)")
            tk.Label(ws_post_rows_container, text="(No post-cal required yet)", fg=FG_DIM, bg=BG, font=("Consolas", 9)).grid(row=0, column=0, sticky="w")
            return

        post_runs = ws_q.get("post_runs") or {}
        prun = post_runs.get(str(display_run)) or {}
        pzero_map = prun.get("zero") or {}
        pspan_map = prun.get("span") or {}

        sel = _selected_pollutants(sess)
        total = len(sel) if sel else 0
        z_cnt = 0
        s_cnt = 0
        try:
            for c in sel:
                if isinstance((pzero_map or {}).get(c), dict) and (pzero_map or {}).get(c):
                    z_cnt += 1
                if isinstance((pspan_map or {}).get(c), dict) and (pspan_map or {}).get(c):
                    s_cnt += 1
        except Exception:
            pass

        # status string
        if required:
            ws_post_status_var.set(f"Post-Cal REQUIRED for Run {display_run} (zero {z_cnt}/{total}, span {s_cnt}/{total})")
        else:
            # show last completion summary if available
            overall = None
            try:
                comp = (postcal.get("completed_runs") or {}).get(str(display_run)) or {}
                if isinstance(comp, dict) and "pass" in comp:
                    overall = bool(comp.get("pass"))
            except Exception:
                overall = None
            if overall is True:
                ws_post_status_var.set(f"Post-Cal COMPLETE for Run {display_run} (PASS)")
            elif overall is False:
                ws_post_status_var.set(f"Post-Cal COMPLETE for Run {display_run} (FAIL — channels invalidated)")
            else:
                ws_post_status_var.set(f"Post-Cal status for Run {display_run}")

        # header
        hdr = [
            "Pollutant",
            "Units",
            "Zero tgt",
            "Capture",
            "Post Zero",
            "ΔZero",
            "Zero OK",
            "Span tgt",
            "Capture",
            "Post Span",
            "Recov%",
            "ΔRecov",
            "Span OK",
            "Valid",
        ]
        for c, h in enumerate(hdr):
            tk.Label(ws_post_rows_container, text=h, fg=FG, bg=BG, font=("Consolas", 9, "bold")).grid(
                row=0, column=c, sticky="w", padx=(0, 10), pady=(0, 4)
            )

        pres = _pollutant_prescriptions(sess)
        pre_zero_map = ws_q.get("zero") or {}
        pre_span_map = ws_q.get("span") or {}

        valid_map = (prun.get("channel_valid") or {}) if isinstance(prun, dict) else {}

        r = 1
        for code in sel:
            p = pres.get(code) or {}
            units = str(p.get("expected_units") or p.get("units") or "").strip()

            pre_z = pre_zero_map.get(code) or {}
            pre_s = pre_span_map.get(code) or {}

            pz = (pzero_map or {}).get(code) or {}
            ps = (pspan_map or {}).get(code) or {}

            # targets
            default_zero_tgt = pz.get("target")
            if default_zero_tgt in (None, ""):
                default_zero_tgt = pre_z.get("target")
            if default_zero_tgt in (None, ""):
                default_zero_tgt = 0.0

            default_span_tgt = ps.get("target")
            if default_span_tgt in (None, ""):
                default_span_tgt = pre_s.get("target")
            if default_span_tgt in (None, ""):
                default_span_tgt = _parse_float((p or {}).get("span_target"), default="")
            if default_span_tgt in (None, ""):
                default_span_tgt = ""

            v_zero_tgt = tk.StringVar(value=str(default_zero_tgt))
            v_span_tgt = tk.StringVar(value=str(default_span_tgt))

            post_zero = _parse_float(pz.get("meas"))
            post_span = _parse_float(ps.get("meas"))

            pre_zero = _parse_float(pre_z.get("meas"))
            pre_recov = _parse_float(pre_s.get("recovery_pct"))

            post_recov = _parse_float(ps.get("recovery_pct"))

            drift_zero = None
            if (pre_zero is not None) and (post_zero is not None):
                drift_zero = float(post_zero) - float(pre_zero)

            drift_recov = None
            if (pre_recov is not None) and (post_recov is not None):
                drift_recov = float(post_recov) - float(pre_recov)

            v_post_zero = tk.StringVar(value=_fmt_pollutant_measurement(post_zero, "(n/a)", code))
            v_dz = tk.StringVar(value=_fmt_num(drift_zero, 3, "—"))
            zero_ok_text = _ws_row_status_text(pz, pass_text="PASS") if pz else "—"
            zero_ok_pass = _ws_row_pass_state(pz)
            v_zero_ok = tk.StringVar(value=zero_ok_text)

            v_post_span = tk.StringVar(value=_fmt_pollutant_measurement(post_span, "(n/a)", code))
            v_post_recov = tk.StringVar(value=_fmt_num(post_recov, 2, "—"))
            v_dr = tk.StringVar(value=_fmt_num(drift_recov, 2, "—"))
            span_ok_text = _ws_row_status_text(ps, pass_text="PASS") if ps else "—"
            span_ok_pass = _ws_row_pass_state(ps)
            v_span_ok = tk.StringVar(value=span_ok_text)

            v_valid = tk.StringVar(value="OK" if bool(valid_map.get(code, True)) else "INVALID")

            tk.Label(ws_post_rows_container, text=code, fg=FG, bg=BG, font=("Consolas", 9)).grid(
                row=r, column=0, sticky="w", padx=(0, 10)
            )
            tk.Label(ws_post_rows_container, text=units, fg=FG_DIM, bg=BG, font=("Consolas", 9)).grid(
                row=r, column=1, sticky="w", padx=(0, 10)
            )

            ent_zero_tgt = tk.Entry(ws_post_rows_container, textvariable=v_zero_tgt, bg=PANEL_BG, fg=FG, insertbackground=FG, relief="flat", width=8, font=("Consolas", 9))
            ent_zero_tgt.grid(row=r, column=2, sticky="w", padx=(0, 10))

            tk.Button(
                ws_post_rows_container,
                text="Post ZERO",
                bg=BTN_BG,
                fg=FG,
                relief="flat",
                font=("Consolas", 8),
                command=lambda c=code: ws_capture_post_zero(c),
            ).grid(row=r, column=3, sticky="w", padx=(0, 10))

            tk.Label(ws_post_rows_container, textvariable=v_post_zero, fg=(FG_OK if zero_ok_pass is True else (BAD if zero_ok_pass is False else VAL_FG)), bg=BG, font=("Consolas", 9)).grid(row=r, column=4, sticky="w", padx=(0, 10))
            tk.Label(ws_post_rows_container, textvariable=v_dz, fg=(FG_OK if zero_ok_pass is True else (BAD if zero_ok_pass is False else VAL_FG)), bg=BG, font=("Consolas", 9)).grid(row=r, column=5, sticky="w", padx=(0, 10))
            tk.Label(
                ws_post_rows_container,
                textvariable=v_zero_ok,
                fg=FG_OK if zero_ok_pass is True else (BAD if zero_ok_pass is False else FG_DIM),
                bg=BG,
                font=("Consolas", 9, "bold"),
            ).grid(row=r, column=6, sticky="w", padx=(0, 10))

            ent_span_tgt = tk.Entry(ws_post_rows_container, textvariable=v_span_tgt, bg=PANEL_BG, fg=FG, insertbackground=FG, relief="flat", width=8, font=("Consolas", 9))
            ent_span_tgt.grid(row=r, column=7, sticky="w", padx=(0, 10))

            tk.Button(
                ws_post_rows_container,
                text="Post SPAN",
                bg=BTN_BG,
                fg=FG,
                relief="flat",
                font=("Consolas", 8),
                command=lambda c=code: ws_capture_post_span(c),
            ).grid(row=r, column=8, sticky="w", padx=(0, 10))

            tk.Label(ws_post_rows_container, textvariable=v_post_span, fg=(FG_OK if span_ok_pass is True else (BAD if span_ok_pass is False else VAL_FG)), bg=BG, font=("Consolas", 9)).grid(row=r, column=9, sticky="w", padx=(0, 10))
            tk.Label(ws_post_rows_container, textvariable=v_post_recov, fg=(FG_OK if span_ok_pass is True else (BAD if span_ok_pass is False else VAL_FG)), bg=BG, font=("Consolas", 9)).grid(row=r, column=10, sticky="w", padx=(0, 10))
            tk.Label(ws_post_rows_container, textvariable=v_dr, fg=(FG_OK if span_ok_pass is True else (BAD if span_ok_pass is False else VAL_FG)), bg=BG, font=("Consolas", 9)).grid(row=r, column=11, sticky="w", padx=(0, 10))
            tk.Label(
                ws_post_rows_container,
                textvariable=v_span_ok,
                fg=FG_OK if span_ok_pass is True else (BAD if span_ok_pass is False else FG_DIM),
                bg=BG,
                font=("Consolas", 9, "bold"),
            ).grid(row=r, column=12, sticky="w", padx=(0, 10))

            tk.Label(
                ws_post_rows_container,
                textvariable=v_valid,
                fg=FG_OK if v_valid.get() == "OK" else BAD,
                bg=BG,
                font=("Consolas", 9, "bold"),
            ).grid(row=r, column=13, sticky="w", padx=(0, 10))

            ws_post_row_vars[code] = {"zero_tgt": v_zero_tgt, "span_tgt": v_span_tgt}
            r += 1


    def _populate_fuel(sess: Dict[str, Any]) -> None:
        comb = _fuel_combustion(sess) or {}
        # theoretical CO2/O2 (dry %) for quick comparison with measured values
        try:
            dry_fr = comb.get("dry_mol_fracs") or {}
            if isinstance(dry_fr, dict):
                comp_vars["theo_co2_dry"].set(_fmt_num(100.0 * float(dry_fr.get("CO2") or 0.0), 3, "(n/a)"))
                comp_vars["theo_o2_dry"].set(_fmt_num(100.0 * float(dry_fr.get("O2") or 0.0), 3, "(n/a)"))
            else:
                comp_vars["theo_co2_dry"].set("(n/a)")
                comp_vars["theo_o2_dry"].set("(n/a)")
        except Exception:
            comp_vars["theo_co2_dry"].set("(n/a)")
            comp_vars["theo_o2_dry"].set("(n/a)")
        fuel_vars["family"].set(str(comb.get("family") or "").upper() or "(n/a)")
        fuel_vars["mw"].set(_fmt_num_g(comb.get("MW_mix"), 6))
        # "HHV/LHV (vol)" preference:
        hhv = comb.get("HHV_Btu_scf")
        lhv = comb.get("LHV_Btu_scf")
        if hhv is None:
            hhv = comb.get("HHV_Btu_gal")
        if lhv is None:
            lhv = comb.get("LHV_Btu_gal")
        fuel_vars["hhv_vol"].set(_fmt_num_g(hhv, 6))
        fuel_vars["lhv_vol"].set(_fmt_num_g(lhv, 6))

        f_sel = comb.get("F_selected")
        if f_sel is None:
            f_sel = comb.get("Fd_sel_dscf_per_MMBtu")
        f_hhv = comb.get("F_HHV") if comb.get("F_HHV") is not None else comb.get("Fd_HHV_dscf_per_MMBtu")
        f_lhv = comb.get("F_LHV") if comb.get("F_LHV") is not None else comb.get("Fd_LHV_dscf_per_MMBtu")
        fuel_vars["f_sel"].set(_fmt_num_g(f_sel, 6))
        fuel_vars["f_hhv"].set(_fmt_num_g(f_hhv, 6))
        fuel_vars["f_lhv"].set(_fmt_num_g(f_lhv, 6))
        fuel_vars["note"].set(str(comb.get("note") or "OK"))

        # products
        prod_tree.delete(*prod_tree.get_children())
        prods = comb.get("products_per_MMBtu")
        if not isinstance(prods, dict):
            prods = None

        if prods is None:
            prod_list = comb.get("products") or []
            dry_fr = comb.get("dry_mol_fracs") or {}
            wet_fr = comb.get("wet_mol_fracs") or {}
            if isinstance(prod_list, list) and prod_list:
                prods = {}
                for r in prod_list:
                    try:
                        sp = str(r.get("species") or "").strip()
                        if not sp:
                            continue
                        scf = r.get("scf_per_MMBtu_std")
                        acf = r.get("acf_per_MMBtu_site")
                        dry_pct = 100.0 * float(dry_fr.get(sp)) if sp in dry_fr else 0.0
                        wet_pct = 100.0 * float(wet_fr.get(sp)) if sp in wet_fr else 0.0
                        prods[sp] = {
                            "dry_pct": dry_pct,
                            "wet_pct": wet_pct,
                            "std_scf_per_MMBtu": float(scf) if scf not in (None, "") else 0.0,
                            "site_acf_per_MMBtu": float(acf) if acf not in (None, "") else 0.0,
                        }
                    except Exception:
                        continue

        if not prods:
            prod_tree.insert("", "end", values=("—", "(n/a)", "(n/a)", "(n/a)", "(n/a)"))
            return

        order = ["CO2", "H2O", "SO2", "N2", "O2"]
        for sp in order:
            if sp not in prods:
                continue
            row = prods[sp]
            prod_tree.insert("", "end", values=(
                sp,
                _fmt_num(row.get("dry_pct"), 3, "0.000"),
                _fmt_num(row.get("wet_pct"), 3, "0.000"),
                _fmt_num(row.get("std_scf_per_MMBtu"), 2, "0.00"),
                _fmt_num(row.get("site_acf_per_MMBtu"), 2, "0.00"),
            ))

        for sp, row in prods.items():
            if sp in order:
                continue
            prod_tree.insert("", "end", values=(
                sp,
                _fmt_num(row.get("dry_pct"), 3, "0.000"),
                _fmt_num(row.get("wet_pct"), 3, "0.000"),
                _fmt_num(row.get("std_scf_per_MMBtu"), 2, "0.00"),
                _fmt_num(row.get("site_acf_per_MMBtu"), 2, "0.00"),
            ))

    def _populate_limits(sess: Dict[str, Any]) -> None:
        reg_tree.delete(*reg_tree.get_children())
        reg = sess.get("regulatory") or {}
        lims = reg.get("limits") or []
        if not lims:
            reg_tree.insert("", "end", values=("—", "", "", "", "", "", "", ""))
            return
        for lim in lims:
            if not isinstance(lim, dict):
                continue
            reg_tree.insert("", "end", values=(
                str(lim.get("pollutant") or ""),
                str(lim.get("limit_type") or ""),
                _fmt_num(lim.get("value"), 3, ""),
                str(lim.get("units") or ""),
                str(lim.get("avg_time") or ""),
                str(lim.get("basis") or ""),
                _fmt_num(lim.get("o2_ref_pct"), 1, ""),
                str(lim.get("notes") or ""),
            ))

    def _populate_source(sess: Dict[str, Any]) -> None:
        src_text.delete("1.0", "end")
        src_text.insert("1.0", _format_source_summary(sess))

    def _populate_test_matrix(sess: Dict[str, Any]) -> None:
        tm_tree.delete(*tm_tree.get_children())
        tm = sess.get("test_matrix")
        if not tm:
            tm_tree.insert("", "end", values=("—", "(none)", "", "", "", "", ""))
            return
        for i, t in enumerate(tm.get("tests", []) or []):
            if not isinstance(t, dict):
                continue
            tid = str(t.get("id") or "")
            name = str(t.get("name") or tid)
            req = "Y" if bool(t.get("required")) else "N"
            pts = str(t.get("points") or 0)
            mn = str(t.get("min_points") or 0)
            perf = "Y" if bool(t.get("performed")) else "N"
            wav = "Y" if bool(t.get("waived")) else "N"
            iid = f"TM_{i}"
            tm_tree.insert("", "end", iid=iid, values=(tid, name, req, pts, mn, perf, wav))

    def _ensure_runs(sess: Dict[str, Any]) -> None:
        blk = _ensure_daq_schema(sess)
        runs = blk.get("runs") or []
        if not isinstance(runs, list):
            runs = []
        if not runs:
            runs.append({
                "run_no": 1,
                "start_iso": _now_iso_local(),
                "end_iso": None,
                "notes": "",
                "method_inputs": {},
            })
        # normalize run_no
        for idx, r in enumerate(runs):
            if not isinstance(r, dict):
                continue
            if not r.get("run_no"):
                r["run_no"] = idx + 1
            r.setdefault("start_iso", None)
            r.setdefault("end_iso", None)
            r.setdefault("notes", "")
            r.setdefault("method_inputs", {})
        blk["runs"] = runs
        if blk.get("active_run_index") is None or int(blk.get("active_run_index") or 0) >= len(runs):
            blk["active_run_index"] = 0

    # dynamic method input vars
    method_vars: Dict[str, tk.StringVar] = {}
    derived_vars: Dict[str, tk.StringVar] = {}
    m2_calc_vars: Dict[str, tk.StringVar] = {}
    method_entries: Dict[str, tk.Entry] = {}

    def _clear_method_frame():
        for w in method_frame.winfo_children():
            try:
                w.destroy()
            except Exception:
                pass
        method_vars.clear()
        derived_vars.clear()
        m2_calc_vars.clear()
        method_entries.clear()

    # Most recent computed Method 19 result (used by other live panels).
    last_m19_res: Dict[str, Any] = {}

    def _update_m19_crosswalk_display() -> None:
        """Update derived exhaust/fuel crosswalk display.

        Uses *current* UI entries (method_vars) + live O2 (if available.)
        """
        nonlocal sess
        if not derived_vars:
            return

        # Use optional live O2 (preferred if user did not override)
        o2_live = _parse_float(last_frame.get("O2")) if isinstance(last_frame, dict) else None

        # Refresh session + pollutant prescriptions from disk (keeps DAQ Runner aligned to MOLE Control)
        try:
            sess2 = _load_session_from_disk()
        except Exception:
            sess2 = sess
        pres = _pollutant_prescriptions(sess2)

        # Auto-fill common stack-measured inputs to minimize keystrokes
        co2_live = _parse_float(last_frame.get("CO2")) if isinstance(last_frame, dict) else None
        co_live = _parse_float(last_frame.get("CO")) if isinstance(last_frame, dict) else None
        try:
            # Barometric pressure default from Site Conditions (use as default override only if blank)
            if "baro_psia" in method_vars and str(method_vars["baro_psia"].get() or "").strip() == "":
                pbar = getattr(last_site_active, "P_bar_psia", None) if last_site_active else None
                if pbar is not None:
                    method_vars["baro_psia"].set(_fmt_num(pbar, 3))

            # O2 / CO2 / CO from live analyzers (only if the operator has not provided overrides)
            if o2_live is not None and str(method_vars["o2_dry_pct"].get() or "").strip() == "":
                method_vars["o2_dry_pct"].set(_fmt_num(o2_live, 3))
            if co2_live is not None and str(method_vars["co2_dry_pct"].get() or "").strip() == "":
                method_vars["co2_dry_pct"].set(_fmt_num(co2_live, 3))
            if co_live is not None and str(method_vars["co_dry_pct"].get() or "").strip() == "":
                u_co = str((pres.get("CO") or {}).get("units") or "").lower()
                if "ppb" in u_co:
                    co_pct = float(co_live) / 10000000.0
                elif "ppm" in u_co:
                    co_pct = float(co_live) / 10000.0
                else:
                    co_pct = (float(co_live) / 10000.0) if float(co_live) > 1.0 else float(co_live)
                method_vars["co_dry_pct"].set(_fmt_num(co_pct, 4))
        except Exception:
            pass

        # Auto-populate IMAP from live frame if HP mode is IMAP and the field is blank
        try:
            if isinstance(last_frame, dict):
                mode = (method_vars.get("hp_mode").get() if method_vars.get("hp_mode") else "")
                if str(mode).upper().strip() == "IMAP":
                    sv_imap = method_vars.get("imap_value")
                    if sv_imap is not None and (sv_imap.get() or "").strip() == "":
                        for _k in ("IMAP", "MAP", "Intake Manifold Air Pressure", "IntakeManifoldAirPressure"):
                            if _k in last_frame and last_frame.get(_k) not in (None, ""):
                                v = _parse_float(last_frame.get(_k), None)
                                if v is not None:
                                    sv_imap.set(_fmt_num(v, 2))
                                    break
        except Exception:
            pass

        ui_inputs: Dict[str, Any] = {}
        for k, sv in method_vars.items():
            try:
                ui_inputs[k] = sv.get()
            except Exception:
                ui_inputs[k] = ""

        try:
            res = _solve_m19_crosswalk(sess2, ui_inputs, o2_live, last_site_active)
            sess = sess2
        except Exception as e:
            res = {'mode': 'ERROR', 'note': 'Compute error: ' + type(e).__name__ + ': ' + str(e)}

        # Persist for other panels.
        try:
            nonlocal last_m19_res
            last_m19_res = res if isinstance(res, dict) else {}
        except Exception:
            pass

        def _set(key: str, val: str) -> None:
            try:
                if key in derived_vars:
                    derived_vars[key].set(val)
            except Exception:
                pass

        # Mode summary
        mode = str(res.get("mode") or "(n/a)")
        _set("mode", mode)

        # O2
        o2 = res.get("o2_used_pct")
        o2_src = str(res.get("o2_source") or "")
        if o2 is None:
            _set("o2_used", "(n/a)")
        else:
            _set("o2_used", f"{_fmt_num(o2, 3)}  ({o2_src})" if o2_src else _fmt_num(o2, 3))

        fac = res.get("o2_factor")
        _set("o2_factor", _fmt_num(fac, 6) if fac is not None else "(n/a)")

        fd = res.get("fd_dscf_per_mmbtu")
        _set("fd", _fmt_num(fd, 2) if fd is not None else "(n/a)")

        # Moisture + wet-to-dry bookkeeping (override wins, otherwise estimate)
        h2o_est = res.get("h2o_wet_frac_est")
        h2o_used = res.get("h2o_wet_frac_used")
        h2o_src = str(res.get("h2o_wet_source") or "")
        if h2o_used is None:
            h2o_used = h2o_est
        if h2o_used is None:
            _set("h2o_wet", "(n/a)")
            _set("h2o_wet_used", "(n/a)")
        else:
            h2o_line = _fmt_num(100.0 * float(h2o_used), 3)
            if h2o_src:
                h2o_line += f"  ({h2o_src})"
            _set("h2o_wet", h2o_line)  # legacy slot
            _set("h2o_wet_used", h2o_line)

        fac = res.get("wet_to_dry_factor_used")
        if fac is None:
            fac = res.get("dry_factor")
        _set("dry_factor", _fmt_num(fac, 6) if fac is not None else "(n/a)")
        _set("wet_to_dry_factor", _fmt_num(fac, 6) if fac is not None else "(n/a)")

        # Swirl α suggestion (deg) — not applied automatically
        alpha_sug = res.get("swirl_alpha_suggested_deg")
        if alpha_sug is None:
            _set("swirl_alpha_suggested", "(n/a)")
        else:
            _set("swirl_alpha_suggested", _fmt_num(alpha_sug, 1))

        # Qd-to-ACFM/velocity (computed when possible; locked read-back only when Qd is the operator entry)
        q_acfm_qd = res.get("stack_flow_acfm_from_qd_calc")
        v_fps_qd = res.get("stack_velocity_fps_from_qd_calc")
        # Backward-compat fallbacks
        if q_acfm_qd is None:
            q_acfm_qd = res.get("stack_flow_acfm_calc")
        if v_fps_qd is None:
            v_fps_qd = res.get("stack_velocity_fps_calc")

        _set("acfm_from_qd", _fmt_num(q_acfm_qd, 2) if q_acfm_qd is not None else "(n/a)")
        _set("vel_from_qd", _fmt_num(v_fps_qd, 3) if v_fps_qd is not None else "(n/a)")

        # If Qd was manually entered, treat ACFM/velocity as computed read-backs (locked).
        qd_entered = _parse_float(ui_inputs.get("qd_dscfh") or ui_inputs.get("Qd_dscfh"))
        if qd_entered is not None and qd_entered > 0:
            try:
                e_acfm = method_entries.get("stack_flow_acfm")
                e_vel = method_entries.get("stack_velocity_fps")
                for _e in (e_acfm, e_vel):
                    if _e is not None:
                        try:
                            _e.configure(
                                state="readonly",
                                bg=BG,
                                readonlybackground=BG,
                                fg=ACC,
                                insertbackground=ACC,
                                font=("Consolas", 9, "bold"),
                            )
                        except Exception:
                            pass

                # Populate the fields with the computed values (or n/a) without creating trace loops.
                if "stack_flow_acfm" in method_vars:
                    _s = _fmt_num(q_acfm_qd, 2) if q_acfm_qd is not None else "(n/a)"
                    if str(method_vars["stack_flow_acfm"].get() or "") != _s:
                        method_vars["stack_flow_acfm"].set(_s)
                if "stack_velocity_fps" in method_vars:
                    _s = _fmt_num(v_fps_qd, 3) if v_fps_qd is not None else "(n/a)"
                    if str(method_vars["stack_velocity_fps"].get() or "") != _s:
                        method_vars["stack_velocity_fps"].set(_s)
            except Exception:
                pass
        else:
            # Qd is blank -> allow manual entry of ACFM/velocity
            try:
                e_acfm = method_entries.get("stack_flow_acfm")
                e_vel = method_entries.get("stack_velocity_fps")
                for _e in (e_acfm, e_vel):
                    if _e is not None:
                        try:
                            _e.configure(
                                state="normal",
                                bg=PANEL_BG,
                                readonlybackground=PANEL_BG,
                                fg=FG,
                                insertbackground=FG,
                                font=("Consolas", 9),
                            )
                        except Exception:
                            pass
            except Exception:
                pass
        r = res.get("heat_input_mmbtu_hr")
        r_basis = str(res.get("heat_input_basis") or "")
        r_src = str(res.get("heat_input_source") or "")
        if r is None:
            _set("heat_input", "(n/a)")
        else:
            _set("heat_input", f"{_fmt_num(r, 6)}  ({r_src})" if r_src else _fmt_num(r, 6))
        _set("heat_input_basis", r_basis if r_basis else "(n/a)")

        qd_h = res.get("exh_flow_dscfh")
        qd_m = res.get("exh_flow_dscfm")
        qd_src = str(res.get("exh_flow_source") or "")
        if qd_h is None:
            _set("q_dscfh", "(n/a)")
        else:
            _set("q_dscfh", f"{_fmt_num(qd_h, 2)}  ({qd_src})" if qd_src else _fmt_num(qd_h, 2))
        _set("q_dscfm", _fmt_num(qd_m, 2) if qd_m is not None else "(n/a)")

        qf = res.get("fuel_flow_value")
        qf_units = str(res.get("fuel_flow_units") or "")
        qf_src = str(res.get("fuel_flow_source") or "")
        qf_scfh = res.get("fuel_flow_scfh")
        qf_scfm = res.get("fuel_flow_scfm")
        if qf_scfh is not None and qf_scfm is not None:
            # Choice B: scfh | scfm
            line = f"{_fmt_num(qf_scfh, 2)} scfh | {_fmt_num(qf_scfm, 2)} scfm"
            if qf_src:
                line += f" ({qf_src})"
            _set("fuel_flow", line)
        elif qf is None:
            _set("fuel_flow", "(n/a)")
        else:
            qf_num = _parse_float(qf)
            if qf_num is None:
                tail = f" ({qf_src})" if qf_src else ""
                _set("fuel_flow", f"{str(qf)}{tail}".strip())
            else:
                val = _fmt_num(qf_num, 6)
                tail = " ".join([u for u in [qf_units, f"({qf_src})" if qf_src else ""] if u])
                _set("fuel_flow", f"{val} {tail}".strip())

        # Horsepower (engine / bhp-hr conversions)
        hp_used = res.get("hp_used")
        hp_util = res.get("hp_util_pct")
        if hp_used is None:
            _set("hp_used", "(n/a)")
            try:
                hp_calc_var.set("--")
            except Exception:
                pass
        else:
            _set("hp_used", _fmt_num(hp_used, 1))
            try:
                hp_calc_var.set(_fmt_num(hp_used, 1))
            except Exception:
                pass

        if hp_util is None:
            _set("hp_util_pct", "(n/a)")
            try:
                hp_util_var.set("--")
            except Exception:
                pass
        else:
            _set("hp_util_pct", _fmt_num(hp_util, 1))
            try:
                hp_util_var.set(_fmt_num(hp_util, 1))
            except Exception:
                pass

        note = str(res.get("note") or "")
        _set("note", note)

        # Method 2 computed helpers (only present when STACK_MEASURED UI is active)
        try:
            def _set_m2(key: str, val: str) -> None:
                if key in m2_calc_vars:
                    m2_calc_vars[key].set(val)
            v_ax = res.get("stack_velocity_fps_calc")
            v_mag = res.get("stack_velocity_fps_calc_mag")
            q_acfm = res.get("stack_flow_acfm_calc")
            qd_calc = res.get("qd_dscfh_calc")
            if v_ax is None and v_mag is not None:
                v_ax = v_mag
            _set_m2("calc_stack_velocity_fps", _fmt_num(v_ax, 3) if v_ax is not None else "(n/a)")
            # show magnitude if available
            _set_m2("calc_stack_velocity_fps_mag", _fmt_num(v_mag, 3) if v_mag is not None else "")
            _set_m2("calc_stack_flow_acfm", _fmt_num(q_acfm, 2) if q_acfm is not None else "(n/a)")
            _set_m2("calc_qd_dscfh", _fmt_num(qd_calc, 2) if qd_calc is not None else "(n/a)")
        except Exception:
            pass


    def _build_method_inputs(sess: Dict[str, Any], run: Dict[str, Any]) -> None:
        _clear_method_frame()

        src = sess.get("source") or {}
        ex = src.get("exhaust_flow") or {}
        raw_method = str(ex.get("method") or "").strip()
        method = _effective_exhaust_flow_method(sess, raw_method)

        method_label = f"Exhaust Flow Method: {method or '(unset)'}"
        if str(method or "").strip().upper() != str(raw_method or "").strip().upper():
            method_label = f"Exhaust Flow Method: {method} (diagnostics override)"
        tk.Label(method_frame, text=method_label, fg=ACC, bg=BG, font=("Consolas", 9, "bold")).pack(anchor="w", pady=(0, 6))
        if str(method or "").strip().upper() != str(raw_method or "").strip().upper():
            tk.Label(
                method_frame,
                text="Diagnostics mode excludes EPA Method 2 / STACK_MEASURED inputs. Use Method 19 fuel or heat-input basis below.",
                fg=BAD,
                bg=BG,
                font=("Consolas", 9),
                justify="left",
                wraplength=980,
            ).pack(anchor="w", pady=(0, 8))
        # --- Horsepower / Load module (Engine sources) -------------------------------
        # NOTE: this UI builder is passed the current session dict as `sess`.
        # Use that object (not a global) to avoid NameError at startup.
        src_cfg = sess.get("source", {}) if isinstance(sess, dict) else {}
        src_cat = str(src_cfg.get("source_category") or "").strip().lower()
        ex_cfg = (src_cfg.get("exhaust_flow") or {}) if isinstance(src_cfg.get("exhaust_flow"), dict) else {}
        mf_cfg = (ex_cfg.get("manufacturer") or {}) if isinstance(ex_cfg.get("manufacturer"), dict) else {}

        rated_hp = _parse_float(
            src_cfg.get("site_rated_power")
            or src_cfg.get("max_power")
            or mf_cfg.get("rated_power_hp")
            or mf_cfg.get("rated_hp")
            or src_cfg.get("rated_power_hp"),
            None,
        )

        # Create vars (persisted per-run in run['method_inputs'])
        mi0 = (run.get("method_inputs") or {})
        hp_mode_default = (mi0.get("hp_mode") or "").strip()
        if not hp_mode_default:
            if _parse_float(mi0.get("actual_hp"), None) is not None:
                hp_mode_default = "DIRECT_HP"
            elif _parse_float(mi0.get("load_fraction"), None) is not None or _parse_float(mf_cfg.get("load_fraction"), None) is not None:
                hp_mode_default = "LOAD_FRACTION"
            else:
                hp_mode_default = "DIRECT_HP"

        method_vars["hp_mode"] = tk.StringVar(value=str(hp_mode_default).upper())
        lf0 = mi0.get("load_fraction")
        if lf0 in (None, ""):
            lf0 = mf_cfg.get("load_fraction")
        method_vars["load_fraction"] = tk.StringVar(value="" if lf0 in (None, "") else str(lf0))

        ah0 = mi0.get("actual_hp")
        method_vars["actual_hp"] = tk.StringVar(value="" if ah0 in (None, "") else str(ah0))

        im0 = mi0.get("imap_value")
        method_vars["imap_value"] = tk.StringVar(value="" if im0 in (None, "") else str(im0))

        iu0 = mi0.get("imap_units")
        if iu0 in (None, ""):
            iu0 = mf_cfg.get("imap_units") or "kPa"
        method_vars["imap_units"] = tk.StringVar(value=str(iu0))

        im_idle0 = mi0.get("imap_idle")
        if im_idle0 in (None, ""):
            im_idle0 = mf_cfg.get("imap_idle")
        method_vars["imap_idle"] = tk.StringVar(value="" if im_idle0 in (None, "") else str(im_idle0))

        im_full0 = mi0.get("imap_full")
        if im_full0 in (None, ""):
            im_full0 = mf_cfg.get("imap_full")
        method_vars["imap_full"] = tk.StringVar(value="" if im_full0 in (None, "") else str(im_full0))

        im_mid0 = mi0.get("imap_mid")
        if im_mid0 in (None, ""):
            im_mid0 = mf_cfg.get("imap_mid")
        method_vars["imap_mid"] = tk.StringVar(value="" if im_mid0 in (None, "") else str(im_mid0))

        im_mid_util0 = mi0.get("imap_mid_util")
        if im_mid_util0 in (None, ""):
            im_mid_util0 = mf_cfg.get("imap_mid_util")
        method_vars["imap_mid_util"] = tk.StringVar(value="" if im_mid_util0 in (None, "") else str(im_mid_util0))

        show_hp = (src_cat in ("engine", "turbine", "compressor", "generator")) or (rated_hp is not None)

        hp_calc_var = tk.StringVar(value="--")
        hp_util_var = tk.StringVar(value="--")

        if show_hp:
            hp_frame = tk.LabelFrame(method_frame, text="Horsepower / Load (Engine)", bg=BG, fg=FG, padx=6, pady=4)
            hp_frame.pack(fill="x", pady=(0, 8))
            _configure_runner_form_grid(hp_frame, minspec="runner_hp_load")

            # Rated HP (from Wizard)
            tk.Label(hp_frame, text="Rated HP (Wizard):", bg=BG, fg=FG).grid(row=0, column=0, sticky="w")
            tk.Label(hp_frame, text="--" if rated_hp is None else _fmt_num(rated_hp), bg=BG, fg=FG).grid(row=0, column=1, sticky="w", padx=(6, 0))

            # Mode
            tk.Label(hp_frame, text="HP Input Mode:", bg=BG, fg=FG).grid(row=1, column=0, sticky="w", pady=(4, 0))
            hp_mode_menu = ttk.Combobox(
                hp_frame,
                textvariable=method_vars["hp_mode"],
                values=["LOAD_FRACTION", "DIRECT_HP", "IMAP"],
                state="readonly",
                width=14,
            )
            hp_mode_menu.grid(row=1, column=1, sticky="w", padx=(6, 0), pady=(4, 0))

            # Load fraction
            tk.Label(hp_frame, text="Load Fraction (0-1):", bg=BG, fg=FG).grid(row=2, column=0, sticky="w", pady=(4, 0))
            ent_lf = tk.Entry(hp_frame, textvariable=method_vars["load_fraction"], width=12)
            ent_lf.grid(row=2, column=1, sticky="w", padx=(6, 0), pady=(4, 0))

            # Direct HP
            tk.Label(hp_frame, text="Actual HP (bhp):", bg=BG, fg=FG).grid(row=3, column=0, sticky="w", pady=(4, 0))
            ent_hp = tk.Entry(hp_frame, textvariable=method_vars["actual_hp"], width=12)
            ent_hp.grid(row=3, column=1, sticky="w", padx=(6, 0), pady=(4, 0))

            # IMAP
            tk.Label(hp_frame, text="IMAP:", bg=BG, fg=FG).grid(row=4, column=0, sticky="w", pady=(4, 0))
            imap_row = tk.Frame(hp_frame, bg=BG)
            imap_row.grid(row=4, column=1, sticky="w", padx=(6, 0), pady=(4, 0))
            ent_imap = tk.Entry(imap_row, textvariable=method_vars["imap_value"], width=10)
            ent_imap.pack(side="left")
            im_units = ttk.Combobox(
                imap_row,
                textvariable=method_vars["imap_units"],
                values=["kPa", "psig", "psia", "bar", "inH2O", "inHg"],
                state="readonly",
                width=7,
            )
            im_units.pack(side="left", padx=(6, 0))

            tk.Label(hp_frame, text="IMAP Idle (min):", bg=BG, fg=FG).grid(row=5, column=0, sticky="w", pady=(4, 0))
            ent_imap_idle = tk.Entry(hp_frame, textvariable=method_vars["imap_idle"], width=12)
            ent_imap_idle.grid(row=5, column=1, sticky="w", padx=(6, 0), pady=(4, 0))

            tk.Label(hp_frame, text="IMAP Full (max):", bg=BG, fg=FG).grid(row=6, column=0, sticky="w", pady=(4, 0))
            ent_imap_full = tk.Entry(hp_frame, textvariable=method_vars["imap_full"], width=12)
            ent_imap_full.grid(row=6, column=1, sticky="w", padx=(6, 0), pady=(4, 0))

            tk.Label(hp_frame, text="IMAP Mid (opt):", bg=BG, fg=FG).grid(row=7, column=0, sticky="w", pady=(4, 0))
            ent_imap_mid = tk.Entry(hp_frame, textvariable=method_vars["imap_mid"], width=12)
            ent_imap_mid.grid(row=7, column=1, sticky="w", padx=(6, 0), pady=(4, 0))

            tk.Label(hp_frame, text="Mid Util (0-1 or %):", bg=BG, fg=FG).grid(row=8, column=0, sticky="w", pady=(4, 0))
            ent_imap_mid_util = tk.Entry(hp_frame, textvariable=method_vars["imap_mid_util"], width=12)
            ent_imap_mid_util.grid(row=8, column=1, sticky="w", padx=(6, 0), pady=(4, 0))

            # Computed outputs (from crosswalk solver)
            tk.Label(hp_frame, text="Computed HP Used:", bg=BG, fg=FG).grid(row=0, column=2, sticky="w", padx=(18, 0))
            tk.Label(hp_frame, textvariable=hp_calc_var, bg=BG, fg=FG).grid(row=0, column=3, sticky="w", padx=(6, 0))
            tk.Label(hp_frame, text="Utilization (%):", bg=BG, fg=FG).grid(row=1, column=2, sticky="w", padx=(18, 0), pady=(4, 0))
            tk.Label(hp_frame, textvariable=hp_util_var, bg=BG, fg=FG).grid(row=1, column=3, sticky="w", padx=(6, 0), pady=(4, 0))

            def _sync_hp_inputs(*_a: Any) -> None:
                mode = (method_vars["hp_mode"].get() or "").upper().strip()
                lf_state = "normal" if mode == "LOAD_FRACTION" else "disabled"
                hp_state = "normal" if mode == "DIRECT_HP" else "disabled"
                im_state = "normal" if mode == "IMAP" else "disabled"
                ent_lf.configure(state=lf_state)
                ent_hp.configure(state=hp_state)
                try:
                    ent_imap.configure(state=im_state)
                    im_units.configure(state="readonly" if mode == "IMAP" else "disabled")
                    ent_imap_idle.configure(state=im_state)
                    ent_imap_full.configure(state=im_state)
                    ent_imap_mid.configure(state=im_state)
                    ent_imap_mid_util.configure(state=im_state)
                except Exception:
                    pass

            method_vars["hp_mode"].trace_add("write", _sync_hp_inputs)
            _sync_hp_inputs()

        grid = tk.Frame(method_frame, bg=BG)
        grid.pack(fill="x")
        _configure_runner_form_grid(grid, minspec="runner_single_pair_wide")

        def row(r: int, label: str, key: str, width: int = 20):
            sv = tk.StringVar(value="")
            method_vars[key] = sv
            tk.Label(grid, text=label, fg=FG, bg=BG, font=("Consolas", 9)).grid(row=r, column=0, sticky="w", padx=(0, 8), pady=2)
            e = tk.Entry(grid, textvariable=sv, bg=PANEL_BG, fg=FG, insertbackground=FG, relief="flat", width=width, font=("Consolas", 9))
            e.grid(row=r, column=1, sticky="w", pady=2)
            method_entries[key] = e
            return sv

        mi = run.get("method_inputs") or {}
        if not isinstance(mi, dict):
            mi = {}
            run["method_inputs"] = mi

        if method == "STOICH_FUEL":
            row(0, "Fuel flow (this run):", "fuel_flow_value", 18)
            row(1, with_colon(TEXT_FUEL_FLOW_UNITS), "fuel_flow_units", 18)
            row(2, with_colon(TEXT_O2_DRY_OPTIONAL), "o2_dry_pct", 18)

            # defaults from source schema
            sf = ex.get("stoich_fuel") or {}
            method_vars["fuel_flow_units"].set(str(mi.get("fuel_flow_units") or sf.get("fuel_flow_units") or "scfh"))
            if mi.get("fuel_flow_value") is not None:
                method_vars["fuel_flow_value"].set(str(mi.get("fuel_flow_value")))
            elif sf.get("fuel_flow_value") is not None:
                method_vars["fuel_flow_value"].set(str(sf.get("fuel_flow_value") or ""))
            method_vars["o2_dry_pct"].set(str(mi.get("o2_dry_pct") or sf.get("o2_dry_pct") or ""))

        elif method == "STACK_MEASURED":
            sm = ex.get("stack_measured") or {}

            # Left: EPA method (from config). Right: geometry summary (from Source Details).
            tk.Label(
                grid,
                text=f"EPA Method: {sm.get('epa_method','')}",
                fg=ACCENT,
                bg=BG,
                font=("Consolas", 9),
            ).grid(row=0, column=0, sticky="w", pady=2)

            geom = _stack_geom(sess)
            g_parts: List[str] = []
            if geom.get("shape", "").startswith("ROUND"):
                if geom.get("diameter_in") is not None:
                    g_parts.append(f"D={_fmt_num(geom.get('diameter_in'))} in")
            else:
                if geom.get("width_in") is not None and geom.get("height_in") is not None:
                    g_parts.append(f"W×H={_fmt_num(geom.get('width_in'))}×{_fmt_num(geom.get('height_in'))} in")

            if geom.get("De_in") is not None:
                g_parts.append(f"De={_fmt_num(geom.get('De_in'))} in")
            if geom.get("area_ft2") is not None:
                g_parts.append(f"A={_fmt_num(geom.get('area_ft2'))} ft²")

            # Method 1 traverse planner (informational)
            pts_line = geom.get("traverse_points_per_line")
            if pts_line is None:
                pts_line = _suggest_traverse_points_per_line(geom.get("De_in"), geom.get("upstream_D"), geom.get("downstream_D"))
            offs = _method1_offsets_from_wall_frac(pts_line)
            if pts_line and offs:
                g_parts.append("M1 pts/line=" + str(int(pts_line)) + " (wall frac: " + ", ".join(_fmt_num(x) for x in offs) + ")")
            if geom.get("upstream_D") is not None or geom.get("downstream_D") is not None:
                u = geom.get("upstream_D") if geom.get("upstream_D") is not None else 0.0
                d = geom.get("downstream_D") if geom.get("downstream_D") is not None else 0.0

                # EPA Method 1 site criteria (typical): >=8D upstream straight run, >=2D downstream straight run.
                UP_MIN_D = 8.0
                DN_MIN_D = 2.0
                ok = (u >= UP_MIN_D and d >= DN_MIN_D)

                plane_txt = (
                    f"Plane={'OK' if ok else 'NON-IDEAL'} "
                    f"(Up={u:g}D, Down={d:g}D; targets: Up≥{UP_MIN_D:g}D, Down≥{DN_MIN_D:g}D)"
                )
                De_in = geom.get("De_in")
                if De_in is not None and De_in > 0:
                    up_ft = (u * De_in) / 12.0
                    dn_ft = (d * De_in) / 12.0
                    up_req_ft = (UP_MIN_D * De_in) / 12.0
                    dn_req_ft = (DN_MIN_D * De_in) / 12.0
                    plane_txt += f" | straight-run: Up={_fmt_num(up_ft)} ft (≥{_fmt_num(up_req_ft)}), Down={_fmt_num(dn_ft)} ft (≥{_fmt_num(dn_req_ft)})"

                g_parts.append(plane_txt)
            if geom.get("De_in") is not None and geom.get("De_in") < 6.0:
                g_parts.append("SMALL STACK (<6in): consider M2C/standard pitot")

            geom_txt = " | ".join(g_parts) if g_parts else "Stack geometry not set (see Source Details)."
            lbl_geom = tk.Label(grid, text=geom_txt, fg=FG, bg=BG, font=("Consolas", 8), justify="left")
            lbl_geom.grid(row=0, column=1, sticky="we", pady=2)

            def _wrap_geom(_ev=None):
                try:
                    w = max(40, lbl_geom.winfo_width() - 12)
                    if w <= 40:
                        w = max(40, grid.winfo_width() - 180)
                    lbl_geom.configure(wraplength=w)
                except Exception:
                    pass
            grid.bind("<Configure>", _wrap_geom)
            _wrap_geom()

            tk.Label(grid, text="Direct entry (optional):", fg=FG, bg=BG, font=("Consolas", 9, "bold")).grid(
                row=1, column=0, columnspan=2, sticky="w", pady=(8, 2)
            )
            row(2, with_colon(TEXT_QD_DRY_DSCFH), "qd_dscfh", 18)
            row(3, "Stack flow (acfm):", "stack_flow_acfm", 18)
            row(4, "Stack velocity (ft/s):", "stack_velocity_fps", 18)

            tk.Label(grid, text="EPA M2 / pitot (avg traverse) inputs:", fg=FG, bg=BG, font=("Consolas", 9, "bold")).grid(
                row=5, column=0, columnspan=2, sticky="w", pady=(10, 2)
            )
            row(6, "Pitot ΔP (inH2O):", "pitot_dp_inh2o", 18)
            row(7, "Pitot Cp:", "pitot_cp", 18)
            row(8, "Stack temp (F):", "stack_temp_F", 18)
            row(9, "Stack static (inH2O):", "stack_static_inh2o", 18)
            row(10, "Baro override (psia):", "baro_psia", 18)
            row(11, "CO dry %:", "co_dry_pct", 18)
            row(12, "CO2 dry %:", "co2_dry_pct", 18)
            row(13, "O2 dry %:", "o2_dry_pct", 18)
            row(14, "H2O wet %:", "h2o_wet_pct", 18)
            row(15, "Avg swirl α (deg):", "swirl_alpha_deg", 18)

            # --- Computed (EPA Method 2 helpers) ---
            try:
                tk.Label(grid, text="Computed (EPA Method 2):", fg=ACCENT, bg=BG, font=("Consolas", 9, "bold")).grid(
                    row=16, column=0, columnspan=2, sticky="w", pady=(10, 2)
                )

                # read-only computed vars (updated by _update_m19_crosswalk_display)
                m2_calc_vars.clear()
                m2_calc_vars["calc_stack_velocity_fps"] = tk.StringVar(value="(n/a)")
                m2_calc_vars["calc_stack_velocity_fps_mag"] = tk.StringVar(value="")
                m2_calc_vars["calc_stack_flow_acfm"] = tk.StringVar(value="(n/a)")
                m2_calc_vars["calc_qd_dscfh"] = tk.StringVar(value="(n/a)")

                def _m2_row(r: int, label: str, key: str, w: int = 20):
                    tk.Label(grid, text=label, fg=FG, bg=BG, font=("Consolas", 9)).grid(row=r, column=0, sticky="w", padx=(0, 8), pady=2)
                    _ro_entry(grid, m2_calc_vars[key], width=w).grid(row=r, column=1, sticky="w", pady=2)

                _m2_row(17, "Velocity (ft/s) calc:", "calc_stack_velocity_fps", 22)
                _m2_row(18, "Stack flow (acfm) calc:", "calc_stack_flow_acfm", 22)
                _m2_row(19, f"{TEXT_QD_DRY_DSCFH} calc:", "calc_qd_dscfh", 22)

                def _use_calc_to_direct() -> None:
                    # Copy calculated Qd only into Direct Entry (leave ACFM/velocity to be derived from Qd)
                    def _clean_num(s: str) -> str:
                        s = (s or "").strip()
                        if not s or s.lower().startswith("(n/a"):
                            return ""
                        return s.replace(",", "")

                    try:
                        if "qd_dscfh" in method_vars:
                            method_vars["qd_dscfh"].set(_clean_num(m2_calc_vars["calc_qd_dscfh"].get()))
                        # Clear optional direct-entry fields so Qd is the single source of truth
                        if "stack_flow_acfm" in method_vars:
                            method_vars["stack_flow_acfm"].set("")
                        if "stack_velocity_fps" in method_vars:
                            method_vars["stack_velocity_fps"].set("")
                    except Exception:
                        pass

                tk.Button(
                    grid,
                    text="Use calculated → Direct Entry",
                    command=_use_calc_to_direct,
                    bg=BTN_BG,
                    fg=FG,
                    relief="flat",
                    activebackground=BTN_BG_HOVER,
                    activeforeground=FG,
                    font=("Consolas", 9, "bold"),
                ).grid(row=20, column=0, columnspan=2, sticky="w", pady=(6, 2))
            except Exception:
                pass


            # Populate from existing run inputs where available; otherwise default Cp from Source Details.
            method_vars["qd_dscfh"].set(str(mi.get("qd_dscfh") or mi.get("Qd_dscfh") or ""))
            method_vars["stack_flow_acfm"].set(str(mi.get("stack_flow_acfm") or ""))
            method_vars["stack_temp_F"].set(str(mi.get("stack_temp_F") or ""))
            method_vars["stack_velocity_fps"].set(str(mi.get("stack_velocity_fps") or ""))

            method_vars["pitot_dp_inh2o"].set(str(mi.get("pitot_dp_inh2o") or mi.get("pitot_dp_inH2O") or ""))
            method_vars["pitot_cp"].set(str(mi.get("pitot_cp") or geom.get("pitot_cp") or "0.84"))
            method_vars["stack_static_inh2o"].set(str(mi.get("stack_static_inh2o") or mi.get("stack_static_inH2O") or ""))
            method_vars["baro_psia"].set(str(mi.get("baro_psia") or mi.get("p_bar_psia") or ""))
            method_vars["co_dry_pct"].set(str(mi.get("co_dry_pct") or ""))
            method_vars["co2_dry_pct"].set(str(mi.get("co2_dry_pct") or ""))
            method_vars["o2_dry_pct"].set(str(mi.get("o2_dry_pct") or ""))
            method_vars["h2o_wet_pct"].set(str(mi.get("h2o_wet_pct") or mi.get("h2o_wet_percent") or ""))
            method_vars["swirl_alpha_deg"].set(str(mi.get("swirl_alpha_deg") or mi.get("alpha_avg_deg") or ""))

        else:
            tk.Label(method_frame, text="(No exhaust flow method selected in Source Details.)", fg=BAD, bg=BG, font=("Consolas", 9)).pack(anchor="w")

        # ---- Derived crosswalk outputs (always visible) ----
        try:
            sep = tk.Frame(method_frame, bg=PANEL_BG, height=1)
            sep.pack(fill="x", pady=(10, 8))
        except Exception:
            pass

        tk.Label(method_frame, text="Derived (Method 19 crosswalk)", fg=ACC, bg=BG, font=("Consolas", 10, "bold")).pack(anchor="w")
        out = tk.Frame(method_frame, bg=BG)
        out.pack(fill="x", pady=(4, 0))
        _configure_runner_form_grid(out, minspec="runner_single_pair")

        # Reset derived vars for this rebuild
        derived_vars.clear()

        derived_vars["mode"] = tk.StringVar(value="(n/a)")
        derived_vars["o2_used"] = tk.StringVar(value="(n/a)")
        derived_vars["o2_factor"] = tk.StringVar(value="(n/a)")
        derived_vars["fd"] = tk.StringVar(value="(n/a)")
        derived_vars["heat_input"] = tk.StringVar(value="(n/a)")
        derived_vars["heat_input_basis"] = tk.StringVar(value="(n/a)")
