    # Test matrix toggles (persist)
    # -------------------------------

    def _get_selected_tm_index() -> Optional[int]:
        try:
            sel = tm_tree.selection()
            if not sel:
                return None
            iid = sel[0]
            if iid.startswith("TM_"):
                return int(iid.split("_", 1)[1])
        except Exception:
            return None
        return None

    def toggle_tm_performed() -> None:
        nonlocal sess
        try:
            idx = _get_selected_tm_index()
            if idx is None:
                return
            sess = _load_session()
            tm = sess.get("test_matrix") or {}
            tests = tm.get("tests") or []
            if idx < 0 or idx >= len(tests):
                return
            t = tests[idx]
            if not isinstance(t, dict):
                return
            t["performed"] = (not bool(t.get("performed")))
            if bool(t.get("performed")):
                t["waived"] = False
                t["waive_reason"] = None
            _save_session(sess)
            _populate_test_matrix(sess)
            log(f"Test {t.get('id')} performed={t.get('performed')}")
        except Exception as e:
            messagebox.showerror("Test Matrix", str(e))

    def toggle_tm_waived() -> None:
        nonlocal sess
        try:
            idx = _get_selected_tm_index()
            if idx is None:
                return
            sess = _load_session()
            tm = sess.get("test_matrix") or {}
            tests = tm.get("tests") or []
            if idx < 0 or idx >= len(tests):
                return
            t = tests[idx]
            if not isinstance(t, dict):
                return
            new_val = (not bool(t.get("waived")))
            t["waived"] = new_val
            if new_val:
                t["performed"] = False
                t["waive_reason"] = (var_waive_reason.get() or "").strip() or None
            else:
                t["waive_reason"] = None
            _save_session(sess)
            _populate_test_matrix(sess)
            log(f"Test {t.get('id')} waived={t.get('waived')}")
        except Exception as e:
            messagebox.showerror("Test Matrix", str(e))

    btn_tm_toggle_perf.configure(command=toggle_tm_performed)
    btn_tm_toggle_waive.configure(command=toggle_tm_waived)

