    def _win_creationflags() -> int:
        try:
            if os.name == "nt":
                return int(getattr(subprocess, "CREATE_NEW_CONSOLE", 0) | getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0))
        except Exception:
            pass
        return 0

    def launch_qaqc_console() -> None:
        if diagnostics_ui:
            messagebox.showinfo(
                "QA/QC Console",
                "Formal QA/QC console actions are disabled in Diagnostics Runner.",
            )
            return
        try:
            cmd = _entrypoint_for_subprocess() + ["--config", str(cfg_path)]
            subprocess.Popen(cmd, creationflags=_win_creationflags())
            log("Spawned QA/QC console process.")
        except Exception as e:
            messagebox.showerror("QA/QC Launch Failed", str(e))

    btn_tm_launch_console.configure(command=launch_qaqc_console)
    try:
        if diagnostics_ui:
            btn_tm_launch_console.configure(text="QA/QC Console Disabled", state="disabled")
    except Exception:
        pass

