    def _set_ftir_validation_set_review(selected_set: Dict[str, Any], decision: str) -> None:
        nonlocal sess
        sess = _report_builder_save_to_session(show_message=False)
        _ensure_daq_schema(sess)
        blk = _ftir_validation_block(sess)
        if _ftir_validation_is_locked(blk):
            raise ValueError("FTIR validation review is locked. Unlock review before changing comparison-set decisions.")
        set_reviews = dict(blk.get("set_reviews") or {}) if isinstance(blk.get("set_reviews"), dict) else {}
        set_key = str(selected_set.get("set_key") or "").strip()
        if not set_key:
            raise ValueError("Selected comparison set does not have a stable set key.")
        decision_norm = str(decision or "").strip().upper()
        if decision_norm == "REJECTED":
            reason = str(var_ftir_validation_set_review_reason.get() or "").strip()
            if not reason:
                raise ValueError("A rejection reason is required for a rejected comparison set.")
            set_reviews[set_key] = {
                "decision": "REJECTED",
                "reason": reason,
                "reviewer": _report_builder_actor(sess),
                "updated_iso": now_iso(),
            }
        elif decision_norm == "ACCEPTED":
            set_reviews[set_key] = {
                "decision": "ACCEPTED",
                "reason": str(var_ftir_validation_set_review_reason.get() or "").strip(),
                "reviewer": _report_builder_actor(sess),
                "updated_iso": now_iso(),
            }
        else:
            set_reviews.pop(set_key, None)
        blk["set_reviews"] = set_reviews
        blk["review_notes"] = _report_builder_text_get(txt_ftir_validation_review_notes)
        blk["reviewer"] = _report_builder_actor(sess)
        sess["ftir_validation"] = blk
        _save_session(sess)
        _refresh_ftir_validation_preview(sess)
        _refresh_report_builder_status(sess)

    def _accept_selected_ftir_validation_set() -> None:
        row = _selected_ftir_validation_set_row()
        if not isinstance(row, dict):
            messagebox.showinfo("FTIR Validation Review", "Select a comparison set first.")
            return
        try:
            _set_ftir_validation_set_review(row, "ACCEPTED")
        except Exception as e:
            messagebox.showerror("FTIR Validation Review", str(e))

    def _reject_selected_ftir_validation_set() -> None:
        row = _selected_ftir_validation_set_row()
        if not isinstance(row, dict):
            messagebox.showinfo("FTIR Validation Review", "Select a comparison set first.")
            return
        try:
            _set_ftir_validation_set_review(row, "REJECTED")
        except Exception as e:
            messagebox.showerror("FTIR Validation Review", str(e))

    def _clear_all_ftir_validation_set_reviews() -> None:
        nonlocal sess
        if not messagebox.askyesno("FTIR Validation Review", "Clear all FTIR validation comparison-set review decisions for this session?"):
            return
        try:
            sess = _report_builder_save_to_session(show_message=False)
            _ensure_daq_schema(sess)
            blk = _ftir_validation_block(sess)
            if _ftir_validation_is_locked(blk):
                raise ValueError("FTIR validation review is locked. Unlock review before clearing comparison-set decisions.")
            blk["set_reviews"] = {}
            blk["review_notes"] = _report_builder_text_get(txt_ftir_validation_review_notes)
            blk["reviewer"] = _report_builder_actor(sess)
            sess["ftir_validation"] = blk
            _save_session(sess)
            _refresh_ftir_validation_preview(sess)
            _refresh_report_builder_status(sess)
        except Exception as e:
            messagebox.showerror("FTIR Validation Review", str(e))

    def _refresh_ftir_validation_preview(sess_local: Optional[Dict[str, Any]] = None) -> None:
        ftir_validation_preview_rows.clear()
        ftir_validation_sweep_rows.clear()
        ftir_validation_set_rows.clear()
        _report_builder_tree_clear(ftir_stats_tree)
        _report_builder_tree_clear(ftir_alignment_tree)
        _report_builder_tree_clear(ftir_sets_tree)
        _report_builder_tree_clear(ftir_windows_tree)
        try:
            sess_use = dict(sess_local) if isinstance(sess_local, dict) else _report_builder_save_to_session(show_message=False)
            _ensure_daq_schema(sess_use)
            cfg = _ftir_validation_block(sess_use)
            if not bool(cfg.get("enabled")):
                var_ftir_validation_review_status.set("FTIR validation preview disabled for this session.")
                return
            preview = {}
            source_label = "LIVE_COMPUTE"
            if _ftir_validation_is_locked(cfg):
                preview = _load_ftir_validation_locked_snapshot(cfg)
                if preview:
                    source_label = "LOCKED_REVIEW_SNAPSHOT"
            if not isinstance(preview, dict) or not preview:
                preview = _build_ftir_validation_preview_payload(sess_use)
            if not isinstance(preview, dict):
                preview = {}
            ftir_src = preview.get("ftir_source") if isinstance(preview.get("ftir_source"), dict) else {}
            mole_src = preview.get("mole_source") if isinstance(preview.get("mole_source"), dict) else {}
            qa = preview.get("qa") if isinstance(preview.get("qa"), dict) else {}
            execution = preview.get("execution") if isinstance(preview.get("execution"), dict) else {}
            alignment_review = preview.get("alignment_review") if isinstance(preview.get("alignment_review"), dict) else {}
            import_preview = qa.get("import_preview") if isinstance(qa.get("import_preview"), dict) else {}
            aligned_rows = list(preview.get("aligned_rows") or [])
            comparison_sets = [row for row in list(preview.get("comparison_sets") or []) if isinstance(row, dict)]
            unpaired_rows = [row for row in aligned_rows if not bool(row.get("paired"))]
            snap = preview.get("review_snapshot") if isinstance(preview.get("review_snapshot"), dict) else {}
            sign = preview.get("signoff") if isinstance(preview.get("signoff"), dict) else {}
            qa_counts = qa.get("row_status_counts") if isinstance(qa.get("row_status_counts"), dict) else {}
            auto_map = import_preview.get("autodetected_columns_used") if isinstance(import_preview.get("autodetected_columns_used"), dict) else {}
            vendor_note = str(import_preview.get("vendor_profile_note") or "").strip()
            blocking_issues = [str(v) for v in list(qa.get("blocking_issues") or []) if str(v or "").strip()]
            qa_warnings = [str(v) for v in list(qa.get("warnings") or []) if str(v or "").strip()]
            acceptance_basis = str(preview.get("acceptance_basis") or "").strip() or "(n/a)"
            acceptance_note = str(preview.get("acceptance_basis_note") or "").strip()
            recommended_offset = alignment_review.get("recommended_offset") if isinstance(alignment_review.get("recommended_offset"), dict) else {}
            before_summary = alignment_review.get("before_summary") if isinstance(alignment_review.get("before_summary"), dict) else {}
            after_summary = alignment_review.get("after_summary") if isinstance(alignment_review.get("after_summary"), dict) else {}
            set_review_counts = {"ACCEPTED": 0, "REJECTED": 0}
            for block in comparison_sets:
                decision = str(block.get("review_decision") or "").strip().upper()
                if decision in set_review_counts:
                    set_review_counts[decision] += 1
            status_lines = [
                " | ".join([
                    f"Source: {source_label}",
                    f"Status: {preview.get('status') or '(n/a)'}",
                    f"Overall: {preview.get('overall_status') or '(n/a)'}",
                    f"Acceptance basis: {acceptance_basis}",
                    f"Vendor: {str((ftir_src.get('vendor_profile_used') if isinstance(ftir_src, dict) else '') or '(n/a)')}",
                    f"Mode: {cfg.get('validation_mode') or '(n/a)'}",
                    f"Paired windows: {int(preview.get('paired_window_count') or 0)}",
                    f"Aligned rows: {len(aligned_rows)}",
                    f"Excluded rows: {int(preview.get('excluded_count') or 0)}",
                    f"Signoff: {str(sign.get('decision') or 'UNSIGNED').strip().upper() or 'UNSIGNED'}",
                    f"Unpaired candidates: {len(unpaired_rows)}",
                    f"FTIR records: {int((ftir_src.get('record_count') or 0) if isinstance(ftir_src, dict) else 0)}",
                    f"MOLE rows: {int((mole_src.get('record_count') or 0) if isinstance(mole_src, dict) else 0)}",
                    (f"Snapshot: {str(snap.get('snapshot_iso') or '').strip()}" if str(snap.get("snapshot_iso") or "").strip() else ""),
                ]).strip(" |"),
            ]
            if qa:
                status_lines.append(
                    " | ".join([
                        f"Lock ready: {'YES' if bool(qa.get('lock_ready')) else 'NO'}",
                        f"Signoff ready: {'YES' if bool(qa.get('signoff_ready')) else 'NO'}",
                        f"QA pass/warn/error: {int(qa_counts.get('PASS') or 0)}/{int(qa_counts.get('WARN') or 0)}/{int(qa_counts.get('ERROR') or 0)}",
                        f"Timestamp: {str(import_preview.get('timestamp_column') or '(n/a)')}",
                    ])
                )
                if auto_map:
                    status_lines.append(
                        "Auto-map preview: "
                        + ", ".join([f"{code}->{col}" for code, col in sorted(auto_map.items())])
                    )
                if vendor_note:
                    status_lines.append("Vendor profile note: " + vendor_note)
                if blocking_issues:
                    status_lines.append("Blocking issues: " + " ; ".join(blocking_issues))
                if qa_warnings:
                    status_lines.append("Warnings: " + " ; ".join(qa_warnings))
            if execution:
                status_lines.append(
                    "Execution: "
                    + " | ".join([
                        f"profile={execution.get('profile') or '(n/a)'}",
                        f"sets completed={execution.get('completed_run_count') or 0}",
                        f"next set={execution.get('next_comparison_set_no') or '(n/a)'}",
                        f"live status={execution.get('live_review_status') or '(n/a)'}",
                        f"frozen sets={execution.get('frozen_comparison_set_count') or 0}",
                    ])
                )
                if str(execution.get("note") or "").strip():
                    status_lines.append("Execution note: " + str(execution.get("note") or "").strip())
            if alignment_review:
                status_lines.append(
                    "Alignment review: "
                    + " | ".join([
                        f"current offset={_fmt_num(alignment_review.get('current_offset_seconds'), 2, '')} s",
                        f"before paired={int(before_summary.get('paired_row_count') or 0)}",
                        f"after paired={int(after_summary.get('paired_row_count') or 0)}",
                        (
                            f"recommended offset={_fmt_num(recommended_offset.get('offset_seconds'), 2, '')} s"
                            if recommended_offset
                            else "recommended offset=(n/a)"
                        ),
                    ])
                )
            if comparison_sets:
                status_lines.append(
                    "Comparison-set review: "
                    + " | ".join([
                        f"sets={len(comparison_sets)}",
                        f"accepted={set_review_counts['ACCEPTED']}",
                        f"rejected={set_review_counts['REJECTED']}",
                    ])
                )
            if acceptance_note:
                status_lines.append("Acceptance basis note: " + acceptance_note)
            if str(snap.get("delta_trace_json_path") or "").strip():
                status_lines.append("Frozen delta trace: " + str(snap.get("delta_trace_json_path") or "").strip())
            if str(preview.get("coverage_note") or "").strip():
                status_lines.append(str(preview.get("coverage_note") or "").strip())
            var_ftir_validation_review_status.set("\n".join([line for line in status_lines if line]))
            for row in list(preview.get("method301") or []):
                if not isinstance(row, dict):
                    continue
                ftir_stats_tree.insert(
                    "",
                    "end",
                    values=(
                        str(row.get("analyte") or ""),
                        int(row.get("paired_window_count") or 0),
                        _fmt_num(row.get("relative_bias_pct"), 3, ""),
                        _fmt_num(row.get("correction_factor"), 4, ""),
                        _fmt_num(row.get("t_statistic"), 3, ""),
                        _fmt_num(row.get("f_statistic"), 3, ""),
                        str(row.get("bias_status") or ""),
                        str(row.get("precision_status") or ""),
                        str(row.get("overall_status") or ""),
                    ),
                )
            sweep_rows = [row for row in list(alignment_review.get("sweep_rows") or []) if isinstance(row, dict)]
            recommended_offset_value = None
            try:
                recommended_offset_value = float(recommended_offset.get("offset_seconds")) if recommended_offset else None
            except Exception:
                recommended_offset_value = None
            for row in sweep_rows:
                offset_value = _parse_float(row.get("offset_seconds"), default=None)
                iid = ftir_alignment_tree.insert(
                    "",
                    "end",
                    values=(
                        _fmt_num(offset_value, 3, ""),
                        int(row.get("paired_row_count") or 0),
                        int(row.get("comparison_set_count") or 0),
                        _fmt_num(row.get("avg_abs_offset_seconds"), 3, ""),
                        _fmt_num(row.get("avg_abs_drift_seconds"), 3, ""),
                        "YES" if (recommended_offset_value is not None and offset_value is not None and abs(recommended_offset_value - offset_value) < 1e-6) else "",
                    ),
                )
                ftir_validation_sweep_rows[str(iid)] = dict(row)
            if not sweep_rows:
                ftir_alignment_tree.insert("", "end", values=("", 0, 0, "", "", "NO SWEEP DATA"))
            before_after_by_set = {
                str(row.get("set_key") or "").strip(): row
                for row in list(alignment_review.get("before_after_by_set") or [])
                if isinstance(row, dict) and str(row.get("set_key") or "").strip()
            }
            for block in comparison_sets:
                set_key = str(block.get("set_key") or "").strip()
                review_row = before_after_by_set.get(set_key, {})
                iid = ftir_sets_tree.insert(
                    "",
                    "end",
                    values=(
                        str(block.get("set_no") or ""),
                        str(block.get("label") or ""),
                        str(block.get("inclusion_status") or ""),
                        str(block.get("formal_basis") or ""),
                        str(block.get("review_decision") or ""),
                        str(block.get("review_reason") or ""),
                        int(review_row.get("before_paired_row_count") or 0),
                        int(review_row.get("after_paired_row_count") or 0),
                        _fmt_num(review_row.get("before_avg_abs_offset_seconds"), 3, ""),
                        _fmt_num(review_row.get("after_avg_abs_offset_seconds"), 3, ""),
                    ),
                )
                ftir_validation_set_rows[str(iid)] = dict(block)
            if not comparison_sets:
                ftir_sets_tree.insert("", "end", values=("", "NO COMPARISON SETS", "", "", "", "", 0, 0, "", ""))
            for row in aligned_rows:
                if not isinstance(row, dict):
                    continue
                set_review_decision = str(row.get("set_review_decision") or "").strip().upper()
                review_label = (
                    "SET_REJECTED"
                    if set_review_decision == "REJECTED"
                    else ("SET_ACCEPTED" if set_review_decision == "ACCEPTED" else ("EXCLUDED" if bool(row.get("excluded")) else "INCLUDED"))
                )
                review_reason = str(row.get("set_review_reason") or row.get("exclusion_reason") or "").strip()
                iid = ftir_windows_tree.insert(
                    "",
                    "end",
                    values=(
                        str(row.get("run_no") or ""),
                        str(row.get("label") or ""),
                        str(row.get("analyte") or ""),
                        str(row.get("status") or ""),
                        str(row.get("qa_status") or ""),
                        review_label,
                        review_reason,
                        _fmt_num(row.get("offset_seconds_adjusted"), 2, ""),
                        _fmt_num(row.get("drift_seconds_adjusted"), 2, ""),
                        (
                            f"{_fmt_num(row.get('mole_coverage_ratio'), 2, '')}/{_fmt_num(row.get('ftir_coverage_ratio'), 2, '')}"
                            if row.get("mole_coverage_ratio") is not None or row.get("ftir_coverage_ratio") is not None
                            else ""
                        ),
                        int(row.get("mole_count") or 0),
                        int(row.get("ftir_count") or 0),
                        _fmt_num(row.get("mole_avg"), 4, ""),
                        _fmt_num(row.get("ftir_avg"), 4, ""),
                        _fmt_num(row.get("difference"), 4, ""),
                    ),
                )
                ftir_validation_preview_rows[str(iid)] = dict(row)
            if not aligned_rows:
                ftir_windows_tree.insert("", "end", values=("", "", "", "NO ALIGNED WINDOWS", "", "", "", "", "", "", 0, 0, "", "", ""))
            if not list(preview.get("method301") or []):
                ftir_stats_tree.insert("", "end", values=("", 0, "", "", "", "", "", "", "NO STATS"))
        except Exception as e:
            var_ftir_validation_review_status.set(f"FTIR validation preview failed: {e}")
            _report_builder_tree_clear(ftir_stats_tree)
            _report_builder_tree_clear(ftir_windows_tree)

    def _report_builder_actor(sess_local: Dict[str, Any]) -> str:
        try:
            actor = str(((sess_local.get("project") or {}).get("operator")) or "").strip()
            if actor:
                return actor
        except Exception:
            pass
        for env_key in ("USERNAME", "USER"):
            try:
                actor = str(os.environ.get(env_key) or "").strip()
                if actor:
                    return actor
            except Exception:
                pass
        return "operator"

    def _report_builder_load_form(sess_local: Optional[Dict[str, Any]] = None) -> None:
        try:
            sess_use = dict(sess_local) if isinstance(sess_local, dict) else _load_session()
            blk = _report_builder_block(sess_use)
            parties = blk.get("parties") if isinstance(blk.get("parties"), dict) else {}
            process_control = blk.get("process_control") if isinstance(blk.get("process_control"), dict) else {}
            deviations = blk.get("deviations_approvals") if isinstance(blk.get("deviations_approvals"), dict) else {}
            correspondence = blk.get("correspondence") if isinstance(blk.get("correspondence"), dict) else {}
            ftir_validation = _ftir_validation_block(sess_use)
            project = sess_use.get("project") if isinstance(sess_use.get("project"), dict) else {}
            source = sess_use.get("source") if isinstance(sess_use.get("source"), dict) else {}

            var_report_client_name.set(str(parties.get("client_name") or ""))
            var_report_facility_owner.set(str(parties.get("facility_owner_operator_name") or project.get("site_facility") or ""))
            var_report_test_company.set(str(parties.get("test_company_name") or project.get("operator") or ""))
            var_report_laboratory.set(str(parties.get("laboratory_name") or ""))
            var_report_session_operator.set(str(parties.get("session_operator_name") or project.get("operator") or ""))
            var_report_responsible_official.set(str(parties.get("responsible_official_name") or ""))
            var_report_responsible_title.set(str(parties.get("responsible_official_title") or ""))
            var_report_agency_contact.set(str(correspondence.get("agency_contact") or ""))
            var_report_notice_of_intent.set(str(correspondence.get("notice_of_intent_date") or ""))
            var_report_submission_status.set(str(correspondence.get("submission_status") or ""))
            var_report_observer_contacts.set("; ".join([str(item) for item in _report_builder_split_list(parties.get("observer_contacts"))]))
            var_report_approval_dates.set("; ".join([str(item) for item in _report_builder_split_list(correspondence.get("approval_dates"))]))

            _report_builder_text_set(
                txt_report_process_narrative,
                process_control.get("process_narrative")
                or process_control.get("process_narrative_seed")
                or " ".join(
                    [
                        part
                        for part in [
                            str(source.get("service_class") or "").strip(),
                            str(source.get("source_category") or "").strip(),
                            str(source.get("application") or source.get("source_application") or "").strip(),
                        ]
                        if part
                    ]
                ).strip(),
            )
            _report_builder_text_set(txt_report_control_equipment, process_control.get("control_equipment_description"))
            _report_builder_text_set(txt_report_planned_deviations, "\n".join(_report_builder_split_list(deviations.get("planned_deviations"))))
            _report_builder_text_set(txt_report_field_deviations, "\n".join(_report_builder_split_list(deviations.get("field_deviations"))))
            _report_builder_text_set(txt_report_alt_approvals, "\n".join(_report_builder_split_list(deviations.get("alternative_method_approvals"))))
            _report_builder_text_set(txt_report_impact_statement, deviations.get("impact_statement"))
            _report_builder_text_set(txt_report_correspondence_notes, correspondence.get("notes"))
            var_ftir_validation_enabled.set(bool(ftir_validation.get("enabled")))
            var_ftir_validation_mode.set(str(ftir_validation.get("validation_mode") or "METHOD_301_INFORMED_COMPARISON"))
            var_ftir_validation_vendor.set(str(ftir_validation.get("ftir_vendor_profile") or "AUTO"))
            var_ftir_validation_file.set(str(ftir_validation.get("ftir_file_path") or ""))
            var_ftir_validation_timestamp_col.set(str(ftir_validation.get("ftir_timestamp_column") or ""))
            var_ftir_validation_delimiter.set(str(ftir_validation.get("ftir_delimiter") or "AUTO"))
            var_ftir_validation_offset_s.set(_fmt_num(ftir_validation.get("time_offset_seconds"), 3, "0"))
            var_ftir_validation_analytes.set("; ".join([str(item) for item in list(ftir_validation.get("analytes") or []) if str(item or "").strip()]))
            var_ftir_validation_master_clock.set(str(ftir_validation.get("timestamp_master_clock") or "SESSION_MASTER_CLOCK"))
            execution = ftir_validation.get("execution") if isinstance(ftir_validation.get("execution"), dict) else {}
            alignment_review = ftir_validation.get("alignment_review") if isinstance(ftir_validation.get("alignment_review"), dict) else {}
            var_ftir_validation_execution_enabled.set(bool(execution.get("enabled")))
            var_ftir_validation_execution_profile.set(str(execution.get("profile") or "SESSION_RUNS"))
            var_ftir_validation_purge_min.set(_fmt_num(execution.get("purge_minutes_required"), 2, "5"))
            var_ftir_validation_require_purge.set(bool(execution.get("require_purge_event", True)))
            var_ftir_validation_require_bias.set(bool(execution.get("require_bias_event", True)))
            var_ftir_validation_sweep_min_s.set(_fmt_num(alignment_review.get("sweep_min_seconds"), 2, "-120"))
            var_ftir_validation_sweep_max_s.set(_fmt_num(alignment_review.get("sweep_max_seconds"), 2, "120"))
            var_ftir_validation_sweep_step_s.set(_fmt_num(alignment_review.get("sweep_step_seconds"), 2, "15"))
            _report_builder_text_set(
                txt_ftir_validation_column_map,
                "\n".join([f"{k}={v}" for k, v in sorted((ftir_validation.get("column_map") or {}).items())]),
            )
            _report_builder_text_set(
                txt_ftir_validation_manual_windows,
                "\n".join([
                    ",".join([
                        str(item.get("run_no") or ""),
                        str(item.get("start_ts_iso") or ""),
                        str(item.get("end_ts_iso") or ""),
                        str(item.get("label") or ""),
                    ]).rstrip(",")
                    for item in list(ftir_validation.get("manual_windows") or [])
                    if isinstance(item, dict)
                ]),
            )
            _report_builder_text_set(txt_ftir_validation_notes, ftir_validation.get("notes"))
            _report_builder_text_set(txt_ftir_validation_review_notes, ftir_validation.get("review_notes"))
            signoff = ftir_validation.get("signoff") if isinstance(ftir_validation.get("signoff"), dict) else {}
            var_ftir_validation_signoff_by.set(str(signoff.get("by") or ""))
            var_ftir_validation_signoff_role.set(str(signoff.get("role") or ""))
            var_ftir_validation_signoff_decision.set(str(signoff.get("decision") or "UNSIGNED"))
            var_ftir_validation_signoff_basis.set(str(signoff.get("basis") or ""))
            _report_builder_text_set(txt_ftir_validation_signoff_note, signoff.get("note"))
            var_ftir_validation_exclusion_reason.set("")
            var_ftir_validation_set_review_reason.set("")
            _apply_ftir_validation_lock_state(sess_use)
        except Exception:
            pass

    def _report_builder_completeness(sess_local: Dict[str, Any]) -> Dict[str, Any]:
        blk = _report_builder_block(sess_local)
        parties = blk.get("parties") if isinstance(blk.get("parties"), dict) else {}
        process_control = blk.get("process_control") if isinstance(blk.get("process_control"), dict) else {}
        deviations = blk.get("deviations_approvals") if isinstance(blk.get("deviations_approvals"), dict) else {}
        correspondence = blk.get("correspondence") if isinstance(blk.get("correspondence"), dict) else {}
        ftir_validation = _ftir_validation_block(sess_local)

        sections: List[Dict[str, Any]] = []

        def _status(required: List[Tuple[str, Any]], optional: Optional[List[Tuple[str, Any]]] = None) -> Dict[str, Any]:
            optional = optional or []
            missing = [label for label, value in required if not (bool(value) if isinstance(value, list) else str(value or "").strip())]
            have_optional = any((bool(value) if isinstance(value, list) else str(value or "").strip()) for _, value in optional)
            if not missing and required:
                state = "Available"
            elif len(missing) < len(required) or have_optional:
                state = "Partial"
            else:
                state = "Gap"
            return {"status": state, "missing": missing}

        party_eval = _status(
            [
                ("Client name", parties.get("client_name")),
                ("Facility owner / operator", parties.get("facility_owner_operator_name")),
                ("Test company", parties.get("test_company_name")),
                ("Responsible official", parties.get("responsible_official_name")),
            ],
            [
                ("Laboratory", parties.get("laboratory_name")),
                ("Observer contacts", parties.get("observer_contacts")),
                ("Responsible title", parties.get("responsible_official_title")),
            ],
        )
        sections.append({"label": "Parties / certification", **party_eval})

        process_eval = _status(
            [
                ("Process narrative", process_control.get("process_narrative")),
                ("Control equipment description", process_control.get("control_equipment_description")),
            ],
        )
        sections.append({"label": "Process / control", **process_eval})

        dev_eval = _status(
            [],
            [
                ("Planned deviations", deviations.get("planned_deviations")),
                ("Field deviations", deviations.get("field_deviations")),
                ("Alternative approvals", deviations.get("alternative_method_approvals")),
                ("Impact statement", deviations.get("impact_statement")),
            ],
        )
        if not any(str(item.get("label") or "").strip() == "Deviations / approvals" for item in sections):
            dev_eval["status"] = "Available" if any(
                bool(val) if isinstance(val, list) else str(val or "").strip()
                for val in [
                    deviations.get("planned_deviations"),
                    deviations.get("field_deviations"),
                    deviations.get("alternative_method_approvals"),
                    deviations.get("impact_statement"),
                ]
            ) else "Gap"
            dev_eval["missing"] = [] if dev_eval["status"] == "Available" else [
                "Planned deviations or field deviations or approval references"
            ]
        sections.append({"label": "Deviations / approvals", **dev_eval})

        corr_eval = _status(
            [],
            [
                ("Notice of intent date", correspondence.get("notice_of_intent_date")),
                ("Agency contact", correspondence.get("agency_contact")),
                ("Approval dates", correspondence.get("approval_dates")),
                ("Submission status", correspondence.get("submission_status")),
                ("Correspondence notes", correspondence.get("notes")),
            ],
        )
        corr_eval["status"] = "Available" if any(
            bool(val) if isinstance(val, list) else str(val or "").strip()
            for val in [
                correspondence.get("notice_of_intent_date"),
                correspondence.get("agency_contact"),
                correspondence.get("approval_dates"),
                correspondence.get("submission_status"),
                correspondence.get("notes"),
            ]
        ) else "Gap"
        corr_eval["missing"] = [] if corr_eval["status"] == "Available" else [
            "Agency / correspondence tracking metadata"
        ]
        sections.append({"label": "Regulatory correspondence", **corr_eval})

        ftir_eval = _status(
            [
                ("FTIR data file", ftir_validation.get("ftir_file_path") if bool(ftir_validation.get("enabled")) else "disabled"),
                ("Analytes", ftir_validation.get("analytes") if bool(ftir_validation.get("enabled")) else ["disabled"]),
            ],
            [
                ("Timestamp column", ftir_validation.get("ftir_timestamp_column")),
                ("Manual windows", ftir_validation.get("manual_windows")),
                ("Column map", ftir_validation.get("column_map")),
            ],
        )
        if not bool(ftir_validation.get("enabled")):
            ftir_eval = {"status": "Available", "missing": []}
        sections.append({"label": "FTIR validation", **ftir_eval})

        counts = {"Available": 0, "Partial": 0, "Gap": 0}
        for item in sections:
            status = str(item.get("status") or "")
            if status in counts:
                counts[status] += 1
        summary = f"Report metadata completeness A/P/G = {counts['Available']}/{counts['Partial']}/{counts['Gap']}"
        warn_sections = [item for item in sections if str(item.get("status") or "") != "Available"]
        return {
            "sections": sections,
            "counts": counts,
            "summary": summary,
            "warn": bool(warn_sections),
            "warn_sections": warn_sections,
        }

    def _report_builder_save_to_session(*, show_message: bool = False) -> Dict[str, Any]:
        nonlocal sess
        sess = _load_session()
        _ensure_daq_schema(sess)
        blk = _report_builder_block(sess)
        parties = blk.get("parties") if isinstance(blk.get("parties"), dict) else {}
        process_control = blk.get("process_control") if isinstance(blk.get("process_control"), dict) else {}
        deviations = blk.get("deviations_approvals") if isinstance(blk.get("deviations_approvals"), dict) else {}
        correspondence = blk.get("correspondence") if isinstance(blk.get("correspondence"), dict) else {}
        meta = blk.get("meta") if isinstance(blk.get("meta"), dict) else {}
        ftir_validation = _ftir_validation_block(sess)
        ftir_locked = _ftir_validation_is_locked(ftir_validation)
        ftir_signed = _ftir_validation_is_signed(ftir_validation)

        parties.update({
            "client_name": str(var_report_client_name.get() or "").strip(),
            "facility_owner_operator_name": str(var_report_facility_owner.get() or "").strip(),
            "test_company_name": str(var_report_test_company.get() or "").strip(),
            "laboratory_name": str(var_report_laboratory.get() or "").strip(),
            "session_operator_name": str(var_report_session_operator.get() or "").strip(),
            "responsible_official_name": str(var_report_responsible_official.get() or "").strip(),
            "responsible_official_title": str(var_report_responsible_title.get() or "").strip(),
            "observer_contacts": _report_builder_split_list(var_report_observer_contacts.get()),
        })
        process_control.update({
            "process_narrative": _report_builder_text_get(txt_report_process_narrative),
            "control_equipment_description": _report_builder_text_get(txt_report_control_equipment),
        })
        deviations.update({
            "planned_deviations": _report_builder_split_list(_report_builder_text_get(txt_report_planned_deviations)),
            "field_deviations": _report_builder_split_list(_report_builder_text_get(txt_report_field_deviations)),
            "alternative_method_approvals": _report_builder_split_list(_report_builder_text_get(txt_report_alt_approvals)),
            "impact_statement": _report_builder_text_get(txt_report_impact_statement),
        })
        correspondence.update({
            "notice_of_intent_date": str(var_report_notice_of_intent.get() or "").strip(),
            "agency_contact": str(var_report_agency_contact.get() or "").strip(),
            "approval_dates": _report_builder_split_list(var_report_approval_dates.get()),
            "submission_status": str(var_report_submission_status.get() or "").strip(),
            "notes": _report_builder_text_get(txt_report_correspondence_notes),
        })
        if not ftir_locked:
            ftir_validation.update({
                "enabled": bool(var_ftir_validation_enabled.get()),
                "validation_mode": str(var_ftir_validation_mode.get() or "METHOD_301_INFORMED_COMPARISON").strip().upper() or "METHOD_301_INFORMED_COMPARISON",
                "ftir_vendor_profile": str(var_ftir_validation_vendor.get() or "AUTO").strip().upper() or "AUTO",
                "ftir_file_path": str(var_ftir_validation_file.get() or "").strip(),
                "ftir_timestamp_column": str(var_ftir_validation_timestamp_col.get() or "").strip(),
                "ftir_delimiter": str(var_ftir_validation_delimiter.get() or "AUTO").strip().upper() or "AUTO",
                "time_offset_seconds": _parse_float(var_ftir_validation_offset_s.get(), default=0.0),
                "analytes": _report_builder_split_list(var_ftir_validation_analytes.get()),
                "timestamp_master_clock": str(var_ftir_validation_master_clock.get() or "SESSION_MASTER_CLOCK").strip(),
                "column_map": (
                    mole_ftir_validation._normalize_column_map(_report_builder_text_get(txt_ftir_validation_column_map))
                    if mole_ftir_validation is not None
                    else {}
                ),
                "manual_windows": (
                    mole_ftir_validation._normalize_manual_windows(_report_builder_text_get(txt_ftir_validation_manual_windows))
                    if mole_ftir_validation is not None
                    else []
                ),
                "execution": {
                    "enabled": bool(var_ftir_validation_execution_enabled.get()),
                    "profile": str(var_ftir_validation_execution_profile.get() or "SESSION_RUNS").strip().upper() or "SESSION_RUNS",
                    "comparison_set_policy": "RUN_EQUALS_SET",
                    "purge_minutes_required": _parse_float(var_ftir_validation_purge_min.get(), default=5.0),
                    "require_purge_event": bool(var_ftir_validation_require_purge.get()),
                    "require_bias_event": bool(var_ftir_validation_require_bias.get()),
                    "planned_run_count": ((ftir_validation.get("execution") or {}).get("planned_run_count") if isinstance(ftir_validation.get("execution"), dict) else None),
                    "comparison_sets_completed": ((ftir_validation.get("execution") or {}).get("comparison_sets_completed") if isinstance(ftir_validation.get("execution"), dict) else 0),
                    "next_comparison_set_no": ((ftir_validation.get("execution") or {}).get("next_comparison_set_no") if isinstance(ftir_validation.get("execution"), dict) else 1),
                    "purge_due_after_run_no": ((ftir_validation.get("execution") or {}).get("purge_due_after_run_no") if isinstance(ftir_validation.get("execution"), dict) else None),
                    "purge_due_after_iso": str((((ftir_validation.get("execution") or {}) if isinstance(ftir_validation.get("execution"), dict) else {}).get("purge_due_after_iso") or "")).strip(),
                    "bias_due_after_run_no": ((ftir_validation.get("execution") or {}).get("bias_due_after_run_no") if isinstance(ftir_validation.get("execution"), dict) else None),
                    "bias_due_after_iso": str((((ftir_validation.get("execution") or {}) if isinstance(ftir_validation.get("execution"), dict) else {}).get("bias_due_after_iso") or "")).strip(),
                    "last_completed_run_no": ((ftir_validation.get("execution") or {}).get("last_completed_run_no") if isinstance(ftir_validation.get("execution"), dict) else None),
                    "last_completed_iso": str((((ftir_validation.get("execution") or {}) if isinstance(ftir_validation.get("execution"), dict) else {}).get("last_completed_iso") or "")).strip(),
                    "last_purge_run_no": ((ftir_validation.get("execution") or {}).get("last_purge_run_no") if isinstance(ftir_validation.get("execution"), dict) else None),
                    "last_purge_iso": str((((ftir_validation.get("execution") or {}) if isinstance(ftir_validation.get("execution"), dict) else {}).get("last_purge_iso") or "")).strip(),
                    "last_bias_run_no": ((ftir_validation.get("execution") or {}).get("last_bias_run_no") if isinstance(ftir_validation.get("execution"), dict) else None),
                    "last_bias_iso": str((((ftir_validation.get("execution") or {}) if isinstance(ftir_validation.get("execution"), dict) else {}).get("last_bias_iso") or "")).strip(),
                    "live_review_status": str((((ftir_validation.get("execution") or {}) if isinstance(ftir_validation.get("execution"), dict) else {}).get("live_review_status") or "")).strip(),
                },
                "alignment_review": {
                    **(dict(ftir_validation.get("alignment_review") or {}) if isinstance(ftir_validation.get("alignment_review"), dict) else {}),
                    "sweep_min_seconds": _parse_float(var_ftir_validation_sweep_min_s.get(), default=-120.0),
                    "sweep_max_seconds": _parse_float(var_ftir_validation_sweep_max_s.get(), default=120.0),
                    "sweep_step_seconds": _parse_float(var_ftir_validation_sweep_step_s.get(), default=15.0),
                },
                "notes": _report_builder_text_get(txt_ftir_validation_notes),
                "review_notes": _report_builder_text_get(txt_ftir_validation_review_notes),
                "reviewer": _report_builder_actor(sess),
            })
        if not ftir_signed:
            ftir_validation["signoff"] = {
                "decision": str(var_ftir_validation_signoff_decision.get() or "UNSIGNED").strip().upper() or "UNSIGNED",
                "basis": str(var_ftir_validation_signoff_basis.get() or "").strip().upper(),
                "by": str(var_ftir_validation_signoff_by.get() or "").strip(),
                "role": str(var_ftir_validation_signoff_role.get() or "").strip(),
                "iso": "",
                "note": _report_builder_text_get(txt_ftir_validation_signoff_note),
            }
        meta.update({
            "updated_by": _report_builder_actor(sess),
            "updated_iso": now_iso(),
        })
        blk["parties"] = parties
        blk["process_control"] = process_control
        blk["deviations_approvals"] = deviations
        blk["correspondence"] = correspondence
        blk["meta"] = meta
        sess["report_builder"] = blk
        sess["ftir_validation"] = ftir_validation
        _ftir_validation_execution_status(sess)
        _save_session(sess)
        _refresh_report_builder_status(sess)
        _apply_ftir_validation_lock_state(sess)
        if show_message:
            messagebox.showinfo("Report Builder", "Report metadata saved.")
        return sess

    def _refresh_report_builder_status(sess_local: Optional[Dict[str, Any]] = None) -> None:
        try:
            sess_use = dict(sess_local) if isinstance(sess_local, dict) else _load_session()
            _ensure_daq_schema(sess_use)
            completeness = _report_builder_completeness(sess_use)
            pths = _report_builder_paths(sess_use)
            summary = _read_json(pths["summary_json"]) if pths["summary_json"].exists() else {}
            final_blk: Dict[str, Any] = {}
            ftir_blk: Dict[str, Any] = {}
            ftir_cfg = _ftir_validation_block(sess_use)
            if isinstance(summary, dict):
                final_blk = summary.get("final_report") if isinstance(summary.get("final_report"), dict) else {}
                ftir_blk = summary.get("ftir_validation") if isinstance(summary.get("ftir_validation"), dict) else {}
                rc_blk = summary.get("report_context") if isinstance(summary.get("report_context"), dict) else {}
                if str(final_blk.get("markdown_path") or "").strip():
                    pths["final_report_md"] = Path(str(final_blk.get("markdown_path")))
                if str(final_blk.get("docx_path") or "").strip():
                    pths["final_report_docx"] = Path(str(final_blk.get("docx_path")))
                if str(final_blk.get("pdf_path") or "").strip():
                    pths["final_report_pdf"] = Path(str(final_blk.get("pdf_path")))
                if str(final_blk.get("index_path") or "").strip():
                    pths["final_report_index"] = Path(str(final_blk.get("index_path")))
                if str(rc_blk.get("json_path") or "").strip():
                    pths["report_context_json"] = Path(str(rc_blk.get("json_path")))
            if not isinstance(ftir_blk, dict) or not ftir_blk:
                ftir_blk = dict(ftir_cfg)
            ftir_exec_state = _ftir_validation_execution_status(sess_use)

            report_context = _read_json(pths["report_context_json"]) if pths["report_context_json"].exists() else {}
            coverage = report_context.get("coverage") if isinstance(report_context, dict) else {}
            available_ct = int((coverage or {}).get("Available") or 0) if isinstance(coverage, dict) else 0
            partial_ct = int((coverage or {}).get("Partial") or 0) if isinstance(coverage, dict) else 0
            gap_ct = int((coverage or {}).get("Gap") or 0) if isinstance(coverage, dict) else 0
            final_md_exists = bool(pths["final_report_md"].exists())
            final_docx_exists = bool(pths["final_report_docx"].exists())
            final_pdf_exists = bool(pths["final_report_pdf"].exists())
            final_exists = bool(final_md_exists or final_docx_exists or final_pdf_exists)
            pack_exists = bool(pths["summary_json"].exists())

            if final_exists:
                var_report_builder_status.set("Formal report artifacts are available for this session.")
            elif pack_exists:
                var_report_builder_status.set("Report pack exists. Final report artifact is missing or stale.")
            else:
                var_report_builder_status.set("No formal report artifacts generated for this session.")

            var_report_builder_target.set(
                "Targets: report_pack_v1 + final_report_v1 (md/docx/pdf)"
                + (f" | coverage A/P/G = {available_ct}/{partial_ct}/{gap_ct}" if (available_ct or partial_ct or gap_ct) else "")
            )
            var_report_builder_completeness.set(str(completeness.get("summary") or "Report metadata completeness: (n/a)"))

            render_status = final_blk.get("render_status") if isinstance(final_blk.get("render_status"), dict) else {}
            lines = [
                f"Session dir: {pths['session_dir']}",
                f"Report pack dir: {pths['report_pack_dir']}",
                f"Final report dir: {pths['final_report_dir']}",
                f"Summary JSON: {pths['summary_json']} [{'YES' if pths['summary_json'].exists() else 'NO'}]",
                f"Report context: {pths['report_context_json']} [{'YES' if pths['report_context_json'].exists() else 'NO'}]",
                f"Final report (Markdown): {pths['final_report_md']} [{'YES' if final_md_exists else 'NO'}]",
                f"Final report (DOCX): {pths['final_report_docx']} [{'YES' if final_docx_exists else 'NO'}]",
                f"Final report (PDF): {pths['final_report_pdf']} [{'YES' if final_pdf_exists else 'NO'}]",
                f"Final report index: {pths['final_report_index']} [{'YES' if pths['final_report_index'].exists() else 'NO'}]",
                "",
                "Protocol notes:",
                "- Formal deliverables are built from the active session package, evidence bundle, report context, and final report contract.",
                f"- {_report_builder_o2_note(sess_use)}",
                f"- {completeness.get('summary') or 'Report metadata completeness: (n/a)'}",
            ]
            section_rows = list(completeness.get("sections") or [])
            if section_rows:
                lines.append("- Report metadata sections:")
                for item in section_rows:
                    if not isinstance(item, dict):
                        continue
                    missing = ", ".join([str(v) for v in list(item.get("missing") or []) if str(v or "").strip()])
                    row = f"  * {item.get('label') or 'Section'}: {item.get('status') or '(n/a)'}"
                    if missing:
                        row += f" | missing: {missing}"
                    lines.append(row)
            if isinstance(report_context, dict):
                run_block = ((report_context.get("normalized_blocks") or {}).get("run_aggregation") if isinstance(report_context.get("normalized_blocks"), dict) else {}) or {}
                if isinstance(run_block, dict):
                    lines.append(f"- Run aggregation status: {run_block.get('status') or '(n/a)'}")
                    lines.append(f"- Run coverage note: {run_block.get('coverage_note') or '(n/a)'}")
                template_contract = report_context.get("template_contract") if isinstance(report_context.get("template_contract"), dict) else {}
                if isinstance(template_contract, dict):
                    lines.append(f"- Report contract: {template_contract.get('contract_version') or report_context.get('contract_version') or '(n/a)'}")
            if isinstance(render_status, dict):
                docx_row = render_status.get("docx") if isinstance(render_status.get("docx"), dict) else {}
                pdf_row = render_status.get("pdf") if isinstance(render_status.get("pdf"), dict) else {}
                lines.append(f"- DOCX render status: {(docx_row.get('status') if isinstance(docx_row, dict) else None) or '(n/a)'}")
                if isinstance(docx_row, dict) and str(docx_row.get("reason") or "").strip():
                    lines.append(f"  reason: {docx_row.get('reason')}")
                lines.append(f"- PDF render status: {(pdf_row.get('status') if isinstance(pdf_row, dict) else None) or '(n/a)'}")
                if isinstance(pdf_row, dict) and str(pdf_row.get("reason") or "").strip():
                    lines.append(f"  reason: {pdf_row.get('reason')}")
            if isinstance(ftir_blk, dict) and ftir_blk:
                sign = ftir_blk.get("signoff") if isinstance(ftir_blk.get("signoff"), dict) else {}
                qa = ftir_blk.get("qa") if isinstance(ftir_blk.get("qa"), dict) else {}
                lines.append(f"- FTIR validation status: {ftir_blk.get('status') or '(n/a)'}")
                lines.append(f"- FTIR validation overall: {ftir_blk.get('overall_status') or '(n/a)'}")
                lines.append(f"- FTIR validation acceptance basis: {ftir_blk.get('acceptance_basis') or '(n/a)'}")
                lines.append(f"- FTIR validation acceptance note: {ftir_blk.get('acceptance_basis_note') or '(n/a)'}")
                lines.append(f"- FTIR validation source: {ftir_blk.get('source') or '(n/a)'}")
                lines.append(f"- FTIR validation paired windows: {ftir_blk.get('paired_window_count') or 0}")
                lines.append(f"- FTIR validation excluded rows: {ftir_blk.get('excluded_count') or 0}")
                if isinstance(qa, dict) and qa:
                    lines.append(f"- FTIR validation QA summary: {qa.get('summary') or '(n/a)'}")
                    lines.append(f"- FTIR validation lock ready: {'YES' if bool(qa.get('lock_ready')) else 'NO'}")
                    lines.append(f"- FTIR validation signoff ready: {'YES' if bool(qa.get('signoff_ready')) else 'NO'}")
                    if list(qa.get("blocking_issues") or []):
                        lines.append(f"  blocking issues: {len(list(qa.get('blocking_issues') or []))}")
                    if list(qa.get("warnings") or []):
                        lines.append(f"  warnings: {len(list(qa.get('warnings') or []))}")
                lines.append(f"- FTIR validation review locked: {'YES' if bool(ftir_blk.get('review_locked')) else 'NO'}")
                if bool(ftir_blk.get('review_locked')):
                    lines.append(f"  locked by: {ftir_blk.get('review_lock_by') or '(n/a)'} @ {ftir_blk.get('review_lock_iso') or '(n/a)'}")
                elif str(ftir_blk.get('review_unlock_by') or '').strip() or str(ftir_blk.get('review_unlock_iso') or '').strip():
                    lines.append(f"  last unlock: {ftir_blk.get('review_unlock_by') or '(n/a)'} @ {ftir_blk.get('review_unlock_iso') or '(n/a)'}")
                snap = ftir_blk.get("review_snapshot") if isinstance(ftir_blk.get("review_snapshot"), dict) else {}
                if isinstance(snap, dict) and snap:
                    snap_json_txt = str(snap.get("json_path") or "").strip()
                    snap_exists = Path(snap_json_txt).exists() if snap_json_txt else False
                    lines.append(f"- FTIR locked snapshot: {snap_json_txt or '(n/a)'} [{'YES' if snap_exists else 'NO'}]")
                    if str(snap.get("snapshot_iso") or "").strip() or str(snap.get("snapshot_by") or "").strip():
                        lines.append(f"  snapshot by: {snap.get('snapshot_by') or '(n/a)'} @ {snap.get('snapshot_iso') or '(n/a)'}")
                lines.append(f"- FTIR validation signoff: {str(sign.get('decision') or 'UNSIGNED').strip().upper() or 'UNSIGNED'}")
                if str(sign.get("basis") or "").strip():
                    lines.append(f"  basis: {sign.get('basis')}")
                if str(sign.get("by") or "").strip() or str(sign.get("iso") or "").strip():
                    lines.append(f"  by: {sign.get('by') or '(n/a)'} | role: {sign.get('role') or '(n/a)'} | at: {sign.get('iso') or '(n/a)'}")
                lines.append(f"- FTIR validation note: {ftir_blk.get('coverage_note') or '(n/a)'}")
                if isinstance(ftir_exec_state, dict) and bool(ftir_exec_state.get("enabled")):
                    lines.append(f"- FTIR live execution profile: {ftir_exec_state.get('profile') or '(n/a)'}")
                    lines.append(
                        f"- FTIR live comparison sets completed / next / frozen: "
                        f"{ftir_exec_state.get('comparison_sets_completed') or 0} / "
                        f"{ftir_exec_state.get('next_comparison_set_no') or '(n/a)'} / "
                        f"{ftir_exec_state.get('frozen_comparison_set_count') or 0}"
                    )
                    lines.append(f"- FTIR live cadence status: {ftir_exec_state.get('live_review_status') or '(n/a)'}")
                    lines.append(f"- FTIR live cadence note: {ftir_exec_state.get('note') or '(n/a)'}")
            tpl = _ftir_validation_template_paths()
            lines.extend([
                "",
                "FTIR validation templates:",
                f"- Template folder: {tpl['template_dir']}",
                f"- Import template CSV: {tpl['import_csv']} [{'YES' if tpl['import_csv'].exists() else 'NO'}]",
                f"- Manual windows CSV: {tpl['manual_windows_csv']} [{'YES' if tpl['manual_windows_csv'].exists() else 'NO'}]",
                f"- Column map CSV: {tpl['column_map_csv']} [{'YES' if tpl['column_map_csv'].exists() else 'NO'}]",
                f"- Alignment worksheet: {tpl['alignment_xlsx']} [{'YES' if tpl['alignment_xlsx'].exists() else 'NO'}]",
            ])

            report_builder_text.configure(state="normal")
            report_builder_text.delete("1.0", "end")
            report_builder_text.insert("1.0", "\n".join(lines).strip() + "\n")
            report_builder_text.configure(state="disabled")
        except Exception as e:
            try:
                var_report_builder_status.set("Report builder status refresh failed.")
                report_builder_text.configure(state="normal")
                report_builder_text.delete("1.0", "end")
                report_builder_text.insert("1.0", f"Report builder refresh failed:\n{e}")
                report_builder_text.configure(state="disabled")
            except Exception:
                pass

    def _lock_ftir_validation_review() -> None:
        nonlocal sess
        try:
            sess = _report_builder_save_to_session(show_message=False)
            _ensure_daq_schema(sess)
            blk = _ftir_validation_block(sess)
            if _ftir_validation_is_locked(blk):
                _apply_ftir_validation_lock_state(sess)
                return
            if not bool(blk.get("enabled")):
                raise ValueError("Enable FTIR validation before locking the review.")
            blk["review_locked"] = True
            blk["review_lock_by"] = _report_builder_actor(sess)
            blk["review_lock_iso"] = now_iso()
            sess["ftir_validation"] = blk
            preview = _build_ftir_validation_preview_payload(sess)
            qa = preview.get("qa") if isinstance(preview.get("qa"), dict) else {}
            blocking_issues = [str(v) for v in list(qa.get("blocking_issues") or []) if str(v or "").strip()]
            qa_warnings = [str(v) for v in list(qa.get("warnings") or []) if str(v or "").strip()]
            if blocking_issues:
                if not messagebox.askyesno(
                    "FTIR Validation Review",
                    "FTIR validation QA is not lock-ready.\n\n"
                    + "\n".join([f"- {item}" for item in blocking_issues])
                    + ("\n\nWarnings:\n" + "\n".join([f"- {item}" for item in qa_warnings]) if qa_warnings else "")
                    + "\n\nLock review anyway?",
                ):
                    blk["review_locked"] = False
                    blk["review_lock_by"] = ""
                    blk["review_lock_iso"] = ""
                    sess["ftir_validation"] = blk
                    return
            blk["review_snapshot"] = _write_ftir_validation_locked_snapshot(sess, preview)
            sess["ftir_validation"] = blk
            _save_session(sess)
            _refresh_report_builder_status(sess)
            _refresh_ftir_validation_preview(sess)
            _apply_ftir_validation_lock_state(sess)
        except Exception as e:
            messagebox.showerror("FTIR Validation Review", str(e))

    def _signoff_ftir_validation_review() -> None:
        nonlocal sess
        try:
            sess = _load_session()
            _ensure_daq_schema(sess)
            blk = _ftir_validation_block(sess)
            if not _ftir_validation_is_locked(blk):
                raise ValueError("Lock FTIR validation review before signing off.")
            decision = str(var_ftir_validation_signoff_decision.get() or "UNSIGNED").strip().upper() or "UNSIGNED"
            basis = str(var_ftir_validation_signoff_basis.get() or "").strip().upper()
            approver = str(var_ftir_validation_signoff_by.get() or "").strip()
            role = str(var_ftir_validation_signoff_role.get() or "").strip()
            note = _report_builder_text_get(txt_ftir_validation_signoff_note)
            if decision == "UNSIGNED":
                raise ValueError("Select a signoff decision before signing off.")
            if not approver:
                raise ValueError("Approver name is required.")
            if decision == "ACCEPTED" and basis not in ("FORMAL_METHOD_301", "METHOD_301_INFORMED_COMPARISON"):
                raise ValueError("Accepted FTIR validation signoff requires basis FORMAL_METHOD_301 or METHOD_301_INFORMED_COMPARISON.")
            if decision == "REJECTED" and basis != "NOT_ACCEPTED":
                raise ValueError("Rejected FTIR validation signoff requires basis NOT_ACCEPTED.")
            snap_payload = _load_ftir_validation_locked_snapshot(blk) or _build_ftir_validation_preview_payload(sess)
            qa = snap_payload.get("qa") if isinstance(snap_payload.get("qa"), dict) else {}
            blocking_issues = [str(v) for v in list(qa.get("blocking_issues") or []) if str(v or "").strip()]
            derived_basis = str(snap_payload.get("acceptance_basis") or "").strip().upper()
            if decision == "ACCEPTED":
                if derived_basis == "NOT_ACCEPTED":
                    raise ValueError("Current FTIR comparison package does not support accepted signoff. Use NOT_ACCEPTED.")
                if basis == "FORMAL_METHOD_301" and derived_basis != "FORMAL_METHOD_301":
                    raise ValueError("Formal Method 301 acceptance is not supported by the current FTIR comparison package.")
            if decision == "ACCEPTED" and blocking_issues:
                if not messagebox.askyesno(
                    "FTIR Validation Signoff",
                    "FTIR validation QA is not signoff-ready.\n\n"
                    + "\n".join([f"- {item}" for item in blocking_issues])
                    + "\n\nSign off anyway?",
                ):
                    return
            signoff = {
                "decision": decision,
                "basis": basis,
                "by": approver,
                "role": role,
                "iso": now_iso(),
                "note": note,
            }
            blk["signoff"] = signoff
            snap_payload["signoff"] = dict(signoff)
            blk["review_snapshot"] = _write_ftir_validation_locked_snapshot(sess, snap_payload)
            sess["ftir_validation"] = blk
            _save_session(sess)
            _report_builder_load_form(sess)
            _refresh_report_builder_status(sess)
            _refresh_ftir_validation_preview(sess)
            _apply_ftir_validation_lock_state(sess)
        except Exception as e:
            messagebox.showerror("FTIR Validation Signoff", str(e))

    def _clear_ftir_validation_signoff() -> None:
        nonlocal sess
        if not messagebox.askyesno("FTIR Validation Signoff", "Clear FTIR validation signoff for this locked review?"):
            return
        try:
            sess = _load_session()
            _ensure_daq_schema(sess)
            blk = _ftir_validation_block(sess)
            blk["signoff"] = {
                "decision": "UNSIGNED",
                "basis": "",
                "by": "",
                "role": "",
                "iso": "",
                "note": "",
            }
            if _ftir_validation_is_locked(blk):
                snap_payload = _load_ftir_validation_locked_snapshot(blk) or _build_ftir_validation_preview_payload(sess)
                snap_payload["signoff"] = dict(blk["signoff"])
                blk["review_snapshot"] = _write_ftir_validation_locked_snapshot(sess, snap_payload)
            sess["ftir_validation"] = blk
            _save_session(sess)
            _report_builder_load_form(sess)
            _refresh_report_builder_status(sess)
            _refresh_ftir_validation_preview(sess)
            _apply_ftir_validation_lock_state(sess)
        except Exception as e:
            messagebox.showerror("FTIR Validation Signoff", str(e))

    def _unlock_ftir_validation_review() -> None:
        nonlocal sess
        if not messagebox.askyesno("FTIR Validation Review", "Unlock FTIR validation review and allow edits?"):
            return
        try:
            sess = _load_session()
            _ensure_daq_schema(sess)
            blk = _ftir_validation_block(sess)
            blk["review_locked"] = False
            blk["review_unlock_by"] = _report_builder_actor(sess)
            blk["review_unlock_iso"] = now_iso()
            blk["review_snapshot"] = {}
            blk["signoff"] = {
                "decision": "UNSIGNED",
                "basis": "",
                "by": "",
                "role": "",
                "iso": "",
                "note": "",
            }
            sess["ftir_validation"] = blk
            _save_session(sess)
            _report_builder_load_form(sess)
            _refresh_report_builder_status(sess)
            _refresh_ftir_validation_preview(sess)
            _apply_ftir_validation_lock_state(sess)
        except Exception as e:
            messagebox.showerror("FTIR Validation Review", str(e))

    def _browse_ftir_validation_file() -> None:
        try:
            current_path = Path(str(var_ftir_validation_file.get() or "")).expanduser()
            if current_path.exists():
                initial_dir = str(current_path.parent.resolve())
            else:
                initial_dir = str(_ftir_validation_template_paths()["template_dir"].resolve())
        except Exception:
            initial_dir = str(Path.cwd())
        chosen = filedialog.askopenfilename(
            title="Select FTIR Validation Data File",
            initialdir=initial_dir,
            filetypes=[
                ("Delimited data", "*.csv;*.tsv;*.txt;*.jsonl"),
                ("CSV", "*.csv"),
                ("TSV/TXT", "*.tsv;*.txt"),
                ("JSONL", "*.jsonl"),
                ("All files", "*.*"),
            ],
        )
        if chosen:
            var_ftir_validation_file.set(str(chosen))

    def _open_ftir_validation_template_folder() -> None:
        _open_fs_target(_ftir_validation_template_paths().get("template_dir"), title="Open FTIR Template Folder Failed")

    def _open_ftir_validation_import_template() -> None:
        _open_fs_target(_ftir_validation_template_paths().get("import_csv"), title="Open FTIR Import Template Failed")

    def _open_ftir_validation_alignment() -> None:
        _open_fs_target(_ftir_validation_template_paths().get("alignment_xlsx"), title="Open FTIR Alignment Worksheet Failed")

    def build_formal_report_ui() -> None:
        nonlocal sess
        if diagnostics_ui:
            messagebox.showinfo(
                "Report Builder",
                "Formal report generation is disabled in Diagnostics Runner.\n\n"
                "Diagnostics sessions are excluded from compliance support and formal final-report output.",
            )
            return
        try:
            sess = _report_builder_save_to_session(show_message=False)
            completeness = _report_builder_completeness(sess)
            warn_rows = list(completeness.get("warn_sections") or [])
            ftir_blk = _ftir_validation_block(sess)
            ftir_exec = _ftir_validation_execution_status(sess)
            if warn_rows:
                msg_lines = [
                    "Formal report metadata is incomplete.",
                    "",
                    "The build can continue, but the final deliverable will still contain partial or gap sections.",
                    "",
                ]
                for item in warn_rows:
                    if not isinstance(item, dict):
                        continue
                    row = f"- {item.get('label') or 'Section'}: {item.get('status') or '(n/a)'}"
                    missing = ", ".join([str(v) for v in list(item.get("missing") or []) if str(v or "").strip()])
                    if missing:
                        row += f" | missing: {missing}"
                    msg_lines.append(row)
                msg_lines.append("")
                msg_lines.append("Build anyway?")
                if not messagebox.askyesno("Report Builder", "\n".join(msg_lines)):
                    _refresh_report_builder_status(sess)
                    return
            if bool(ftir_blk.get("enabled")) and bool(ftir_exec.get("enabled")) and not bool(ftir_exec.get("cadence_ready_for_next_run")):
                if not messagebox.askyesno(
                    "Report Builder",
                    "FTIR live execution cadence is not clear.\n\n"
                    + f"Status: {ftir_exec.get('live_review_status') or '(n/a)'}\n"
                    + f"Note: {ftir_exec.get('note') or '(n/a)'}\n\n"
                    + "Build anyway?",
                ):
                    _refresh_report_builder_status(sess)
                    return
            if bool(ftir_blk.get("enabled")) and not _ftir_validation_is_locked(ftir_blk):
                if not messagebox.askyesno(
                    "Report Builder",
                    "FTIR validation is enabled, but the review is not locked.\n\n"
                    "Build anyway without freezing the FTIR validation review state?",
                ):
                    _refresh_report_builder_status(sess)
                    return
            snap = _ftir_validation_snapshot_block(ftir_blk)
            if bool(ftir_blk.get("enabled")) and _ftir_validation_is_locked(ftir_blk):
                snap_json_txt = str((snap.get("json_path") if isinstance(snap, dict) else "") or "").strip()
                snap_exists = Path(snap_json_txt).expanduser().exists() if snap_json_txt else False
                if not snap_exists:
                    if not messagebox.askyesno(
                        "Report Builder",
                        "FTIR validation review is locked, but the frozen snapshot artifact is missing.\n\n"
                        "Build anyway using a live recompute?",
                    ):
                        _refresh_report_builder_status(sess)
                        return
                sign = _ftir_validation_signoff_block(ftir_blk)
                if str(sign.get("decision") or "UNSIGNED").strip().upper() == "UNSIGNED":
                    if not messagebox.askyesno(
                        "Report Builder",
                        "FTIR validation review is locked, but no signoff has been recorded.\n\n"
                        "Build anyway without an FTIR validation approval decision?",
                    ):
                        _refresh_report_builder_status(sess)
                        return
            outputs = init_outputs(sess, cfg_path, None)
            try:
                from mole_report_pack_v1 import generate_report_pack_v1
            except Exception as e:
                raise RuntimeError(f"mole_report_pack_v1.py not available: {e}")
            out_dir = generate_report_pack_v1(session=sess, cfg_path=cfg_path, session_dir=outputs.out_dir)
            _refresh_report_builder_status(sess)
            pths = _report_builder_paths(sess)
            final_docx = pths.get("final_report_docx")
            final_pdf = pths.get("final_report_pdf")
            final_md = pths.get("final_report_md")
            log(f"Formal report deliverables generated: {out_dir}")
            messagebox.showinfo(
                "Report Builder",
                "Formal report deliverables generated.\n\n"
                f"Report pack: {out_dir}\n"
                f"Final report (DOCX): {final_docx}\n"
                f"Final report (PDF): {final_pdf}\n"
                f"Final report (Markdown): {final_md}",
            )
        except Exception as e:
            messagebox.showerror("Report Builder", str(e))

    def _open_report_builder_final() -> None:
        sess_use = _load_session()
        _ensure_daq_schema(sess_use)
        _refresh_report_builder_status(sess_use)
        pths = _report_builder_paths(sess_use)
        target = pths.get("final_report_docx")
        if not isinstance(target, Path) or not target.exists():
            target = pths.get("final_report_pdf")
        if not isinstance(target, Path) or not target.exists():
            target = pths.get("final_report_md")
        _open_fs_target(target, title="Open Final Report Failed")

