        tree.heading('scale', text='Scale')
        tree.heading('offset', text='Offset')
        tree.heading('corrected', text='Corrected')
        tree.column('channel', width=160, anchor='w')
        tree.column('raw', width=120, anchor='e')
        tree.column('scale', width=90, anchor='e')
        tree.column('offset', width=90, anchor='e')
        tree.column('corrected', width=120, anchor='e')
        tree.pack(fill='both', expand=True)

        edit = tk.Frame(body, bg=BG)
        edit.pack(fill='x', pady=(10, 0))
        _configure_runner_form_grid(edit, minspec="runner_channel_offsets")

        var_chan = tk.StringVar(value='')
        var_scale = tk.StringVar(value='1.0')
        var_offset = tk.StringVar(value='0.0')
        var_target = tk.StringVar(value='')

        def _get_raw_value(ch_name: str):
            try:
                if isinstance(last_frame, dict):
                    rc = last_frame.get('_raw_channels')
                    if isinstance(rc, dict) and ch_name in rc:
                        return rc.get(ch_name)
                    return last_frame.get(ch_name)
            except Exception:
                return None
            return None

        def _refresh_table() -> None:
            try:
                tree.delete(*tree.get_children())
            except Exception:
                pass

            co3 = _co_block(sess)
            ch_map = (co3.get('channels') or {}) if isinstance(co3.get('channels'), dict) else {}

            channels = []
            try:
                channels.extend(_display_selected_pollutants(sess))
            except Exception:
                pass
            for x in ('O2', 'CO2'):
                if x not in channels:
                    channels.append(x)
            for k in sorted([str(k) for k in ch_map.keys()]):
                if k not in channels:
                    channels.append(k)

            # If last_frame has numeric channels not yet listed, include a few common ones
            try:
                if isinstance(last_frame, dict):
                    for k in ('SAMPLE_FLOW', 'SAMPLE_FLOW_SLM', 'SAMPLE_FLOW_SCFM', 'FLOW', 'FLOW_SCFM'):
                        if k in last_frame and k not in channels:
                            channels.append(k)
            except Exception:
                pass

            for ch_name in channels:
                rawv = _get_raw_value(ch_name)
                try:
                    rawf = float(rawv) if rawv is not None and rawv != '' else None
                except Exception:
                    rawf = None

                spec = ch_map.get(ch_name) if isinstance(ch_map, dict) else None
                off = 0.0
                scl = 1.0
                try:
                    if isinstance(spec, dict):
                        off = float(spec.get('offset') or 0.0)
                        scl = float(spec.get('scale') or 1.0)
                except Exception:
                    off, scl = 0.0, 1.0

                corr = None
                if rawf is not None:
                    corr = rawf * scl + off

                tree.insert('', 'end', values=(
                    ch_name,
                    _fmt_num(rawf, 3, '(n/a)'),
                    _fmt_num(scl, 6, '1.0'),
                    _fmt_num(off, 6, '0.0'),
                    _fmt_num(corr, 3, '(n/a)')
                ))

        def _select_row(_evt=None):
            try:
                sel = tree.selection()
                if not sel:
                    return
                vals = tree.item(sel[0], 'values') or []
                if not vals:
                    return
                var_chan.set(str(vals[0]))
                # pull current values from config to avoid formatting artifacts
                co4 = _co_block(sess)
                sp = (co4.get('channels') or {}).get(var_chan.get())
                if isinstance(sp, dict):
                    var_scale.set(str(sp.get('scale') if sp.get('scale') is not None else '1.0'))
                    var_offset.set(str(sp.get('offset') if sp.get('offset') is not None else '0.0'))
                else:
                    var_scale.set('1.0')
                    var_offset.set('0.0')
            except Exception:
                pass

        tree.bind('<<TreeviewSelect>>', _select_row)

        # Editor row
        tk.Label(edit, text='Channel', bg=BG, fg=FG_DIM, font=('Consolas', 9)).grid(row=0, column=0, sticky='w')
        ent_chan = tk.Entry(edit, textvariable=var_chan, bg=PANEL_BG, fg=FG, insertbackground=FG, relief='flat', font=('Consolas', 10, 'bold'))
        ent_chan.grid(row=0, column=1, sticky='we', padx=(8, 10))

        tk.Label(edit, text='Scale', bg=BG, fg=FG_DIM, font=('Consolas', 9)).grid(row=0, column=2, sticky='w')
        ent_scl = tk.Entry(edit, textvariable=var_scale, width=10, bg=PANEL_BG, fg=FG, insertbackground=FG, relief='flat', font=('Consolas', 10, 'bold'))
        ent_scl.grid(row=0, column=3, sticky='w', padx=(8, 10))

        tk.Label(edit, text='Offset', bg=BG, fg=FG_DIM, font=('Consolas', 9)).grid(row=0, column=4, sticky='w')
        ent_off = tk.Entry(edit, textvariable=var_offset, width=10, bg=PANEL_BG, fg=FG, insertbackground=FG, relief='flat', font=('Consolas', 10, 'bold'))
        ent_off.grid(row=0, column=5, sticky='w', padx=(8, 10))

        tk.Label(edit, text='Target', bg=BG, fg=FG_DIM, font=('Consolas', 9)).grid(row=1, column=2, sticky='w', pady=(8, 0))
        ent_tgt = tk.Entry(edit, textvariable=var_target, width=10, bg=PANEL_BG, fg=FG, insertbackground=FG, relief='flat', font=('Consolas', 10, 'bold'))
        ent_tgt.grid(row=1, column=3, sticky='w', padx=(8, 10), pady=(8, 0))

        def _save_one() -> None:
            try:
                ch_name = str(var_chan.get() or '').strip()
                if not ch_name:
                    return
                scl = float(var_scale.get() or 1.0)
                off = float(var_offset.get() or 0.0)
                co5 = _co_block(sess)
                cm = co5.get('channels')
                if not isinstance(cm, dict):
                    cm = {}
                    co5['channels'] = cm
                cm[ch_name] = {'scale': scl, 'offset': off}
                _save_session(sess)
                _refresh_table()
            except Exception as e:
                try:
                    messagebox.showerror('Save Failed', str(e))
                except Exception:
                    pass

        def _zero_now() -> None:
            try:
                ch_name = str(var_chan.get() or '').strip()
                if not ch_name:
                    return
                scl = float(var_scale.get() or 1.0)
                rawv = _get_raw_value(ch_name)
                rawf = float(rawv) if rawv is not None and rawv != '' else None
                if rawf is None:
                    return
                var_offset.set(str(-rawf * scl))
                _save_one()
            except Exception:
                pass

        def _match_target() -> None:
            try:
                ch_name = str(var_chan.get() or '').strip()
                if not ch_name:
                    return
                tgt = float(var_target.get())
                scl = float(var_scale.get() or 1.0)
                rawv = _get_raw_value(ch_name)
                rawf = float(rawv) if rawv is not None and rawv != '' else None
                if rawf is None:
                    return
                var_offset.set(str(tgt - rawf * scl))
                _save_one()
            except Exception:
                pass

        btn_row = tk.Frame(edit, bg=BG)
        btn_row.grid(row=2, column=0, columnspan=6, sticky='we', pady=(10, 0))
        tk.Button(btn_row, text='Save', command=_save_one, bg=BTN_BG, fg=FG, relief='flat').pack(side='left', padx=(0, 8))
        tk.Button(btn_row, text='Zero Now', command=_zero_now, bg=BTN_BG, fg=FG, relief='flat').pack(side='left', padx=(0, 8))
        tk.Button(btn_row, text='Match Target', command=_match_target, bg=BTN_BG, fg=FG, relief='flat').pack(side='left', padx=(0, 8))
        tk.Button(btn_row, text='Refresh', command=_refresh_table, bg=BTN_BG, fg=FG, relief='flat').pack(side='right')

        edit.columnconfigure(1, weight=1)

        _refresh_table()

