    def _ws_get_cfg(sess: Dict[str, Any]) -> Tuple[Dict[str, Any], Dict[str, Any], Dict[str, Any]]:
        """Return (ws, ws_cfg, ws_qaqc) dicts (ensuring schema)."""
        blk = _ensure_daq_schema(sess)
        ws = (blk.get("worksteps") or {})
        ws_cfg = (ws.get("config") or {})
        ws_q = (ws.get("qaqc") or {})
        return ws, ws_cfg, ws_q

    def _tm_planned_run_minutes(sess: Dict[str, Any], run_no: Optional[int]) -> Tuple[Optional[float], str]:
        """
        Return planned minutes for a specific sampling run from the Test Matrix.

        Priority:
          1) test_matrix.plan.run_durations_min[run_no-1] (per-run override)
          2) test_matrix.plan.minutes_per_run (global default)

        Returns (minutes, source) where source ∈ {"TEST_MATRIX_RUN", "TEST_MATRIX", "NONE"}.
        """
        try:
            tm = sess.get("test_matrix") or {}
            plan = tm.get("plan") or {}

            # Per-run overrides (if present)
            rd = plan.get("run_durations_min")
            if run_no is not None:
                try:
                    rn_i = int(run_no)
                except Exception:
                    rn_i = None
                if rn_i is not None and rn_i > 0 and isinstance(rd, list) and len(rd) >= rn_i:
                    v = rd[rn_i - 1]
                    if v is not None:
                        mv = float(v)
                        if mv > 0.0:
                            return float(mv), "TEST_MATRIX_RUN"

            # Global minutes per run
            mr = plan.get("minutes_per_run")
            if mr is None:
                return None, "NONE"
            mr_f = float(mr)
            if not (mr_f > 0.0):
                return None, "NONE"
            return float(mr_f), "TEST_MATRIX"
        except Exception:
            return None, "NONE"

    def _tm_minutes_per_run(sess: Dict[str, Any]) -> Optional[float]:
        """Return global planned minutes per run from Test Matrix (plan.minutes_per_run), if available."""
        try:
            tm = sess.get("test_matrix") or {}
            plan = tm.get("plan") or {}
            mr = plan.get("minutes_per_run")
            if mr is None:
                return None
            mr_f = float(mr)
            if not (mr_f > 0.0):
                return None
            return float(mr_f)
        except Exception:
            return None

    def _tm_total_planned_minutes(sess: Dict[str, Any]) -> Optional[float]:
        """Sum planned minutes across all planned sampling runs in the Test Matrix."""
        try:
            tm = sess.get("test_matrix") or {}
            plan = tm.get("plan") or {}
            total_runs = int(plan.get("sample_runs") or 0)
            if total_runs <= 0:
                rd = plan.get("run_durations_min")
                if isinstance(rd, list) and len(rd) > 0:
                    total_runs = len(rd)
            if total_runs <= 0:
                return None

            total = 0.0
            any_ok = False
            for rn in range(1, total_runs + 1):
                m, _src = _tm_planned_run_minutes(sess, rn)
                if m is None:
                    continue
                try:
                    mf = float(m)
                except Exception:
                    continue
                if mf <= 0.0:
                    continue
                total += mf
                any_ok = True
            return float(total) if any_ok else None
        except Exception:
            return None

    def _tm_remaining_planned_seconds(sess: Dict[str, Any]) -> Optional[int]:
        """Remaining planned time (seconds) across current + future planned runs."""
        try:
            tm = sess.get("test_matrix") or {}
            plan = tm.get("plan") or {}
            total_runs = int(plan.get("sample_runs") or 0)
            if total_runs <= 0:
                return None

            # Planned durations in seconds for each run 1..N
            durs_s = []
            for rn in range(1, total_runs + 1):
                m, _src = _tm_planned_run_minutes(sess, rn)
                if m is None:
                    return None
                durs_s.append(int(round(float(m) * 60.0)))

            # Determine current run number (latest open run), otherwise next planned run.
            blk = sess.get("daq_runner") or {}
            runs = blk.get("runs") or []

            open_rn = None
            for r in runs:
                if not isinstance(r, dict):
                    continue
                try:
                    rn_i = int(r.get("run_no") or 0)
                except Exception:
                    continue
                if rn_i <= 0:
                    continue
                ended = bool(str(r.get("end_iso") or "").strip())
                if not ended:
                    if open_rn is None or rn_i > open_rn:
                        open_rn = rn_i

            if open_rn is None:
                # No open run -> next planned run number
                cur_rn = (len(runs) + 1) if isinstance(runs, list) else 1
            else:
                cur_rn = int(open_rn)

            if cur_rn <= 0:
                cur_rn = 1
            if cur_rn > total_runs:
                return 0

            # Current run remaining seconds: use countdown remaining if active.
            rem_cur = None
            try:
                end_ep = ws_runtime.get("test_end_epoch")
                if end_ep is not None:
                    rem = int(round(float(end_ep) - time.time()))
                    rem_cur = max(0, rem)
            except Exception:
                rem_cur = None

            if rem_cur is None:
                # If run already exists and has a target_duration_s, use that.
                tgt_s = None
                for r in runs:
                    if not isinstance(r, dict):
                        continue
                    try:
                        rn_i = int(r.get("run_no") or 0)
                    except Exception:
                        continue
                    if rn_i == cur_rn:
                        try:
                            v = r.get("target_duration_s")
                            if v is not None:
                                tgt_s = int(float(v))
                        except Exception:
                            tgt_s = None
                        break

                if tgt_s is not None and tgt_s > 0:
                    rem_cur = int(tgt_s)
                else:
                    rem_cur = int(durs_s[cur_rn - 1])

            total_rem = int(rem_cur)
            for rn in range(cur_rn + 1, total_runs + 1):
                total_rem += int(durs_s[rn - 1])
            return int(max(0, total_rem))
        except Exception:
            return None



    def _ws_save_cfg_from_ui(sess: Dict[str, Any]) -> None:
        """Persist Worksteps UI settings into session JSON."""
        ws, ws_cfg, _ = _ws_get_cfg(sess)

        def _i(v: str, default: int) -> int:
            try:
                return int(float(str(v).strip()))
            except Exception:
                return int(default)

        def _f(v: str, default: float) -> float:
            try:
                return float(str(v).strip())
            except Exception:
                return float(default)

        ws_cfg["capture_window_s"] = max(1, _i(var_ws_cap_win.get(), ws_cfg.get("capture_window_s", 10)))
        ws_cfg["stability_window_s"] = max(1, _i(var_ws_stab_win.get(), ws_cfg.get("stability_window_s", 15)))
        ws_cfg["purge_mult_t90"] = max(0.1, _f(var_ws_purge_mult.get(), ws_cfg.get("purge_mult_t90", 2.0)))
        ws_cfg["min_purge_s"] = max(0, _i(var_ws_min_purge.get(), ws_cfg.get("min_purge_s", 60)))
        ws_cfg["span_tol_pct"] = max(0.0, _f(var_ws_span_tol.get(), ws_cfg.get("span_tol_pct", 2.0)))
        # Operator-selected test duration (minutes). When >0, a countdown runs while recording.
        tm_mr = _tm_minutes_per_run(sess)
        if tm_mr is not None:
            # Mirror Test Matrix minutes-per-run into Worksteps config for traceability.
            ws_cfg["test_duration_min"] = float(tm_mr)
        else:
            # Manual override fallback when Test Matrix plan is absent.
            ws_cfg["test_duration_min"] = max(0.0, _f(var_ws_run_minutes.get(), ws_cfg.get("test_duration_min", 20.0)))
        ws_cfg["apply_mdc_floor"] = bool(var_ws_apply_mdc_floor.get())

        # (optional) allow UI to set events_path if needed
        if not str(ws.get("events_path") or "").strip():
            job = str(
                (sess.get("project") or {}).get("job_id")
                or (sess.get("project_session") or {}).get("job_id")
                or sess.get("job_id")
                or "session"
            ).strip() or "session"
            ws["events_path"] = str(cfg_path.parent / f"mole_worksteps_{job}.jsonl")

    def _ws_log_event(sess: Dict[str, Any], event: str, payload: Dict[str, Any]) -> None:
        """Append a JSONL event to the worksteps log file."""
        try:
            ws, _, _ = _ws_get_cfg(sess)
            p = str(ws.get("events_path") or "").strip()
            if not p:
                return
            # Attach a lightweight site snapshot when available (for QA/QC traceability)
            pay = dict(payload or {})
            try:
                if last_site_active is not None:
                    pay.setdefault(
                        "site",
                        {
                            "ts_iso": str(last_site_active.timestamp_iso or _now_iso()),
                            "mode": str(last_site_active.mode or ""),
                            "source": str(last_site_active.source or ""),
                            "T_amb_F": last_site_active.T_amb_F,
                            "P_bar_psia": last_site_active.P_bar_psia,
                            "RH_frac": last_site_active.RH_frac,
                            "z": last_site_active.z,
                        },
                    )
            except Exception:
                pass

            rec = {"ts_iso": _iso_now(), "event": str(event), "payload": pay}
            Path(p).parent.mkdir(parents=True, exist_ok=True)
            with open(p, "a", encoding="utf-8") as f:
                f.write(json.dumps(rec) + "\n")

            # Weather logging: only when session recording is enabled; worksteps events count as
            # "recording engaged" for calibration/QA/QC.
            try:
                if _session_record_enabled(sess):
                    _append_weather_log(sess, last_site_active, kind="WS_EVENT", note=str(event))
            except Exception:
                pass
        except Exception:
            pass

    def _ws_recent_series(code: str, window_s: float) -> List[Tuple[float, float]]:
        """Return [(epoch, value), ...] for last window_s seconds."""
        try:
            w = float(window_s)
        except Exception:
            w = 10.0
        if w <= 0:
            w = 10.0
        t_now = time.time()
        out: List[Tuple[float, float]] = []
        try:
            for t, fr in list(frame_hist):
                if (t_now - t) <= w:
                    v = _parse_float(fr.get(code))
                    if v is not None:
                        out.append((t, float(v)))
        except Exception:
            pass
        return out

    def _ws_avg_std(code: str, window_s: float) -> Tuple[Optional[float], Optional[float], int]:
        pts = _ws_recent_series(code, window_s)
        if not pts:
            return None, None, 0
        vals = [v for _, v in pts]
        n = len(vals)
        try:
            avg = float(sum(vals) / n)
        except Exception:
            avg = None
        try:
            std = float(statistics.pstdev(vals)) if n > 1 else 0.0
        except Exception:
            std = None
        return avg, std, n

    def _spec_engine_shadow_enabled(sess: Dict[str, Any]) -> bool:
        if mole_spec_engine is None or not isinstance(sess, dict):
            return False
        try:
            blk = _ensure_daq_schema(sess)
            cfg = blk.get("spec_engine") if isinstance(blk.get("spec_engine"), dict) else {}
            return bool(cfg.get("enabled", True) and cfg.get("shadow_mode", True))
        except Exception:
            return False

    def _spec_engine_eval_with_parity(
        sess: Dict[str, Any],
        step_name: str,
        code: str,
        *,
        target: Any = None,
        tol_abs: Any = None,
        tol_pct: Any = None,
        units: str = "",
        capture_window_s: Any = None,
        legacy_pass: Any = None,
        allow_missing_target_pass: bool = False,
        extra_inputs: Optional[Dict[str, Any]] = None,
        extra_outputs: Optional[Dict[str, Any]] = None,
        emit_log: bool = False,
    ) -> Optional[Dict[str, Any]]:
        if mole_spec_engine is None or not isinstance(sess, dict):
            return None
        try:
            blk = _ensure_daq_schema(sess)
            spec_cfg = blk.get("spec_engine") if isinstance(blk.get("spec_engine"), dict) else {}
            if not bool(spec_cfg.get("enabled", True)):
                return None
            parity_enabled = bool(spec_cfg.get("shadow_mode", True))
            _, ws_cfg, _ = _ws_get_cfg(sess)
            force_abs_basis = False
            try:
                force_abs_basis = (tol_abs not in (None, "")) and ((tol_pct in (None, "")) or (float(target) == 0.0))
            except Exception:
                force_abs_basis = (tol_abs not in (None, "")) and (tol_pct in (None, ""))
            try:
                window_s = float(capture_window_s if capture_window_s is not None else ws_cfg.get("capture_window_s", 10))
            except Exception:
                window_s = 10.0
            series = _ws_recent_series(code, window_s)
            result = mole_spec_engine.evaluate_channel_step(
                code,
                {
                    "step": str(step_name or "").strip().upper(),
                    "basis": ("ABS" if force_abs_basis else ""),
                    "units": str(units or "").strip(),
                    "stability_frac_of_tol": ws_cfg.get("stability_frac_of_tol", 0.5),
                    "min_stability_abs": 0.05 if str(code or "").strip().upper() in ("O2", "CO2") else 0.5,
                    "allow_missing_target_pass": bool(allow_missing_target_pass),
                    "stable_required_for_pass": False,
                    "treat_purge_as_zero": True,
                },
                series,
                {
                    "target": target,
                    "units": str(units or "").strip(),
                },
                {
                    "tol_abs": tol_abs,
                    "tol_pct": tol_pct,
                    "stability_frac_of_tol": ws_cfg.get("stability_frac_of_tol", 0.5),
                    "min_stability_abs": 0.05 if str(code or "").strip().upper() in ("O2", "CO2") else 0.5,
                },
            )
            comparison = {
                "legacy_pass": (None if legacy_pass is None else bool(legacy_pass)),
                "shadow_pass": (None if result.get("pass") is None else bool(result.get("pass"))),
                "match": (
                    None
                    if (not parity_enabled) or legacy_pass is None or result.get("pass") is None
                    else bool(bool(legacy_pass) == bool(result.get("pass")))
                ),
            }
            evidence = mole_spec_engine.build_evidence_record(
                step=step_name,
                channel=code,
                inputs={
                    "targets": {"target": target, "units": str(units or "").strip()},
                    "tolerances": {"tol_abs": tol_abs, "tol_pct": tol_pct},
                    "window_s": window_s,
                    "series_len": len(series),
                    **(dict(extra_inputs or {})),
                },
                outputs={
                    "legacy_pass": legacy_pass,
                    **(dict(extra_outputs or {})),
                },
                result=result,
                formula_version=str(spec_cfg.get("formula_version") or "spec_engine_v1"),
                event="STEP_EVAL_SHADOW",
            )
            evidence["comparison"] = comparison
            if emit_log and parity_enabled and bool(spec_cfg.get("capture_logging", True)):
                _ws_log_event(sess, ("SPEC_ENGINE_SHADOW" if comparison.get("match") is not False else "SPEC_ENGINE_SHADOW_MISMATCH"), evidence)
            return {
                "result": result,
                "comparison": comparison,
                "evidence": evidence,
                "parity_enabled": parity_enabled,
            }
        except Exception:
            return None

    def _spec_engine_shadow_capture(
        sess: Dict[str, Any],
        step_name: str,
        code: str,
        *,
        target: Any = None,
        tol_abs: Any = None,
        tol_pct: Any = None,
        units: str = "",
        capture_window_s: Any = None,
        legacy_pass: Any = None,
        allow_missing_target_pass: bool = False,
        extra_inputs: Optional[Dict[str, Any]] = None,
        extra_outputs: Optional[Dict[str, Any]] = None,
    ) -> Optional[Dict[str, Any]]:
        return _spec_engine_eval_with_parity(
            sess,
            step_name,
            code,
            target=target,
            tol_abs=tol_abs,
            tol_pct=tol_pct,
            units=units,
            capture_window_s=capture_window_s,
            legacy_pass=legacy_pass,
            allow_missing_target_pass=allow_missing_target_pass,
            extra_inputs=extra_inputs,
            extra_outputs=extra_outputs,
            emit_log=True,
        )

    def _spec_engine_row_payload(record: Any) -> Dict[str, Any]:
        if not isinstance(record, dict):
            return {}
        for key in ("spec_engine", "spec_engine_shadow"):
            payload = record.get(key)
            if isinstance(payload, dict):
                return payload
        return {}

    def _spec_engine_row_result(record: Any) -> Dict[str, Any]:
        payload = _spec_engine_row_payload(record)
        result = payload.get("result")
        return dict(result) if isinstance(result, dict) else {}

    def _spec_engine_row_match(record: Any) -> Optional[bool]:
        payload = _spec_engine_row_payload(record)
        comparison = payload.get("comparison")
        if not isinstance(comparison, dict):
            return None
        match = comparison.get("match")
        if match is None:
            return None
        try:
            return bool(match)
        except Exception:
            return None

    def _apply_spec_engine_result(record: Dict[str, Any], evaluation: Optional[Dict[str, Any]]) -> None:
        if not isinstance(record, dict) or not isinstance(evaluation, dict):
            return
        result = dict(evaluation.get("result") or {})
        if result:
            for key in (
                "avg",
                "std",
                "n",
                "target",
                "tolerance",
                "basis",
                "comparison_value",
                "recovery_pct",
                "stable",
                "stability_range",
                "stability_threshold",
                "within_tolerance",
                "status",
                "reason",
            ):
                if key in result and (result.get(key) is not None or key in ("stable", "within_tolerance", "status", "reason")):
                    record[key] = result.get(key)
            if "pass" in result:
                record["pass"] = bool(result.get("pass"))
        comparison = evaluation.get("comparison")
        if isinstance(comparison, dict) and comparison.get("legacy_pass") is not None:
            record["legacy_pass"] = bool(comparison.get("legacy_pass"))
        _attach_spec_engine_shadow(record, evaluation)

    def _attach_spec_engine_shadow(record: Dict[str, Any], shadow: Optional[Dict[str, Any]]) -> None:
        if not isinstance(record, dict) or not isinstance(shadow, dict):
            return
        payload = {
            "formula_version": str(((shadow.get("evidence") or {}).get("formula_version") or "spec_engine_v1")),
            "comparison": dict(shadow.get("comparison") or {}),
            "result": dict(shadow.get("result") or {}),
        }
        record["spec_engine"] = dict(payload)
        record["spec_engine_shadow"] = dict(payload)

    def _ws_row_display_value(record: Any, result_key: str, *fallback_keys: str) -> Any:
        result = _spec_engine_row_result(record)
        if isinstance(result, dict) and result.get(result_key) is not None:
            return result.get(result_key)
        if isinstance(record, dict):
            for key in fallback_keys:
                if record.get(key) not in (None, ""):
                    return record.get(key)
        return None

    def _ws_row_status_text(record: Any, *, pass_text: str = "OK") -> str:
        if not isinstance(record, dict) or not record:
            return ""
        result = _spec_engine_row_result(record)
        label = ""
        if result:
            status = str(result.get("status") or "").strip().upper()
            passed = result.get("pass")
            if status == "NO_TARGET":
                label = "NO TARGET"
            elif status == "NO_DATA":
                label = "NO DATA"
            elif passed is True:
                label = str(pass_text)
                if result.get("stable") is False:
                    label = f"{label} / UNSTABLE"
            elif passed is False:
                label = "FAIL" if status in ("", "FAIL") else status.replace("_", " ")
            elif status:
                label = status.replace("_", " ")
        elif "pass" in record:
            try:
                label = str(pass_text) if bool(record.get("pass")) else "FAIL"
            except Exception:
                label = ""
        if label and _spec_engine_row_match(record) is False:
            label = f"{label} / PARITY!"
        return label

    def _ws_row_pass_state(record: Any) -> Optional[bool]:
        result = _spec_engine_row_result(record)
        if result and "pass" in result:
            try:
                return bool(result.get("pass"))
            except Exception:
                return None
        if isinstance(record, dict) and "pass" in record:
            try:
                return bool(record.get("pass"))
            except Exception:
                return None
        return None

    def _ws_latest_postcal_drift_record(sess: Dict[str, Any], code: str) -> Optional[Dict[str, Any]]:
        try:
            blk = _ensure_daq_schema(sess)
            ws_q = (((blk.get("worksteps") or {}).get("qaqc")) or {})
            post_runs = ws_q.get("post_runs") if isinstance(ws_q.get("post_runs"), dict) else {}
            best_key = None
            best_prun = None
            best_rank: Tuple[int, str] = (-1, "")
            for key, prun in post_runs.items():
                if not isinstance(prun, dict):
                    continue
                key_s = str(key or "").strip()
                try:
                    rank = int(key_s)
                except Exception:
                    rank = -1
                candidate_rank = (rank, key_s)
                if candidate_rank >= best_rank:
                    best_rank = candidate_rank
                    best_key = key_s
                    best_prun = prun
            if not isinstance(best_prun, dict):
                return None
            zrec = ((best_prun.get("zero") or {}).get(code) or {})
            srec = ((best_prun.get("span") or {}).get(code) or {})
            ch_valid = ((best_prun.get("channel_valid") or {}).get(code))
            if ch_valid is not None:
                return {
                    "pass": bool(ch_valid),
                    "status": "PASS" if bool(ch_valid) else "FAIL",
                    "details": {"code": code, "run_no": best_key, "source": "post_runs.channel_valid"},
                }
            z_ok = _ws_row_pass_state(zrec)
            s_ok = _ws_row_pass_state(srec)
            if z_ok is None and s_ok is None:
                return None
            if z_ok is None or s_ok is None:
                return {
                    "pass": None,
                    "status": "NO_DATA",
                    "details": {"code": code, "run_no": best_key, "source": "post_runs.partial"},
                }
            passed = bool(z_ok and s_ok)
            return {
                "pass": passed,
                "status": "PASS" if passed else "FAIL",
                "details": {"code": code, "run_no": best_key, "source": "post_runs.zero_span"},
            }
        except Exception:
            return None

    def _ws_derive_validity(sess: Dict[str, Any], code: str, zero_record: Any, span_record: Any, channel_valid: Any = None) -> Dict[str, Any]:
        drift_record = _ws_latest_postcal_drift_record(sess, code)
        fallback_state = "VALID"
        if channel_valid is False:
            fallback_state = "INVALID"
        elif zero_record or span_record:
            zero_ok = _ws_row_pass_state(zero_record)
            span_ok = _ws_row_pass_state(span_record)
            if zero_ok is False or span_ok is False:
                fallback_state = "INVALID"
            elif isinstance(drift_record, dict) and drift_record.get("pass") is False:
                fallback_state = "INVALID"
            elif zero_ok is None or span_ok is None:
                fallback_state = "DEGRADED"
        if mole_spec_engine is None or not hasattr(mole_spec_engine, "derive_analyzer_validity"):
            return {"state": fallback_state, "reason": ""}
        try:
            validity = mole_spec_engine.derive_analyzer_validity(
                (_spec_engine_row_result(zero_record) or zero_record),
                (_spec_engine_row_result(span_record) or span_record),
                drift_record,
                latched_invalid=bool(channel_valid is False),
                invalidate_on_drift=True,
            )
        except Exception:
            validity = {"state": fallback_state, "reason": ""}
        state = str((validity or {}).get("state") or fallback_state).strip().upper() or fallback_state
        if channel_valid is False and state != "INVALID":
            validity = dict(validity or {})
            validity["state"] = "INVALID"
            validity["reason"] = str(validity.get("reason") or "Channel is latched invalid.")
            return validity
        return dict(validity or {"state": state, "reason": ""})

    def _ws_validity_snapshot(sess: Dict[str, Any], codes: Optional[Sequence[str]] = None) -> Dict[str, Dict[str, Any]]:
        try:
            blk = _ensure_daq_schema(sess)
            ws_q = (((blk.get("worksteps") or {}).get("qaqc")) or {})
        except Exception:
            return {}

        code_set: set[str] = set()
        try:
            for code in (codes or []):
                code_u = str(code or "").strip().upper()
                if code_u:
                    code_set.add(code_u)
        except Exception:
            pass
        try:
            code_set.update(_selected_pollutants(sess))
        except Exception:
            pass
        for block_name in ("zero", "mid", "span", "channel_valid"):
            block = ws_q.get(block_name) if isinstance(ws_q.get(block_name), dict) else {}
            for key in block.keys():
                code_u = str(key or "").strip().upper()
                if code_u:
                    code_set.add(code_u)
        try:
            for prun in ((ws_q.get("post_runs") or {}).values() if isinstance(ws_q.get("post_runs"), dict) else []):
                if not isinstance(prun, dict):
                    continue
                for block_name in ("zero", "span", "channel_valid"):
                    block = prun.get(block_name) if isinstance(prun.get(block_name), dict) else {}
                    for key in block.keys():
                        code_u = str(key or "").strip().upper()
                        if code_u:
                            code_set.add(code_u)
        except Exception:
            pass

        out: Dict[str, Dict[str, Any]] = {}
        for code in sorted(code_set):
            zero_record = ((ws_q.get("zero") or {}).get(code) or {})
            span_record = ((ws_q.get("span") or {}).get(code) or {})
            channel_valid = (ws_q.get("channel_valid") or {}).get(code, True)
            out[code] = _ws_derive_validity(sess, code, zero_record, span_record, channel_valid)
        return out

    def _ws_spec_parity_summary(sess: Dict[str, Any]) -> str:
        try:
            blk = _ensure_daq_schema(sess)
            ws_q = (((blk.get("worksteps") or {}).get("qaqc")) or {})
            total = 0
            mismatch = 0

            def _scan_rows(rows: Any) -> None:
                nonlocal total, mismatch
                if not isinstance(rows, dict):
                    return
                for row in rows.values():
                    match = _spec_engine_row_match(row)
                    if match is None:
                        continue
                    total += 1
                    if match is False:
                        mismatch += 1

            _scan_rows(ws_q.get("zero"))
            _scan_rows(ws_q.get("mid"))
            _scan_rows(ws_q.get("span"))
            for prun in ((ws_q.get("post_runs") or {}).values() if isinstance(ws_q.get("post_runs"), dict) else []):
                if not isinstance(prun, dict):
                    continue
                _scan_rows(prun.get("zero"))
                _scan_rows(prun.get("span"))

            if total <= 0:
                return "Spec parity: no captured checks yet"
            if mismatch <= 0:
                return f"Spec parity: {total}/{total} aligned"
            return f"Spec parity: {total - mismatch}/{total} aligned ({mismatch} mismatch)"
        except Exception:
            return "Spec parity: (n/a)"


    def _ws_estimate_t90(code: str, start_epoch: float, end_epoch: float, v0: float, v1: float) -> Optional[float]:
        """Estimate T90 from the cached live series between start_epoch and end_epoch."""
        try:
            s = float(start_epoch)
            e = float(end_epoch)
        except Exception:
            return None
        if e <= s:
            return None

        # Build series
        series: List[Tuple[float, float]] = []
        try:
            for t, fr in list(frame_hist):
                if s <= t <= e:
                    v = _parse_float(fr.get(code))
                    if v is not None:
                        series.append((t, float(v)))
        except Exception:
            pass
        if len(series) < 3:
            return None

        target = float(v0) + 0.9 * (float(v1) - float(v0))
        direction = 1 if (v1 - v0) >= 0 else -1

        for t, v in series:
            if direction >= 0 and v >= target:
                return max(0.0, float(t - s))
            if direction < 0 and v <= target:
                return max(0.0, float(t - s))
        return None

    def _ws_default_zero_tol(code: str, ws_cfg: Dict[str, Any]) -> float:
        c = str(code).upper()
        # Treat CO2 like O2 (both are % channels in most stack analyzers)
        if c in ("O2", "CO2"):
            return float(ws_cfg.get("zero_tol_abs_o2", 0.2))
        return float(ws_cfg.get("zero_tol_abs_default", 2.0))

    def _ws_is_stable(sess: Dict[str, Any], code: str) -> bool:
        """Stability check based on recent range.

        Policy: stability should be *commensurate with the active tolerance regime*.
        - During Worksteps gas steps (ZERO/MID/SPAN/POST_* and PURGE), stability threshold is a
          fraction of the step tolerance band so SIM noise doesn't keep everything "UNSTABLE".
        - During normal testing (regulatory limits), fall back to conservative absolute thresholds.
        """
        _, ws_cfg, ws_q = _ws_get_cfg(sess)
        try:
            w = float(ws_cfg.get("stability_window_s", 15))
        except Exception:
            w = 15.0

        pts = _ws_recent_series(code, w)
        if len(pts) < 3:
            return False
        vals = [v for _, v in pts]
        rng = max(vals) - min(vals)

        c = str(code).upper().strip()
        # conservative absolute minimum thresholds
        min_thr = 0.05 if c == "O2" else 0.5
        # fraction of tolerance band to treat as "stable"
        try:
            frac = float(ws_cfg.get("stability_frac_of_tol", 0.5))
        except Exception:
            frac = 0.25
        if frac <= 0:
            frac = 0.25

        # Determine active step mode (PURGE behaves like ambient air)
        step_mode = None
        try:
            step_mode = str((ws_q or {}).get("active_gas_step") or "").strip().upper()
        except Exception:
            step_mode = None
        if step_mode == "PURGE":
            step_mode = "AMBIENT"

        tol_band = None
        try:
            if step_mode in ("ZERO", "POST_ZERO"):
                tol_band = float(_ws_default_zero_tol(c, ws_cfg))
            elif step_mode == "AMBIENT":
                if c == "O2":
                    tol_band = float(ws_cfg.get("ambient_o2_tol_abs", 1.0))
                elif c == "CO2":
                    tol_band = float(ws_cfg.get("ambient_co2_tol_abs", 0.5))
                else:
                    tol_band = float(_ws_default_zero_tol(c, ws_cfg))
            elif step_mode in ("MID",):
                tgt = _parse_float(((ws_q.get("mid") or {}).get(c) or {}).get("target"))
                if tgt is not None:
                    tol_pct = float(ws_cfg.get("span_tol_pct", 2.0))
                    tol_band = abs(float(tgt)) * tol_pct / 100.0
            elif step_mode in ("SPAN", "POST_SPAN"):
                tgt = _parse_float(((ws_q.get("span") or {}).get(c) or {}).get("target"))
                if tgt is not None:
                    tol_pct = float(ws_cfg.get("span_tol_pct", 2.0))
                    tol_band = abs(float(tgt)) * tol_pct / 100.0
        except Exception:
            tol_band = None

        thr = min_thr
        try:
            if tol_band is not None:
                thr = max(float(min_thr), float(frac) * float(tol_band))
        except Exception:
            thr = min_thr
        return float(rng) <= float(thr)

    def _ws_recommended_purge_seconds(sess: Dict[str, Any]) -> Optional[int]:
        """Compute purge seconds from response times (T90) + minimum purge."""
        _, ws_cfg, ws_q = _ws_get_cfg(sess)
        try:
            purge_mult = float(ws_cfg.get("purge_mult_t90", 2.0))
        except Exception:
            purge_mult = 2.0
        try:
            min_purge = int(float(ws_cfg.get("min_purge_s", 60)))
        except Exception:
            min_purge = 60

        t90s: List[float] = []
        try:
            for code in _selected_pollutants(sess):
                t90 = _parse_float((ws_q.get("response", {}).get(code, {}) or {}).get("t90_s"))
                if t90 is not None and t90 > 0:
                    t90s.append(float(t90))
        except Exception:
            pass
        if not t90s:
            return int(min_purge) if min_purge is not None else None

        rec = int(round(max(float(min_purge), purge_mult * max(t90s))))
        return max(0, rec)

    def _ws_update_status_indicators(sess: Dict[str, Any]) -> None:
        """Refresh Worksteps runtime labels (purge recommendation + stability)."""
        # purge recommendation
        rec = _ws_recommended_purge_seconds(sess)
        if rec is None:
            ws_purge_reco_var.set("Recommended purge: (n/a)")
        else:
            ws_purge_reco_var.set(f"Recommended purge: {rec} s")

        # stability summary
        try:
            sels = _selected_pollutants(sess)
            if not sels:
                ws_stable_var.set("Stability: (n/a)")
            else:
                stable_cnt = sum(1 for c in sels if _ws_is_stable(sess, c))
                all_stable = stable_cnt == len(sels)
                ws_stable_var.set(f"Stability: {'STABLE' if all_stable else 'UNSTABLE'} ({stable_cnt}/{len(sels)})")
        except Exception:
            ws_stable_var.set("Stability: (n/a)")

        try:
            ws_parity_var.set(_ws_spec_parity_summary(sess))
        except Exception:
            ws_parity_var.set("Spec parity: (n/a)")

        # purge timer (if running)
        try:
            end_ep = ws_runtime.get("purge_end_epoch")
            if end_ep:
                rem = int(round(float(end_ep) - time.time()))
                if rem > 0:
                    ws_purge_timer_var.set(f"Timer: {rem} s remaining")
                else:
                    ws_purge_timer_var.set("Timer: DONE")
        except Exception:
            pass

    def ws_initiate_zero_air() -> None:
        nonlocal sess
        if not last_frame:
            messagebox.showwarning("No live data", "No live frame yet. Start acquisition (UI) and wait for data.")
            return
        try:
            sess = _load_session()
            _ensure_daq_schema(sess)
            _ws_save_cfg_from_ui(sess)
            _, _, ws_q = _ws_get_cfg(sess)
            _ws_set_active_gas_step(sess, ws_q, "ZERO")

            # Transition start marker for response-time estimation
            base: Dict[str, Any] = {}
            for code in _selected_pollutants(sess):
                avg, _, _ = _ws_avg_std(code, float(var_ws_cap_win.get() or 10))
                base[code] = avg

            ws_q.setdefault("transitions", {})
            ws_q["transitions"]["zero_air"] = {
                "start_iso": _iso_now(),
                "start_epoch": time.time(),
                "baseline": base,
            }

            # Log snapshot (all keys from last_frame)
            _ws_log_event(sess, "ZERO_AIR_INIT", {"frame": dict(last_frame)})
            # TRAINING: drive SIM_TRAINING manifold mode
            if _mole_env_mode(sess) == "TRAINING":
                try:
                    drv = acq.get("driver")
                    if drv is not None and hasattr(drv, "update_scenario"):
                        codes = _selected_pollutants(sess)
                        pres = _pollutant_prescriptions(sess)
                        drv.update_scenario(build_sim_training_scenario(sess, codes=codes, prescriptions=pres))
                    if drv is not None and hasattr(drv, "set_manifold_mode"):
                        drv.set_manifold_mode("ZERO")
                except Exception:
                    pass

            _save_session(sess)
            refresh_all()
        except Exception as e:
            messagebox.showerror("ZERO AIR init failed", str(e))


