    def _ws_step_is_complete(ws_q: Dict[str, Any], step_key: str, sess: Dict[str, Any]) -> bool:
        # True when ALL selected pollutants have a capture for the given step.
        try:
            codes = list(_selected_pollutants(sess) or [])
            if not codes:
                return False
            blk = ws_q.get(step_key) or {}
            if not isinstance(blk, dict):
                return False
            for code in codes:
                row = blk.get(code)
                if not isinstance(row, dict):
                    return False
                if not _ws_row_is_countable(row):
                    return False
                if step_key == "mid":
                    if row.get("avg") is None:
                        return False
                else:
                    if row.get("meas") is None:
                        return False
            return True
        except Exception:
            return False

    def _ws_step_expected_gas(step_key: str) -> Optional[str]:
        mapping = {"zero": "ZERO", "mid": "MID", "span": "SPAN"}
        return mapping.get(str(step_key or "").strip().lower())

    def _ws_capture_context(ws_q: Dict[str, Any], step_key: str) -> Dict[str, Any]:
        expected = _ws_step_expected_gas(step_key)
        active = str((ws_q or {}).get("active_gas_step") or "").strip().upper()
        return {
            "expected_step": expected,
            "active_step": active,
            "context_match": bool(expected is None or active == expected),
            "canonicalized": False,
        }

    def _ws_row_is_countable(row: Any) -> bool:
        if not isinstance(row, dict):
            return False
        if row.get("context_match") is False:
            return False
        canon = row.get("canonicalized")
        if canon is None:
            return True
        return bool(canon)

    def _ws_canonicalize_step_on_advance(sess: Dict[str, Any], ws_q: Dict[str, Any], next_step: str) -> None:
        try:
            prev_active = str((ws_q or {}).get("active_gas_step") or "").strip().upper()
            next_active = str(next_step or "").strip().upper()
            step_map = {"ZERO": "zero", "MID": "mid", "SPAN": "span"}
            step_key = step_map.get(prev_active)
            if not step_key or prev_active == next_active:
                return
            blk = ws_q.get(step_key)
            if not isinstance(blk, dict):
                return
            ws_q.setdefault("channel_valid", {})
            changed = False
            for code, row in list(blk.items()):
                if not isinstance(row, dict):
                    continue
                row["canonicalized_on_advance_to"] = next_active
                if row.get("context_match") is False:
                    row["canonicalized"] = False
                    changed = True
                    continue
                row["canonicalized"] = True
                row["canonicalized_at"] = _iso_now()
                changed = True
                ok = bool(row.get("pass"))
                if not ok:
                    ws_q["channel_valid"][code] = False
                else:
                    ws_q["channel_valid"].setdefault(code, True)
            if changed:
                try:
                    _ws_log_event(sess, "STEP_CANONICALIZED", {"step": step_key.upper(), "advanced_to": next_active})
                except Exception:
                    pass
        except Exception:
            pass

    def _ws_set_active_gas_step(sess: Dict[str, Any], ws_q: Dict[str, Any], next_step: str) -> None:
        try:
            _ws_canonicalize_step_on_advance(sess, ws_q, next_step)
        except Exception:
            pass
        try:
            ws_q["active_gas_step"] = str(next_step or "").strip().upper()
        except Exception:
            pass

    def _ws_post_step_is_complete(step_blk: Dict[str, Any], sess: Dict[str, Any]) -> bool:
        # True when ALL selected pollutants have a post-cal capture (meas) in step_blk.
        try:
            codes = list(_selected_pollutants(sess) or [])
            if not codes:
                return False
            for code in codes:
                row = (step_blk or {}).get(code)
                if not isinstance(row, dict):
                    return False
                if row.get("meas") is None:
                    return False
            return True
        except Exception:
            return False

    def ws_capture_zero(code: str) -> None:
        nonlocal sess
        if not last_frame:
            messagebox.showwarning("No live data", "No live frame yet. Start acquisition (UI) and wait for data.")
            return

        try:
            sess = _load_session()
            if _mole_env_mode(sess) == "TRAINING":
                try:
                    drv = acq.get("driver")
                    cur = ""
                    if drv is not None and hasattr(drv, "get_manifold_mode"):
                        cur = str(drv.get_manifold_mode() or "")
                    cur_u = cur.strip().upper()
                    if cur_u and cur_u not in ("ZERO",):
                        ok = messagebox.askyesno("Training Coach", f"SIM gas mode is '{cur_u}'. Expected ZERO. Capture anyway?")
                        if not ok:
                            return
                except Exception:
                    pass
            _ensure_daq_schema(sess)
            _ws_save_cfg_from_ui(sess)
            ws, ws_cfg, ws_q = _ws_get_cfg(sess)
            was_complete = _ws_step_is_complete(ws_q, "zero", sess)

            w = float(ws_cfg.get("capture_window_s", 10))
            avg, std, n = _ws_avg_std(code, w)
            if avg is None:
                messagebox.showwarning("Capture ZERO", f"No valid readings for {code} in the last {_fmt_num(w, 0, '0')}s.")
                return

            # Target from UI (per-row); fallback to 0
            tgt = 0.0
            try:
                v = ws_row_vars.get(code, {}).get("zero_tgt")
                if v is not None:
                    tgt = float(str(v.get()).strip())
            except Exception:
                tgt = 0.0

            tol = _ws_default_zero_tol(code, ws_cfg)
            legacy_ok = abs(float(avg) - float(tgt)) <= float(tol)

            ws_q.setdefault("zero", {})
            ws_q["zero"][code] = {
                **_ws_capture_context(ws_q, "zero"),
                "ts_iso": _iso_now(),
                "meas": float(avg),
                "avg": float(avg),
                "std": float(std) if std is not None else None,
                "n": int(n),
                "target": float(tgt),
                "tol_abs": float(tol),
                "pass": bool(legacy_ok),
            }
            _apply_spec_engine_result(
                ws_q["zero"][code],
                _spec_engine_shadow_capture(
                    sess,
                    "ZERO",
                    code,
                    target=float(tgt),
                    tol_abs=float(tol),
                    units=str((ws_row_vars.get(code, {}).get("units").get() if ws_row_vars.get(code, {}).get("units") else "") or ""),
                    capture_window_s=w,
                    legacy_pass=legacy_ok,
                    extra_inputs={"avg": float(avg), "std": (float(std) if std is not None else None), "n": int(n)},
                ),
            )
            ok = bool(ws_q["zero"][code].get("pass"))

            now_complete = _ws_step_is_complete(ws_q, "zero", sess)

            # MDC (only meaningful when target is ~0)
            if abs(float(tgt)) <= 1e-9:
                mdc = max(0.0, float(avg))
                ws_q.setdefault("mdc", {})
                ws_q["mdc"][code] = float(mdc)

            # Response-time estimate if we have a transition start marker
            try:
                trans = (ws_q.get("transitions") or {}).get("zero_air") or {}
                s_ep = float(trans.get("start_epoch") or 0.0)
                base_v = (trans.get("baseline") or {}).get(code)
                if base_v is not None:
                    t90 = _ws_estimate_t90(code, s_ep, time.time(), float(base_v), float(avg))
                    if t90 is not None:
                        ws_q.setdefault("response", {})
                        ws_q["response"][code] = {"t90_s": float(t90), "source": "ZERO_AIR"}
            except Exception:
                pass

            _ws_log_event(
                sess,
                "CAPTURE_ZERO",
                {
                    "pollutant": code,
                    "avg": float(avg),
                    "std": float(std) if std is not None else None,
                    "n": int(n),
                    "target": float(tgt),
                    "tol_abs": float(tol),
                    "pass": bool(ok),
                    "legacy_pass": bool(legacy_ok),
                    "status": ws_q["zero"][code].get("status"),
                    "stable": ws_q["zero"][code].get("stable"),
                    "parity_match": _spec_engine_row_match(ws_q["zero"][code]),
                },
            )

            _save_session(sess)
            refresh_all()
            if now_complete and not was_complete:
                _show_simple_splash("ZERO CAPTURE COMPLETE", "ZERO STEP COMPLETE", "All analytes captured for ZERO.", auto_ms=5000)
        except Exception as e:
            messagebox.showerror("Capture ZERO failed", str(e))


    def ws_capture_mid(code: str) -> None:
        """Capture MID gas response for a pollutant (3-pt CAL)."""
        nonlocal sess
        try:
            # Guard: If session is 2-pt CAL, allow capture but label as optional.
            cal_pts = int(_cal_points_effective(sess) or 2)
            if cal_pts < 3:
                # Still allow capture (operator may be doing an ad-hoc bias check)
                pass

            sess = _load_session()
            if _mole_env_mode(sess) == "TRAINING":
                try:
                    drv = acq.get("driver")
                    cur = ""
                    if drv is not None and hasattr(drv, "get_manifold_mode"):
                        cur = str(drv.get_manifold_mode() or "")
                    cur_u = cur.strip().upper()
                    if cur_u and cur_u not in ("MID",):
                        ok = messagebox.askyesno("Training Coach", f"SIM gas mode is '{cur_u}'. Expected MID. Capture anyway?")
                        if not ok:
                            return
                except Exception:
                    pass
            _ensure_daq_schema(sess)
            _ws_save_cfg_from_ui(sess)
            ws, ws_cfg, ws_q = _ws_get_cfg(sess)
            cal_pts_eff = int(_cal_points_effective(sess) or 2)
            was_complete = _ws_step_is_complete(ws_q, "mid", sess) if cal_pts_eff >= 3 else False

            window_s = float(ws_cfg.get("capture_window_s") or 10.0)
            avg, std, n = _ws_avg_std(code, window_s)
            if avg is None:
                messagebox.showwarning("Capture MID", f"No valid readings for {code} in the last {_fmt_num(window_s, 0, '0')}s.")
                return

            tgt = _safe_float(ws_row_vars.get(code, {}).get("mid_tgt").get() if ws_row_vars.get(code, {}).get("mid_tgt") else None)

            span_tol_pct = float(ws_cfg.get("span_tol_pct") or 5.0)

            recovery = None
            legacy_ok = True
            if tgt is None or tgt == 0:
                # No target: record but do not assert pass/fail
                legacy_ok = True
            else:
                recovery = (avg / tgt) * 100.0
                legacy_ok = abs(recovery - 100.0) <= span_tol_pct

            ws_q.setdefault("mid", {})
            ws_q["mid"][code] = {
                **_ws_capture_context(ws_q, "mid"),
                "ts_iso": _iso_now(),
                "window_s": float(window_s),
                "target": float(tgt) if tgt is not None else None,
                "avg": float(avg),
                "std": float(std),
                "n": int(n),
                "recovery_pct": float(recovery) if recovery is not None else None,
                "tol_pct": float(span_tol_pct),
                "pass": bool(legacy_ok),
            }
            _apply_spec_engine_result(
                ws_q["mid"][code],
                _spec_engine_shadow_capture(
                    sess,
                    "MID",
                    code,
                    target=(float(tgt) if tgt is not None else None),
                    tol_pct=float(span_tol_pct),
                    units=str((ws_row_vars.get(code, {}).get("units").get() if ws_row_vars.get(code, {}).get("units") else "") or ""),
                    capture_window_s=window_s,
                    legacy_pass=legacy_ok,
                    allow_missing_target_pass=bool(tgt in (None, 0.0)),
                    extra_inputs={"avg": float(avg), "std": float(std), "n": int(n)},
                ),
            )
            recovery = _ws_row_display_value(ws_q["mid"][code], "recovery_pct", "recovery_pct")
            ok = bool(ws_q["mid"][code].get("pass"))

            now_complete = _ws_step_is_complete(ws_q, "mid", sess) if cal_pts_eff >= 3 else False

            # Response-time estimate from MID transition marker
            try:
                trans = (ws_q.get("transitions") or {}).get("mid_gas") or {}
                s_ep = trans.get("start_epoch")
                e_ep = time.time()
                base = (trans.get("baseline") or {}).get(code)
                if s_ep and base is not None:
                    t90 = _ws_estimate_t90(code, float(s_ep), float(e_ep), float(base), float(avg))
                    ws_q.setdefault("response", {})
                    if code not in ws_q["response"]:
                        ws_q["response"][code] = {}
                    if t90:
                        ws_q["response"][code].setdefault("t90_s", float(t90))
                        ws_q["response"][code].setdefault("method", "t90_from_mid")
            except Exception:
                pass

            _ws_log_event(
                sess,
                "CAPTURE_MID",
                {
                    "pollutant": code,
                    "avg": float(avg),
                    "std": float(std),
                    "target": float(tgt) if tgt is not None else None,
                    "recovery": float(recovery) if recovery is not None else None,
                    "tol_pct": float(span_tol_pct),
                    "pass": bool(ok),
                    "legacy_pass": bool(legacy_ok),
                    "status": ws_q["mid"][code].get("status"),
                    "stable": ws_q["mid"][code].get("stable"),
                    "parity_match": _spec_engine_row_match(ws_q["mid"][code]),
                },
            )

            _save_session(sess)
            refresh_all()
            if cal_pts_eff >= 3 and now_complete and not was_complete:
                _show_simple_splash("MID CAPTURE COMPLETE", "MID STEP COMPLETE", "All analytes captured for MID (3-pt CAL).", auto_ms=5000)
        except Exception as e:
            messagebox.showerror("Capture MID failed", str(e))


    def ws_capture_span(code: str) -> None:
        nonlocal sess
        if not last_frame:
            messagebox.showwarning("No live data", "No live frame yet. Start acquisition (UI) and wait for data.")
            return

        try:
            sess = _load_session()
            if _mole_env_mode(sess) == "TRAINING":
                try:
                    drv = acq.get("driver")
                    cur = ""
                    if drv is not None and hasattr(drv, "get_manifold_mode"):
                        cur = str(drv.get_manifold_mode() or "")
                    cur_u = cur.strip().upper()
                    if cur_u and cur_u not in ("SPAN",):
                        ok = messagebox.askyesno("Training Coach", f"SIM gas mode is '{cur_u}'. Expected SPAN. Capture anyway?")
                        if not ok:
                            return
                except Exception:
                    pass
            _ensure_daq_schema(sess)
            _ws_save_cfg_from_ui(sess)
            ws, ws_cfg, ws_q = _ws_get_cfg(sess)
            was_complete = _ws_step_is_complete(ws_q, "span", sess)

            w = float(ws_cfg.get("capture_window_s", 10))
            avg, std, n = _ws_avg_std(code, w)
            if avg is None:
                messagebox.showwarning("Capture SPAN", f"No valid readings for {code} in the last {_fmt_num(w, 0, '0')}s.")
                return

            # Target span concentration from UI entry (required)
            tgt = None
            try:
                v = ws_row_vars.get(code, {}).get("span_tgt")
                if v is not None:
                    txt = str(v.get()).strip()
                    tgt = float(txt) if txt != "" else None
            except Exception:
                tgt = None

            if tgt is None or float(tgt) == 0.0:
                messagebox.showwarning("Capture SPAN", f"Please enter a non-zero SPAN target for {code} (cylinder concentration).")
                return

            span_tol_pct = float(ws_cfg.get("span_tol_pct", 2.0))
            recovery = (float(avg) / float(tgt)) * 100.0
            legacy_ok = abs(recovery - 100.0) <= float(span_tol_pct)

            ws_q.setdefault("span", {})
            ws_q["span"][code] = {
                **_ws_capture_context(ws_q, "span"),
                "ts_iso": _iso_now(),
                "meas": float(avg),
                "avg": float(avg),
                "std": float(std) if std is not None else None,
                "n": int(n),
                "target": float(tgt),
                "recovery_pct": float(recovery),
                "tol_pct": float(span_tol_pct),
                "pass": bool(legacy_ok),
            }
            _apply_spec_engine_result(
                ws_q["span"][code],
                _spec_engine_shadow_capture(
                    sess,
                    "SPAN",
                    code,
                    target=float(tgt),
                    tol_pct=float(span_tol_pct),
                    units=str((ws_row_vars.get(code, {}).get("units").get() if ws_row_vars.get(code, {}).get("units") else "") or ""),
                    capture_window_s=w,
                    legacy_pass=legacy_ok,
                    extra_inputs={"avg": float(avg), "std": (float(std) if std is not None else None), "n": int(n)},
                ),
            )
            recovery = _ws_row_display_value(ws_q["span"][code], "recovery_pct", "recovery_pct")
            ok = bool(ws_q["span"][code].get("pass"))

            now_complete = _ws_step_is_complete(ws_q, "span", sess)

            # Response-time estimate from span transition marker
            try:
                trans = (ws_q.get("transitions") or {}).get("span_gas") or {}
                s_ep = float(trans.get("start_epoch") or 0.0)
                base_v = (trans.get("baseline") or {}).get(code)
                if base_v is not None:
                    t90 = _ws_estimate_t90(code, s_ep, time.time(), float(base_v), float(avg))
                    if t90 is not None:
                        ws_q.setdefault("response", {})
                        ws_q["response"][code] = {"t90_s": float(t90), "source": "SPAN_GAS"}
            except Exception:
                pass

            _ws_log_event(
                sess,
                "CAPTURE_SPAN",
                {
                    "pollutant": code,
                    "avg": float(avg),
                    "std": float(std) if std is not None else None,
                    "n": int(n),
                    "target": float(tgt),
                    "recovery_pct": float(recovery) if recovery is not None else None,
                    "tol_pct": float(span_tol_pct),
                    "pass": bool(ok),
                    "legacy_pass": bool(legacy_ok),
                    "status": ws_q["span"][code].get("status"),
                    "stable": ws_q["span"][code].get("stable"),
                    "parity_match": _spec_engine_row_match(ws_q["span"][code]),
                },
            )

            _save_session(sess)
            refresh_all()
            if now_complete and not was_complete:
                _show_simple_splash("SPAN CAPTURE COMPLETE", "SPAN STEP COMPLETE", "All analytes captured for SPAN.", auto_ms=5000)
        except Exception as e:
            messagebox.showerror("Capture SPAN failed", str(e))

    
    # -------------------------------
    # Post-run Bias / Post-Cal (required after each run)
    # -------------------------------

    def _ws_postcal_ctx(sess: Dict[str, Any]) -> Tuple[Optional[int], Dict[str, Any], Dict[str, Any], Dict[str, Any], Dict[str, Any]]:
        """
        Return (run_no, ws, ws_cfg, ws_q, prun) for the currently required post-cal run.
        If no post-cal is required, run_no is None.
        """
        blk = _ensure_daq_schema(sess)
        ws = (blk.get("worksteps") or {})
        ws_cfg = (ws.get("config") or {})
        ws_q = (ws.get("qaqc") or {})
        postcal = ws.get("postcal") or {}

        if not bool(postcal.get("required")):
            return None, ws, ws_cfg, ws_q, {}

        run_no = postcal.get("run_no")
        if run_no in (None, ""):
            # fallback: active run
            try:
                runs = blk.get("runs") or []
                idx = int(blk.get("active_run_index") or 0)
                if isinstance(runs, list) and runs and 0 <= idx < len(runs):
                    run_no = (runs[idx] or {}).get("run_no")
            except Exception:
                run_no = None

        try:
            run_no_i = int(run_no) if run_no not in (None, "") else None
        except Exception:
            run_no_i = None

        if run_no_i is None:
            return None, ws, ws_cfg, ws_q, {}

        ws_q.setdefault("post_runs", {})
        prun = ws_q["post_runs"].get(str(run_no_i))
        if not isinstance(prun, dict):
            prun = {}
            ws_q["post_runs"][str(run_no_i)] = prun

        prun.setdefault("zero", {})
        prun.setdefault("span", {})
        prun.setdefault("channel_valid", {})
        prun.setdefault("transitions", {})
        prun.setdefault("completed_iso", None)
        prun.setdefault("overall_pass", None)

        return int(run_no_i), ws, ws_cfg, ws_q, prun

    def _ws_postcal_is_complete(sess: Dict[str, Any], run_no: int) -> bool:
        try:
            _, _, ws_q = _ws_get_cfg(sess)
            prun = (ws_q.get("post_runs") or {}).get(str(run_no)) or {}
            z = prun.get("zero") or {}
            s = prun.get("span") or {}
            sels = _selected_pollutants(sess)
            if not sels:
                return False
            return all((c in z) and (c in s) for c in sels)
        except Exception:
            return False

    def _ws_finalize_postcal(sess: Dict[str, Any], run_no: int) -> None:
        """Compute drift/bias outcomes, invalidate channels as needed, and clear the post-cal gate."""
        blk = _ensure_daq_schema(sess)
        ws = (blk.get("worksteps") or {})
        ws_q = (ws.get("qaqc") or {})
        postcal = ws.get("postcal") or {}
        post_runs = ws_q.get("post_runs") or {}
        prun = post_runs.get(str(run_no)) or {}
        if not isinstance(prun, dict):
            return

        pre_zero_map = ws_q.get("zero") or {}
        pre_span_map = ws_q.get("span") or {}

        zmap = prun.get("zero") or {}
        smap = prun.get("span") or {}
        ch_valid = prun.get("channel_valid") or {}

        overall_pass = True
        for code in _selected_pollutants(sess):
            pz = zmap.get(code) or {}
            ps = smap.get(code) or {}

            z_ok = bool(pz.get("pass")) if pz else False
            s_ok = bool(ps.get("pass")) if ps else False
            ok = bool(z_ok and s_ok)

            # Drift values vs PRE (if available)
            try:
                pre_z = _parse_float((pre_zero_map.get(code) or {}).get("meas"))
                post_z = _parse_float(pz.get("meas"))
                if pre_z is not None and post_z is not None:
                    pz["drift_abs"] = float(post_z) - float(pre_z)
            except Exception:
                pass
            try:
                pre_r = _parse_float((pre_span_map.get(code) or {}).get("recovery_pct"))
                post_r = _parse_float(ps.get("recovery_pct"))
                if pre_r is not None and post_r is not None:
                    ps["drift_recovery_pct"] = float(post_r) - float(pre_r)
            except Exception:
                pass

            ch_valid[code] = ok
            if not ok:
                overall_pass = False

                # invalidate channel globally (does not kill the test)
                ws_q.setdefault("channel_valid", {})
                ws_q["channel_valid"][code] = False

        prun["channel_valid"] = ch_valid
        
        # Overall post-cal health (PASS/WARN/FAIL)
        try:
            hb = prun.get("health_by_channel") or {}
            vals = [str(v) for v in hb.values() if v]
            if any(v == "FAIL" for v in vals):
                prun["postcal_health"] = "FAIL"
            elif any(v == "WARN" for v in vals):
                prun["postcal_health"] = "WARN"
            elif vals:
                prun["postcal_health"] = "PASS"
            else:
                prun["postcal_health"] = "WARN"
        except Exception:
            prun["postcal_health"] = "WARN"

        # Optional: persist QA/QC cal events to Master DB for trending
        try:
            _persist_qaqc_trending_events(sess, run_no, prun)
        except Exception:
            pass

        prun["completed_iso"] = _iso_now()
        prun["overall_pass"] = bool(overall_pass)

        # persist completion marker
        postcal.setdefault("completed_runs", {})
        postcal["completed_runs"][str(run_no)] = {
            "completed_iso": prun.get("completed_iso"),
            "pass": bool(overall_pass),
            "channel_valid": dict(ch_valid),
        }

        # clear gate for next run
        postcal["required"] = False
        postcal["run_no"] = None

        _ws_log_event(sess, "POSTCAL_COMPLETE", {"run_no": run_no, "pass": bool(overall_pass), "channel_valid": dict(ch_valid)})

    def ws_post_initiate_zero_air() -> None:
        nonlocal sess
        if not last_frame:
            messagebox.showwarning("No live data", "No live frame yet. Start acquisition (UI) and wait for data.")
            return
        try:
            sess = _load_session()
            _ensure_daq_schema(sess)
            _ws_save_cfg_from_ui(sess)

            run_no, ws, ws_cfg, ws_q, prun = _ws_postcal_ctx(sess)
            # Active gas step for live spec coloring
            try:
                ws_q["active_gas_step"] = "POST_ZERO"
            except Exception:
                pass
            if run_no is None:
                messagebox.showinfo("Post-Cal", "No post-cal is currently required (end a Test Run to trigger it).")
                return

            # Transition start marker for post-cal response calculations
            base: Dict[str, Any] = {}
            for code in _selected_pollutants(sess):
                avg, _, _ = _ws_avg_std(code, float(var_ws_cap_win.get() or 10))
                base[code] = avg

            prun.setdefault("transitions", {})
            prun["transitions"]["zero_air"] = {
                "start_iso": _iso_now(),
                "start_epoch": time.time(),
                "baseline": base,
            }

            _ws_log_event(sess, "POST_ZERO_AIR_INIT", {"run_no": run_no, "frame": dict(last_frame)})

            # TRAINING: drive SIM_TRAINING manifold mode

            if _mole_env_mode(sess) == "TRAINING":

                try:

                    drv = acq.get("driver")

                    if drv is not None and hasattr(drv, "update_scenario"):

                        codes = _selected_pollutants(sess)

                        pres = _pollutant_prescriptions(sess)

                        drv.update_scenario(build_sim_training_scenario(sess, codes=codes, prescriptions=pres))

                    if drv is not None and hasattr(drv, "set_manifold_mode"):

                        drv.set_manifold_mode("POST_ZERO")

                except Exception:

                    pass

            _save_session(sess)
            refresh_all()
        except Exception as e:
            messagebox.showerror("POST ZERO AIR init failed", str(e))

